insert into public.revision_content (id, data, updated_at) values
  ('cards-1', $xxb${"theme":1,"cards":[{"id":"t1-01","q":"Quand et où est né Baden-Powell ?","a":"Le **22 février 1857**, à Londres.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"22 février 1857, à Londres","no":["8 janvier 1857, à Oxford","22 février 1867, à Londres","29 juillet 1857, à Nyeri"]}},{"id":"t1-02","q":"Quel est le nom complet de B-P, et quel titre reçoit-il en 1929 ?","a":"Robert Stephenson Smyth Baden-Powell. En 1929, le roi George V le fait **Lord Baden-Powell of Gilwell**.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Robert Stephenson Smyth Baden-Powell ; Lord Baden-Powell of Gilwell","no":["Robert Smyth Baden-Powell ; Lord of Brownsea","Robert Stephenson Baden-Powell ; Lord of Mafeking","Henry Robert Baden-Powell ; Sir of Gilwell"]}},{"id":"t1-03","q":"Quelles étaient les professions du père et de la mère de B-P ?","a":"Père : pasteur protestant et professeur de géométrie à Oxford. Mère : naturaliste (Henrietta Grace Smyth).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Père pasteur et professeur de géométrie à Oxford ; mère naturaliste","no":["Père militaire ; mère institutrice","Père médecin à Londres ; mère musicienne","Père professeur de dessin ; mère infirmière"]}},{"id":"t1-04","q":"Qui était le parrain de B-P ?","a":"Robert Stephenson, fils de l'inventeur de la locomotive.","src":"fiches-BP.pdf","qcm":{"ok":"Robert Stephenson, fils de l'inventeur de la locomotive","no":["Le roi George V","M. MacLaren, donateur du parc de Gilwell","Lord Kitchener, son supérieur militaire"]}},{"id":"t1-05","q":"Quelle carrière B-P a-t-il eue avant le scoutisme, et quand l'a-t-il quittée ?","a":"Militaire de **1876 à 1910**. Il démissionne en 1910 pour se consacrer entièrement au mouvement.","src":"fiches-BP.pdf, Bases du scoutisme.pdf","qcm":{"ok":"Militaire, de 1876 à 1910","no":["Enseignant, de 1880 à 1907","Militaire, de 1870 à 1920","Explorateur, de 1876 à 1910"]}},{"id":"t1-06","q":"Quel épisode a rendu B-P célèbre, et pourquoi compte-t-il pour le scoutisme ?","a":"Le **siège de Mafeking** (guerre des Boers, 1899-1900). C'est là que B-P découvre l'enthousiasme et l'utilité des jeunes (les « cadets de Mafeking »).","src":"Bases du scoutisme.pdf","qcm":{"ok":"Le siège de Mafeking (1899-1900)","no":["La bataille d'Omdurman (1898)","La guerre de Crimée (1854-1856)","La bataille de Waterloo (1815)"]}},{"id":"t1-07","q":"Donne les trois surnoms africains de B-P et leur sens.","a":"**M'hala Panzi** (Natal) : l'homme qui se couche pour tuer. **Kantakye** (Ashantis) : l'homme au grand chapeau. **Impeesa** (Matabélés) : le loup qui ne dort jamais.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"M'hala Panzi, Kantakye et Impeesa","no":["Impeesa, Akela et Baloo","Kantakye, Bagheera et Kaa","M'hala Panzi, Mowgli et Akela"]}},{"id":"t1-08","q":"Quels instruments jouait B-P, et quelle fut sa première collection ?","a":"Piano et violon. Sa première collection : un dessin fait à 3 ans (il adorait dessiner).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Piano et violon ; un dessin fait à 3 ans","no":["Flûte et tambour ; une collection de timbres","Guitare et piano ; des coquillages","Violon et trompette ; des papillons"]}},{"id":"t1-09","q":"Quand B-P épouse-t-il Olave Soames, et où se sont-ils rencontrés ?","a":"Le **30 octobre 1912**. Ils se sont rencontrés lors d'une croisière (aux Antilles).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Le 30 octobre 1912 ; rencontrés lors d'une croisière","no":["Le 22 février 1912 ; rencontrés à Brownsea","Le 30 octobre 1920 ; rencontrés au Jamboree","Le 8 mai 1910 ; rencontrés à Gilwell"]}},{"id":"t1-10","q":"Combien d'enfants ont eu Olave et B-P ?","a":"Trois : **Peter** (1913, prénom d'après Peter Pan), **Heather** (1915) et **Betty** (1917).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Trois : Peter, Heather et Betty","no":["Deux : Peter et Betty","Trois : Peter, Agnès et Olave","Quatre : Peter, Heather, Betty et George"]}},{"id":"t1-11","q":"Pourquoi B-P a-t-il arrêté de fumer en entrant dans l'armée ?","a":"Trois raisons : l'économie, le goût (il fumait par habitude) et l'odorat, un sens précieux dans l'art du « scouting » que le tabac altère.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Par économie, par goût et pour préserver son odorat","no":["Sur ordre de son colonel","Pour raisons de santé uniquement","Par superstition militaire"]}},{"id":"t1-12","q":"Combien de livres B-P a-t-il écrits ?","a":"**32** au cours de sa vie.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"32","no":["12","50","8"]}},{"id":"t1-13","q":"Que signifie le signe « fin de piste » sur la tombe de B-P, et où est-il enterré ?","a":"Il signifie « retourné à la maison ». B-P est mort le **8 janvier 1941** à **Nyeri (Kenya)**, à 83 ans.","src":"fiches-BP.pdf, Bases du scoutisme.pdf","qcm":{"ok":"« Retourné à la maison » ; à Nyeri (Kenya), mort le 8 janvier 1941","no":["« Piste perdue » ; à Londres, mort en 1937","« Fin du voyage » ; à Gilwell, mort en 1941","« Sois prêt » ; à Mafeking, mort en 1939"]}},{"id":"t1-14","q":"Que se passe-t-il pour B-P en 1939 ?","a":"Il est mis en nomination pour le **prix Nobel de la paix**. Le prix n'est pas remis, la Seconde Guerre mondiale débutant cette année-là.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Il est proposé pour le prix Nobel de la paix","no":["Il reçoit le prix Nobel de la paix","Il est fait Lord Baden-Powell of Gilwell","Il crée le louvetisme"]}},{"id":"t1-15","q":"Que devient Olave en 1916 puis en 1930 ?","a":"1916 : elle remplace Agnès, sœur de B-P, chez les guides. 1930 : elle est choisie **Chef guide mondiale**.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"1916 : elle remplace Agnès chez les guides ; 1930 : Chef guide mondiale","no":["1916 : elle fonde les louveteaux ; 1930 : Chef scout du monde","1916 : elle épouse B-P ; 1930 : présidente de Gilwell","1916 : Chef guide mondiale ; 1930 : elle se retire"]}},{"id":"t1-16","q":"Quels cadeaux les scouts du monde ont-ils offerts à B-P et Olave en 1913 et en 1929 ?","a":"1913 : une « Standard Landaulette ». 1929, au 3e Jamboree mondial : une Rolls-Royce baptisée **« Jam Roll »** (100 000 scouts ont donné un penny chacun).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Une Standard Landaulette, puis une Rolls-Royce « Jam Roll »","no":["Une Rolls-Royce, puis un yacht « Jamboree »","Un cheval, puis une Standard Landaulette","Une maison à Gilwell, puis une Bentley « Scout »"]}},{"id":"t1-17","q":"Quelles sont les dates exactes du premier camp scout, et où a-t-il eu lieu ?","a":"Du **29 juillet au 9 août 1907**, sur l'île de **Brownsea** (Angleterre).","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Du 29 juillet au 9 août 1907, sur l'île de Brownsea","no":["Du 1er au 15 août 1908, à Gilwell","Du 29 juillet au 9 août 1909, à Crystal Palace","Du 8 au 20 mai 1907, sur l'île de Wight"]}},{"id":"t1-18","q":"Combien de jeunes à Brownsea, et que faisaient-ils ?","a":"Une vingtaine de jeunes. Jeux d'observation, de traque et de poursuite ; secourisme, nœuds, brêlages, camping, cuisine au feu de camp.","src":"fiches-BP.pdf","note":"Âge des jeunes : 9 à 17 ans selon fiches-BP, 12 à 17 ans selon Quiz-BP.","qcm":{"ok":"Une vingtaine : observation, traque, secourisme, nœuds, camping","no":["Une centaine : marches et défilés militaires","Une dizaine : cours de dessin et de musique","Huit : uniquement de la natation"]}},{"id":"t1-19","q":"Quels noms ont reçu les premières patrouilles de l'histoire ?","a":"Les **loups, les taureaux, les courlis et les corbeaux**.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Les loups, les taureaux, les courlis et les corbeaux","no":["Les lions, les aigles, les castors et les renards","Les loups, les ours, les cerfs et les hiboux","Les iguanes, les rats palmistes, les courlis et les lions"]}},{"id":"t1-20","q":"Qui utilisait l'île de Brownsea avant B-P ?","a":"Les pirates et les contrebandiers.","src":"fiches-BP.pdf, Quiz-BP.pdf","qcm":{"ok":"Les pirates et les contrebandiers","no":["Des moines bénédictins","Des chercheurs d'or","Une colonie de naturalistes"]}},{"id":"t1-21","q":"Quel livre de B-P est publié en 1908, et sous quelle forme ?","a":"**Scouting for Boys** (Éclaireurs), en six livraisons bimensuelles puis réunies en volume (éditeur Pearson).","src":"Bases du scoutisme.pdf, fiches-BP.pdf","qcm":{"ok":"Scouting for Boys, en six livraisons bimensuelles","no":["Le Livre de la jungle, en un seul volume","Aids to Scouting, en feuilleton quotidien","La route du succès, en douze livraisons"]}},{"id":"t1-22","q":"Que se passe-t-il à Crystal Palace en 1909 ?","a":"Le premier rallye : B-P invite les éclaireurs à se rassembler, **10 000** viennent.","src":"Bases du scoutisme.pdf, Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Le premier rallye : 10 000 éclaireurs","no":["Le premier Jamboree mondial : 8 000 scouts","Le premier camp de chefs : 100 chefs","Le premier Jamboree sur les ondes"]}},{"id":"t1-23","q":"Que rappellent 1914 et 1916 dans l'histoire du mouvement ?","a":"**1914** : création du louvetisme. **1916** : publication du Livre du louveteau.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"1914 : le louvetisme ; 1916 : le Livre du louveteau","no":["1914 : les guides ; 1916 : la Route","1914 : le Livre du louveteau ; 1916 : le louvetisme","1914 : Gilwell ; 1916 : le premier Jamboree"]}},{"id":"t1-24","q":"La Route : quelle date de création, et quel livre B-P écrit-il pour les routiers ?","a":"Création en **1918** (annale Rallye) ou **1919** (Bases du scoutisme). Livre : *La route du succès*, publié en **1922** selon l'annale Rallye.","src":"Connaissance du mvt rallye dak23.pdf, Bases du scoutisme.pdf","note":"Les sources ne s'accordent pas : à retenir avec la date de chaque source.","qcm":{"ok":"1918 ou 1919 selon les sources ; La route du succès","no":["1925 selon les sources ; Scouting for Boys","1910 ou 1912 selon les sources ; le Livre du louveteau","1918 ou 1919 selon les sources ; Aids to Scouting"]}},{"id":"t1-25","q":"Qu'est-ce que Gilwell, et qui a donné le parc au scoutisme ?","a":"Le camp de formation des chefs lancé en **1919**. Le parc a été donné au scoutisme par **M. MacLaren**.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Le camp de formation des chefs (1919), parc donné par M. MacLaren","no":["Le premier camp scout (1907), donné par le roi","Le siège mondial du scoutisme, donné par Olave","Un camp de louveteaux (1914), donné par Lord Kitchener"]}},{"id":"t1-26","q":"Où et quand a eu lieu le premier Jamboree mondial, et que se passe-t-il pour B-P ?","a":"À **Londres en 1920** (8 000 scouts de 34 pays). B-P est proclamé **Chef scout du monde**.","src":"Quiz-BP.pdf, Bases du scoutisme.pdf, fiches-BP.pdf","qcm":{"ok":"Londres, 1920 : B-P proclamé Chef scout du monde","no":["Birkenhead, 1929 : B-P fait Lord","Paris, 1924 : B-P reçoit le Nobel","Londres, 1907 : B-P fonde la Route"]}},{"id":"t1-27","q":"D'où vient le mot « jamboree », et à quel rythme ont lieu ces rassemblements ?","a":"D'un mot zoulou qui veut dire « ralliement ». Rassemblements internationaux tous les **4 ans**.","src":"Bases du scoutisme.pdf","qcm":{"ok":"D'un mot zoulou, « ralliement » ; tous les 4 ans","no":["D'un mot anglais, « fête » ; tous les ans","D'un mot hindi, « camp » ; tous les 2 ans","D'un mot latin, « réunion » ; tous les 5 ans"]}},{"id":"t1-28","q":"Que sait-on du Jamboree de 1929 ?","a":"Il a eu lieu à **Birkenhead** (près de Liverpool), pour le 20e anniversaire, avec **50 000** scouts.","src":"Bases du scoutisme.pdf","qcm":{"ok":"À Birkenhead, pour le 20e anniversaire, avec 50 000 scouts","no":["À Londres, pour le 10e anniversaire, avec 8 000 scouts","À Paris, pour le 25e anniversaire, avec 30 000 scouts","À Gilwell, pour le 20e anniversaire, avec 10 000 scouts"]}},{"id":"t1-29","q":"Quelle est la date du premier Jamboree sur les ondes ?","a":"**1958**.","src":"Quiz-BP.pdf","qcm":{"ok":"1958","no":["1929","1948","1968"]}},{"id":"t1-30","q":"Quels sont les trois degrés historiques du mouvement et leurs âges ?","a":"**Louveteaux** (8-11 ans), **éclaireurs** (12-17 ans), **routiers** (17 ans et plus).","src":"Bases du scoutisme.pdf","note":"Repères historiques du texte. Les âges peuvent différer dans les textes nationaux actuels.","qcm":{"ok":"Louveteaux 8-11 ans, éclaireurs 12-17 ans, routiers 17 ans et plus","no":["Louveteaux 6-9 ans, éclaireurs 10-14 ans, routiers 15 ans et plus","Louveteaux 8-12 ans, éclaireurs 13-16 ans, routiers 18 ans et plus","Castors 5-7 ans, louveteaux 8-11 ans, éclaireurs 12 ans et plus"]}},{"id":"t1-31","q":"Les 15 éléments fondamentaux : quels sont les trois groupes de cinq ?","a":"Les **5 buts**, les **5 dimensions** et les **5 moteurs**.","src":"Bases du scoutisme.pdf","qcm":{"ok":"5 buts, 5 dimensions et 5 moteurs","no":["5 lois, 5 promesses et 5 devises","5 buts, 5 méthodes et 5 valeurs","5 branches, 5 dimensions et 5 étapes"]}},{"id":"t1-32","q":"Cite les 5 buts du scoutisme (acronyme SSSDF).","a":"**S**anté, **S**ervice du prochain, **S**ens de Dieu, **D**ébrouillardise (sens du concret), **F**ormation du caractère.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Santé, Service du prochain, Sens de Dieu, Débrouillardise, Formation du caractère","no":["Santé, Sport, Solidarité, Discipline, Fraternité","Service, Silence, Sens civique, Devoir, Fidélité","Sagesse, Service, Sécurité, Discipline, Formation"]}},{"id":"t1-33","q":"Cite les 5 dimensions du scoutisme.","a":"La nature et le camp, la patrouille, la règle du jeu (la loi scoute), le civisme (la B.A.), l'engagement (la promesse).","src":"Bases du scoutisme.pdf","qcm":{"ok":"Nature et camp, patrouille, loi scoute, civisme (B.A.), promesse","no":["Jeu, chant, prière, marche, uniforme","Nature, sport, école, famille, religion","Patrouille, troupe, groupe, district, nation"]}},{"id":"t1-34","q":"Cite les 5 moteurs du scoutisme.","a":"L'intérêt, l'action, les responsabilités, le système des patrouilles, la CDH et le CDC.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Intérêt, action, responsabilités, système des patrouilles, CDH et CDC","no":["Discipline, uniforme, grades, sanctions, récompenses","Jeu, chant, veillée, prière, camp","Loi, promesse, devise, salut, B.A."]}},{"id":"t1-35","q":"Que dit le texte sur le « sens de Dieu » comme but ?","a":"Il n'est pas en soi un but défini par B-P. Le but du scoutisme n'est pas de former de futurs prêtres, mais de bons citoyens.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Pas un but défini par B-P : former des citoyens, pas des prêtres","no":["Le premier but fixé par B-P : former d'abord des croyants","Un but réservé aux routiers, qui s'engagent dans leur Église","Le but principal : préparer des vocations de prêtres"]}},{"id":"t1-36","q":"La promesse scoute est un triple engagement. Lequel ?","a":"**Être loyal, aider autrui, observer la loi scoute.** Engagement volontaire, pris sur l'honneur devant ses frères.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Être loyal, aider autrui, observer la loi scoute","no":["Obéir, servir, prier","Être prêt, être propre, être poli","Aimer sa patrie, sa famille et son chef"]}},{"id":"t1-37","q":"Pourquoi la loi scoute n'est-elle pas un règlement avec sanctions ?","a":"C'est une série de « conseils de vie » proposés au jeune, qui choisit de faire de son mieux. Pas de sanction : une discussion pour l'aider à progresser.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Ce sont des conseils de vie : pas de sanction, une discussion","no":["Elle est sanctionnée par le conseil des chefs","Elle ne s'applique que pendant les camps","Elle est imposée par l'État"]}},{"id":"t1-38","q":"Combien d'articles compte la loi de B-P, et quel est le 11e ?","a":"**10 articles** écrits. Le 11e, non écrit : « **Le scout n'est pas un sot.** »","src":"Bases du scoutisme.pdf","qcm":{"ok":"10 articles ; le 11e : « Le scout n'est pas un sot »","no":["12 articles ; le 11e : « Le scout est propre »","10 articles ; le 11e : « Le scout sourit »","11 articles ; le 11e : « Le scout est prêt »"]}},{"id":"t1-39","q":"D'où vient la devise « Sois prêt » ?","a":"Des initiales de B-P : **Be Prepared**.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx","qcm":{"ok":"Des initiales de B-P : Be Prepared","no":["D'une devise militaire de Mafeking","D'une prière d'Olave","Du blason de la famille Baden-Powell"]}},{"id":"t1-40","q":"Quelles qualités la devise exige-t-elle de l'éclaireur ?","a":"Le **sens des autres**, la **compétence**, l'**observation suivie du réflexe**.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx","qcm":{"ok":"Le sens des autres, la compétence, l'observation suivie du réflexe","no":["La force physique, la vitesse et l'endurance à la marche","L'obéissance aux chefs, la ponctualité et la propreté","Le courage au combat, l'habileté manuelle et la ruse"]}},{"id":"t1-41","q":"Que signifie être prêt d'esprit et prêt de corps selon B-P ?","a":"**D'esprit** : s'être donné la discipline d'obéir et avoir pensé d'avance aux situations possibles. **De corps** : s'être rendu fort, actif, capable de faire au bon moment l'action qu'il faut.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx","qcm":{"ok":"D'esprit : discipline et anticipation ; de corps : fort, actif, capable d'agir à temps","no":["D'esprit : connaître la loi par cœur ; de corps : porter l'uniforme","D'esprit : prier chaque jour ; de corps : courir longtemps","D'esprit : obéir sans réfléchir ; de corps : être grand"]}},{"id":"t1-42","q":"La bonne action (B.A.) : quelle règle sur la récompense, et que faire si on l'oublie ?","a":"On n'accepte **jamais de récompense** (de l'argent, ce serait du travail payé). Si on l'oublie, on fait **deux bonnes actions le lendemain**.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Jamais de récompense ; si on l'oublie, deux B.A. le lendemain","no":["Une petite récompense est permise ; rien à rattraper","Jamais de récompense ; une punition si on l'oublie","Une récompense en argent ; deux B.A. la semaine suivante"]}},{"id":"t1-43","q":"Que devient la B.A. à la meute, à la troupe et au clan ?","a":"Meute : un plaisir fait chaque jour. Troupe : un réflexe d'aider, service spontané. Clan : un service permanent dans la communauté.","src":"Bases du scoutisme.pdf","qcm":{"ok":"Meute : un plaisir chaque jour ; troupe : un réflexe d'aider ; clan : un service permanent","no":["Meute : un service permanent ; troupe : un plaisir ; clan : un réflexe","Elle est identique dans les trois branches","Meute : une corvée ; troupe : un devoir ; clan : facultative"]}},{"id":"t1-44","q":"Décris le salut scout et ce que signifient ses éléments.","a":"Main droite, **trois doigts du milieu levés** (triple promesse ; franchise, dévouement, pureté), **pouce sur l'auriculaire** (le fort protège le faible).","src":"Bases du scoutisme.pdf","qcm":{"ok":"Main droite, trois doigts du milieu levés, pouce sur l'auriculaire","no":["Main gauche, deux doigts levés, pouce replié sur la paume","Main droite, quatre doigts levés, pouce replié sur la paume","Main droite à plat sur le cœur, doigts serrés vers le haut"]}},{"id":"t1-45","q":"Pourquoi les scouts se serrent-ils la main gauche ?","a":"Elle est du côté du cœur, et un chef ashanti l'a tendue à B-P : les plus braves serrent la main gauche, en abandonnant leur bouclier.","src":"Bases du scoutisme.pdf, fiches-BP.pdf","qcm":{"ok":"Côté du cœur ; les braves la tendent en posant leur bouclier","no":["Pour garder la main droite libre de saluer en même temps","Par coutume des officiers anglais de l'armée des Indes","Pour se distinguer des guides, qui serrent la main droite"]}},{"id":"t1-46","q":"Que signifie la fleur de lys, et que veut dire le trèfle ?","a":"La fleur de lys indique le **nord** sur les cartes : le scout sait toujours retrouver son chemin. Le **trèfle** est le symbole des guides.","src":"fiches-BP.pdf, Bases du scoutisme.pdf","qcm":{"ok":"Le nord sur les cartes ; le trèfle est le symbole des guides","no":["La royauté française ; le trèfle est celui des louveteaux","La pureté ; le trèfle est celui des routiers","Le sud ; le trèfle est celui des chefs"]}},{"id":"t1-47","q":"Quel est l'appel scout, et quand le lance-t-on ?","a":"« Sont-ils là les éclaireurs, sont-ils là ? » Réponse : « Ils sont là les éclaireurs, ils sont là. » On le lance avant d'entrer dans un coin de patrouille ou au Kraal.","src":"Bases du scoutisme.pdf","qcm":{"ok":"« Sont-ils là les éclaireurs ? », avant d'entrer au coin de patrouille ou au Kraal","no":["« Toujours prêts ! », au lever des couleurs","« Sois prêt ! », à la fin de chaque réunion","« Akela, nous ferons de notre mieux », à la veillée"]}},{"id":"t1-48","q":"Quelle est la taille d'une patrouille ?","a":"Historiquement **huit** (début du mouvement, Bases du scoutisme). Aujourd'hui **cinq à sept** (LE SCOUTISME).","src":"Bases du scoutisme.pdf, LE SCOUTISME.docx","note":"Les sources divergent : huit (Bases du scoutisme, débuts du mouvement), cinq à sept (LE SCOUTISME), six à huit (Manuel du CP).","qcm":{"ok":"Huit à l'origine, cinq à sept aujourd'hui","no":["Douze à l'origine, dix aujourd'hui","Quatre à l'origine, six aujourd'hui","Toujours exactement six"]}},{"id":"t1-49","q":"Qu'est-ce que « l'esprit scout » ?","a":"L'attitude qu'on doit avoir, balisée par la loi scoute : vivre scoutement partout et faire passer le bonheur des autres au moins autant que le sien.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx","qcm":{"ok":"Vivre scoutement partout, le bonheur des autres autant que le sien","no":["Porter l'uniforme en toute occasion, même hors des activités","Obéir sans discuter à son chef, en camp comme en ville","Gagner les concours entre patrouilles pour l'honneur de la troupe"]}},{"id":"t1-50","q":"Qui a eu l'idée de créer les scouts au Sénégal, et en quelle année ?","a":"Le R.P. **Lecocq**, curé de Dakar (Sacré-Cœur), en **1931**. Naissance officieuse en décembre 1931.","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Le R.P. Lecocq, curé de Dakar, en 1931","no":["Léon Fabert, militaire, en 1932","Le R.P. Doutremepuich, en 1938","Gabriel Sagna, en 1931"]}},{"id":"t1-51","q":"Quel jour et où les quatre premiers scouts du Sénégal ont-ils fait leur promesse ?","a":"Le **8 mai 1932**, dans la cour de l'**école Saint Michel** à Dakar (fête de Sainte Jeanne d'Arc).","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Le 8 mai 1932, à l'école Saint Michel de Dakar","no":["Le 23 avril 1931, à la cathédrale de Dakar","Le 8 mai 1931, à Saint-Louis","Le 30 octobre 1932, au Sacré-Cœur"]}},{"id":"t1-52","q":"Qui sont les quatre premiers scouts du Sénégal ?","a":"Gabriel Sagna, Emmanuel Nunez, Georges Monteiro et Paul de Souza.","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Gabriel Sagna, Emmanuel Nunez, Georges Monteiro et Paul de Souza","no":["Léon Fabert, Gabriel Sagna, Albert Ndiaye et Paul de Souza","Albert Ndiaye, Emmanuel Nunez, René Caillé et Georges Monteiro","Gabriel Sagna, Charles Foucault, Paul de Souza et Léon Fabert"]}},{"id":"t1-53","q":"Quelles sont les deux premières patrouilles du Sénégal et leurs chefs ?","a":"**Rats palmistes** (CP Gabriel Sagna, SP Paul de Souza) et **Iguanes** (CP Emmanuel Nunez, SP Georges Monteiro).","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Rats palmistes (CP Gabriel Sagna) et Iguanes (CP Emmanuel Nunez)","no":["Loups (CP Paul de Souza) et Corbeaux (CP Georges Monteiro)","Iguanes (CP Gabriel Sagna) et Rats palmistes (CP Emmanuel Nunez)","Lions (CP Gabriel Sagna) et Aigles (CP Emmanuel Nunez)"]}},{"id":"t1-54","q":"Qui sont le chef de troupe et l'aumônier de la première troupe, et comment s'appelle-t-elle ?","a":"Troupe **Sainte Jeanne d'Arc**. Chef de troupe : **Léon Fabert** (jeune militaire du 6e RAC). Aumônier : **R.P. Doutremepuich**.","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Troupe Sainte Jeanne d'Arc ; CT Léon Fabert ; aumônier R.P. Doutremepuich","no":["Troupe René Caillé ; CT R.P. Lecocq ; aumônier Léon Fabert","Troupe Saint Michel ; CT Gabriel Sagna ; aumônier R.P. Lecocq","Troupe Charles Foucault ; CT Léon Fabert ; aumônier R.P. Lecocq"]}},{"id":"t1-55","q":"À quel mouvement le scoutisme sénégalais est-il affilié en 1932 ?","a":"Aux **Scouts de France** (affiliation officielle en 1932).","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Aux Scouts de France","no":["Aux Éclaireurs de France","À la Boy Scouts Association britannique","Aux Scouts et Guides de France"]}},{"id":"t1-56","q":"Quelles unités apparaissent après la première troupe, et quand les routiers ?","a":"Une meute, puis les troupes **René Caillé** et **Charles Foucault**. Les scouts aînés deviennent routiers en **1938**.","src":"Historique Scoutisme Senegal.pdf","qcm":{"ok":"Une meute, puis les troupes René Caillé et Charles Foucault ; routiers en 1938","no":["Une compagnie de guides ; routiers en 1932","Les troupes Saint Michel et Saint Georges ; routiers en 1945","Une meute seulement ; routiers en 1950"]}},{"id":"t1-57","q":"Qui est le saint patron des éclaireurs, et quand le célèbre-t-on ?","a":"**Saint Georges**, le **23 avril**.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Saint Georges, le 23 avril","no":["Saint Michel, le 29 septembre","Sainte Jeanne d'Arc, le 8 mai","Saint Paul, le 29 juin"]}},{"id":"t1-58","q":"Qu'est-ce que le carnet de preuves, et quelles sont ses 4 parties ?","a":"Le manuel-guide de l'éclaireur qui lui permet de progresser. Parties : **volontaire, engagé, technicien, animateur**.","src":"Connaissance du mvt rallye dak23.pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Le guide de progression : volontaire, engagé, technicien, animateur","no":["Le carnet de notes : novice, aspirant, scout, chef","Le registre de troupe : louveteau, éclaireur, routier, chef","Le manuel du chef : recrue, membre, assistant, responsable"]}},{"id":"t1-59","q":"Quelle est la plus haute distinction dans le scoutisme ?","a":"Le **Loup de bronze**.","src":"Connaissance du mvt rallye dak23.pdf","note":"Source unique (annale Rallye Dakar 2023).","qcm":{"ok":"Le Loup de bronze","no":["Le Castor d'or","La Croix de Gilwell","Le Lys d'or"]}},{"id":"t1-60","q":"Qui est le premier Sénégalais à avoir reçu le Loup de bronze ?","a":"**Albert Ndiaye**.","src":"Connaissance du mvt rallye dak23.pdf","note":"Source unique (annale Rallye Dakar 2023).","qcm":{"ok":"Albert Ndiaye","no":["Gabriel Sagna","Emmanuel Nunez","Léon Fabert"]}}]}$xxb$::jsonb, now()),
  ('cards-10', $xxb${"theme":10,"cards":[{"id":"t10-01","q":"Qu'est-ce que la trésorerie selon le guide du trésorier ?","a":"L'**ensemble des sommes d'argent disponibles en caisse ou placées en banque**. Sa gestion permet de contrôler les entrées et sorties d'argent, avec pour objectif d'**optimiser l'équilibre financier**.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Les sommes disponibles en caisse ou placées en banque","no":["Le total des cotisations attendues sur l'année","La valeur du matériel et des biens du groupe","Les dons promis par les parents et partenaires"]}},{"id":"t10-02","q":"Quelles sont les trois missions attendues du trésorier ?","a":"Une mission d'**accompagnement** des scouts (aider les chefs à bâtir leur budget, suivre les comptes d'unité…), une mission de **performance** (établir le budget prévisionnel, garantir le respect des procédures financières) et une mission **technique** (tenir les comptes, récupérer journaux et pièces justificatives auprès des chefs d'unité).","src":"LE GUIDE DU TRÉSORIER.pdf","note":"Le plan du guide annonce une « mission politique », mais le corps du texte parle de « mission de performance ».","qcm":{"ok":"Accompagnement, performance et technique","no":["Accompagnement, contrôle et animation","Collecte, dépense et archivage","Formation, représentation et technique"]}},{"id":"t10-03","q":"Avec qui le trésorier fixe-t-il le montant des participations financières des parents ?","a":"Avec le **responsable de groupe**, au vu du **budget et du plan d'action**.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Le responsable de groupe, au vu du budget et du plan d'action","no":["Le commissaire de district, selon un barème national","Les chefs d'unité, selon le coût de chaque camp","L'assemblée des parents, lors de la rentrée"]}},{"id":"t10-04","q":"Que désigne le guide par « extra-jobs » ?","a":"Une **activité additive visant à alimenter la caisse**. Le trésorier travaille avec les responsables sur le financement des projets d'unité et sur le **juste recours** aux extra-jobs.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Une activité additive visant à alimenter la caisse","no":["Un emploi rémunéré confié aux chefs d'unité","Une tâche bénévole hors du programme scout","Une subvention exceptionnelle de la région"]}},{"id":"t10-05","q":"Comment le trésorier doit-il savoir gérer un budget, et de quelle instance est-il membre ?","a":"Il doit savoir gérer et suivre un budget **« en bon père de famille »**. Il est **membre du Conseil de groupe** et y rend compte de son action.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"« En bon père de famille » ; membre du Conseil de groupe","no":["« Au centime près » ; membre du Conseil des chefs","« En entrepreneur audacieux » ; membre du conseil de district","« Avec rigueur militaire » ; membre de l'équipe régionale"]}},{"id":"t10-06","q":"Une patrouille dépense 2 000 F pour fabriquer des articles et les vend 5 000 F. Quel est le résultat ?","a":"Recettes 5 000 F − dépenses 2 000 F = **bénéfice de 3 000 F**. Si les dépenses avaient été de 6 000 F, on aurait eu une **perte de 1 000 F**.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Un bénéfice de 3 000 F","no":["Un bénéfice de 7 000 F","Une perte de 3 000 F","Un bénéfice de 2 000 F"]}},{"id":"t10-07","q":"Dans le vocabulaire du guide, les cotisations sont-elles un emploi ou une ressource ?","a":"Une **ressource** : un moyen permettant de réaliser une opération. L'**emploi** est la manière dont la ressource est utilisée ; toute dépense (emploi) s'accompagne obligatoirement d'un financement (ressource).","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Une ressource","no":["Un emploi","Une charge","Un solde"]}},{"id":"t10-08","q":"Quelles mentions minimales une pièce justificative doit-elle porter pour être recevable ?","a":"**La date, les noms et adresses des parties, le montant et l'objet.** Chaque recette ou dépense doit être justifiée : facture d'achat, reçu, décharge, ticket de banque…","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Date, noms et adresses des parties, montant, objet","no":["Date, signature du trésorier, montant, cachet","Numéro de pièce, montant, rubrique budgétaire","Nom de l'unité, montant, visa du chef de groupe"]}},{"id":"t10-09","q":"Quand le budget prévisionnel annuel est-il élaboré, et qui le valide ?","a":"**Au début de l'année**, chaque entité élabore son budget prévisionnel annuel, qui doit être **validé par son instance de décision**. Il couvre fonctionnement, investissements, aménagements et activités programmées.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"En début d'année ; validé par son instance de décision","no":["En fin d'année ; validé par le trésorier régional","Avant chaque camp ; validé par le chef d'unité","À mi-année ; validé par l'assemblée des parents"]}},{"id":"t10-10","q":"Quel rythme le guide recommande-t-il pour établir le budget, et pourquoi ?","a":"Un rythme **trimestriel**, pour connaître la situation à la fin de chaque trimestre et **éviter les tensions de trésorerie** (par exemple, prévoir une activité lucrative avant un mois de grosses dépenses).","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Trimestriel, pour anticiper les tensions de trésorerie","no":["Mensuel, pour suivre chaque dépense d'unité","Semestriel, pour coller au calendrier des camps","Annuel, pour simplifier la présentation au conseil"]}},{"id":"t10-11","q":"Que signifie un solde final égal à zéro dans le budget ?","a":"Une situation d'**équilibre**, mais **sans aucune réserve** pour financer un surplus de dépenses : il faudra **chercher des fonds**. (Solde > 0 : des fonds sont disponibles ; solde < 0 : il faut chercher des fonds.)","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Équilibre sans réserve : il faudra chercher des fonds","no":["Fonds disponibles pour des dépenses supplémentaires","Déficit à combler par un emprunt immédiat","Excédent à placer en dépôt à terme"]}},{"id":"t10-12","q":"Quand le concept de « trésorerie zéro » est-il apparu, et que suppose-t-il ?","a":"Au **début des années 1970**. Il suppose que les **excédents soient placés** pour en tirer des produits financiers et que les **insuffisances soient comblées au coût le plus faible**.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Début des années 1970 : placer les excédents, combler les manques au moindre coût","no":["Début des années 1950 : garder une réserve égale aux dépenses de l'année","Fin des années 1980 : dépenser tout l'argent disponible avant l'exercice suivant","Début des années 1990 : interdire tout emprunt et tout placement bancaire"]}},{"id":"t10-13","q":"À quoi sert le tableau des notes de frais ?","a":"À suivre, **article par article**, les dépenses faites par un chef à qui le trésorier a **remis de l'argent** pour des achats (courses de l'intendant, médicaments du secouriste…). Solde = montant reçu − total des dépenses.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Suivre les achats d'un chef ayant reçu de l'argent du trésorier","no":["Rembourser les frais personnels avancés par les parents","Récapituler les comptes de l'année devant le conseil","Prévoir les dépenses de chaque trimestre à venir"]}},{"id":"t10-14","q":"Quel lien existe entre le tableau des comptes et le tableau des recettes et dépenses ?","a":"Le **tableau des comptes** est un **récapitulatif aux montants cumulés** sur une période choisie par le conseil ; chacune de ses lignes doit être justifiée par le **tableau des recettes et dépenses** (tenu par ordre chronologique) et par les pièces justificatives. Le solde final d'une période devient le solde initial de la suivante.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Le tableau des comptes cumule ; le cahier recettes-dépenses détaille","no":["Le tableau des comptes détaille ; le cahier ne donne que des totaux","Ce sont deux noms différents pour un même document comptable","Le tableau des comptes remplace le cahier dès la fin de l'année"]}},{"id":"t10-15","q":"Que signifient les abréviations PCR et PCD ?","a":"**PCR** : pièce de caisse **recette** (approvisionnement de la caisse, signée par le trésorier et par le donneur). **PCD** : pièce de caisse **dépense** (sortie d'argent au bénéfice d'une personne ou d'une entité).","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Pièce de caisse recette ; pièce de caisse dépense","no":["Pièce de compte rendu ; pièce de contrôle des dépenses","Procès-verbal de caisse ; pièce de crédit différé","Pièce de caisse réglée ; pièce de caisse due"]}},{"id":"t10-16","q":"À quoi sert particulièrement une décharge ?","a":"Elle a la même utilité qu'une pièce de caisse, mais permet surtout de **décharger le trésorier de sa responsabilité** en montrant qu'il a **remis tel montant à telle personne**. Elle peut aussi prouver une somme reçue d'un tiers.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Prouver que le trésorier a remis une somme à quelqu'un","no":["Autoriser le trésorier à dépenser sans facture","Annuler une dépense déjà enregistrée au cahier","Transmettre la caisse au nouveau trésorier"]}},{"id":"t10-17","q":"Quel principe impose que toute dépense soit « vue » par deux personnes, et que faire si le chef d'unité est aussi trésorier ?","a":"Le principe de **séparation des tâches** : toute dépense doit être vue par **au moins deux personnes différentes**. Si le chef d'unité assure la fonction de trésorier, on adapte avec une **double signature** sur chaque justificatif ou pièce de caisse.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Séparation des tâches ; double signature des pièces","no":["Contrôle annuel ; visa du commissaire de district","Transparence ; affichage public des comptes","Délégation ; signature unique du chef de groupe"]}},{"id":"t10-18","q":"Quelles sont les quatre fonctions incompatibles à dissocier ?","a":"La **décision/autorisation** (le conseil), l'**ordonnancement** (chef de groupe, chef d'unité, commissaire…), l'**enregistrement / fonction financière** (souvent réunies chez le trésorier) et le **contrôle** (par le conseil). Une même personne ne doit pas commander, payer et enregistrer une opération.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Décision, ordonnancement, enregistrement/finance, contrôle","no":["Budget, achat, paiement, archivage des pièces","Collecte, dépense, vérification, rapport annuel","Décision, trésorerie, intendance, audit externe"]}},{"id":"t10-19","q":"Qui prend en général les décisions de décaissement pour le groupe ?","a":"Le **Chef de Groupe**, en se fiant au budget préétabli avec le conseil. Pour l'unité : le chef d'unité ; pour le district : le commissaire de district ; pour une branche régionale : le commissaire régional de branche. Le trésorier conseille mais n'est généralement pas celui qui décide.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Le Chef de groupe","no":["Le trésorier de groupe","Le commissaire de district","Le conseil des parents"]}},{"id":"t10-20","q":"Qu'est-ce qu'un dépôt à terme (DAT) et quels avantages le guide cite-t-il ?","a":"Une **somme bloquée en banque** pendant une période fixée au contrat (6 mois, 12 mois…) **contre des intérêts** ; un malus peut s'appliquer en cas de rupture avant l'échéance. Avantages : **placement sans risque, rémunération connue d'avance, taux négociable**.","src":"LE GUIDE DU TRÉSORIER.pdf","qcm":{"ok":"Somme bloquée en banque contre intérêts, sans risque","no":["Compte courant retirable à tout moment, sans frais","Prêt bancaire remboursable à la fin du camp","Épargne placée en bourse à rendement variable"]}},{"id":"t10-21","q":"Quel cordage le scout doit-il utiliser pour les nœuds et les brelages ?","a":"Un cordage de **10 à 20 mm** de diamètre, en **chanvre** (cher), **sisal** ou **polypropylène** (bon rapport qualité/prix). On évite la vulgaire ficelle (« bonne pour les louveteaux ») et le septain.","src":"Matelotage.pdf","qcm":{"ok":"10 à 20 mm, en chanvre, sisal ou polypropylène","no":["4 à 8 mm, en coton, nylon ou ficelle","20 à 30 mm, en acier, chanvre ou jute","5 à 10 mm, en septain, sisal ou raphia"]}},{"id":"t10-22","q":"Quelles cordes chaque patrouille doit-elle préparer pour les brelages ?","a":"Des cordes de **5 à 6 m**, débutant par un **œil épissé** et terminées par une **épissure** ; il en faut **une dizaine par patrouille/équipe**.","src":"Matelotage.pdf","qcm":{"ok":"Une dizaine de cordes de 5-6 m, œil épissé et épissure","no":["Cinq cordes de 10 m, terminées par un nœud simple","Une vingtaine de cordes de 2 m, sans finition","Trois cordes de 15 m, terminées par des surliures"]}},{"id":"t10-23","q":"Quel est le meilleur moyen de ranger une corde sans l'abîmer ?","a":"La **lover** (l'enrouler sur elle-même de façon régulière) **et la suspendre**, après avoir défait tous les nœuds sauf les épissures d'extrémité, à l'abri de l'humidité.","src":"Matelotage.pdf","qcm":{"ok":"La lover et la suspendre","no":["L'étaler en biture au sol","La raccourcir en jambe de chien","La plier et la sécher au soleil"]}},{"id":"t10-24","q":"Quelle différence entre le courant et le dormant ?","a":"Le **courant** est le bout par lequel on tient la corde pour la nouer ; le **dormant** est la partie inactive pendant qu'on travaille avec le courant.","src":"Matelotage.pdf","qcm":{"ok":"Courant : bout qui noue ; dormant : partie inactive","no":["Courant : partie inactive ; dormant : bout qui noue","Courant : ganse ouverte ; dormant : ganse fermée","Courant : corde mouillée ; dormant : corde sèche"]}},{"id":"t10-25","q":"Que signifient « étaler en biture » et « décommettre » ?","a":"**Étaler en biture** : ranger un cordage à plat et en zigzag. **Décommettre** : desserrer les torons d'un cordage (les torons sont ses éléments constitutifs).","src":"Matelotage.pdf","qcm":{"ok":"Ranger à plat en zigzag ; desserrer les torons","no":["Enrouler régulièrement ; serrer les torons","Hisser une voile ; couper le cordage","Entourer un objet ; épisser le bout"]}},{"id":"t10-26","q":"Combien de familles de nœuds retiennent les Scouts du Sénégal, et où rangent-ils les nœuds d'amarrage ?","a":"**Deux familles** : les **nœuds d'arrêt** et les **nœuds de jonction**. Les nœuds d'amarrage ne forment pas une famille à part : ils sont **rangés avec les nœuds d'arrêt**, alors que certains pays en font une famille distincte.","src":"Matelotage.pdf","note":"Le support de Benoît Maugis (Matelotage1_Niveau4_Maugis.pdf) traite les nœuds d'amarrage et d'ajut comme des familles distinctes ; Matelotage.pdf signale lui-même cette différence d'usage.","qcm":{"ok":"Deux : arrêt et jonction ; l'amarrage est rangé avec l'arrêt","no":["Trois : arrêt, jonction et amarrage, chacun à part","Deux : arrêt et amarrage ; la jonction va avec l'arrêt","Quatre : arrêt, jonction, amarrage et décoratifs"]}},{"id":"t10-27","q":"À quoi servent les nœuds d'arrêt ?","a":"À **arrêter l'effilochement** d'une corde, **marquer une longueur**, **caler une corde dans un trou** et **alourdir le bout** d'une corde.","src":"Matelotage.pdf","qcm":{"ok":"Arrêter l'effilochement, marquer une longueur, caler, alourdir","no":["Joindre deux cordes pour en augmenter la longueur","Assembler deux perches selon un angle voulu","Hisser une charge et tendre un hauban de tente"]}},{"id":"t10-28","q":"Parmi les 10 nœuds d'aspirant, lequel sert à délimiter un sous-camp ?","a":"Le **tour mort** (double passage d'un cordage autour de son point d'amarrage).","src":"Matelotage.pdf","qcm":{"ok":"Le tour mort","no":["Le nœud de chaise","Le nœud de ganse","Le nœud de tisserand"]}},{"id":"t10-29","q":"À quoi sert le nœud de chaise ?","a":"À **maintenir un objet ou un être vivant à un diamètre constant** ; il est très utilisé pour **porter secours** (monter ou descendre une personne).","src":"Matelotage.pdf, Section MATELOTAGE.docx","qcm":{"ok":"Maintenir à diamètre constant, notamment pour porter secours","no":["Joindre deux cordes de diamètres différents","Raccourcir une corde sans avoir à la couper","Alourdir le bout d'une corde avant de la lancer"]}},{"id":"t10-30","q":"Quel nœud d'aspirant sert à débuter (et éventuellement terminer) un brelage ?","a":"Le **nœud de cabestan (ou de batelier)** : il attache un cordage sous **tension constante** à un point fixe (anneau, poutre, mât) et sert à **débuter un brelage**.","src":"Matelotage.pdf, Section MATELOTAGE.docx","note":"Dans le tableau de classification de Matelotage.pdf, il est nommé « cabestan ou d'écoute », alors que « nœud d'écoute » désigne ailleurs le nœud de tisserand.","qcm":{"ok":"Le nœud de cabestan (ou de batelier)","no":["Le nœud de tisserand (ou d'écoute)","Le nœud de pêcheur (ou joint anglais)","Le nœud de vache (ou plat inversé)"]}},{"id":"t10-31","q":"Quels sont les deux usages du nœud plat (ou droit) ?","a":"**Attacher deux cordes de même diamètre** et **attacher les bandages en secourisme**. Il n'est pas efficace pour les gros câbles : préférer alors le carrick.","src":"Matelotage.pdf, Section MATELOTAGE.docx","qcm":{"ok":"Joindre deux cordes de même diamètre ; nouer les bandages","no":["Joindre deux cordes de diamètres différents ; faire un filet","Raccourcir une corde ; soulager une partie usée","Hisser un rondin ; tendre la corde d'une tente"]}},{"id":"t10-32","q":"Quel nœud utiliser pour joindre deux cordes de diamètres différents, et comment le faire ?","a":"Le **nœud de tisserand (ou d'écoute)**. On fait une **ganse avec la plus grosse corde** ; c'est la **petite corde qui fait le nœud** et qui se coince sous la traction.","src":"Matelotage.pdf, Section MATELOTAGE.docx","qcm":{"ok":"Le tisserand : ganse avec la grosse corde, nœud avec la petite","no":["Le tisserand : ganse avec la petite corde, nœud avec la grosse","Le pêcheur : un nœud simple fait sur chacune des cordes","Le plat : deux nœuds simples faits en sens inverse"]}},{"id":"t10-33","q":"Comment le nœud de pêcheur est-il formé, et quel est son avantage ?","a":"Par **deux nœuds simples**, chacun fait avec une extrémité autour de l'autre corde, et qui doivent **s'emboîter**. Il joint deux cordes de **même diamètre** et est **plus solide que le nœud plat** (fortes tractions, cordes mouillées).","src":"Section MATELOTAGE.docx, Matelotage.pdf","qcm":{"ok":"Deux nœuds simples emboîtés ; plus solide que le nœud plat","no":["Deux demi-clés croisées ; plus rapide que le nœud plat","Une ganse et un tour ; plus facile à défaire que le plat","Trois tours morts ; plus décoratif que le carrick"]}},{"id":"t10-34","q":"Qu'est-ce que le nœud de vache ?","a":"C'est un **nœud plat fait à l'envers** : les deux nœuds simples sont faits **dans le même sens** (droite sur gauche, puis encore droite sur gauche). Il ne tient pas à la traction et fait une boule.","src":"Section MATELOTAGE.docx, Matelotage.pdf","note":"Matelotage.pdf lui attribue l'utilité « joindre 2 cordes de même épaisseur », alors que Section MATELOTAGE.docx affirme qu'il « n'est d'aucune utilité ».","qcm":{"ok":"Un nœud plat dont les deux nœuds simples vont dans le même sens","no":["Un nœud de pêcheur dont l'un des nœuds simples est inversé","Un nœud de chaise refait autour d'un poteau ou d'un arbre","Un tour mort terminé par deux demi-clés serrées au poteau"]}},{"id":"t10-35","q":"Quel nœud permet de joindre deux gros câbles ?","a":"Le **nœud de carrick** : il joint 2 câbles (fortes cordes de gros diamètre) et sert aussi d'ornement. Sans **ligatures** aux extrémités, il se retourne et fait une boule.","src":"Matelotage.pdf, Section MATELOTAGE.docx","qcm":{"ok":"Le nœud de carrick","no":["Le nœud plat","Le nœud de vache","Le nœud de capucin"]}},{"id":"t10-36","q":"À quoi sert la jambe de chien ?","a":"À **raccourcir une corde sans la couper** et à **mettre hors tension une partie usée ou abîmée**. La corde doit rester un minimum tendue, sinon le nœud ne tient pas.","src":"Matelotage.pdf, Section MATELOTAGE.docx","qcm":{"ok":"Raccourcir une corde et soulager une partie usée","no":["Joindre deux câbles de gros diamètre","Alourdir l'extrémité d'une corde à lancer","Fabriquer une bague de foulard"]}},{"id":"t10-37","q":"Pour écrire un message en morse sur une corde, que représentent le nœud simple et le nœud de capucin ?","a":"Le **nœud simple** représente les **points (dih)** et le **nœud de capucin** les **barres (dah)** du morse.","src":"Section MATELOTAGE.docx","qcm":{"ok":"Nœud simple = point ; nœud de capucin = trait","no":["Nœud simple = trait ; nœud de capucin = point","Nœud simple = espace ; nœud de capucin = fin de mot","Nœud en huit = point ; nœud de carrick = trait"]}},{"id":"t10-38","q":"Quel brelage sert à former un trépied, et lequel assemble deux perches perpendiculaires ?","a":"Le brelage **en tête de bigue** forme un **trépied** ; le brelage **carré** assemble **2 perches perpendiculaires**. Diagonal : angle quelconque ; triple : 3 perches ; en long : perches parallèles ; ligature auto-serrante : support en V inversé pour un toit d'abri.","src":"Matelotage.pdf","qcm":{"ok":"Tête de bigue pour le trépied ; carré pour l'angle droit","no":["Triple pour le trépied ; diagonal pour l'angle droit","En long pour le trépied ; en étoile pour l'angle droit","Carré pour le trépied ; tête de bigue pour l'angle droit"]}},{"id":"t10-39","q":"D'où vient le mot « topographie », et en quels ensembles les scouts la répartissent-ils ?","a":"Du grec **topos** (lieu) et **graphien** (dessiner) : science de la mesure puis de la représentation, sur un plan ou une carte, des formes et détails du terrain. Chez les scouts, elle se répartit en **signalisation** et **orientation**.","src":"Topographie.pdf","qcm":{"ok":"Topos (lieu) et graphien (dessiner) ; signalisation et orientation","no":["Topos (relief) et graphien (mesurer) ; cartographie et secourisme","Tropos (direction) et graphien (écrire) ; morse et sémaphore","Topos (carte) et metron (mesure) ; astronomie et exploration"]}},{"id":"t10-40","q":"Quels sont les deux grands types de pistes ?","a":"Les pistes **directives** (tracées pour qu'un groupe arrive à une destination donnée) et les pistes **indicatives** (tracées pour montrer le chemin parcouru par le groupe traceur).","src":"Topographie.pdf","qcm":{"ok":"Directives et indicatives","no":["Directes et détournées","Ouvertes et fermées","Diurnes et nocturnes"]}},{"id":"t10-41","q":"Quelles règles de taille et d'emplacement s'appliquent aux signes de piste ?","a":"Signes **discrets, de 10 à 15 cm maximum**, placés **à gauche du chemin** (et non sur le chemin) et **pas plus haut qu'un mètre**. Les signes importants (début de piste, messages) sont plus visibles.","src":"Topographie.pdf","qcm":{"ok":"10 à 15 cm, à gauche du chemin, à moins d'un mètre de haut","no":["20 à 30 cm, à droite du chemin, à hauteur des yeux","5 cm au plus, au milieu du chemin, au ras du sol","30 à 50 cm, à droite du chemin, sur les troncs"]}},{"id":"t10-42","q":"En suivant une piste, qui efface les signes et quelle distance garder dans la patrouille ?","a":"Les signes sont **détruits ou effacés par le dernier pisteur** ; entre le premier et le dernier pisteur, on garde une distance égale à **trois signes**. En cas de perte de la piste, revenir au dernier signe.","src":"Topographie.pdf","qcm":{"ok":"Le dernier pisteur ; une distance de trois signes","no":["Le premier pisteur ; une distance de cinq signes","Le chef de patrouille ; une distance de deux signes","Le traceur de la piste ; une distance d'un signe"]}},{"id":"t10-43","q":"Quand sont nés et morts Samuel Morse ?","a":"Né le **27 avril 1791** en Nouvelle-Angleterre (États-Unis), mort à **New York le 2 avril 1872**. Il fut d'abord **peintre portraitiste**, puis professeur de peinture et de sculpture.","src":"Topographie.pdf, Samuel Finley Breese Morse.docx","qcm":{"ok":"Né le 27 avril 1791, mort le 2 avril 1872","no":["Né le 24 mai 1791, mort le 2 avril 1844","Né le 27 avril 1801, mort le 2 avril 1882","Né le 2 avril 1791, mort le 27 avril 1872"]}},{"id":"t10-44","q":"Quel fut le premier message télégraphique de Morse, et quand ?","a":"Le **24 mai 1844**, sur la ligne **Washington – Baltimore** (financée par le Congrès en 1843), envoyé à son assistant **Alfred Vail** : « What Hath God Wrought », un verset de la Bible.","src":"Topographie.pdf, Samuel Finley Breese Morse.docx","note":"SESSION SIGNALISATION ORIENTATION-1.pdf dit le code « inventé en 1832 » ; Topographie.pdf situe en 1832 la rencontre avec Charles Thomas Jackson, en 1836 l'appareil achevé et en 1844 la première transmission.","qcm":{"ok":"Le 24 mai 1844, de Washington à Baltimore","no":["Le 27 avril 1832, de New York à Boston","Le 24 mai 1836, de Washington à New York","Le 2 avril 1843, de Baltimore à Philadelphie"]}},{"id":"t10-45","q":"Selon la règle générale du morse, combien de temps comptent un ti, un ta, l'espace entre deux lettres et l'espace entre deux mots ?","a":"Ti = **1 temps** ; ta = **3** ; espace entre deux lettres = **3** ; espace entre deux mots = **7**.","src":"Méthodes Apprentissage du Morse.docx","qcm":{"ok":"1, 3, 3 et 7 temps","no":["1, 2, 3 et 5 temps","1, 3, 5 et 7 temps","1, 2, 2 et 4 temps"]}},{"id":"t10-46","q":"En quoi consiste la méthode Koch d'apprentissage du morse ?","a":"Commencer par **2 caractères** (n'importe lesquels), puis **ajouter un caractère** chaque fois que les précédents sont assimilés. (La méthode Farnsworth, elle, mémorise la sonorité globale de chaque lettre, avec un espacement d'abord long puis réduit.)","src":"Méthodes Apprentissage du Morse.docx","qcm":{"ok":"Apprendre 2 caractères, puis en ajouter un à chaque fois","no":["Mémoriser la sonorité globale de chaque lettre","Associer chaque lettre à un mot qui commence par elle","Apprendre les lettres par paires de signaux opposés"]}},{"id":"t10-47","q":"En morse, que signifient les procédures VE, AR et SK ?","a":"**VE** : bien reçu, message compris. **AR** : fin de message, j'attends une réponse. **SK** : fin de transmission, je n'attends pas de réponse.","src":"Topographie.pdf, Méthodes Apprentissage du Morse.docx","qcm":{"ok":"Bien reçu ; fin de message ; fin de transmission","no":["Attendez ; erreur ; début de transmission","Répétez ; transmettez ; fin de message","Début de transmission ; attendez ; bien reçu"]}},{"id":"t10-48","q":"Avec quel code secret « JAEMABNZ » se lit-il « JEAN » ?","a":"La **clef de deux** : on supprime une lettre sur deux (la deuxième). Autre code du même document : la **lettre décalée** (MFPQPME = LEOPOLD), où l'on prend la lettre qui précède.","src":"Topographie.pdf","qcm":{"ok":"La clef de deux","no":["La lettre décalée","Le nombre clef","Les lettres en cage"]}},{"id":"t10-49","q":"Quels sont les trois nords, et vers lequel pointe l'aiguille de la boussole ?","a":"Le nord **magnétique**, le nord **géographique** (le pôle Nord, où aboutissent les méridiens) et le nord **cartésien** (du quadrillage de la carte). L'aiguille pointe vers le **nord magnétique**. L'angle qui les sépare s'appelle la **déclinaison**.","src":"Topographie.pdf, Les trois nords.docx","qcm":{"ok":"Magnétique, géographique, cartésien ; l'aiguille vise le magnétique","no":["Magnétique, géographique, cartésien ; l'aiguille vise le géographique","Magnétique, polaire, céleste ; l'aiguille vise le polaire","Géographique, céleste, cartésien ; l'aiguille vise le cartésien"]}},{"id":"t10-50","q":"Où les documents situent-ils le nord magnétique ?","a":"Près du pôle Nord, dans les **îles de la Reine Elizabeth (Territoires du Nord-Ouest, Canada)**. Sa position **varie légèrement d'année en année**.","src":"Topographie.pdf, Les trois nords.docx","note":"Le document pdfcoffee.com_orientation-et-topographie le situe à environ 1 250 km du pôle Nord géographique et parle d'un déplacement d'environ 10 km par an.","qcm":{"ok":"Dans les îles de la Reine Elizabeth, au Canada","no":["Exactement au pôle Nord géographique","En Sibérie, près du cercle polaire","Au Groenland, près de la côte est"]}},{"id":"t10-51","q":"Vers quelles dates la boussole à aiguille aimantée fut-elle utilisée par les navigateurs chinois, les marchands arabes et les Vikings ?","a":"**Vers 1100** (navigateurs chinois), **vers 1220** (marchands arabes) et **vers 1250** (Vikings). Le principe avait été découvert par les Chinois plus de 1000 ans av. J.-C. Les militaires utilisent une graduation de **6 400 millièmes**.","src":"Topographie.pdf, La boussole.docx","qcm":{"ok":"Vers 1100, 1220 et 1250","no":["Vers 1000, 1100 et 1200","Vers 1220, 1250 et 1300","Vers 1100, 1350 et 1492"]}},{"id":"t10-52","q":"Sur quel élément de la boussole doit-on juxtaposer l'aiguille aimantée pour obtenir l'azimut désiré ?","a":"Sur la **flèche incrustée**. Les six parties de la boussole : tablier, habitacle rotatif (cadran), point indice, aiguille aimantée, flèche incrustée, flèche de direction.","src":"Topographie.pdf, La boussole.docx","qcm":{"ok":"La flèche incrustée","no":["Le point indice","La flèche de direction","Le tablier"]}},{"id":"t10-53","q":"Quel est le contre-azimut (azimut de retour) de 125° ? Et de 315° ?","a":"On **ajoute 180°** si l'azimut ne dépasse pas 180°, sinon on **retranche 180°** : 125° → **305°** ; 315° → **135°**.","src":"La boussole.docx, Section ORIENTATION.docx","qcm":{"ok":"305° et 135°","no":["235° et 45°","55° et 225°","305° et 225°"]}},{"id":"t10-54","q":"Comment orienter une carte avec une boussole ?","a":"Mettre le **Nord du cadran devant le repère**, poser la boussole sur la carte en **alignant leurs bords**, puis **tourner l'ensemble carte-boussole** jusqu'à ce que le Nord de l'aiguille arrive sur le Nord du cadran.","src":"Topographie.pdf","qcm":{"ok":"Nord du cadran au repère, bords alignés, tourner l'ensemble","no":["Tourner la boussole seule jusqu'à viser le haut","Mettre l'aiguille sur le Sud puis retourner la carte","Aligner la carte sur le soleil puis lire l'azimut"]}},{"id":"t10-55","q":"Combien de directions compte la rose des vents d'usage courant, et à combien de degrés correspond l'Ouest-Nord-Ouest ?","a":"**16 directions**. L'Ouest-Nord-Ouest est à **292,5°** (repères : Nord 0°, Est 90°, Sud 180°, Ouest 270°, Nord-Ouest 315°).","src":"Topographie.pdf, La rose des vents.docx","qcm":{"ok":"16 directions ; ONO = 292,5°","no":["16 directions ; ONO = 247,5°","32 directions ; ONO = 315°","8 directions ; ONO = 337,5°"]}},{"id":"t10-56","q":"Qu'est-ce qu'un millième, et combien en compte un tour complet ?","a":"L'angle sous lequel on voit un **objet de 1 m à 1 km**. Il permet d'estimer vite distances et dimensions : un objet de 2 m vu sous 2 millièmes est à 1 km. Un tour = **6 400 millièmes** (= 360° = 400 grades).","src":"Topographie.pdf, La rose des vents.docx","qcm":{"ok":"L'angle d'un objet de 1 m vu à 1 km ; 6 400 par tour","no":["L'angle d'un objet de 1 m vu à 100 m ; 4 000 par tour","La millième partie d'un degré ; 360 000 par tour","L'angle d'un objet de 10 m vu à 1 km ; 400 par tour"]}},{"id":"t10-57","q":"Comment trouver l'étoile polaire à partir de la Grande Ourse ?","a":"Repérer les **deux étoiles du bout de la « casserole »** (côté opposé au manche) et **reporter 5 fois** leur écart vers le haut. L'étoile polaire n'est **pas la plus brillante** du ciel ; elle est située à 431 années-lumière.","src":"Topographie.pdf, Section ORIENTATION.docx","qcm":{"ok":"Reporter 5 fois l'écart des deux étoiles du bout de la casserole","no":["Reporter 3 fois l'écart des deux étoiles du manche","Chercher l'étoile la plus brillante du ciel nocturne","Reporter 7 fois l'écart des deux étoiles de Cassiopée"]}},{"id":"t10-58","q":"Comment s'orienter avec un croissant de lune ?","a":"Par la **méthode du croissant** : tracer mentalement la ligne qui relie les **cornes du croissant** et la prolonger jusqu'à l'horizon : elle indique **approximativement le Sud**.","src":"SESSION SIGNALISATION ORIENTATION-1.pdf","note":"Ce document dit qu'on ne peut pas s'orienter avec la pleine lune ; Section ORIENTATION.docx applique à la Lune la méthode de la montre et n'exclut que la nouvelle lune.","qcm":{"ok":"Prolonger la ligne des cornes jusqu'à l'horizon : le Sud","no":["Prolonger la ligne des cornes jusqu'à l'horizon : le Nord","Suivre le côté éclairé du croissant : l'Est","Viser le centre du croissant à minuit : l'Ouest"]}},{"id":"t10-59","q":"Avec une boussole, quelle heure est-il environ si l'azimut du soleil est de 227° ?","a":"Le soleil se déplace de **15° par heure** et se trouve à **180° à midi**. 227 − 180 = 47 ; 47 ÷ 15 ≈ 3 ; l'azimut dépasse 180°, donc on ajoute : **environ 15 h** (heure solaire).","src":"Section ORIENTATION.docx","qcm":{"ok":"Environ 15 h","no":["Environ 9 h","Environ 13 h","Environ 17 h"]}},{"id":"t10-60","q":"Comment trouver le Sud avec une montre à aiguilles ?","a":"Montre à plat, **petite aiguille pointée vers le soleil** ; on prend la **bissectrice** de l'angle entre la petite aiguille et le **12** : elle donne le **Sud** (le Nord à l'opposé, entre 6 h et 18 h). Il faut être à l'heure solaire.","src":"Topographie.pdf, Section ORIENTATION.docx","note":"Topographie.pdf estime l'heure solaire à environ deux heures de moins que l'heure de la montre ; Section ORIENTATION.docx ne donne que des repères pour le Québec et la France.","qcm":{"ok":"Bissectrice entre la petite aiguille et le 12","no":["Bissectrice entre la grande aiguille et le 6","Direction de la grande aiguille à midi pile","Bissectrice entre la petite aiguille et le 6"]}}]}$xxb$::jsonb, now()),
  ('cards-11', $xxb${"theme":11,"cards":[{"id":"t11-01","q":"Qui est le saint patron des éclaireurs, et à quelle date le fête-t-on ?","a":"**Saint Georges**, fêté le **23 avril**.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Saint Georges, le 23 avril","no":["Saint Paul, le 29 juin","Saint François, le 4 octobre","Saint Georges, le 22 février"]}},{"id":"t11-02","q":"Que rappellent les années 1907, 1908 et 1909 dans l'histoire du scoutisme ?","a":"**1907** : 1er camp scout à l'île de Brownsea. **1908** : publication de *Scouting for Boys*. **1909** : 1er rallye à Crystal Palace.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Brownsea, Scouting for Boys, rallye de Crystal Palace","no":["Scouting for Boys, Brownsea, rallye de Crystal Palace","Brownsea, louvetisme, Scouting for Boys","Rallye de Crystal Palace, Brownsea, création de la route"]}},{"id":"t11-03","q":"Que rappellent les années 1914, 1916, 1918 et 1922 ?","a":"**1914** : création du louvetisme. **1916** : publication du *Livre du louveteau*. **1918** : création de la route. **1922** : publication de *La route du succès*.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Louvetisme, Livre du louveteau, route, La route du succès","no":["Route, Livre du louveteau, louvetisme, La route du succès","Louvetisme, La route du succès, route, Livre du louveteau","Livre du louveteau, louvetisme, La route du succès, route"]}},{"id":"t11-04","q":"Quelle est la plus haute distinction du scoutisme, et qui est le premier Sénégalais à l'avoir reçue ?","a":"Le **Loup de bronze** ; le premier Sénégalais à l'avoir reçu est **Albert Ndiaye**.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Le Loup de bronze, reçu par Albert Ndiaye","no":["Le Loup d'argent, reçu par Albert Ndiaye","Le Loup de bronze, reçu par Léonard Pierre Sambou","La Croix de Saint Georges, reçue par Albert Ndiaye"]}},{"id":"t11-05","q":"Qui a inventé le morse, et en quelle année ?","a":"**Samuel Finlay Breese Morse**, en **1832**.","src":"Connaissance du mvt rallye dak23.pdf","qcm":{"ok":"Samuel Morse, en 1832","no":["Samuel Morse, en 1907","Robert Stephenson, en 1832","Samuel Morse, en 1857"]}},{"id":"t11-06","q":"Quelles sont les parties du carnet de preuves ?","a":"Le carnet de preuves est le manuel-guide de l'éclaireur qui lui permet de progresser. Il a **4 parties** : **volontaire, engagé, technicien et animateur**.","src":"Connaissance du mvt rallye dak23.pdf, Questions Réponses Rallye 2017.pdf","note":"Le corrigé 2017 annonce aussi 4 parties mais n'en cite que trois (Engagé, Techniciens, Animateurs) ; le corrigé DAK23 ajoute la partie volontaire.","qcm":{"ok":"Volontaire, engagé, technicien, animateur","no":["Aspirant, engagé, technicien, animateur","Volontaire, novice, technicien, animateur","Volontaire, engagé, animateur, routier"]}},{"id":"t11-07","q":"Selon le corrigé du Rallye DAK23, qui étaient le commissaire national à la branche verte, le commissaire de région et le Général ?","a":"CNBV : **Maurice Prospère Diatta** ; commissaire de région : **Rémi Niakh** ; Général : **Antoine Ghislain Kaly** (réponses valables en 2023).","src":"Connaissance du mvt rallye dak23.pdf","note":"Ces noms changent avec les mandats : en 2017, le corrigé donnait Serge Daniel Badji (Général) et Dimitri Coly (CNBV). Vérifier les titulaires actuels.","qcm":{"ok":"Maurice P. Diatta, Rémi Niakh, Antoine G. Kaly","no":["Dimitri Coly, Michel A. Ndour, Serge D. Badji","Maurice P. Diatta, Patrice Ndour, Serge D. Badji","Rémi Niakh, Maurice P. Diatta, Joseph F. Preira"]}},{"id":"t11-08","q":"Combien de districts compte la région scoute de Dakar, et lesquels ?","a":"**5 districts** : **Plateau, Grand Dakar I, Grand Dakar II, Niayes, Magola**.","src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"5 : Plateau, Grand Dakar I et II, Niayes, Magola","no":["4 : Plateau, Grand Dakar, Niayes, Magola","6 : Plateau, Grand Dakar I et II, Niayes, Magola, Pikine","5 : Plateau, Grand Dakar, Niayes, Magola, Rufisque"]}},{"id":"t11-09","q":"Combien de régions scoutes le corrigé 2017 compte-t-il au Sénégal ?","a":"**6 régions** : **Dakar, Fleuve, Petite Côte, Ziguinchor, Thiès, Kaolack**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"6 : Dakar, Fleuve, Petite Côte, Ziguinchor, Thiès, Kaolack","no":["14, une par région administrative","5 : Dakar, Fleuve, Ziguinchor, Thiès, Kaolack","6 : Dakar, Fleuve, Petite Côte, Ziguinchor, Thiès, Louga"]}},{"id":"t11-10","q":"Combien de pays sont membres de l'OMMS selon le corrigé 2022, et quand célèbre-t-on le scoutisme africain ?","a":"**172 pays** ; le scoutisme africain est célébré le **13 mars**.","src":"Questions Réponses Rallye 2022.pdf","qcm":{"ok":"172 pays ; le 13 mars","no":["193 pays ; le 13 mars","172 pays ; le 22 février","150 pays ; le 23 avril"]}},{"id":"t11-11","q":"Combien d'éléments compte la méthode scoute depuis la 41e Conférence mondiale (2017, Azerbaïdjan) ?","a":"**8 éléments** : la loi et la promesse, la progression personnelle, l'éducation par l'action, la relation adultes-jeunes, le cadre symbolique, le contact avec la nature, la vie en petit groupe (système des équipes), l'engagement communautaire (impact social).","src":"Questions Réponses Rallye 2022.pdf","qcm":{"ok":"8 éléments","no":["7 éléments","5 éléments","10 éléments"]}},{"id":"t11-12","q":"Quel nouvel élément de la méthode scoute, ajouté en 2017, est aussi appelé « impact social » ?","a":"L'**engagement communautaire** (ou impact social).","src":"Questions Réponses Rallye 2022.pdf","qcm":{"ok":"L'engagement communautaire","no":["La relation adultes-jeunes","Le cadre symbolique","L'éducation par l'action"]}},{"id":"t11-13","q":"Quels sont les principes fondamentaux du scoutisme ?","a":"**Devoir envers Dieu**, **devoir envers autrui**, **devoir envers soi-même**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Devoir envers Dieu, envers autrui, envers soi-même","no":["Devoir envers Dieu, envers la patrie, envers la nature","Devoir envers soi-même, envers la patrouille, envers le chef","Devoir envers la famille, envers autrui, envers la patrie"]}},{"id":"t11-14","q":"Quelle est l'origine de la devise « Toujours prêt » et son double sens ?","a":"Elle vient de l'anglais **Be Prepared**. Double sens : **prêt pour ce qui est de l'esprit**, **prêt pour ce qui est du corps**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Be Prepared ; prêt d'esprit et prêt de corps","no":["Do your best ; prêt d'esprit et prêt de corps","Be Prepared ; prêt à servir et prêt à obéir","Look wide ; prêt de cœur et prêt de corps"]}},{"id":"t11-15","q":"Comment se déroule le cérémonial de la montée des couleurs (corrigé 2017) ?","a":"« **Attention pour les couleurs** » puis « **Paré pour les couleurs** » ; « **Envoyez – Scouts saluez** » suivi de coups de sifflet saccadés ; **hymne national** ; « **Pour le Sénégal** » – « **Que Dieu nous garde** ».","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Attention, Paré, Envoyez-saluez, hymne, Pour le Sénégal","no":["Paré, Attention, hymne, Envoyez-saluez, Pour le Sénégal","Attention, Envoyez-saluez, prière, Paré, Toujours prêt","Rassemblement, hymne, Paré, Envoyez-saluez, Toujours prêt"]}},{"id":"t11-16","q":"Selon une annale de 2018, que célèbre-t-on à la Pensée scoute, et en quelle année le scoutisme est-il créé ?","a":"La Pensée scoute célèbre la **naissance de B-P** (né le **22 février 1857**). Le scoutisme est créé en **1907** ; en 2018 il avait **111 ans** dans le monde et **90 ans** au Sénégal.","src":"Questions-Reponses Rallye National Branche Verte Kaolack 2018.pdf","qcm":{"ok":"La naissance de B-P ; scoutisme créé en 1907","no":["La mort de B-P ; scoutisme créé en 1907","La naissance de B-P ; scoutisme créé en 1908","Le camp de Brownsea ; scoutisme créé en 1909"]}},{"id":"t11-17","q":"Qu'est-ce que la Cour d'honneur, et quel est son rôle ?","a":"C'est l'**organe directeur de la troupe**, qui en assure la viabilité et le succès. Elle prend les décisions qui orientent la troupe : **objectifs de l'année, admission à la promesse, sanction des progressions**. C'est elle que le chef de troupe convoque pour finaliser le programme annuel.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"L'organe directeur de la troupe","no":["La réunion des seuls chefs de la maîtrise","Le conseil des parents de la troupe","La réunion hebdomadaire de patrouille"]}},{"id":"t11-18","q":"Qu'est-ce que le fanion et quelles sont ses dimensions ?","a":"L'**emblème de la patrouille** : il est pour la patrouille ce que l'étendard est pour la troupe. Dimensions : **longueur 40 cm, hauteur 25 cm, tresse 2 cm**, hampe 140.","src":"Questions Réponses Rallye 2017.pdf","note":"Le corrigé donne « Hampe : 140 » sans unité.","qcm":{"ok":"Emblème de la pat ; 40 cm sur 25 cm","no":["Emblème de la troupe ; 40 cm sur 25 cm","Emblème de la pat ; 60 cm sur 40 cm","Emblème de la pat ; 25 cm sur 15 cm"]}},{"id":"t11-19","q":"Citez quatre symboles de la branche verte (corrigé 2017).","a":"**Étendard, rassemblement, fanion, manoir**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Étendard, rassemblement, fanion, manoir","no":["Totem, rocher du conseil, fanion, tanière","Étendard, flamme, fanion, clan","Étendard, rassemblement, totem, kraal"]}},{"id":"t11-20","q":"Que contient le livre d'or de la patrouille ?","a":"Le dessin ou la photo de l'**animal totem**, l'historique du **saint patron**, la **prière et l'hymne**, la **loi, la devise, le cri**, les règlements, le **langage secret**, la **liste des membres** avec filiation et adresse.","src":"CP RALLYE DAK23.pdf, Questions Réponses Rallye 2023.pdf, Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Totem, saint patron, prière, loi, membres","no":["Comptes rendus de réunions et de camps","Programme annuel et budget de la troupe","Fiches techniques des activités de la pat"]}},{"id":"t11-21","q":"Que contient le cahier de bord de la patrouille ?","a":"Les **comptes rendus** des conseils de pat, camps, week-ends, excursions et sorties, et les faits divers de la patrouille : c'est la **mémoire de la pat**.","src":"CP RALLYE DAK23.pdf, Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Les comptes rendus de la vie de la pat","no":["La liste des membres et leurs adresses","L'historique du saint patron et le totem","La loi, la devise et le cri de la pat"]}},{"id":"t11-22","q":"Combien de phases comprend la promesse scoute, et lesquelles ?","a":"**4 phases** : 1) la **décision du jeune** ; 2) la **décision du groupe**, qui prend effet lors de la cour d'honneur ; 3) la **veillée de promesse** ; 4) l'**engagement**.","src":"CP RALLYE DAK23.pdf","qcm":{"ok":"4 : décision du jeune, du groupe, veillée, engagement","no":["3 : décision du jeune, veillée, engagement","4 : demande écrite, veillée, engagement, fête","5 : décision du jeune, du CP, du groupe, veillée, engagement"]}},{"id":"t11-23","q":"Quelles sont les étapes de nomination du CP ?","a":"**Choix du CP par les jeunes** ; lettre manuscrite de demande d'investiture au CT (facultative) ; **cour d'honneur** ; **cérémonie d'investiture**.","src":"CP RALLYE DAK23.pdf","qcm":{"ok":"Choix des jeunes, lettre, cour d'honneur, investiture","no":["Désignation par le CT, cour d'honneur, investiture","Choix des jeunes, conseil des chefs, promesse","Élection en conseil de pat, lettre au CG, investiture"]}},{"id":"t11-24","q":"Dans quelle circonstance le fanion de patrouille est-il planté à terre ?","a":"Lors de l'**investiture du CP**.","src":"CP RALLYE DAK23.pdf","qcm":{"ok":"Lors de l'investiture du CP","no":["Lors de la montée des couleurs","Lors de la veillée de promesse","Lors de l'allumage du kraal"]}},{"id":"t11-25","q":"Quelles sont les étapes d'un camp, et quels points comporte sa fiche technique ?","a":"Étapes : **préparation, vécu du camp, évaluation**. Fiche technique : intitulé, période, objectif, cible, lieu, modalités de participation, contenu pédagogique, horaires, staff, chronogramme.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Préparation, vécu du camp, évaluation","no":["Installation, vécu du camp, rangement","Préparation, installation, veillée","Inscription, vécu du camp, compte rendu"]}},{"id":"t11-26","q":"Quel chant entonne-t-on à l'allumage et à l'extinction du kraal, et que signifie-t-il ?","a":"Le chœur d'**Engonyama** (Ingonyama). Traduction : « **Il est un lion ; oui, il est mieux que ça ; il est un hippopotame** ».","src":"Questions Réponses Rallye 2023.pdf","qcm":{"ok":"Engonyama : « Il est un lion… un hippopotame »","no":["Le chant des adieux : « Faut-il nous quitter… »","La légende du feu : « Il est un lion… un éléphant »","Engonyama : « Il est un aigle… un éléphant »"]}},{"id":"t11-27","q":"Qu'est-ce que la déclinaison ?","a":"Le **décalage entre le Nord magnétique et le Nord géographique**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Écart entre Nord magnétique et Nord géographique","no":["Écart entre Nord géographique et Nord de la carte","Angle entre le Nord et la direction à suivre","Écart entre l'étoile polaire et le Nord magnétique"]}},{"id":"t11-28","q":"Comment trouver le nord avec une montre à aiguilles ?","a":"Poser la montre à plat, placer une brindille à côté, **faire coïncider l'ombre de la brindille avec l'aiguille des heures** : le nord est indiqué par la **bissectrice de l'angle** formé par l'axe 12h-6h et l'aiguille des heures.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Ombre sur l'aiguille des heures, puis bissectrice avec 12h","no":["Aiguille des minutes vers le soleil, puis bissectrice avec 6h","Ombre sur l'aiguille des minutes, le nord est à 12h","Aiguille des heures vers la lune, le nord est à 3h"]}},{"id":"t11-29","q":"Comment s'oriente-t-on avec la grande ourse, la petite ourse, Cassiopée et la croix du sud ?","a":"**Grande ourse** : sa queue indique le nord. **Petite ourse** : sa tête est dirigée vers le nord. **Cassiopée** : elle se trouve au nord. **Croix du sud** : sa pointe du bas indique le sud.","src":"Questions Réponses Rallye 2023.pdf, TOPO RALLYE DAK23.pdf","qcm":{"ok":"Croix du sud : la pointe du bas indique le sud","no":["Croix du sud : la pointe du haut indique le nord","Cassiopée : elle se trouve au sud","Grande ourse : sa tête indique le sud"]}},{"id":"t11-30","q":"Peut-on s'orienter avec la pleine lune ? Comment utilise-t-on la lune ?","a":"**Non**. On ne s'oriente avec la lune que lorsqu'elle est en **croissant**. On trace une ligne imaginaire passant par les deux extrémités du croissant : les **bonnes lettres B et Q** indiquent le nord dans le sens du tracé ; avec les **mauvaises lettres P et D**, le nord est dans le sens opposé.","src":"TOPO RALLYE DAK23.pdf, Questions Réponses Rallye 2023.pdf","qcm":{"ok":"Non : seulement en croissant (lettres B, Q bonnes)","no":["Oui : la pleine lune se lève toujours au nord","Non : seulement en croissant (lettres P, D bonnes)","Oui : la face éclairée indique le sud"]}},{"id":"t11-31","q":"Comment oriente-t-on une carte avec une boussole ?","a":"Mettre le **Nord du cadran devant le repère** de la boussole ; poser la boussole sur la carte en **alignant son bord avec celui de la carte** ; **tourner l'ensemble** carte-boussole jusqu'à ce que le Nord de l'aiguille arrive sur le Nord du cadran.","src":"TOPO RALLYE DAK23.pdf","qcm":{"ok":"Aligner boussole et bord de carte, tourner l'ensemble","no":["Tourner seulement la boussole sur la carte immobile","Placer le Sud du cadran sur le bas de la carte","Viser une étoile puis tourner la carte vers elle"]}},{"id":"t11-32","q":"Quels sont les types de boussole et leur utilité ?","a":"**Boussole d'orientation** : orienter une carte. **Boussole de visée** : déterminer la direction d'un objectif (on lit dans un miroir avec un viseur). **Compas** : suivre une direction en continu (sur les bateaux).","src":"TOPO RALLYE DAK23.pdf","qcm":{"ok":"Le compas sert à suivre une direction en continu","no":["Le compas sert à orienter une carte","La boussole de visée sert à suivre une direction en continu","La boussole d'orientation sert à viser un objectif"]}},{"id":"t11-33","q":"Qu'est-ce qu'une courbe de niveau, et qu'est-ce que la rose des vents ?","a":"**Courbe de niveau** : ligne formée par les points du relief situés à la **même altitude**. **Rose des vents** : cercle imaginaire représentant les **16 directions** du vent, chacune correspondant à un angle en degrés.","src":"TOPO RALLYE DAK23.pdf","qcm":{"ok":"Ligne joignant des points de même altitude","no":["Ligne joignant des points de même distance","Ligne joignant des points de même latitude","Ligne indiquant la pente la plus forte"]}},{"id":"t11-34","q":"Citez trois codages autres que le morse, et décodez « MF TDPVU FTU MPZBM ».","a":"Codages : **dents de scie, alphabet clé de 100, clé de 10, sémaphore**. Le message se lit « **Le scout est loyal** » (chaque lettre décalée d'un rang).","src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"Le scout est loyal","no":["Le scout est loyal et franc","Le chef est loyal","Le scout est pur"]}},{"id":"t11-35","q":"Quels types de signalisation existe-t-il (corrigé 2022) ? Et que signifie GPS ?","a":"Signalisation **verticale, horizontale, lumineuse**. GPS : **Global Positioning System**.","src":"Questions Réponses Rallye 2022.pdf, TOPO RALLYE DAK23.pdf","qcm":{"ok":"Verticale, horizontale, lumineuse","no":["Verticale, horizontale, sonore","Routière, ferroviaire, maritime","Lumineuse, sonore, gestuelle"]}},{"id":"t11-36","q":"Quels sont les dix nœuds de l'aspirant ?","a":"**Ganse, demi-clé, simple, tour mort, ganse à tête d'alouette, plat, pêcheur, cabestan, tisserand, chaise**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Ganse, demi-clé, simple, plat, pêcheur, cabestan, chaise…","no":["Carrick, tête de turc, pendu, gueule de raie, chaise…","Jambe de chien, capucin, carrick, pomme de touline…","Brêlage carré, diagonal, en long, en étoile, triple…"]}},{"id":"t11-37","q":"Quelles familles de nœuds citent les corrigés, et à quelle famille appartiennent le plat, le huit et le simple ?","a":"Familles citées : **arrêt, coulant, jonction**. Le **plat** est un nœud de **jonction** ; le **huit** et le **simple** sont des nœuds d'**arrêt**.","src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"Plat : jonction ; huit et simple : arrêt","no":["Plat : arrêt ; huit et simple : jonction","Plat : coulant ; huit et simple : arrêt","Plat : jonction ; huit : coulant ; simple : arrêt"]}},{"id":"t11-38","q":"Quel nœud utiliser pour sortir un camarade tombé dans une fosse ou un puits ?","a":"Le nœud de **chaise**.","src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"Le nœud de chaise","no":["Le nœud de cabestan","Le nœud de jambe de chien","Le nœud de capucin"]}},{"id":"t11-39","q":"Selon les corrigés, quel nœud relie deux cordes de diamètres différents ? Et quel nœud raccourcit une corde sans la couper ?","a":"Pour relier deux cordes d'inégale grosseur, les corrigés 2017 et 2022 donnent le **nœud de vache**. Pour raccourcir une corde : la **jambe de chien**.","src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"Vache ; jambe de chien","no":["Plat ; capucin","Cabestan ; jambe de chien","Vache ; demi-clé"]}},{"id":"t11-40","q":"Quel nœud amarre vite une corde sur un crochet pour soulever une charge, et lequel sert à hisser un rondin ?","a":"Sur un crochet : la **gueule de raie**. Pour hisser ou tirer un rondin : le **nœud de bois** (simple ou double). Pour faire tomber des branches : la **ganse à tête d'alouette** (corrigé 2017).","src":"matelotage rallye dak23.pdf, Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Gueule de raie ; nœud de bois","no":["Nœud de bois ; gueule de raie","Cabestan ; nœud de chaise","Gueule de raie ; jambe de chien"]}},{"id":"t11-41","q":"Que signifient décommettre, toron et frapper un cordage ?","a":"**Décommettre** : desserrer les torons d'un cordage. **Toron** : élément constitutif d'un cordage. **Frapper** un cordage : l'attacher sur un point fixe.","src":"matelotage rallye dak23.pdf","qcm":{"ok":"Frapper : attacher un cordage sur un point fixe","no":["Frapper : couper un cordage d'un coup sec","Frapper : ranger un cordage à plat en zigzag","Frapper : resserrer les torons d'un cordage"]}},{"id":"t11-42","q":"Que signifient élinguer, étaler en biture et glène ?","a":"**Élinguer** : placer un cordage autour d'un objet pour le hisser. **Étaler en biture** : ranger un cordage à plat et en zigzag. **Glène** : cordage enroulé de façon régulière avant d'être rangé.","src":"matelotage rallye dak23.pdf","qcm":{"ok":"Glène : cordage enroulé régulièrement pour le ranger","no":["Glène : cordage rangé à plat et en zigzag","Glène : cordage placé autour d'un objet à hisser","Glène : élément constitutif d'un cordage"]}},{"id":"t11-43","q":"À quoi servent le brêlage carré, le brêlage en tête de bigue et le brêlage en long ?","a":"**Carré** : assembler 2 perches perpendiculaires. **Tête de bigue** : former un trépied. **En long** : assembler 2 perches parallèles. Le **triple** assemble 3 perches perpendiculaires deux à deux.","src":"matelotage rallye dak23.pdf","note":"Le corrigé donne la même utilité au brêlage diagonal et au brêlage en étoile (angle quelconque) ; ils diffèrent seulement par la disposition des perches.","qcm":{"ok":"Tête de bigue : former un trépied","no":["Tête de bigue : assembler 2 perches parallèles","Brêlage en long : former un trépied","Brêlage carré : assembler 3 perches"]}},{"id":"t11-44","q":"Quels gestes composent le PAS et que doit contenir le message d'alerte ?","a":"**Protéger – Alerter – Secourir**. Message d'alerte : **présentation, nature de l'accident, adresse, nombre de victimes, premières mesures prises, risques particuliers**.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Protéger, Alerter, Secourir","no":["Prévenir, Alerter, Soigner","Protéger, Ausculter, Soigner","Prévenir, Assister, Secourir"]}},{"id":"t11-45","q":"Comment baliser le lieu d'un accident de la route ?","a":"Avec des triangles (ou moyens du bord) sur **100 à 150 m le jour** et **200 à 300 m la nuit**, dans les deux sens de circulation. Le **triangle de pré-signalisation** sert à ce balisage.","src":"Questions Réponses Rallye 2017.pdf, secourisme rallye dak23.pdf","qcm":{"ok":"100 à 150 m le jour, 200 à 300 m la nuit","no":["50 à 100 m le jour, 100 à 150 m la nuit","200 à 300 m le jour, 100 à 150 m la nuit","100 à 150 m le jour comme la nuit"]}},{"id":"t11-46","q":"Quelle est la CAT face à une hémorragie externe ?","a":"**Compression manuelle locale** (main sur la plaie), **pansement compressif**, **point de compression** à distance (artère contre l'os), et le **garrot** seulement en dernier recours.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Compression locale, pansement compressif, garrot en dernier","no":["Garrot d'abord, puis pansement compressif","Position du choqué et diète absolue","Laver la plaie et laisser saigner"]}},{"id":"t11-47","q":"Quelle est la CAT face à une hémorragie interne ?","a":"**Position du choqué**, **diète absolue** (ni boire ni manger), **couvrir la victime**, **évacuation d'urgence** pour une intervention chirurgicale.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Position du choqué, diète, couvrir, évacuer","no":["Compression locale, pansement, garrot","Faire boire de l'eau sucrée, allonger, surveiller","PLS, faire marcher la victime, évacuer"]}},{"id":"t11-48","q":"En quoi consiste l'examen d'une victime ?","a":"Vérifier le **saignement**, la **conscience**, la **respiration**, la **circulation** (pouls) et le **squelette** (luxation, entorse, fracture).","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Saignement, conscience, respiration, circulation, squelette","no":["Température, tension, glycémie, vue, ouïe","Conscience, âge, poids, groupe sanguin","Saignement, fièvre, appétit, sommeil"]}},{"id":"t11-49","q":"Que signifient LVA, VA, MCE, RCP, EEE et DAE ?","a":"**LVA** : Libération des Voies Aériennes. **VA** : Ventilation Artificielle. **MCE** : Massage Cardiaque Externe. **RCP** : Réanimation Cardio-Pulmonaire. **EEE** : Emballer, Étiqueter, Évacuer. **DAE** : Défibrillateur Automatisé Externe.","src":"secourisme rallye dak23.pdf, Questions Réponses Rallye 2017.pdf","qcm":{"ok":"EEE : Emballer, Étiqueter, Évacuer","no":["EEE : Examiner, Écouter, Évacuer","EEE : Emballer, Examiner, Envoyer","EEE : Éloigner, Étiqueter, Évacuer"]}},{"id":"t11-50","q":"Quelle est la CAT en cas d'absence de respiration, et quelle est la fréquence cardiaque normale d'un adulte ?","a":"Absence de respiration : **LVA + VA**. Fréquence cardiaque normale d'un adulte : **60 à 80 battements par minute**.","src":"Questions Réponses Rallye 2017.pdf, secourisme rallye dak23.pdf","qcm":{"ok":"LVA + VA ; 60 à 80 battements par minute","no":["MCE seul ; 60 à 80 battements par minute","LVA + VA ; 100 à 120 battements par minute","PLS ; 40 à 60 battements par minute"]}},{"id":"t11-51","q":"Quels sont les numéros d'urgence donnés dans les annales ?","a":"**Sapeurs-pompiers : 18** ; **Police : 17** ou 800 00 20 17 ; **Gendarmerie : 800 00 20 20** ; **SAMU : 1515** ; Assistance publique de Pikine : 800 55 55 55.","src":"Questions Réponses Rallye 2017.pdf, secourisme rallye dak23.pdf","qcm":{"ok":"Pompiers 18, Police 17, SAMU 1515","no":["Pompiers 17, Police 18, SAMU 1515","Pompiers 18, Police 17, SAMU 15","Pompiers 15, Police 17, SAMU 1818"]}},{"id":"t11-52","q":"Quels sont les trois degrés de brûlure et la CAT du 3e degré ?","a":"**1er degré** : épiderme seul (peau rouge). **2e degré** : épiderme et derme (cloques, à ne pas percer). **3e degré** : jusqu'à l'hypoderme (peau cuite, cartonnée). CAT du 3e degré : protocole **EEE** : arroser à l'eau tiède environ 15 min (20 min si brûlure chimique), envelopper dans un drap stérile, évacuer à l'hôpital.","src":"secourisme rallye dak23.pdf, Questions Réponses Rallye 2023.pdf","qcm":{"ok":"Protocole EEE : arroser, emballer, évacuer","no":["Percer les cloques puis appliquer un pansement","Protocole RIRE : refroidir, immobiliser, reposer","Appliquer de la glace directement sur la peau"]}},{"id":"t11-53","q":"Quelle est la CAT face à un coup de chaleur chez une victime consciente ?","a":"Amener la victime dans un **endroit frais**, l'**allonger sur le dos pieds surélevés**, **déboutonner ou enlever ses vêtements**, la **rafraîchir** et la surveiller.","src":"Questions Réponses Rallye 2017.pdf","qcm":{"ok":"Endroit frais, allongée pieds surélevés, rafraîchir","no":["Couvrir la victime, la faire boire chaud","PLS au soleil, surveiller la respiration","La faire marcher, lui donner du sel"]}},{"id":"t11-54","q":"Que signifie le protocole RIRE pour une fracture fermée ?","a":"**Refroidissement** (glace dans un linge, jamais directement sur la peau), **Immobilisation** (attelle, écharpe), **Repos** du membre, **Élévation** du membre blessé. Pour une fracture ouverte : couvrir la plaie, point de compression à distance, puis RIRE.","src":"secourisme rallye dak23.pdf","qcm":{"ok":"Refroidissement, Immobilisation, Repos, Élévation","no":["Réanimation, Immobilisation, Repos, Évacuation","Refroidissement, Isolement, Rééducation, Évacuation","Repos, Immobilisation, Réchauffement, Élévation"]}},{"id":"t11-55","q":"Quelles sont les classes de feu A, B, C et D ?","a":"**A** : solides formant des braises (bois, papier, charbon). **B** : hydrocarbures, alcool, solvants, plastiques. **C** : gaz. **D** : métaux. (E : origine électrique ; F : huiles et graisses.)","src":"secourisme rallye dak23.pdf","qcm":{"ok":"A solides, B hydrocarbures, C gaz, D métaux","no":["A gaz, B solides, C métaux, D hydrocarbures","A solides, B gaz, C hydrocarbures, D électrique","A hydrocarbures, B solides, C gaz, D huiles"]}},{"id":"t11-56","q":"Comment utilise-t-on un extincteur, et quels types existe-t-il ?","a":"**Retirer la goupille**, **percuter** pour mettre sous pression, **faire un test** sur le côté, **viser la base des flammes**. Types : à **eau**, à **CO2**, à **mousse**, à **poudre**.","src":"secourisme rallye dak23.pdf","qcm":{"ok":"Goupille, percuter, test, viser la base des flammes","no":["Goupille, percuter, viser le haut des flammes","Percuter, goupille, viser la fumée","Test, goupille, viser le centre des flammes"]}},{"id":"t11-57","q":"Quels principes doit respecter un dégagement d'urgence, et quelles techniques de relevage connaissez-vous ?","a":"Principes : **victime visible**, **alignement tête-cou-tronc**, **rapidité**, technique adaptée à la situation, prises solides. Relevage : **pont simple**, pont simple amélioré, **pont néerlandais**, pont néerlandais amélioré.","src":"secourisme rallye dak23.pdf","qcm":{"ok":"Alignement tête-cou-tronc et rapidité d'exécution","no":["Attendre les secours avant tout déplacement","Tirer la victime par un seul bras","Toujours la mettre debout avant de la déplacer"]}},{"id":"t11-58","q":"Quels sont les quatre évangélistes et leurs symboles ?","a":"**Matthieu** : l'homme (ou l'ange). **Marc** : le lion. **Luc** : le taureau. **Jean** : l'aigle.","src":"Questions Réponses Rallye 2023.pdf","qcm":{"ok":"Matthieu l'homme, Marc le lion, Luc le taureau, Jean l'aigle","no":["Matthieu le lion, Marc l'homme, Luc l'aigle, Jean le taureau","Matthieu l'homme, Marc le taureau, Luc le lion, Jean l'aigle","Matthieu l'aigle, Marc le lion, Luc l'homme, Jean le taureau"]}},{"id":"t11-59","q":"Quels sont les 5 piliers de l'islam selon les corrigés ?","a":"Les **5 prières quotidiennes**, le **jeûne**, l'**aumône**, le **pèlerinage à La Mecque**, et la profession de foi (« croire en Dieu » en 2015, « les deux témoignages » en 2017).","src":"QUESTIONS REPONSES RALLYE MBOUR 2015.pdf, Questions Réponses Rallye 2017.pdf","note":"Le 5e pilier est formulé « croire en Dieu » (2015) ou « les deux témoignages » (2017) ; le corrigé 2017 écrit aussi « L'Aumônier » pour l'aumône.","qcm":{"ok":"Prière, jeûne, aumône, pèlerinage, profession de foi","no":["Prière, jeûne, aumône, pèlerinage, Tamkharit","Prière, jeûne, Tabaski, pèlerinage, profession de foi","Prière, lecture du Coran, aumône, jeûne, Achoura"]}},{"id":"t11-60","q":"Quels sont la devise et les sceaux du Sénégal ?","a":"Devise : **Un peuple, un but, une foi**. Sceaux : le **lion** (présidence) et le **baobab** (administration).","src":"QUESTIONS REPONSES RALLYE MBOUR 2015.pdf, Questions Réponses Rallye 2022.pdf","qcm":{"ok":"Un peuple, un but, une foi ; lion et baobab","no":["Un peuple, un but, une foi ; lion et étoile","Un peuple, une foi, une loi ; lion et baobab","Unité, travail, progrès ; lion et baobab"]}}]}$xxb$::jsonb, now()),
  ('cards-2', $xxb${"theme":2,"cards":[{"id":"t2-01","q":"Comment l'*Aurore cérémonial* définit-il un cérémonial ?","a":"C'est **l'ensemble des signes qui crée un certain décorum** et qui permet à la troupe de **mesurer l'importance des instants vécus**. Il est souhaitable d'y faire participer les éclaireurs.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Un ensemble de signes créant un décorum pour marquer les moments importants","no":["Un règlement fixant les sanctions et les récompenses de la troupe","Le programme annuel des activités arrêté par la maîtrise de troupe","Le recueil officiel des chants à apprendre avant la promesse"]}},{"id":"t2-02","q":"Comment sont disposées les unités lors de la montée de la meute à la troupe ?","a":"La **troupe en rectangle**, la **meute en cercle** (cercle de parade), séparées par les deux maîtrises qui se tournent le dos, à **5 mètres** l'une de l'autre.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Troupe en rectangle, meute en cercle, maîtrises à 5 mètres","no":["Troupe en cercle, meute en rectangle, maîtrises à 5 mètres","Troupe et meute en carré, maîtrises à 10 mètres","Troupe en demi-cercle, meute en ligne, maîtrises à 3 mètres"]}},{"id":"t2-03","q":"Combien de fois un louveteau reçoit-il le Grand Hurlement en son honneur ?","a":"**Deux fois** : le jour où il **entre dans la meute**, et le jour où il la **quitte pour monter à la troupe** (adieu de toute la meute).","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Deux fois : à son entrée dans la meute et à sa montée à la troupe","no":["Deux fois : à sa promesse et à sa deuxième étoile","Une fois : le jour de sa montée à la troupe","Trois fois : à l'entrée, à chaque étoile et au départ"]}},{"id":"t2-04","q":"Quel chant le CT entonne-t-il après la remise de l'insigne de technicien ou d'animateur ?","a":"**Le chant de la promesse**, pour rappeler au récipiendaire l'engagement qu'il prend comme acteur du développement de sa patrouille et de la troupe.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Le chant de la promesse","no":["Le chant des adieux","Ingonyama","Notre-Dame des Éclaireurs"]}},{"id":"t2-05","q":"Comment l'*Aurore* définit-il la cour d'honneur (C.H.) ?","a":"Un **instrument pédagogique**, l'**instance suprême** du scoutisme, qui vise à **éduquer par la confiance** : on fait appel à la conscience, on évalue. Elle est **gardienne de la loi scoute** dans l'unité.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Une instance qui éduque par la confiance et garde la loi scoute","no":["Un tribunal qui sanctionne les fautes graves par l'exclusion","Un conseil qui fixe le calendrier des sorties de la troupe","Une commission qui gère la caisse et le matériel du camp"]}},{"id":"t2-06","q":"Qu'est-ce que la promesse scoute selon l'*Aurore* ?","a":"Ni un examen ni une distribution honorifique : c'est une **adhésion libre, volontaire et personnelle** du jeune à l'idéal scout, **demandée par le scout lui-même** lorsqu'il s'en estime digne.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Une adhésion libre, volontaire et personnelle à l'idéal scout","no":["Un examen qui clôt la formation de l'éclaireur","Une distinction honorifique décernée par le chef","Une obligation après un an de présence à la troupe"]}},{"id":"t2-07","q":"Quelles sont, dans l'ordre, les quatre phases de la promesse ?","a":"1) **Décision du garçon** (demande manuscrite) ; 2) **décision du groupe** en cour d'honneur ; 3) **veillée de promesse** ; 4) **engagement**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Décision du garçon, cour d'honneur, veillée, engagement","no":["Cour d'honneur, épreuves, engagement, veillée","Demande, examen écrit, investiture, défilé","Veillée, décision du garçon, engagement, accueil"]}},{"id":"t2-08","q":"Quelle est la seule cérémonie scoute que l'on peut faire dans une église ?","a":"**La veillée de promesse.** Son cadre est un haut lieu : chœur de l'église, calvaire, oratoire ou site naturel magnifique où est fixé l'étendard.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"La veillée de promesse","no":["L'engagement (promesse)","L'investiture du chef de patrouille","La montée des couleurs"]}},{"id":"t2-09","q":"Par quel chant, et autour de quoi, débute la veillée de promesse ?","a":"Par le chant **Notre-Dame des Éclaireurs**, **autour d'un feu**. Le feu est **le symbole de l'unité** et **la lumière qui éclaire**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Notre-Dame des Éclaireurs, autour d'un feu","no":["Chevaliers saluons les couleurs, au pied du mât","Ingonyama, autour du kraal","Le chant de la promesse, devant l'autel"]}},{"id":"t2-10","q":"Pendant la veillée, qui dit « Mon Dieu, nous vous offrons la promesse de X… » ?","a":"**Le chef de patrouille**, le **fanion dans la main droite**, la main gauche posée sur l'épaule du garçon confié à sa patrouille.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Le chef de patrouille, fanion en main droite","no":["Le second, les mains tendues vers le ciel","L'aumônier, debout devant l'autel","Le chef de troupe, près du feu"]}},{"id":"t2-11","q":"Comment la troupe est-elle disposée pour l'engagement (promesse) ?","a":"En grande tenue, **en rectangle occupant trois côtés**, **le quatrième formé par les parents et l'assistance**. Un CP placé devant le mât tient l'étendard.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Rectangle sur trois côtés, le quatrième pour les parents","no":["Cercle de parade fermé autour du mât","Demi-cercle face à l'autel de la paroisse","Carré complet, les parents derrière la maîtrise"]}},{"id":"t2-12","q":"Pourquoi l'engagement ne se tient-il pas dans une église ou un lieu fermé ?","a":"Parce que **le rassemblement, élément primordial**, ne pourrait y être respecté. Tous les événements importants de la troupe passent obligatoirement par un rassemblement.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Le rassemblement, élément primordial, n'y serait pas respecté","no":["L'étendard ne doit jamais entrer dans une église","Les parents ne peuvent pas assister à la messe","Le chant national n'y est pas autorisé"]}},{"id":"t2-13","q":"Selon le dialogue de la promesse, quelles sont les trois vertus principales des scouts ?","a":"**Franchise, Dévouement et Pureté.** (À la question « Quels avantages matériels en attends-tu ? », l'aspirant répond : « Aucun ».)","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Franchise, Dévouement et Pureté","no":["Loyauté, Courage et Service","Franchise, Fidélité et Charité","Honneur, Dévouement et Discipline"]}},{"id":"t2-14","q":"Selon la formule de promesse des scouts du Sénégal, que s'engage-t-on à servir de toutes ses forces ?","a":"« Devant tous, avec la grâce de Dieu, je m'engage sur mon honneur, à servir de toutes mes forces **Dieu, l'Église et ma patrie**, à aider mon prochain à tout moment, à observer la loi scoute. »","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Dieu, l'Église et la patrie","no":["Dieu, le Roi et la patrie","Dieu, la famille et le Sénégal","Dieu, l'Afrique et la patrie"]}},{"id":"t2-15","q":"Quel geste fait le récipiendaire en prononçant sa promesse ?","a":"Il fait le **salut scout de la main droite** et pose la **main gauche sur la hampe de l'étendard**, incliné horizontalement devant lui. La troupe salue.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Salut de la main droite, main gauche sur la hampe de l'étendard","no":["Main droite sur la Bible, main gauche au salut","Salut de la main gauche, main droite sur le fanion","Les deux mains posées sur la hampe du drapeau"]}},{"id":"t2-16","q":"Que dit le nouveau scout en prêtant obédience à son chef de patrouille ?","a":"Main gauche dans la main gauche du CP, qui la couvre de sa droite : « Je te promets **de t'obéir comme au chef, de t'aider comme un frère aîné et d'être loyal à la patrouille** ».","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Dans l'investiture du CP, l'Aurore écrit « t'aimer comme un frère aîné » ; le Cérémonial Sénégal et l'Aurore (promesse) disent « t'aider ».","qcm":{"ok":"T'obéir comme au chef, t'aider comme un frère aîné, être loyal","no":["Te suivre partout, te défendre, garder nos secrets","T'obéir sans discuter, te servir, porter ton fanion","T'écouter comme un père, t'aider, servir la troupe"]}},{"id":"t2-17","q":"Combien de temps dure au maximum l'allocution qui suit la promesse ?","a":"Elle doit être très courte : **quatre minutes maximum** selon le *Cérémonial Sénégal*, **cinq minutes maximum** selon l'*Aurore*.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Cérémonial Sénégal : 4 minutes ; Aurore cérémonial : 5 minutes.","qcm":{"ok":"Quatre à cinq minutes au maximum, selon la source","no":["Quinze minutes au maximum","Une demi-heure environ","Aucune limite n'est fixée"]}},{"id":"t2-18","q":"Quels chants terminent la cérémonie de promesse ?","a":"Le chef entonne **le chant de la promesse**, puis **le chant national des S.D.S.** La troupe s'éloigne ensuite, étendard en tête, en chantant.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Le chant de la promesse, puis le chant national des S.D.S.","no":["L'hymne national, puis Ingonyama","Chevaliers saluons les couleurs, puis le chant des adieux","Notre-Dame des Éclaireurs, puis l'hymne national"]}},{"id":"t2-19","q":"Par qui l'investiture d'un chef doit-elle être faite ?","a":"Un chef n'exerce officiellement ses fonctions qu'après son investiture, **obligatoirement faite par le commissaire de district (C.D.) ou en sa présence**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"Par le commissaire de district, ou en sa présence","no":["Par le chef de groupe, ou en sa présence","Par le commissaire de région uniquement","Par l'aumônier de groupe, ou en sa présence"]}},{"id":"t2-20","q":"Qui décide de l'investiture d'un chef de patrouille ?","a":"Le CP fait une **demande manuscrite** au chef de troupe, qui réunit un conseil de maîtrise puis convoque l'intéressé : **c'est la cour d'honneur qui décide**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"La cour d'honneur, après demande manuscrite du CP","no":["Le chef de troupe seul, sur proposition des parents","Le commissaire de district, après un stage de CP","L'aumônier, après un entretien personnel"]}},{"id":"t2-21","q":"Que reçoit le nouveau chef de patrouille lors de son investiture ?","a":"**La cordelière kaki** et **son bâton portant le fanion** de sa nouvelle patrouille. Les deux bandes blanches sont cousues d'avance à leur place.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"La cordelière kaki et le bâton portant le fanion","no":["La cordelière blanche et le sifflet de patrouille","Le foulard gris et la bague à deux torons","La barrette de patrouille et l'étendard"]}},{"id":"t2-22","q":"Lors de l'ouverture d'un camp, que remet le CT au servant pour allumer le kraal ?","a":"**Trois brins d'allumette.** L'étendard est accroché par deux branches en « Y » à **3 m du kraal** ; on chante *Ingonyama* puis *Du fagot jaillit la flamme*.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Trois brins d'allumette","no":["Un seul brin d'allumette","Une torche allumée au feu de veillée","Une bougie bénie par l'aumônier"]}},{"id":"t2-23","q":"Que signifie le geste des campeurs qui mettent chacun leur brindille dans le kraal ?","a":"Que **tous, autant qu'ils sont, acceptent la loi du camp**. Le kraal doit ensuite **rester allumé durant tout le camp** et être respecté.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Que tous acceptent la loi du camp","no":["Que chacun a déjà fait sa promesse","Que chaque patrouille a fini son installation","Que le camp est placé sous la garde du CT"]}},{"id":"t2-24","q":"Que manifeste le cérémonial des couleurs selon l'*Aurore* ?","a":"La **fidélité de la troupe aux principes du scoutisme** symbolisés par les pavillons : **la fraternité scoute** et **le service de la Patrie**. Il doit se dérouler dans un climat calme et solennel.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"La fidélité à la fraternité scoute et au service de la Patrie","no":["La fidélité au chef de troupe et à la paroisse","La fierté d'être la meilleure troupe du district","L'obéissance aux autorités civiles et militaires"]}},{"id":"t2-25","q":"Quand les couleurs sont-elles envoyées (hissées) ?","a":"**À l'ouverture du camp** et **chaque matin au premier rassemblement** de la journée. La cérémonie doit être **brève mais bien préparée**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"À l'ouverture du camp et chaque matin au premier rassemblement","no":["Chaque soir à la veillée et le jour des promesses","Uniquement à l'ouverture et à la fermeture du camp","Chaque jour à midi, avant le repas de la troupe"]}},{"id":"t2-26","q":"Combien de temps avant la cérémonie les servants vont-ils chercher le pavillon au kraal ?","a":"**Un quart d'heure avant** les couleurs. Ils vérifient le libre jeu de la drisse et fixent le pavillon, cabillot en haut.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Nombre de servants : un servant et son aide (Cérémonial Sénégal) ; le CP de la patrouille d'honneur et trois patrouillards (Aurore) ; deux servants par mât (Montée des couleurs).","qcm":{"ok":"Un quart d'heure avant","no":["Deux minutes avant","Une heure avant","La veille au soir"]}},{"id":"t2-27","q":"Avec quels nœuds fixe-t-on les pavillons à la drisse selon l'*Aurore* ?","a":"**En haut, un nœud de chaise autour d'un cabillot** ; **en bas, un nœud de tisserand** unissant la ganse à la drisse.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Nœud de chaise en haut, nœud de tisserand en bas","no":["Nœud plat en haut, nœud de cabestan en bas","Nœud de tisserand en haut, nœud de chaise en bas","Demi-clés en haut, nœud de carrick en bas"]}},{"id":"t2-28","q":"Quelle est la suite des commandements pour la montée des couleurs selon l'*Aurore* ?","a":"CT : **« Attention pour les couleurs ! »** — servants : **« Parés pour les couleurs »** — CT : **« Envoyez ! »** puis, quand les pavillons se déplient, **« Scouts, saluez ! »**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Attention pour les couleurs ! – Parés ! – Envoyez ! – Scouts, saluez !","no":["Garde à vous ! – Prêts ! – Hissez ! – Saluez !","Toujours prêts ! – Parés ! – Amenez ! – Fixe !","Attention ! – Montez ! – Chantez ! – Repos !"]}},{"id":"t2-29","q":"Pendant la montée des couleurs, qui fait le salut scout selon l'*Aurore* ?","a":"**Ceux qui ont prononcé leur promesse** font le salut scout ; **les autres restent au prêt**. Tous suivent des yeux la montée des pavillons.","src":"Aurore Ceremonial Verte.pdf","note":"Le texte « Montée ou levée des couleurs » dit seulement que « les scouts saluent avec la maîtrise », sans distinguer les promis.","qcm":{"ok":"Seuls ceux qui ont prononcé leur promesse","no":["Seuls les chefs et les CP","Tous les scouts, promis ou non","Seuls les servants au pied du mât"]}},{"id":"t2-30","q":"Que chante-t-on lorsque les couleurs sont à bloc ?","a":"**L'hymne national.** Selon le *Cérémonial Sénégal*, on le chante quand les couleurs sont à bloc, puis le chef commande « Prêt » et les servants fixent la drisse ; selon l'*Aurore*, la drisse est attachée puis le CT chante l'hymne.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Ordre hymne / fixation de la drisse inversé entre le Cérémonial Sénégal et l'Aurore.","qcm":{"ok":"L'hymne national","no":["Le chant de la promesse","Ingonyama","Le chant des adieux"]}},{"id":"t2-31","q":"Quel cri termine la montée des couleurs au Sénégal ?","a":"Le chef lance **« Pour le Sénégal »**, les scouts répondent **« Dieu nous garde »**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Le texte « Montée ou levée des couleurs » (non spécifique au Sénégal) donne « Pour son règne ! » – « Dieu nous garde ! ».","qcm":{"ok":"« Pour le Sénégal » – « Dieu nous garde »","no":["« Pour la patrie » – « Toujours prêts »","« Pour le Sénégal » – « Nous servirons »","« Pour l'Afrique » – « Dieu nous garde »"]}},{"id":"t2-32","q":"À la descente des couleurs, que fait un scout occupé ailleurs dans le camp ?","a":"Quelle que soit son activité, il se met **au prêt (« Toujours prêt ») là où il se trouve**, **salue en direction du mât même s'il ne le voit pas**, et ne bouge ni ne parle jusqu'à la fin.","src":"Aurore Ceremonial Verte.pdf, CEREMONIAL+SENEGAL+revise (1) (1).pdf, Montée ou levée des couleurs.docx","qcm":{"ok":"Il se met au prêt sur place et salue vers le mât","no":["Il rejoint le mât au pas de course pour saluer","Il poursuit son activité sans s'arrêter","Il rejoint sa patrouille au kraal et attend"]}},{"id":"t2-33","q":"Quand descend-on les couleurs, et qui s'en charge ?","a":"**Le soir, au coucher du soleil.** La **patrouille d'honneur** (quatre scouts selon l'*Aurore*) ou l'équipe de service. Le texte *Montée des couleurs* ajoute : aussi lorsqu'il pleut.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf, Montée ou levée des couleurs.docx","note":"Signaux de corne différents : Cérémonial Sénégal = coup long + coups brefs au début, coup long à la fin ; Montée des couleurs = coup long au début, second coup bref à la fin ; Aurore = coup long au début, second coup à la fin, puis parle d'un « coup de trompe long » final.","qcm":{"ok":"Au coucher du soleil, par la patrouille d'honneur","no":["À midi, par le chef de troupe","Après la veillée, par les assistants","Au réveil, par le premier CP"]}},{"id":"t2-34","q":"Pour la rentrée des couleurs, commande-t-on « Amenez » ?","a":"Non. On commande **« Envoyez »**, comme pour la levée. **« Amenez »** se dit à la suite d'une **défaite**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Non : « Envoyez », comme pour la levée","no":["Oui : « Amenez », comme dans la marine","Non : « Descendez », au signal du CP","Non : « Rentrez les couleurs », dit l'aumônier"]}},{"id":"t2-35","q":"Qui peut manœuvrer les drisses lors des couleurs ?","a":"**Seuls les scouts ayant prononcé la promesse.** Se voir confier les couleurs est un **privilège**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Seuls les scouts ayant prononcé leur promesse","no":["Tous les scouts, à tour de rôle","Seuls les chefs de patrouille","Seuls les assistants de troupe"]}},{"id":"t2-36","q":"Comment dit-on d'un pavillon plié ? Et d'un pavillon déplié flottant au vent ?","a":"Plié : **ferlé**. Déplié et flottant au vent : **déferlé et battant**.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"Ferlé ; déferlé et battant","no":["Déferlé ; ferlé et battant","En berne ; à bloc et battant","Amené ; envoyé et flottant"]}},{"id":"t2-37","q":"Que signifient « à bloc » et « en berne » ?","a":"**À bloc** : complètement en haut du mât (position normale). **En berne** : à mi-mât (le *Cérémonial* dit « hisser jusqu'à mi-drisse »), **en signe de deuil**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","qcm":{"ok":"À bloc : tout en haut ; en berne : à mi-mât, en signe de deuil","no":["À bloc : à mi-mât ; en berne : tout en haut, en signe de fête","À bloc : tout en haut ; en berne : plié au pied du mât","À bloc : roulé sur la hampe ; en berne : à mi-mât, pour la pluie"]}},{"id":"t2-38","q":"Comment plie-t-on les couleurs et l'étendard au Sénégal ?","a":"**En rectangle.** Le pliage en triangle (pays anglophones, remise des couleurs à la famille d'un soldat mort) **n'est pas de mise au Sénégal**. L'étendard est plié en rectangle, **insigne bien visible dessus**. Le pavillon est rapporté au kraal **ferlé, partie verte en dehors**.","src":"Aurore Ceremonial Verte.pdf, Montée ou levée des couleurs.docx","note":"Le texte « Montée ou levée des couleurs » présente deux techniques (rectangle et triangle) sans exclure le triangle.","qcm":{"ok":"En rectangle","no":["En triangle","Roulé autour de la hampe","En carré, insigne caché"]}},{"id":"t2-39","q":"Que signifie le « petit drapeau » ajouté au mât du Palais présidentiel ?","a":"**La présence du chef de l'État** dans la résidence ou sur le territoire national.","src":"Aurore Ceremonial Verte.pdf","qcm":{"ok":"La présence du chef de l'État","no":["Un deuil national en cours","La visite d'un chef d'État étranger","Un jour de fête nationale"]}},{"id":"t2-40","q":"Selon le texte « Montée ou levée des couleurs », que représente le mât dans le camp ?","a":"Il n'est pas là pour dominer : c'est **le point de ralliement, le cœur du camp**, le point central où l'on se rassemble, proche du lieu de veillée et du coin des chefs.","src":"Montée ou levée des couleurs.docx","qcm":{"ok":"Le point de ralliement, le cœur du camp","no":["Le signe de la supériorité de la troupe","La limite entre les coins de patrouille","Le poste de garde de la patrouille de service"]}},{"id":"t2-41","q":"Quelles sont les dimensions et l'allure du drapeau sénégalais des Scouts du Sénégal ?","a":"Un **carré de 90 cm** de côté, trois bandes verticales **vert, jaune, rouge**, étoile verte à cinq branches, **frange or de 6 cm** sur trois côtés, hampe surmontée d'un **lys stylisé**, inscription « Scouts du Sénégal » sur la bande verte.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Un carré de 90 cm de côté, frangé d'or, hampe à lys stylisé","no":["Un rectangle de 1 m sur 1,50 m, sans frange, hampe à étoile","Un carré de 60 cm de côté, frangé de vert, hampe à lys stylisé","Un rectangle de 90 cm sur 60 cm, frangé d'or, hampe à lance"]}},{"id":"t2-42","q":"Qui porte le drapeau sénégalais et qui l'escorte ?","a":"Un **chef en gants blancs**, toujours escorté de **5 garçons également en gants blancs**. La hampe forme un angle de **45°** avec la verticale.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Un chef ganté, escorté de 5 garçons gantés","no":["Un CP ganté, escorté de 2 éclaireurs","Un assistant, escorté de 3 routiers","Le premier CP, escorté de toute sa patrouille"]}},{"id":"t2-43","q":"Dans un rassemblement, où se place le drapeau sénégalais ?","a":"**Immédiatement à droite du chef** qui commande le rassemblement. Sa présence est obligatoire dans les cérémonies officielles où les SDS sont en corps constitué.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Immédiatement à droite du chef qui commande","no":["Immédiatement à gauche du chef qui commande","Derrière l'étendard de la troupe","Au centre du rectangle, face au mât"]}},{"id":"t2-44","q":"Quelles sont les caractéristiques de la hampe de l'étendard de troupe ?","a":"Étendard en étamine de laine verte de 1 m, fixé par **7 ganses** à une **hampe de 2,10 m** terminée par un **lys en métal découpé et argenté**, avec deux rubans aux couleurs nationales (1 m × 6 cm).","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Hampe de 2,10 m, 7 ganses, lys argenté","no":["Hampe de 1,40 m, 5 ganses, lys doré","Hampe de 1,50 m, 7 ganses, tête de loup","Hampe de 2,50 m, 9 ganses, étoile verte"]}},{"id":"t2-45","q":"Qui porte l'étendard de troupe ?","a":"**Un assistant de troupe**, **encadré par 2 éclaireurs**. Le porte-drapeau et son escorte ont des **gants blancs**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Un assistant de troupe, encadré par 2 éclaireurs","no":["Le chef de troupe, encadré par 5 scouts","Un CP seul, en gants blancs","L'aumônier, encadré par 2 routiers"]}},{"id":"t2-46","q":"Au camp, où se place l'étendard quand les couleurs sont hissées ?","a":"L'étendard **n'est jamais hissé au mât**. Il est placé **au pied du mât** s'il n'y a pas de flamme scoute ; si la flamme est hissée, il est placé **dans l'enceinte du kraal**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Au pied du mât, ou dans le kraal si la flamme est hissée","no":["Hissé au mât, sous le pavillon national","Planté devant la tente du chef de troupe","Hissé au mât à la place de la flamme scoute"]}},{"id":"t2-47","q":"Comment la flamme scoute est-elle hissée par rapport au pavillon ?","a":"Sur une **branche distincte**, **après ou en même temps que le pavillon**, et rentrée **avant ou en même temps** que lui. Elle est mise en berne quand l'étendard est cravaté de crêpe.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Sur une branche distincte, après ou avec le pavillon","no":["Sur la même drisse, juste avant le pavillon","Seule, le pavillon restant au kraal","Toujours au-dessus du pavillon national"]}},{"id":"t2-48","q":"Quelles règles protègent le fanion de patrouille ?","a":"Il n'est porté **que par le CP**, ou en son absence par le second ; il n'est **jamais couché sur le sol** ; il **ne se hisse pas au mât**. À la messe au camp, il peut être planté autour de l'autel.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Porté par le CP ou le second, jamais au sol, jamais hissé","no":["Porté par tout scout promis, hissé chaque matin","Porté par le CT, couché au sol pendant la prière","Porté par le second seul, hissé sous la flamme"]}},{"id":"t2-49","q":"Quelle hauteur minimale a le mât de meute, et que porte-t-il à son sommet ?","a":"Au moins **1,50 m** ; il porte à son sommet **une tête de loup ou un loup entier**, en métal, en bois ou sculpté. Une **flamme jaune** s'y ajoute quand tous les louveteaux concernés ont leur deuxième étoile.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"1,50 m minimum, surmonté d'une tête de loup","no":["1 m minimum, surmonté d'une fleur de lys","2,10 m minimum, surmonté d'une tête de loup","1,50 m minimum, surmonté d'une étoile argentée"]}},{"id":"t2-50","q":"Quelles couleurs de rubans le louveteau attache-t-il au mât de meute selon le brevet gagné ?","a":"Religion : **blanc** ; intelligence : **bleu** ; habileté manuelle : **jaune** ; service du prochain : **rouge** ; aptitudes physiques : **vert**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Religion blanc, intelligence bleu, service rouge, physique vert","no":["Religion bleu, intelligence blanc, service vert, physique rouge","Religion jaune, intelligence vert, service rouge, physique bleu","Religion blanc, intelligence jaune, service vert, physique rouge"]}},{"id":"t2-51","q":"Quels sont les emblèmes propres de l'Association des Scouts du Sénégal ?","a":"À côté des emblèmes nationaux (drapeau et pavillon), les **emblèmes propres** : **mât de meute, étendard de troupe, fanions de communauté, fanions de patrouille, flamme scoute**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Mât de meute, étendard, fanions de communauté et de patrouille, flamme","no":["Drapeau national, pavillon, étendard et mât de pavillon","Foulard, cordelière, bâton, insigne de promesse et flots","Kraal, totem, fanion de district, croix et Bible"]}},{"id":"t2-52","q":"À quoi ressemble l'insigne de promesse des Scouts du Sénégal et où se porte-t-il ?","a":"Le même pour tous : **fleur de lys jaune sur baobab**, porté sur la **poche gauche** de la chemise à partir du jour de la promesse.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Fleur de lys jaune sur baobab, poche gauche","no":["Fleur de lys verte sur baobab, poche droite","Fleur de lys jaune sur antilope, poche gauche","Trèfle jaune sur carte d'Afrique, poche gauche"]}},{"id":"t2-53","q":"Comment fait-on le signe scout, et quelle main serre-t-on entre scouts ?","a":"Main droite, **pouce sur l'ongle du petit doigt, les trois autres doigts tendus**. Les scouts se serrent **la main gauche**. Un novice ne fait pas le signe : il donne la main droite. Ne pas tendre la main gauche aux non-scouts.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Pouce sur l'ongle du petit doigt, trois doigts tendus ; main gauche","no":["Pouce sur l'ongle de l'annulaire, deux doigts tendus ; main gauche","Pouce sur l'ongle du petit doigt, trois doigts tendus ; main droite","Index et majeur tendus, pouce replié ; main droite"]}},{"id":"t2-54","q":"Quand fait-on le salut brandi ?","a":"**Uniquement pendant le refrain du chant de la promesse** et **pour la voûte d'honneur** : bras droit tendu à **45°** en avant, la main faisant le salut.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Au refrain du chant de la promesse et pour la voûte d'honneur","no":["À la montée des couleurs et pendant l'hymne national","À la rencontre d'un convoi funèbre et au défilé","Au Grand Hurlement et lors des remises de brevets"]}},{"id":"t2-55","q":"Comment s'exécute l'acclamation des Scouts du Sénégal ?","a":"Dans les grandes circonstances ou en l'honneur d'un chef ou visiteur de marque. Le chef crie **« SUNU GAL »** en brandissant le poing, les scouts répondent **« TA KANAM »** ; **trois fois**, sur le rythme de Hip ! Hip ! Hourrah !","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf","note":"Orthographe variable : « SUNU GAL TA KANAM » et « CIA-KA-NAM » (Cérémonial Sénégal), « SUNU GAAL CA KANAM » (Aurore).","qcm":{"ok":"Le chef crie « Sunu gal », les scouts répondent « Ta kanam », trois fois","no":["Le chef crie « Ta kanam », les scouts répondent « Sunu gal », une fois","Le chef crie « Scouts toujours », les scouts répondent « Prêts », trois fois","Le chef crie « Sunu gal », les scouts répondent « Dieu nous garde », deux fois"]}},{"id":"t2-56","q":"Quel signe de deuil porte-t-on sur l'uniforme, et qui fixe la durée à la mort d'un garçon de l'unité ?","a":"Un **losange noir sur la manche gauche**. À la mort d'un garçon de l'unité, la durée du deuil est décidée par **la cour d'honneur**. Les emblèmes propres sont cravatés de crêpe noir.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Losange noir, manche gauche ; durée fixée par la cour d'honneur","no":["Brassard noir, manche droite ; durée fixée par l'aumônier","Foulard noir, autour du cou ; durée fixée par le district","Ruban noir, poche gauche ; durée fixée par le chef de groupe"]}},{"id":"t2-57","q":"Où se place l'étendard scout lors d'une messe dans une église ?","a":"L'étendard de l'échelon le plus élevé prend place **dans le chœur, du côté de l'Épître**. Il est tenu **à l'horizontale** pendant l'« homo factus est » et la consécration.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Dans le chœur, côté de l'Épître","no":["Dans le chœur, côté de l'Évangile","À l'entrée de l'église, près des fonts","Au fond de la nef, derrière l'assemblée"]}},{"id":"t2-58","q":"Quelles règles s'appliquent au mât de pavillon ?","a":"De préférence **lisse**, il ne porte **aucun emblème, marque ou pavillon de service**. Les pavillons étrangers sont hissés sur des **mâts distincts, à la même hauteur**. Le pavillon n'est **pas béni**.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Mât lisse sans emblème ; pavillons étrangers sur mâts distincts","no":["Mât décoré du totem ; pavillons étrangers sur le même mât","Mât lisse sans emblème ; pavillons étrangers plus bas","Mât surmonté d'un lys ; pavillons étrangers interdits"]}},{"id":"t2-59","q":"Comment se déroule la cérémonie des couleurs chez les louveteaux ?","a":"La cheftaine appelle **« Meute, meute, meute… »** ; les louveteaux se rassemblent **en demi-cercle autour du mât**. Elle commande **« De notre »**, ils répondent **« Mieux »**. La suite est comme chez les éclaireurs.","src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf","qcm":{"ok":"Appel « Meute ! », demi-cercle autour du mât, « De notre – Mieux »","no":["Appel au sifflet, rectangle face au mât, « Scouts toujours – Prêts »","Appel « Meute ! », cercle de parade, « Akéla – De notre mieux »","Appel « Troupe ! », demi-cercle autour du kraal, « De notre – Mieux »"]}}]}$xxb$::jsonb, now()),
  ('cards-3', $xxb${"theme":3,"cards":[{"id":"t3-01","q":"Quelles sont les étapes de la progression d'un garçon à la troupe ?","a":"À son entrée, il est **volontaire**. Il franchit ensuite trois étapes, dans l'ordre : **Engagé**, **Technicien**, **Animateur**.","src":"La Progression Personnelle (1).pdf, manuel du CP.pdf","qcm":{"ok":"Volontaire, puis Engagé, Technicien, Animateur","no":["Volontaire, puis Technicien, Engagé, Animateur","Aspirant, puis Engagé, Animateur, Technicien","Volontaire, puis Engagé, Animateur, Assistant"]}},{"id":"t3-02","q":"Combien de temps dure l'étape de volontaire, et sous la responsabilité de qui ?","a":"Elle ne doit pas dépasser **3 à 6 mois**. Elle est sous la responsabilité du **chef de patrouille et du second**, avec la supervision du **chef de troupe**.","src":"Livret Carnet de Preuves.pdf","note":"Le Manuel du CT et le projet éducatif ne donnent pas de durée : on demande au volontaire de mûrir sa réflexion « pendant un temps assez long ».","qcm":{"ok":"3 à 6 mois, sous la responsabilité du CP et du second","no":["1 à 2 mois, sous la responsabilité de l'aumônier","6 à 12 mois, sous la responsabilité du CT seul","Un an, sous la responsabilité du conseil de troupe"]}},{"id":"t3-03","q":"Comment le volontaire demande-t-il à faire sa promesse ?","a":"Il écrit une **lettre de demande de promesse** adressée à la **maîtrise**, **sous couvert de son CP**. Une **cour d'honneur** se réunit ensuite pour examiner la demande.","src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Par une lettre à la maîtrise, sous couvert de son CP","no":["Oralement au CT, lors du conseil de troupe","Par une lettre de ses parents au commissaire","Par un vote à main levée en conseil de patrouille"]}},{"id":"t3-04","q":"Quel rôle joue le CP à la cour d'honneur quand un garçon de sa patrouille demande sa promesse ?","a":"En cautionnant la demande, le CP dit qu'il est sûr que le garçon est prêt. Il devient son **défenseur** devant la cour d'honneur, **tout en restant honnête**.","src":"La Progression Personnelle (1).pdf","qcm":{"ok":"Il cautionne la demande et défend le garçon, en restant honnête","no":["Il préside la séance et vote en dernier","Il se retire de la séance car il est juge et partie","Il fait passer au garçon un examen écrit sur la loi"]}},{"id":"t3-05","q":"Selon La Progression Personnelle, quelle est la première obligation d'un scout ?","a":"Faire chaque jour une **B.A.** (bonne action). C'est l'une des conditions pour demander sa promesse, avec l'esprit scout et un cœur tourné vers Dieu.","src":"La Progression Personnelle (1).pdf","qcm":{"ok":"Faire chaque jour une bonne action (B.A.)","no":["Porter chaque jour l'uniforme complet","Payer sa cotisation dès l'inscription","Assister chaque semaine à la réunion"]}},{"id":"t3-06","q":"Qui est Nangmo, dont le volontaire doit « suivre les pas » ?","a":"Un **enfant africain**, « d'un noir d'ébène », qui approchait de ses seize ans. Seul dans la forêt, il a affronté toutes les épreuves et il est revenu **guerrier de la tribu**, faisant la fierté de son village.","src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Un enfant africain devenu guerrier de sa tribu","no":["Le premier chef de patrouille des Scouts du Sénégal","Un chef zoulou que Baden-Powell admirait","Le saint patron africain de la branche verte"]}},{"id":"t3-07","q":"Quelles sont les quatre étapes du cycle préparatoire à la promesse ?","a":"1. **Décision du jeune** (lettre de demande). 2. **Décision du groupe** par la cour d'honneur. 3. **Retraite spirituelle** : la veillée de promesse. 4. **Geste final** : la cérémonie, devant la troupe, le groupe et la famille.","src":"Manuel du CT.pdf, proposition educative eclaireurs VF.pdf","qcm":{"ok":"Décision du jeune, décision de la CH, veillée, cérémonie","no":["Inscription, cotisation, examen écrit, remise du foulard","Décision du CT, accord des parents, camp, défilé","Lettre, conseil de patrouille, retraite, remise du badge"]}},{"id":"t3-08","q":"D'après le Manuel du CT, que représente la promesse ?","a":"La promesse **n'est pas un grade** (comme un passage de caporal à sergent). Ce n'est pas non plus la récompense d'une bonne action. C'est **le début de la vie scoute**.","src":"Manuel du CT.pdf, proposition educative eclaireurs VF.pdf","qcm":{"ok":"Le début de la vie scoute","no":["Un grade, comme le passage de caporal à sergent","La récompense d'une bonne action quotidienne","Le couronnement du parcours d'éclaireur"]}},{"id":"t3-09","q":"Quel insigne sanctionne la promesse, et existe-t-il un insigne pour le 1er degré de compétence générale ?","a":"La promesse est sanctionnée par l'**insigne des SDS**. Il **n'y a pas d'insigne** pour le 1er degré de compétence générale, mais cette étape doit être pleinement vécue.","src":"La Progression Personnelle (1).pdf","qcm":{"ok":"L'insigne des SDS ; pas d'insigne pour le 1er degré","no":["Le badge à tête de biche ; une bande rouge pour le 1er degré","La cordelière kaki ; un flot vert pour le 1er degré","Les deux bandes blanches ; une étoile pour le 1er degré"]}},{"id":"t3-10","q":"Que doit acquérir le scout, après sa promesse, pour devenir « Engagé » ?","a":"Le **1er degré de compétence générale** : esprit scout, vie religieuse, sport, observation, contact nature, hygiène, promotion socio-économique, civisme… L'engagé est « celui qui retrousse ses manches ».","src":"Livret Carnet de Preuves.pdf, La Progression Personnelle (1).pdf","qcm":{"ok":"Le 1er degré de compétence générale","no":["Trois brevets de compétence d'animateur","Trois degrés dans deux séries de services","Le brevet de secouriste de la Croix-Rouge"]}},{"id":"t3-11","q":"Sur quels articles de la loi scoute l'engagé doit-il donner particulièrement l'exemple ?","a":"Les articles **4** (le scout est hospitalier, il est frère de tous) et **8** (le scout est maître de soi, il sourit et chante dans ses difficultés).","src":"Livret Carnet de Preuves.pdf","qcm":{"ok":"Les articles 4 et 8","no":["Les articles 1 et 3","Les articles 2 et 7","Les articles 5 et 10"]}},{"id":"t3-12","q":"Quelle est la condition pour devenir technicien ?","a":"Obtenir **au moins 3 degrés de compétence dans 2 séries de services différentes**, et savoir les mettre en pratique chaque fois que l'occasion se présente.","src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Au moins 3 degrés de compétence dans 2 séries différentes","no":["Au moins 2 degrés de compétence dans 3 séries différentes","Au moins 5 degrés de compétence dans une seule série","Au moins 3 brevets d'animateur dans 2 séries différentes"]}},{"id":"t3-13","q":"Combien de séries de services le carnet de preuves propose-t-il pour l'étape de technicien ?","a":"**Sept séries** selon *La Progression Personnelle*, par exemple « Art et Technique » (menuisier, couturier, maçon) ou « Pionnier » (cuisinier, campeur…).","src":"La Progression Personnelle (1).pdf","note":"Le Manuel du CP parle de six séries. La version Word du carnet en liste six (Art et techniques, Service dans l'Église, Beaux-arts, Contact, Sport, Ingéniosité pratique). La version PDF ajoute notamment une série « Pionnier ».","qcm":{"ok":"Sept séries","no":["Quatre séries","Cinq séries","Dix séries"]}},{"id":"t3-14","q":"Qui décide de l'attribution du badge de technicien ?","a":"Une **cour d'honneur**, convoquée à la suite des épreuves. Ses membres jugent de l'aptitude du jeune à recevoir le badge.","src":"La Progression Personnelle (1).pdf, manuel du CP.pdf","qcm":{"ok":"Une cour d'honneur convoquée après les épreuves","no":["Le conseil de patrouille, après un vote","Le commissaire de district, sur dossier","Le conseil de troupe, en fin d'année"]}},{"id":"t3-15","q":"Comment est fait le badge de technicien ?","a":"C'est une **tête de biche** traversée d'**une bande rouge horizontale**.","src":"La Progression Personnelle (1).pdf, manuel du CP.pdf","qcm":{"ok":"Une tête de biche traversée d'une bande rouge","no":["Une tête de biche traversée de deux bandes rouges","Une fleur de lys traversée d'une bande verte","Une tête de lion traversée d'une bande rouge"]}},{"id":"t3-16","q":"Comment est fait le badge d'animateur ?","a":"C'est une **tête de biche** traversée de **deux bandes rouges horizontales**.","src":"La Progression Personnelle (1).pdf, manuel du CP.pdf","qcm":{"ok":"Une tête de biche et deux bandes rouges","no":["Une tête de biche et trois bandes rouges","Une tête de biche et deux bandes blanches","Une fleur de lys et deux bandes rouges"]}},{"id":"t3-17","q":"Comment la cour d'honneur reconnaît-elle un animateur ?","a":"Elle réunit tous les animateurs, **après consultation des parents, professeurs ou patron**. Elle doit reconnaître un important effort sur soi et un exemple pour les autres. Le vote est **secret** et doit réunir les **¾ des voix**.","src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Vote secret réunissant les ¾ des voix","no":["Vote à main levée à la majorité simple","Vote secret à l'unanimité des présents","Vote secret réunissant les deux tiers des voix"]}},{"id":"t3-18","q":"Citez des brevets de compétence demandés pour devenir animateur.","a":"Par exemple : **acolyte**, **évangéliste**, **catéchiste-missionnaire**, **campeur**, **secouriste**, **sportif**. D'autres compétences pointues sont aussi demandées.","src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf","qcm":{"ok":"Acolyte, évangéliste, catéchiste-missionnaire, secouriste","no":["Menuisier, couturier, maçon, tisserand","Correspondant de presse, interprète, guide touristique","Musicien, sculpteur, bibliothécaire, meneur artiste"]}},{"id":"t3-19","q":"À quoi l'étape d'animateur prépare-t-elle le garçon ?","a":"L'animateur est un **éclaireur accompli**. Il s'initie au **métier de responsable**, à l'**esprit d'équipe et d'entreprise**, pour préparer son entrée dans la **Communauté (la Route)**.","src":"La Progression Personnelle (1).pdf, Manuel du CT.pdf","qcm":{"ok":"Au métier de responsable, pour entrer à la Route","no":["Au rôle de vieux loup, pour encadrer la meute","À la fonction de commissaire de district","Au métier de chef de troupe, dès ses 16 ans"]}},{"id":"t3-20","q":"Comment doit-on évaluer la progression d'un garçon ?","a":"**Pas comme un examen** à un moment ponctuel, mais **chaque fois qu'il y a une activité** : à la maison, à l'école, partout. Faire ses preuves n'est pas une épreuve, c'est montrer qu'on a évolué.","src":"La Progression Personnelle (1).pdf","qcm":{"ok":"En continu, à chaque activité, partout","no":["Par un examen écrit à la fin de l'année","Par une épreuve unique au camp d'été","Par un test oral devant le commissaire"]}},{"id":"t3-21","q":"Que fait le garçon dans son carnet de preuves quand il a maîtrisé une technique ?","a":"Il **colorie** (au crayon de couleur si possible) **le cercle** réservé à cette technique. Il peut ainsi contrôler sans cesse ses progrès.","src":"Livret Carnet de Preuves.pdf, La Progression Personnelle (1).pdf","qcm":{"ok":"Il colorie le cercle réservé à cette technique","no":["Il colle le timbre de la troupe sur la page","Il recopie la technique dans le cahier de bord","Il demande au CP de raturer la ligne"]}},{"id":"t3-22","q":"De combien de rubriques et d'étapes se compose le carnet de preuves ?","a":"**4 rubriques** et **3 étapes de progression** : volontariat, promesse et 1er degré (Engagé), degrés de compétence (Technicien), brevets de compétence (Animateur).","src":"La Progression Personnelle (1).pdf","note":"Le Manuel du CP le décrit en quatre parties (volontaire, engagé, technicien, animateur), plus une partie sur les notions de base du scoutisme.","qcm":{"ok":"4 rubriques et 3 étapes de progression","no":["3 rubriques et 4 étapes de progression","5 rubriques et 3 étapes de progression","4 rubriques et 5 étapes de progression"]}},{"id":"t3-23","q":"Comment est constituée une patrouille scoute ?","a":"D'une bande de **six à huit jeunes âgés de 13 à 17 ans**. C'est la **cellule de base** de la troupe.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","note":"Le Manuel du CP indique des jeunes de 12 à 17 ans. Le projet éducatif parle à un endroit de « sept ou huit jeunes ».","qcm":{"ok":"Six à huit jeunes de 13 à 17 ans","no":["Quatre à six jeunes de 11 à 15 ans","Huit à douze jeunes de 13 à 17 ans","Six à huit jeunes de 15 à 20 ans"]}},{"id":"t3-24","q":"Combien de patrouilles compte une troupe ?","a":"**De 2 à 4 patrouilles au plus.** « Ce n'est pas la troupe qui est divisée en quatre patrouilles, mais bien quatre patrouilles qui forment une troupe. »","src":"Manuel du CT.pdf, proposition educative eclaireurs VF.pdf","qcm":{"ok":"De 2 à 4 patrouilles au plus","no":["De 3 à 6 patrouilles au plus","De 4 à 8 patrouilles au plus","De 1 à 3 patrouilles au plus"]}},{"id":"t3-25","q":"Qui compose la maîtrise de la troupe ?","a":"Le **chef de troupe (CT)**, son ou ses **assistants** et l'**aumônier**. La maîtrise veille sur la bonne marche de la troupe ; ses chefs doivent donner de bons exemples de vie.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","note":"Le Manuel du CP ajoute les conseillers.","qcm":{"ok":"Le CT, ses assistants et l'aumônier","no":["Le CT, les CP et les seconds","Le chef de groupe, le CT et le trésorier","Le CT, l'aumônier et les parents délégués"]}},{"id":"t3-26","q":"Qu'est-ce que la cour d'honneur, et que décide-t-elle ?","a":"C'est l'**organe directeur** de la troupe et la **gardienne de la loi scoute**. Elle est « **loin d'être un tribunal** » : c'est un lieu d'accueil, d'échange et de décision. Elle décide des **objectifs de l'année**, des **admissions à la promesse**, de la **progression et des sanctions**.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","qcm":{"ok":"L'organe directeur de la troupe, gardien de la loi","no":["Le tribunal qui juge les fautes des scouts","L'instance de formation technique des CP et SP","L'assemblée de toute la troupe qui évalue les activités"]}},{"id":"t3-27","q":"Quand la cour d'honneur se réunit-elle ?","a":"Seulement dans des **circonstances particulières** : en **début d'année** pour fixer les objectifs, à une **demande d'admission à la promesse**, et exceptionnellement lors d'un **événement important**.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","note":"Le Manuel du CP dit au contraire qu'elle « se réunit régulièrement » pour évaluer le fonctionnement de la troupe.","qcm":{"ok":"En début d'année, pour une promesse, ou pour un fait important","no":["Chaque semaine, après la réunion de troupe","Tous les quinze jours, avec le conseil de patrouille","Uniquement le dernier jour du camp d'été"]}},{"id":"t3-28","q":"Qui préside la cour d'honneur, et de quel pouvoir dispose-t-il ?","a":"Le **chef de troupe**. Il dirige les débats, conseille et possède un **droit de veto** sur toutes les décisions. Les assistants le conseillent ; le secrétaire est généralement un assistant.","src":"Manuel du CT.pdf","qcm":{"ok":"Le chef de troupe, avec un droit de veto","no":["L'aumônier, avec un droit de veto","Le plus ancien CP, avec une voix prépondérante","Le commissaire de district, avec une voix consultative"]}},{"id":"t3-29","q":"Les délibérations de la cour d'honneur sont-elles publiques ? Peut-on revenir sur une décision ?","a":"Les délibérations sont **secrètes** : rien ne doit sortir de la CDH. **Seule une autre cour d'honneur** peut amender une décision, à condition d'avoir des **faits nouveaux**.","src":"Manuel du CT.pdf","qcm":{"ok":"Secrètes ; seule une autre CH peut l'amender, sur faits nouveaux","no":["Publiques ; elles sont lues au conseil de troupe suivant","Secrètes ; le CT peut seul modifier la décision ensuite","Publiques ; elles sont affichées au local de la troupe"]}},{"id":"t3-30","q":"Qui compose le conseil des chefs, et quel est son rôle ?","a":"La **maîtrise** et les **chefs de patrouille**. Son rôle est d'**organiser la vie de la troupe** et de **coordonner toutes ses activités**.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","note":"Le Manuel du CP y ajoute les SP et l'aumônier. Le projet éducatif lui donne la même composition que la cour d'honneur. La session de Yeumbeul précise que seuls le CT et les CP y votent.","qcm":{"ok":"Maîtrise et CP ; organise et coordonne la vie de la troupe","no":["Toute la troupe ; évalue les activités avec tous les jeunes","Membres de la patrouille ; choisit ses moyens d'action","Maîtrise, CP et SP ; forme les CP aux techniques scoutes"]}},{"id":"t3-31","q":"Qu'est-ce que la haute patrouille ?","a":"Elle réunit la **maîtrise**, les **CP** et les **SP**. Son rôle est de **former les CP et leurs seconds** aux techniques scoutes. C'est « **l'université du chef de patrouille** » et la patrouille modèle de la troupe.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf, manuel du CP.pdf","qcm":{"ok":"Maîtrise, CP et SP : l'université du chef de patrouille","no":["Les meilleurs techniciens : l'équipe de rallye de la troupe","Les CP seuls : le tribunal d'honneur de la troupe","Les animateurs : le conseil qui vote les promesses"]}},{"id":"t3-32","q":"Qu'est-ce que le conseil de troupe ?","a":"Il réunit **toute la troupe**. Son rôle est d'**évaluer les activités** de la troupe avec tous les jeunes. Selon le Manuel du CT, il peut se tenir **une fois tous les deux mois**.","src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf","qcm":{"ok":"Toute la troupe ; évalue les activités, environ tous les 2 mois","no":["Les CP et la maîtrise ; fixe les objectifs, chaque semaine","La maîtrise seule ; juge les sanctions, une fois par an","Les SP et le CT ; prépare les camps, tous les 15 jours"]}},{"id":"t3-33","q":"Qui préside le conseil de patrouille, et à quelle fréquence se tient-il ?","a":"Il est **présidé par le CP**, qui dirige les discussions. C'est le « **cœur de la patrouille** ». Il se tient **au moins tous les 15 jours**, et chaque fois que le besoin s'en fait sentir.","src":"Manuel du CT.pdf, manuel du CP.pdf","note":"Le projet éducatif dit « pas moins de deux fois par trimestre », pas plus d'une demi-heure. Composition : tous les membres selon Structures et Instances, seulement ceux qui ont fait leur promesse selon le Manuel du CP.","qcm":{"ok":"Le CP, au moins tous les quinze jours","no":["Le CT, une fois par mois","Le SP, une fois par trimestre","L'aumônier, chaque semaine"]}},{"id":"t3-34","q":"Comment le second de patrouille (SP) est-il choisi, et quel est son rôle ?","a":"Il est **choisi par le CP**, avec l'assentiment de la **maîtrise**. Il **aide le CP** et le **remplace en son absence**. Le CP et son second forment « **une paire d'amis** ».","src":"manuel du CP.pdf, proposition educative eclaireurs VF.pdf","note":"Le projet éducatif dit « en accord avec la cour d'honneur ».","qcm":{"ok":"Choisi par le CP avec l'accord de la maîtrise","no":["Élu par la patrouille au vote secret","Nommé par l'aumônier après la promesse","Désigné d'office : le plus âgé de la patrouille"]}},{"id":"t3-35","q":"Selon le Manuel du CT, comment se déroule la désignation d'un CP avant son investiture ?","a":"Le CP qui veut servir sa patrouille fait une **demande manuscrite au chef de troupe**. Celui-ci réunit un **conseil de maîtrise**, puis convoque l'intéressé en **cour d'honneur**. C'est la **CH qui décide** de l'investiture.","src":"Manuel du CT.pdf","note":"Les sources divergent : le Manuel du CP dit que le CP « a été nommé par ses frères de patrouille ». Le projet éducatif dit que le chef d'unité l'appelle et le nomme après avis de la CH.","qcm":{"ok":"Demande manuscrite au CT, puis décision de la CH","no":["Élection à main levée en conseil de troupe","Nomination par lettre du commissaire de district","Tirage au sort parmi les SP en haute patrouille"]}},{"id":"t3-36","q":"Que reçoit le nouveau CP lors de la cérémonie d'investiture ?","a":"La **cordelière kaki** et son **bâton portant le fanion** de sa patrouille. Les **deux bandes blanches** sont cousues d'avance à leur place.","src":"Manuel du CT.pdf","qcm":{"ok":"La cordelière kaki et le bâton avec le fanion","no":["Le foulard de région et le carnet de preuves","La flamme scoute et le livre d'or de la troupe","Un sifflet et le cahier de bord de la patrouille"]}},{"id":"t3-37","q":"Que représentent les deux bandes blanches du CP selon la session de Yeumbeul ?","a":"Sa **double mission** : **faire de ses garçons une patrouille**, et **faire de ses garçons des scouts**.","src":"Session le Role du chef de patrouille camp CP SP Yeumbeul.docx","qcm":{"ok":"Faire de ses garçons une patrouille et des scouts","no":["La fidélité à Dieu et la loyauté à la patrie","Le CP et son second, unis comme deux amis","Deux années d'ancienneté dans la troupe"]}},{"id":"t3-38","q":"Selon Baden-Powell, quelle part de bon y a-t-il au moins dans chaque garçon ?","a":"**Au moins 5 %**. C'est au CP de le découvrir et de l'épanouir **jusqu'à 90 ou 95 %**.","src":"Session le Role du chef de patrouille camp CP SP Yeumbeul.docx","qcm":{"ok":"Au moins 5 %, à développer jusqu'à 90 ou 95 %","no":["Au moins 10 %, à développer jusqu'à 100 %","Au moins 50 %, à développer jusqu'à 80 %","Au moins 1 %, à développer jusqu'à 50 %"]}},{"id":"t3-39","q":"Quelles sont les trois grandes idées d'une bonne direction que doit appliquer tout CP ?","a":"**Observer, Juger, Décider.** C'est le message « Ose être un chef ! ».","src":"Session le Role du chef de patrouille camp CP SP Yeumbeul.docx","qcm":{"ok":"Observer, Juger, Décider","no":["Voir, Juger, Agir","Prévoir, Organiser, Commander","Écouter, Ordonner, Contrôler"]}},{"id":"t3-40","q":"Complétez la phrase de B-P : « Attendez beaucoup de vos CP et … »","a":"« … **9 sur 10** ils se révéleront à la hauteur de vos attentes. » Le meilleur progrès se produit dans les troupes où pouvoir et responsabilité sont réellement entre les mains des CP.","src":"manuel du CP.pdf","qcm":{"ok":"9 sur 10 ils se révéleront à la hauteur","no":["8 sur 10 ils se révéleront à la hauteur","1 sur 2 se révélera à la hauteur","99 sur 100 se révéleront à la hauteur"]}},{"id":"t3-41","q":"Selon le projet éducatif, quel rôle d'intermédiaire le CP joue-t-il ?","a":"Il est le **représentant des jeunes auprès de la maîtrise** et le **représentant des adultes auprès des jeunes**. Le CP n'est pas une « courroie de transmission » des ordres de la maîtrise.","src":"proposition educative eclaireurs VF.pdf","qcm":{"ok":"Représentant des jeunes auprès des adultes, et inversement","no":["Courroie de transmission des ordres de la maîtrise","Représentant de la troupe auprès du district","Adjoint du CT chargé de la discipline"]}},{"id":"t3-42","q":"Quelles attitudes la maîtrise doit-elle éviter envers les CP ?","a":"Trois attitudes : **intervenir directement dans une patrouille sans passer par le CP** ; **critiquer un CP devant sa patrouille** ; **abandonner le CP et sa patrouille à leur sort**.","src":"proposition educative eclaireurs VF.pdf","qcm":{"ok":"Intervenir dans une patrouille sans passer par le CP","no":["Réunir régulièrement les CP en haute patrouille","Rencontrer chaque CP lors d'un contact individuel","Laisser la patrouille choisir son totem et sa devise"]}},{"id":"t3-43","q":"Qui attribue les postes d'action dans la patrouille ?","a":"Le **conseil de patrouille**. Les postes sont répartis selon les qualités, les aptitudes, les goûts et les besoins de la patrouille. Les patrouillards rendent compte au conseil de patrouille.","src":"Manuel du CT.pdf","note":"Le Manuel du CP ajoute que chacun change de rôle à la fin de chaque trimestre, seuls le CP et le SP ayant des rôles permanents. Le Manuel du CT parle pourtant de « fonctions permanentes ».","qcm":{"ok":"Le conseil de patrouille","no":["Le chef de troupe","La cour d'honneur","Le conseil de troupe"]}},{"id":"t3-44","q":"Quel est le rôle du secrétaire de patrouille selon le Manuel du CT ?","a":"Il **garde le livre d'or et le cahier de bord**, fait les convocations, s'occupe du courrier et écrit dans le cahier de bord les **rapports** des sorties, explorations et camps.","src":"Manuel du CT.pdf","note":"Le document Cahier de Bord et Livre d'Or dit que le livre d'or est jalousement gardé par le CP.","qcm":{"ok":"Il garde le livre d'or et le cahier de bord","no":["Il tient la caisse et le registre des comptes","Il gère le matériel et en fait l'inventaire","Il prépare les prières et les célébrations"]}},{"id":"t3-45","q":"Selon le Manuel du CT, de quoi l'intendant est-il responsable ?","a":"Du **matériel de la patrouille** : ameublement, matériel de camp, outillage, équipement. Il en tient l'**inventaire** et en assure l'entretien avant et après les camps.","src":"Manuel du CT.pdf","note":"Pour le Manuel du CP, l'intendant s'occupe du ravitaillement et des vivres, et c'est le « matérialiste » qui gère l'équipement.","qcm":{"ok":"Du matériel de la patrouille et de son inventaire","no":["Des cotisations et du registre des comptes","Des cartes, boussoles et sorties d'orientation","Du cahier des chants, danses et jeux"]}},{"id":"t3-46","q":"Quelles sont les cinq parties du livre d'or ?","a":"1. Présentation de l'**animal totem**. 2. Présentation du **saint patron**. 3. Présentation de la **patrouille** (devise, loi, prière, règlements, hymne…). 4. **Fiche signalétique** des membres. 5. **Dédicaces**.","src":"Cahier De Bord et Livre D_Or.pdf","qcm":{"ok":"Totem, saint patron, patrouille, fiche signalétique, dédicaces","no":["Patrouille, troupe, volet administratif, comptes rendus, photos","Totem, programme, assiduité, cotisations, dédicaces","Historique de B-P, loi scoute, uniforme, insignes, chants"]}},{"id":"t3-47","q":"Quelles sont les quatre parties du cahier de bord ?","a":"1. Présentation de la **patrouille** (comme dans le livre d'or). 2. Présentation de la **troupe** (maîtrise et haute patrouille). 3. **Volet administratif**. 4. **Comptes rendus** (camps, sorties, conseils de patrouille…).","src":"Cahier De Bord et Livre D_Or.pdf","qcm":{"ok":"Patrouille, troupe, volet administratif, comptes rendus","no":["Totem, saint patron, fiche signalétique, dédicaces","Patrouille, programme, inventaire, chants","Troupe, carnet de preuves, budget, dédicaces"]}},{"id":"t3-48","q":"Que contient le volet administratif du cahier de bord ?","a":"L'**état nominatif**, le **programme de la patrouille** (en accord avec celui de la troupe), le **tableau d'assiduité** (présence-absence) et l'**état des cotisations**.","src":"Cahier De Bord et Livre D_Or.pdf, Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf","qcm":{"ok":"État nominatif, programme, assiduité, cotisations","no":["Fiche signalétique, dédicaces, autographes, photos","Loi, prière, hymne et règlement de patrouille","Inventaire, menus, trousse de secours, cartes"]}},{"id":"t3-49","q":"Selon le document Cahier de Bord et Livre d'Or, qui garde le livre d'or ?","a":"Le **CP**, qui le garde **jalousement** car il a « une valeur d'or ». C'est « l'**âme et l'histoire** de la patrouille ».","src":"Cahier De Bord et Livre D_Or.pdf","note":"Le Manuel du CT confie le livre d'or au secrétaire. Le Manuel du CP dit qu'il est gardé par le CP, mais placé sous la responsabilité du secrétaire ou de l'archiviste.","qcm":{"ok":"Le CP, qui le garde jalousement","no":["Le CT, au local de la troupe","L'aumônier, à la paroisse","Le trésorier, avec la caisse de patrouille"]}},{"id":"t3-50","q":"Quelle erreur faut-il éviter dans la partie « Dédicaces » du livre d'or ?","a":"**Accumuler des signatures sans texte.** Une signature sans texte ne veut rien dire : il faut rédiger de vraies dédicaces. Les signatures des visiteurs peuvent aller dans une « chasse aux autographes », en partant de la fin du livre.","src":"Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf","qcm":{"ok":"Accumuler des signatures sans texte","no":["Rédiger des dédicaces pour d'anciens membres","Raconter les exploits de la patrouille","Laisser un visiteur écrire un petit mot"]}},{"id":"t3-51","q":"À qui sont dédiées la prière de patrouille et l'hymne de patrouille ?","a":"La **prière** est dédiée au **saint patron**. L'**hymne** est dédié à l'**animal totem**. L'erreur à éviter est d'inverser les deux.","src":"Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf, manuel du CP.pdf","qcm":{"ok":"Prière au saint patron, hymne à l'animal totem","no":["Prière à l'animal totem, hymne au saint patron","Prière et hymne, tous deux au saint patron","Prière à Baden-Powell, hymne à l'animal totem"]}},{"id":"t3-52","q":"Combien d'articles conseille-t-on au maximum pour la loi de patrouille, et pourquoi ?","a":"Il n'y a pas de limite fixée, mais on préfère **ne pas dépasser 5 articles**, car la loi scoute dit déjà comment le scout doit se comporter. La loi de patrouille renforce son caractère sans remplacer la loi scoute.","src":"Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf","qcm":{"ok":"5 articles au plus","no":["10 articles au plus","3 articles exactement","12 articles au moins"]}},{"id":"t3-53","q":"Que doit exprimer la devise de patrouille ?","a":"Une **résolution, un idéal, un objectif à atteindre**, et **non une étape déjà franchie**. On évite les devises humoristiques ou du genre « Vaincre ou mourir », et surtout pas de « sanglant » ou de « tueur ».","src":"manuel du CP.pdf","qcm":{"ok":"Un objectif à atteindre, pas une étape franchie","no":["Une victoire déjà remportée par la patrouille","Une plaisanterie propre à la patrouille","Un défi du type « Vaincre ou mourir »"]}},{"id":"t3-54","q":"Qui porte le fanion de patrouille, et quelles règles le protègent ?","a":"**Seul le CP** le porte. Il peut le confier à son **second** en son absence. Le fanion n'est **jamais couché au sol** et **ne se hisse pas au mât**. Il est symbole de continuité.","src":"manuel du CP.pdf","qcm":{"ok":"Le CP seul, ou son second en son absence","no":["Le plus jeune de la patrouille, à tour de rôle","Le secrétaire, gardien des traditions","Un assistant chef de troupe, en cérémonie"]}},{"id":"t3-55","q":"Quelles sont les dimensions du fanion de patrouille ?","a":"Une **ogive de 25 cm de haut et 40 cm de large**, sur une **hampe de 1,40 m**. L'animal totem y est représenté, la tête tournée vers la hampe.","src":"manuel du CP.pdf","qcm":{"ok":"Ogive de 25 × 40 cm, hampe de 1,40 m","no":["Ogive de 40 × 60 cm, hampe de 2,10 m","Carré de 1 m, hampe de 2,10 m","Triangle de 80 cm, hampe de 1,80 m"]}},{"id":"t3-56","q":"Pourquoi l'équipe nationale de la branche verte a-t-elle réformé les noms des patrouilles ?","a":"Pour **coller aux réalités de la faune africaine** et **uniformiser** les troupes de tout le pays, en respectant les usages de la branche verte. Les fanions doivent se mettre rapidement aux normes nationales.","src":"Patrouilles Africaines.pdf","qcm":{"ok":"Pour coller à la faune africaine et uniformiser les troupes","no":["Pour reprendre les noms des patrouilles de Brownsea","Pour donner à chaque région ses propres totems","Pour remplacer les totems par des noms de saints"]}},{"id":"t3-57","q":"Quelles sont les couleurs et le cri du jour de la patrouille Lion ?","a":"**Rouge et jaune** : le rouge pour l'animal, le jaune pour son milieu de vie (lion rouge sur fond jaune). Cri du jour : « **Lion toujours courageux** ». Cri de nuit : le **rugissement**.","src":"Patrouilles Africaines.pdf","qcm":{"ok":"Rouge et jaune ; « Lion toujours courageux »","no":["Jaune et vert ; « Lion toujours rapide »","Noir et jaune ; « Lion toujours puissant »","Rouge et bleu ; « Lion toujours royal »"]}},{"id":"t3-58","q":"Quel est le cri du jour de la patrouille Requin ?","a":"« **Requin jusqu'au sang** ». Ses couleurs sont le **blanc et le bleu**, et son cri de nuit est le « brizz ».","src":"Patrouilles Africaines.pdf","note":"Ce cri va contre le Manuel du CP, qui demande d'éviter les devises de type « sanglant » ou « tueur ».","qcm":{"ok":"« Requin jusqu'au sang »","no":["« Requin toujours féroce »","« Requin toujours sauveur »","« Requin toujours aux aguets »"]}},{"id":"t3-59","q":"À Brownsea en 1907, quelle couleur de nœud d'épaule distinguait chaque patrouille ?","a":"**Loups : bleu**, **taureaux : vert**, **courlis : jaune**, **corbeaux : rouge**. Ces nœuds en laine sont à l'origine des **flots de patrouille**.","src":"manuel du CP.pdf","qcm":{"ok":"Loups bleu, taureaux vert, courlis jaune, corbeaux rouge","no":["Loups rouge, taureaux bleu, courlis vert, corbeaux jaune","Loups vert, taureaux jaune, courlis bleu, corbeaux rouge","Loups jaune, taureaux rouge, courlis bleu, corbeaux vert"]}},{"id":"t3-60","q":"Selon le Système de fonctionnement, à quel public s'adressent les sessions « Le rôle du CP et de son second » et « Tenue du cahier de bord et du livre d'or » ?","a":"À la **formation des CP/SP**. On y trouve aussi la prière des chefs, la gestion des cotisations de patrouille, l'organisation d'un camp de patrouille et le système de patrouille.","src":"Systeme de Fonctionnement.pdf","qcm":{"ok":"À la formation des CP et SP","no":["Aux sessions pour les volontaires","Aux sessions pour les techniciens","Au tronc commun de toute la troupe"]}}]}$xxb$::jsonb, now()),
  ('cards-4', $xxb${"theme":4,"cards":[{"id":"t4-01","q":"Quel est le nom complet de l'association créée par les Statuts de 2018, et son sigle ?","a":"L'association **« Scouts & Guides du Sénégal »**, en abrégé **S.G.D.S.**, créée entre les membres du Mouvement des Scouts du Sénégal et du Mouvement des Guides du Sénégal.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Scouts & Guides du Sénégal (S.G.D.S.)","no":["Confédération Sénégalaise du Scoutisme (C.S.S.)","Union des Scouts et Guides du Sénégal (U.S.G.S.)","Fédération des Scouts du Sénégal (F.S.S.)"]}},{"id":"t4-02","q":"Quels sont les insignes des Scouts du Sénégal et des Guides du Sénégal ?","a":"Les Scouts ont pour insigne la **fleur de lys stylisée**, les Guides le **trèfle**.","src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Scouts : fleur de lys ; Guides : trèfle","no":["Scouts : trèfle ; Guides : fleur de lys","Scouts : fleur de lys ; Guides : étoile","Scouts : croix potencée ; Guides : trèfle"]}},{"id":"t4-03","q":"À quelles organisations le Mouvement des Scouts du Sénégal est-il affilié selon les Statuts 2018 ?","a":"À l'**OMMS** (Organisation Mondiale du Mouvement Scout), à la **CICS** (Conférence Internationale Catholique du Scoutisme), à la **CSS** (Confédération Sénégalaise du Scoutisme) et au **CNJS** (Conseil National de la Jeunesse du Sénégal).","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"OMMS, CICS, CSS et CNJS","no":["AMGE, CICG, CSS et CNJS","OMMS, AMGE, CICG et CSS","OMMS, CICG, CNJS et AMGE"]}},{"id":"t4-04","q":"À quelles organisations le Mouvement des Guides du Sénégal est-il affilié ?","a":"À l'**AMGE** (Association Mondiale des Guides et des Éclaireuses), à la **CICG** (Conférence Internationale Catholique du Guidisme) et au **CNJS**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"AMGE, CICG et CNJS","no":["OMMS, CICS et CNJS","AMGE, CICS et CSS","OMMS, CICG et CSS"]}},{"id":"t4-05","q":"Par quelle loi l'Association des Scouts et Guides du Sénégal est-elle régie ?","a":"Par la **loi n° 68-08 du 26 mars 1968**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Loi 68-08 du 26 mars 1968","no":["Loi 62-08 du 26 mars 1962","Loi 68-18 du 16 mai 1968","Loi 78-08 du 26 mars 1978"]}},{"id":"t4-06","q":"Quel est le but de l'Association SGDS selon l'article 2 des Statuts ?","a":"**Coordonner l'action des deux Mouvements** en faveur de l'**éducation et de la formation des jeunes**, filles et garçons, au Sénégal, dans le respect et la diversité des races et des nationalités. Elle accueille tous les jeunes croyants et elle est **apolitique**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Coordonner les deux Mouvements pour éduquer et former les jeunes","no":["Représenter les jeunes catholiques auprès de l'État sénégalais","Gérer les écoles catholiques et les paroisses du Sénégal","Organiser les camps nationaux de toutes les associations scoutes"]}},{"id":"t4-07","q":"Quelles sont les catégories de membres de l'Association selon les Statuts 2018 ?","a":"Les **membres adhérents** (les jeunes), les **Chefs et Cheftaines**, les **Conseillers(ères) spirituels(les)**, les **membres d'honneur** et les **Ressources adultes**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Adhérents, chefs, conseillers spirituels, membres d'honneur, ressources adultes","no":["Adhérents, chefs, parents d'élèves, membres bienfaiteurs, anciens scouts","Adhérents, chefs, aumôniers de paroisse, membres fondateurs, sympathisants","Jeunes, chefs, commissaires, membres actifs, membres associés, donateurs"]}},{"id":"t4-08","q":"Comment se perd la qualité de membre de l'Association ?","a":"Par **démission motivée et expliquée** de l'intéressé, ou par **radiation** prononcée pour raisons graves par le **Conseil Général** ou par les instances de base érigées en **Cour d'honneur**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Démission motivée ou radiation par le Conseil Général ou une Cour d'honneur","no":["Démission orale ou exclusion par le chef d'unité seul","Non-paiement de la cotisation ou décision du curé de la paroisse","Atteinte de 26 ans ou radiation par l'Assemblée Régionale"]}},{"id":"t4-09","q":"Comment l'Association est-elle découpée géographiquement (art. 5 des Statuts) ?","a":"Implantée sur tout le territoire national, elle est découpée en **régions et districts** scouts et guides, **groupes/ménies** et **unités**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Régions, districts, groupes/ménies et unités","no":["Diocèses, paroisses, groupes et patrouilles","Départements, communes, districts et unités","Zones, secteurs, groupes et sizaines"]}},{"id":"t4-10","q":"Qu'est-ce que l'Assemblée Générale Ordinaire (AGO) et à quel rythme se réunit-elle ?","a":"C'est l'**instance suprême délibérante et légiférante** de l'Association. Elle se réunit **une fois tous les trois ans**, sur convocation du/de la Président(e).","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Instance suprême, réunie une fois tous les 3 ans","no":["Instance suprême, réunie une fois par an","Organe consultatif, réuni une fois tous les 2 ans","Exécutif national, réuni une fois par trimestre"]}},{"id":"t4-11","q":"Quels délais les Statuts fixent-ils pour les documents de l'AGO ?","a":"Les documents officiels à discuter sont envoyés **deux mois à l'avance** ; les documents et procès-verbaux issus de l'AGO sont envoyés aux participants **dans les quatre mois** qui suivent.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Documents 2 mois avant ; procès-verbaux dans les 4 mois","no":["Documents 1 mois avant ; procès-verbaux dans les 2 mois","Documents 3 mois avant ; procès-verbaux dans les 6 mois","Documents 15 jours avant ; procès-verbaux dans le mois"]}},{"id":"t4-12","q":"Quel est le quorum de l'AGO et que se passe-t-il s'il n'est pas atteint ?","a":"Il faut la **majorité des Régions** et **au moins le tiers** des membres de droit, les **deux Mouvements** étant représentés. Sinon, une autre AGO est convoquée **dans les deux mois**, et ses décisions valent quel que soit le nombre de présents (deux Mouvements et majorité des Régions représentés).","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Majorité des Régions et un tiers des membres de droit","no":["Toutes les Régions et la moitié des membres de droit","Majorité des Régions et deux tiers des membres de droit","Un tiers des Régions et la majorité des membres de droit"]}},{"id":"t4-13","q":"Que fait l'AGO concernant les mandats ?","a":"L'AGO **donne ou renouvelle les mandats** du/de la **Président(e)**, du/de la **Trésorier(ère) Général(e)** et des **Commissaires Généraux**. Elle entend aussi le rapport moral, les rapports d'activités, le rapport financier et celui du commissaire aux comptes.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Président(e), Trésorier(ère) Général(e) et Commissaires Généraux","no":["Commissaires de Région, de District et Chefs de Groupe","Aumôniers nationaux, Permanents et Commissaires nationaux","Membres d'honneur, conseillers et équipes régionales"]}},{"id":"t4-14","q":"Qu'est-ce que la Session Nationale ?","a":"Une **instance de réflexion** convoquée **chaque année** où sont **choisis et élaborés les thèmes d'année** et le **programme commun** aux deux Mouvements. En cas de besoin, elle peut être érigée en Assemblée Générale Extraordinaire.","src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf","note":"Les Statuts 2018 disent qu'elle est convoquée par le/la Président(e) ; le Règlement intérieur dit qu'elle est convoquée par le Conseil Général.","qcm":{"ok":"Instance annuelle qui choisit le thème d'année","no":["Instance triennale qui élit le Président","Instance mensuelle qui gère les finances","Instance annuelle qui investit les chefs d'unité"]}},{"id":"t4-15","q":"Quel est le rôle du Conseil Général et à quelle fréquence se réunit-il ?","a":"C'est l'**Exécutif de l'Association au niveau national** : il prépare l'ordre du jour de l'AGO, de l'AGE et de la Session nationale et exécute leurs décisions. Présidé par le/la Président(e), il se réunit **au moins une fois par trimestre**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Exécutif national, au moins une fois par trimestre","no":["Organe consultatif, une fois par an","Instance suprême, une fois tous les trois ans","Exécutif national, une fois par semestre"]}},{"id":"t4-16","q":"Qu'est-ce que le Haut Conseil et qui le compose ?","a":"Un **organe consultatif** qui assiste le/la Président(e). Il comprend le/la **Président(e)**, le **Commissaire Général des Scouts**, la **Commissaire Générale des Guides**, le/la **Trésorier(ère) Général(e)** et des conseillers (**3 au maximum**).","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Organe consultatif : Président, 2 Commissaires Généraux, Trésorier, 3 conseillers max","no":["Organe exécutif : Président, équipes nationales, Trésorier, 5 conseillers max","Organe consultatif : Président, aumôniers nationaux, Trésorier, 2 conseillers max","Organe de contrôle : 2 commissaires aux comptes et 3 membres d'honneur"]}},{"id":"t4-17","q":"Quel rôle les Statuts donnent-ils au/à la Président(e) de l'Association ?","a":"Il/elle est le **garant moral** de l'Association. Il/elle convoque et préside le **Conseil Général**, le **Haut Conseil**, l'**AGO**, l'**AGE** et la **Session Nationale**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Garant moral ; préside Conseil Général, Haut Conseil, AG et Session","no":["Chef exécutif ; dirige les Équipes nationales et nomme les chefs d'unité","Trésorier ; tient seul les comptes bancaires et signe les dépenses","Aumônier ; responsable de la formation religieuse des deux Mouvements"]}},{"id":"t4-18","q":"Combien de temps dure le mandat du/de la Président(e) de l'Association et combien de fois peut-il être renouvelé ?","a":"**Trois ans**, renouvelable **une fois**. Le/la Président(e) est élu(e) par l'AGO à la majorité absolue des voix, les deux Mouvements obligatoirement représentés.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"3 ans, renouvelable une fois","no":["4 ans, renouvelable une fois","3 ans, renouvelable deux fois","5 ans, non renouvelable"]}},{"id":"t4-19","q":"Combien de commissaires aux comptes l'AGO élit-elle et quelle est la durée de leur mandat ?","a":"**Deux** commissaires aux comptes, qui **ne sont pas membres du Conseil Général**. Mandat de **3 ans renouvelable deux fois**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Deux, pour 3 ans renouvelables deux fois","no":["Un seul, pour 3 ans renouvelables une fois","Trois, pour 2 ans renouvelables deux fois","Deux, pour 4 ans non renouvelables"]}},{"id":"t4-20","q":"Comment sont réparties les voix pour l'élection du Président, des Commissaires Généraux, du Trésorier Général et des commissaires aux comptes ?","a":"**Haut Conseil : 2 voix** (dont celle du Président) ; **chaque équipe nationale : 6 voix** ; **chaque équipe régionale : 6 voix** ; **chaque district : 2 voix**. Les 6 voix supposent au moins 6 membres présents, sinon prorata.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Haut Conseil 2, équipe nationale 6, équipe régionale 6, district 2","no":["Haut Conseil 6, équipe nationale 4, équipe régionale 2, district 1","Haut Conseil 2, équipe nationale 4, équipe régionale 4, district 2","Haut Conseil 1, équipe nationale 6, équipe régionale 3, district 1"]}},{"id":"t4-21","q":"Qui peut être électeur ou éligible dans les instances de l'Association ?","a":"Seuls les membres de chaque instance qui se sont **acquittés de leur cotisation-assurance**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Les membres à jour de leur cotisation-assurance","no":["Les membres ayant au moins cinq ans d'ancienneté","Les membres titulaires du badge de bois","Les membres ayant fait leur départ routier"]}},{"id":"t4-22","q":"Qu'est-ce que l'Assemblée Régionale Ordinaire (ARO) et que fait-elle ?","a":"C'est l'**organe suprême de décision de la Région**. Elle se réunit **tous les trois ans**, est présidée par le/la Commissaire de Région, entend le rapport moral et le rapport financier, et **élit le/la Commissaire de Région**. Ses membres doivent avoir **au moins 18 ans**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Organe suprême de la Région, tous les 3 ans ; élit le Commissaire de Région","no":["Organe consultatif de la Région, chaque année ; élit les chefs d'unité","Organe suprême de la Région, chaque trimestre ; élit le Président","Organe exécutif du district, tous les 2 ans ; élit les Chefs de Groupe"]}},{"id":"t4-23","q":"Qui compose le Conseil de District selon les Statuts 2018 ?","a":"Le/la **Commissaire de District**, les **Conseillers spirituels de District**, les **Chefs de Groupe** (Scouts) ou **Cheftaines de Ménie** (Guides), les **chefs/cheftaines d'unité** et leurs **assistants**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Commissaire, conseillers spirituels, chefs de groupe, chefs et assistants d'unité","no":["Commissaire de Région, équipe régionale, commissaires de district, trésorier","Commissaire de district, chefs de patrouille, parents d'élèves, curé","Président, Trésorier Général, Commissaires Généraux, membres d'honneur"]}},{"id":"t4-24","q":"À quelle fréquence se réunissent le Conseil Régional, le Conseil de District et le Conseil de Groupe, et comment décident-ils ?","a":"**Une fois par trimestre**, et exceptionnellement quand les circonstances l'exigent. Décisions à la **majorité absolue des membres présents**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Une fois par trimestre ; majorité absolue des présents","no":["Une fois par mois ; majorité simple des présents","Une fois par semestre ; majorité des deux tiers","Une fois par an ; unanimité des membres"]}},{"id":"t4-25","q":"Comment est désigné le Commissaire de District selon les Statuts 2018 ?","a":"Il est **élu par le Conseil de District** de son Mouvement, puis **confirmé et investi par son Commissaire de Région**. Mandat de **3 ans renouvelable une fois**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Élu par le Conseil de District, investi par le Commissaire de Région","no":["Nommé par le Commissaire Général, investi par le Président","Élu par l'Assemblée Régionale, investi par l'Équipe nationale","Nommé par le Chef de Groupe, investi par l'aumônier"]}},{"id":"t4-26","q":"Comment sont répartis les voix pour l'élection du Commissaire de District (Statuts 2018) ?","a":"**District (scout/guide) : 2 voix** ; **chaque Groupe/Ménie : 2 voix**.","src":"Statuts SGDS 2018.pdf","note":"Les Statuts de l'ASDS (2024) prévoient une autre répartition : Commissaire de District sortant 2 voix, Chef de Groupe 2 voix.","qcm":{"ok":"District 2 voix ; chaque Groupe/Ménie 2 voix","no":["District 6 voix ; chaque Groupe/Ménie 1 voix","District 1 voix ; chaque Groupe/Ménie 3 voix","District 2 voix ; chaque unité 1 voix"]}},{"id":"t4-27","q":"Comment sont répartis les voix pour l'élection du Chef de Groupe ou de la Cheftaine de Ménie (Statuts 2018) ?","a":"**1 voix** chacun pour : le **Chef de Groupe sortant**, **chaque chef d'unité**, **chaque assistant d'unité** et l'**aumônier**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"1 voix : sortant, chaque chef d'unité, chaque assistant, l'aumônier","no":["2 voix : sortant, chaque chef d'unité ; 1 voix : l'aumônier","1 voix : sortant, chaque chef de patrouille, chaque parent","2 voix : Commissaire de District ; 1 voix : chaque chef d'unité"]}},{"id":"t4-28","q":"Qui nomme et qui investit les Chefs et Cheftaines d'Unité selon les Statuts 2018 ?","a":"Ils sont **nommés chaque année par leur Chef de Groupe** (ou Cheftaine de Ménie) et **investis par leur Commissaire de District**.","src":"Statuts SGDS 2018.pdf","note":"Le Règlement intérieur dit que le Commissaire de District nomme et investit sur proposition du Chef de Groupe ; les Procédures SDS disent que le Commissaire Régional nomme.","qcm":{"ok":"Nommés par le Chef de Groupe, investis par le Commissaire de District","no":["Nommés par le Commissaire Général, investis par le Président","Nommés par l'aumônier, investis par le Chef de Groupe","Élus par les jeunes, investis par le Commissaire de Région"]}},{"id":"t4-29","q":"À quelle fréquence le Chef de Groupe rend-il compte de ses activités au Conseil de District ?","a":"Le Chef de Groupe (ou la Cheftaine de Ménie) fournit **tous les trois mois** un compte rendu d'activités au **Conseil de District**.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Tous les trois mois","no":["Tous les six mois","Une fois par an","Tous les mois"]}},{"id":"t4-30","q":"Quelle majorité faut-il pour modifier les Statuts SGDS 2018 ?","a":"Une AGO ou AGE **spécialement convoquée** (majorité des Régions et au moins le tiers des membres de droit), décidant à la **majorité des 2/3 des membres présents**, les deux Mouvements obligatoirement représentés.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Les 2/3 des présents, en AG spécialement convoquée","no":["Les 3/4 des présents, en Conseil Général","La majorité simple, en Session Nationale","L'unanimité, en Haut Conseil"]}},{"id":"t4-31","q":"Quelles sont les conditions de dissolution de l'Association SGDS ?","a":"Seule une **AGE spécialement convoquée** peut la prononcer, avec au moins la **majorité des Régions** et les **3/4 des membres de droit**. Sinon, nouvelle AGE dans les 2 mois, décision aux **2/3 des présents**. Les biens vont à une **structure de bienfaisance** en rapport avec l'Association.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"AGE avec majorité des Régions et 3/4 des membres de droit","no":["AGO avec un tiers des Régions et la moitié des membres","Conseil Général à l'unanimité de ses membres","Session Nationale avec 2/3 des Régions"]}},{"id":"t4-32","q":"D'où proviennent les ressources de l'Association selon l'article 36 des Statuts ?","a":"Des **cotisations-assurances annuelles** et souscriptions des membres, des **kermesses et soirées culturelles**, des **subventions** (État, collectivités, établissements, organismes nationaux et étrangers), de **ventes** (cartes de vœux, calendriers, revues) et de toute autre activité légale.","src":"Statuts SGDS 2018.pdf","qcm":{"ok":"Cotisations, manifestations, subventions et ventes diverses","no":["Uniquement les dons des paroisses et des diocèses","Uniquement les subventions de l'OMMS","Les cotisations et un impôt prélevé sur les groupes"]}},{"id":"t4-33","q":"Où et quand les Statuts SGDS 2018 et le Règlement intérieur ont-ils été faits ?","a":"Statuts : **à Gorée, le 1er septembre 2018**. Règlement intérieur : **à Joal, 31 août - 1er septembre 1991**.","src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Statuts à Gorée en 2018 ; Règlement intérieur à Joal en 1991","no":["Statuts à Joal en 2018 ; Règlement intérieur à Gorée en 1991","Statuts à Dakar en 2018 ; Règlement intérieur à Thiès en 1991","Statuts à Gorée en 2016 ; Règlement intérieur à Joal en 1983"]}},{"id":"t4-34","q":"Quelles sont les tranches d'âge des branches scoutes selon le Règlement intérieur ?","a":"**Meute** : Louveteaux de **7 à 12 ans** ; **Troupe** : Éclaireurs de **13 à 17 ans** ; **Communauté** : Routiers de **18 ans et au-delà**.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Louveteaux 7-12, Éclaireurs 13-17, Routiers 18 et plus","no":["Louveteaux 8-11, Éclaireurs 12-16, Routiers 17 et plus","Louveteaux 7-11, Éclaireurs 12-15, Routiers 16 et plus","Louveteaux 6-12, Éclaireurs 13-18, Routiers 19 et plus"]}},{"id":"t4-35","q":"Quelles sont les unités et tranches d'âge des branches guides selon le Règlement intérieur ?","a":"**Ronde** : Jeannettes de **7 à 11 ans** ; **Compagnie** : Guides de **12 à 15 ans** ; **Feu** : Guides Aînées de **15 ans et au-delà**.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Ronde 7-11, Compagnie 12-15, Feu 15 et plus","no":["Ronde 7-12, Compagnie 13-17, Feu 18 et plus","Ronde 8-11, Compagnie 12-16, Feu 17 et plus","Ronde 6-10, Compagnie 11-14, Feu 15 et plus"]}},{"id":"t4-36","q":"De quelles unités se composent un Groupe et une Ménie ?","a":"Le **Groupe** : une **Meute**, une **Troupe** et une **Communauté**. La **Ménie** : une **Ronde**, une **Compagnie** et un **Feu**.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Groupe : Meute, Troupe, Communauté ; Ménie : Ronde, Compagnie, Feu","no":["Groupe : Ronde, Troupe, Feu ; Ménie : Meute, Compagnie, Communauté","Groupe : Meute, Patrouille, Clan ; Ménie : Ronde, Équipe, Feu","Groupe : Meute, Troupe, Feu ; Ménie : Ronde, Compagnie, Communauté"]}},{"id":"t4-37","q":"Combien de groupes ou ménies compte un District selon le Règlement intérieur ?","a":"**Au minimum 2 et au maximum 6** groupes ou ménies, dans une zone bien délimitée et cohérente.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"De 2 à 6 groupes ou ménies","no":["De 3 à 8 groupes ou ménies","De 2 à 10 groupes ou ménies","De 4 à 6 groupes ou ménies"]}},{"id":"t4-38","q":"Comment sont organisées la Meute et la Troupe selon le Règlement intérieur ?","a":"**Meute** : **2 à 5 sizaines de 6 garçons**, chacune dirigée par un sizainier aidé d'un second. **Troupe** : **2 à 4 patrouilles de 5 à 8 garçons**, chacune dirigée par un chef de patrouille assisté d'un second.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Meute : 2 à 5 sizaines de 6 ; Troupe : 2 à 4 patrouilles de 5 à 8","no":["Meute : 3 à 6 sizaines de 8 ; Troupe : 2 à 5 patrouilles de 6 à 10","Meute : 2 à 4 sizaines de 5 ; Troupe : 3 à 6 patrouilles de 6 à 8","Meute : 2 à 5 sizaines de 8 ; Troupe : 2 à 4 patrouilles de 8 à 12"]}},{"id":"t4-39","q":"Dans quels cas siège la Cour d'honneur selon le Règlement intérieur ?","a":"Pour les **décisions importantes**, les **investitures** des chefs et cheftaines, l'admission à la **promesse**, au **départ routier** et à l'engagement des Guides Aînées, pour faire réfléchir ceux qui enfreignent gravement les principes, et pour **honorer** les actions méritantes ou **sanctionner** les fautes.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Investitures, promesses, départs routiers, honneurs et sanctions","no":["Élection du Président, vote du budget national et des statuts","Choix du thème d'année et du programme commun aux Mouvements","Contrôle des comptes, nomination des aumôniers et des trésoriers"]}},{"id":"t4-40","q":"Quelle part du revenu des manifestations régionales est versée à la caisse nationale ?","a":"**15 %** du revenu des manifestations organisées par les Régions.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"15 %","no":["10 %","20 %","25 %"]}},{"id":"t4-41","q":"Que perd une Région ou un Groupe qui ne paie pas sa cotisation-assurance ?","a":"La **Région** perd son **droit de vote à l'Assemblée Générale** ; le **Groupe** perd son **droit de vote à l'Assemblée Régionale**.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Le droit de vote (Région à l'AG, Groupe à l'Assemblée Régionale)","no":["Le droit d'organiser des camps pendant un an","Sa reconnaissance officielle par l'Équipe nationale","Le droit de recevoir des subventions de l'État"]}},{"id":"t4-42","q":"Quelles sont les responsabilités du Trésorier Général selon le Règlement intérieur ?","a":"Il gère l'accroissement des biens, tient une **comptabilité claire** et donne la situation des comptes à **chaque réunion ordinaire du Conseil Général**, reçoit les cotisations et délivre des **reçus**. Il a la **signature conjointement avec le/la Président(e)** et présente les comptes généraux à l'Assemblée Générale.","src":"Règlement intérieur de Scouts et Guides.pdf","qcm":{"ok":"Tient les comptes et signe conjointement avec le Président","no":["Nomme les chefs d'unité et signe seul les chèques","Préside le Conseil Général en l'absence du Président","Contrôle les comptes en tant que commissaire aux comptes"]}},{"id":"t4-43","q":"Selon les Procédures SDS, qui nomme les assistants d'unité, chefs d'unité et chefs de groupe ?","a":"Le **Commissaire Régional**. Le chef remplit l'**engagement personnel**, le Chef de Groupe donne son avis et transmet la demande à la région ; le Commissaire Régional la transmet au national et signe la **carte de chef**.","src":"Procédures Administratives et Financières des SDS.pdf, DOSSIER INVESTITURE 2018-2019.docx","note":"Les Statuts 2018 font nommer les chefs d'unité par le Chef de Groupe et élire le Chef de Groupe par le Conseil de Groupe.","qcm":{"ok":"Le Commissaire Régional","no":["Le Commissaire Général","Le Président de l'Association","L'aumônier national"]}},{"id":"t4-44","q":"La nomination est-elle un droit selon les Procédures SDS ?","a":"Non. La nomination est un **mandat donné par le Mouvement** pour mener une action éducative ; elle **ne constitue pas un droit**. Tous les chefs doivent être **régulièrement nommés**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Non, c'est un mandat donné par le Mouvement","no":["Oui, après deux ans d'ancienneté dans le Mouvement","Oui, pour tout membre ayant fait sa promesse","Non, c'est un titre honorifique sans mission"]}},{"id":"t4-45","q":"Quel est le parcours de formation des chefs décrit dans les Procédures SDS ?","a":"**CI** (camp initiation, régional) dès la 1re année ; **CEP** (stage d'approfondissement pédagogique, régional) pour être assistant, à **19 ans au moins** ; **CNB** (camp national de branche) ; puis le **badge de bois**, qui confirme l'aptitude à être chef d'unité.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"CI, puis CEP, puis CNB, puis badge de bois","no":["CEP, puis CI, puis badge de bois, puis CNB","CNB, puis CI, puis CEP, puis badge de bois","CI, puis CNB, puis badge de bois, puis CEP"]}},{"id":"t4-46","q":"Quel âge minimum et quel stage faut-il pour être assistant chef d'unité (Procédures SDS) ?","a":"Avoir participé au stage d'approfondissement pédagogique **CEP** (camp régional) et avoir **au moins 19 ans**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"19 ans et le stage CEP","no":["18 ans et le camp CNB","21 ans et le badge de bois","17 ans et le camp CI"]}},{"id":"t4-47","q":"Que couvre l'assurance des SDS et pour quelle période ?","a":"La **responsabilité civile** des membres et de l'association, et les **dommages corporels** subis par les membres accidentés. Elle est **obligatoire** et couvre la période du **1er octobre au 30 septembre**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Responsabilité civile et dommages corporels, du 1er octobre au 30 septembre","no":["Vol et incendie du matériel de camp, du 1er janvier au 31 décembre","Responsabilité civile seule des chefs, du 1er septembre au 31 août","Frais de transport et de camp, du 1er juillet au 30 juin suivant"]}},{"id":"t4-48","q":"Qui est responsable si un jeune non assuré a un accident ?","a":"La **responsabilité personnelle de son chef d'unité** et celle de **ses parents**. L'association ne peut être tenue pour responsable car le jeune n'est pas considéré comme membre.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Son chef d'unité et ses parents","no":["L'association et l'assureur agréé","Le Commissaire Régional seul","La paroisse qui accueille le groupe"]}},{"id":"t4-49","q":"Dans quel délai et comment déclarer un accident selon les Procédures SDS ?","a":"Envoyer la **déclaration d'accident** à la **permanence nationale dans les 5 jours**, en **3 exemplaires**, avec un **certificat médical** de constatation des blessures, et prévenir les parents par lettre.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Dans les 5 jours, en 3 exemplaires, avec certificat médical","no":["Dans les 48 heures, en 2 exemplaires, avec photos","Dans les 15 jours, en 1 exemplaire, avec témoignages","Dans le mois, en 3 exemplaires, avec facture de pharmacie"]}},{"id":"t4-50","q":"Quelles règles de comptabilité s'appliquent aux unités et groupes (Procédures SDS) ?","a":"Le chef d'unité ou un assistant tient un **cahier de recettes et dépenses** ; **toute dépense** a une **pièce justificative** et toute recette donne lieu à un **reçu**. Le **tableau des comptes de l'année** est transmis au **trésorier régional avant le 31 décembre**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Tableau des comptes au trésorier régional avant le 31 décembre","no":["Tableau des comptes au Trésorier Général avant le 30 septembre","Bilan au Commissaire de District avant le 31 mars","Compte de camp à l'aumônier avant le 1er octobre"]}},{"id":"t4-51","q":"À qui adresser le dossier de camp et dans quel délai ?","a":"Au **Commissaire Régional**, qui assure la liaison avec les autorités administratives et peut **autoriser, refuser ou arrêter** un camp. Il faut prévoir **un mois** entre la remise du dossier et le début du camp.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Au Commissaire Régional, un mois avant le camp","no":["Au Commissaire Général, deux mois avant le camp","Au préfet, une semaine avant le camp","Au Chef de Groupe, quinze jours avant le camp"]}},{"id":"t4-52","q":"Quelle qualification faut-il pour être chef de camp d'unité, et pour être adjoint ?","a":"**Chef de camp** : **un an** d'expérience d'animation, participation à un **camp badge de bois**, compétence de chef d'unité attestée par le Commissaire Régional. **Adjoint** : **6 mois** d'animation et un **camp national de branche**. Si possible, un **secouriste diplômé**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Chef : 1 an et badge de bois ; adjoint : 6 mois et camp national de branche","no":["Chef : 2 ans et CNB ; adjoint : 1 an et camp initiation","Chef : 6 mois et CEP ; adjoint : 3 mois et camp initiation","Chef : 3 ans et brevet de formateur ; adjoint : 1 an et badge de bois"]}},{"id":"t4-53","q":"Quels documents présenter en cas d'inspection d'un camp ?","a":"La **liste des participants**, les **justificatifs des cotisations-assurances**, les **grandes lignes du programme** et le **budget du camp**.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Liste des participants, assurances, programme et budget","no":["Cartes d'identité, carnet de chants, menus et photos","Livret de promesse, tenue complète et brevets","Statuts, Règlement intérieur et fiches de paie"]}},{"id":"t4-54","q":"Comment calcule-t-on le prix de revient de la journée de camp dans le budget prévisionnel ?","a":"On divise le **sous-total des frais** (alimentation, hébergement, petit matériel, divers, amortissement) par le **nombre total de journées** de plein air.","src":"Procédures Administratives et Financières des SDS.pdf","qcm":{"ok":"Sous-total des frais divisé par le nombre total de journées","no":["Total des recettes divisé par le nombre de chefs","Frais de voyage divisés par le nombre de campeurs","Total général multiplié par le nombre de jours"]}},{"id":"t4-55","q":"Quelles colonnes comporte l'état nominatif d'une unité ?","a":"**Prénoms**, **nom**, **date et lieu de naissance**, **entrée dans le scoutisme**, **date de promesse** et **fonction**.","src":"ETAT NOMINATIF.pdf, DOSSIER INVESTITURE 2018-2019.docx","qcm":{"ok":"Nom, naissance, entrée dans le scoutisme, promesse, fonction","no":["Nom, adresse, groupe sanguin, profession des parents","Nom, classe, école, téléphone, montant versé","Nom, totem, brevets, badges, date de départ routier"]}},{"id":"t4-56","q":"Quelle autorité l'Association reconnaît-elle dans la Réglementation religieuse de 1983 ?","a":"L'autorité de l'**Église catholique**, et singulièrement de l'**Assemblée des Ordinaires du Sénégal**, représentée auprès d'elle par les **Aumôniers nationaux**.","src":"Règlementation Religieuse doc.pdf","qcm":{"ok":"L'Assemblée des Ordinaires du Sénégal, via les aumôniers nationaux","no":["La Conférence Internationale Catholique du Scoutisme","Le Ministère de la Jeunesse, via les inspecteurs","Le Conseil Général, via le Président de l'Association"]}},{"id":"t4-57","q":"Qui nomme les aumôniers nationaux et qui titularise les aumôniers de groupe ?","a":"Les **aumôniers nationaux** sont nommés par l'**Assemblée Générale des Ordinaires du Sénégal** (l'Équipe nationale propose plusieurs noms). Les **aumôniers de groupe, ménie ou unité** sont **titularisés par l'aumônier régional**.","src":"Règlementation Religieuse doc.pdf","qcm":{"ok":"Nationaux : Ordinaires du Sénégal ; de groupe : aumônier régional","no":["Nationaux : Conseil Général ; de groupe : Chef de Groupe","Nationaux : Commissaire Général ; de groupe : curé seul","Nationaux : Président ; de groupe : Commissaire de District"]}},{"id":"t4-58","q":"Que doit faire l'aumônier de groupe qui ne peut assister à un camp de son groupe ?","a":"Si le camp dure **plus de trois jours**, il doit **avertir l'aumônier régional** et pourvoir avec lui à son **remplacement**.","src":"Règlementation Religieuse doc.pdf","qcm":{"ok":"Camp de plus de 3 jours : prévenir l'aumônier régional","no":["Camp de plus de 7 jours : prévenir le Commissaire Général","Camp de plus de 2 jours : annuler le camp","Camp de plus de 10 jours : prévenir l'Archevêque"]}},{"id":"t4-59","q":"Quand et pourquoi l'Association des Scouts du Sénégal (ASDS) a-t-elle été créée ?","a":"À la suite d'une résolution de l'**AGO des Scouts et Guides du Sénégal à Ziguinchor en 2022**, des représentants des régions scoutes se sont réunis à **Bambey le 15 septembre 2023** pour créer l'ASDS.","src":"STATUTS DE L_ASDS_Somone_2024_10_05.doc","qcm":{"ok":"À Bambey le 15 septembre 2023, après l'AGO de Ziguinchor (2022)","no":["À Gorée le 1er septembre 2018, après l'AGO de Joal","À Ziguinchor le 15 septembre 2022, après l'AGO de Bambey","À Dakar le 5 octobre 2024, après la Session de Thiès"]}},{"id":"t4-60","q":"Comment est composé le Comité national de l'ASDS (Statuts 2024) ?","a":"**9 membres** : **six adultes** issus de régions différentes, **deux jeunes** du Bureau National des Jeunes et le/la **Commissaire général(e)**, élus pour **3 ans renouvelables une fois**. Le Commissaire général ne peut occuper aucun des postes du bureau du Comité.","src":"STATUTS DE L_ASDS_Somone_2024_10_05.doc","qcm":{"ok":"9 membres : 6 adultes, 2 jeunes et le Commissaire général","no":["7 membres : 5 adultes, 1 jeune et le Commissaire général","12 membres : 8 adultes, 3 jeunes et le Président","9 membres : 4 adultes, 4 jeunes et l'aumônier national"]}},{"id":"t4-61","q":"Quel âge ont les membres des Forums des jeunes de l'ASDS ?","a":"Les Forums des jeunes (national, régional, de district, de groupe) sont composés de personnes **âgées de 15 à 26 ans révolus**.","src":"STATUTS DE L_ASDS_Somone_2024_10_05.doc","qcm":{"ok":"De 15 à 26 ans révolus","no":["De 12 à 18 ans révolus","De 18 à 30 ans révolus","De 13 à 25 ans révolus"]}},{"id":"t4-62","q":"Quelles règles les Statuts ASDS 2024 posent-ils sur les procurations et les doubles fonctions ?","a":"**Les procurations ne sont pas acceptées** dans les instances d'adultes ni dans les fora de jeunes. **Nul ne peut jouir d'une double investiture** : aucun adulte ne peut occuper deux postes de niveaux hiérarchiques différents.","src":"STATUTS DE L_ASDS_Somone_2024_10_05.doc","qcm":{"ok":"Aucune procuration ; pas de double investiture","no":["Une procuration par votant ; double investiture permise","Procurations admises en AG seulement ; deux postes maximum","Procurations admises pour les jeunes ; trois postes maximum"]}},{"id":"t4-63","q":"Combien de groupes compte la région scoute de Dakar selon le document de découpage ?","a":"**18 groupes reconnus** et **5 groupes non reconnus** : Mbao Pie XII, Sébikotane, Malika, Sangalkam et Saint Christophe.","src":"Le découpage de la région de Dakar.docx","qcm":{"ok":"18 groupes reconnus et 5 non reconnus","no":["16 groupes reconnus et 7 non reconnus","18 groupes reconnus et 3 non reconnus","20 groupes reconnus et 5 non reconnus"]}},{"id":"t4-64","q":"Quels sont les districts de la région scoute de Dakar ?","a":"**Plateau**, **Grand Dakar I**, **Grand Dakar II**, **Niayes** et **Magola**.","src":"Le découpage de la région de Dakar.docx","qcm":{"ok":"Plateau, Grand Dakar I, Grand Dakar II, Niayes, Magola","no":["Plateau, Grand Dakar, Pikine, Rufisque, Guédiawaye","Plateau, Médina, Grand Dakar, Niayes, Parcelles","Gorée, Grand Dakar I, Grand Dakar II, Thiaroye, Magola"]}},{"id":"t4-65","q":"Quels groupes forment le district du Grand Dakar I ?","a":"Le **3e Dakar (Saint Pierre)**, le **5e Dakar (Sainte Thérèse)**, le **12e Dakar (Notre Dame des Anges)** et **Saint Christophe**.","src":"Le découpage de la région de Dakar.docx","qcm":{"ok":"3e, 5e, 12e Dakar et Saint Christophe","no":["9e, 10e, 13e et 16e Dakar","1er, 2e, 4e Dakar, Gorée et Bel Air","7e, 11e, 15e, 17e Dakar et Malika"]}},{"id":"t4-66","q":"Quels groupes forment le district du Grand Dakar II ?","a":"Le **9e Dakar**, le **10e Dakar (Saint Paul)**, le **13e Dakar (Martyrs de l'Ouganda)** et le **16e Dakar (Sainte Bakita et Notre Dame des Rails)**.","src":"Le découpage de la région de Dakar.docx","note":"Le document attribue aussi au 9e Dakar le nom « Martyrs de l'Ouganda », comme au 13e : erreur de saisie possible.","qcm":{"ok":"9e, 10e, 13e et 16e Dakar","no":["3e, 5e, 12e Dakar et Saint Christophe","6e, 8e, 14e et 18e Dakar","1er, 2e, 4e Dakar et Bel Air"]}}]}$xxb$::jsonb, now()),
  ('cards-5', $xxb${"theme":5,"cards":[{"id":"t5-01","q":"Quel texte définit les collectivités éducatives, cité en ouverture du cours sur la responsabilité ?","a":"La **loi n° 96-07 du 22 mars 1996** portant transfert des compétences aux régions et aux communautés locales : « un regroupement d'enfants, d'adolescents, d'adultes à l'occasion des vacances et des temps de loisirs… ».","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Loi n° 96-07 du 22 mars 1996","no":["Loi n° 77-64 du 26 mai 1977","Loi n° 96-07 du 22 mars 1986","Loi n° 98-07 du 12 mars 1998"]}},{"id":"t5-02","q":"Quels sont les trois droits du chef scout pour mener à bien sa mission ?","a":"Une **information sur le Projet Pédagogique**, une **assurance de protection** de sa personne et de ses biens, et des **moyens suffisants** pour réaliser une activité.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Information sur le projet pédagogique, assurance, moyens suffisants","no":["Rémunération, congés, assurance maladie","Autorité sur les parents, budget libre, assurance","Choix du lieu de camp, matériel neuf, indemnités"]}},{"id":"t5-03","q":"Quels sont les devoirs du chef scout selon le cours ?","a":"Réaliser le **projet pédagogique** dans le respect des orientations fixées ; **éduquer et former** les jeunes pour qu'ils deviennent des citoyens utiles ; veiller à l'**hygiène et à la sécurité physique, morale et matérielle** des enfants **24 h sur 24**.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Projet pédagogique, éducation, hygiène et sécurité 24 h/24","no":["Projet pédagogique, éducation, sécurité pendant les activités seulement","Encadrement des jeux, cuisine, transport des jeunes","Rapport aux parents, sécurité matérielle, collecte des cotisations"]}},{"id":"t5-04","q":"Dans quels trois cas peut-on être déclaré civilement responsable d'un dommage ?","a":"Quand on a **personnellement causé** le dommage, quand le **jeune sous notre contrôle** l'a causé, ou quand la **chose ou l'animal sous notre garde** en a été l'instrument. L'auteur doit **réparer par des dommages-intérêts**.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Son propre fait, le fait du jeune contrôlé, la chose ou l'animal gardé","no":["Son propre fait seulement, s'il y a eu intention de nuire","Le fait d'un passant, d'un voisin ou d'un parent","Uniquement en cas de condamnation pénale préalable"]}},{"id":"t5-05","q":"Quelle est la différence entre responsabilité civile et responsabilité pénale ?","a":"La responsabilité **civile** oblige l'auteur à **réparer** le dommage par des **dommages-intérêts**. La responsabilité **pénale** tend à la **sanction du coupable** d'un fait expressément prévu et puni par la loi.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Civile : réparer par dommages-intérêts ; pénale : sanctionner une infraction","no":["Civile : sanctionner une infraction ; pénale : réparer le dommage","Civile : concerne les adultes ; pénale : concerne les mineurs","Civile : faute grave ; pénale : faute légère"]}},{"id":"t5-06","q":"Sur quel précepte latin repose le fondement classique de la responsabilité civile ?","a":"« **Neminem laedere** » : ne pas nuire à autrui. Dès qu'on nuit à autrui, on commet une **faute** qui oblige à réparation.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Neminem laedere : ne pas nuire à autrui","no":["Culpa levissima : la faute la plus légère","Nul crime sans loi : principe de légalité","Force majeure : l'événement insurmontable"]}},{"id":"t5-07","q":"Quelles sont les trois conditions de la responsabilité civile, et quel article les fonde ?","a":"La **faute**, le **préjudice** (dommage) et le **lien de causalité**. Article **118 du COCC** : « Est responsable celui qui, par sa faute, cause un dommage à autrui. »","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Faute, préjudice, lien de causalité (article 118 du COCC)","no":["Faute, intention, condamnation (article 4 du Code pénal)","Dommage, témoin, plainte (article 129 du COCC)","Faute, préjudice, assurance (article 143 du COCC)"]}},{"id":"t5-08","q":"Comment le cours définit-il la faute, et une faute très légère suffit-elle ?","a":"La faute est un **manquement à une obligation préexistante** (article 119). Son importance n'a **aucune incidence** : même la faute la plus vénielle, la **culpa levissima**, engage la responsabilité.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Manquement à une obligation préexistante ; même la plus légère suffit","no":["Acte volontaire de nuire ; seule la faute grave compte","Infraction punie par la loi ; il faut une condamnation","Négligence répétée ; une seule faute ne suffit pas"]}},{"id":"t5-09","q":"Quels caractères doit avoir le dommage pour engager la responsabilité ?","a":"Il peut être **matériel ou moral**, actuel ou futur, mais doit toujours être **certain et direct** (article 125). Direct : il découle de la faute sans qu'aucun fait postérieur ait concouru à sa réalisation.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Matériel ou moral, et toujours certain et direct","no":["Uniquement matériel, et chiffré par un expert","Matériel ou moral, mais toujours immédiat","Uniquement corporel, et constaté par un médecin"]}},{"id":"t5-10","q":"Dans quel cas n'y a-t-il pas de responsabilité civile malgré le dommage ?","a":"Quand le fait dommageable est la conséquence d'une **force majeure** ou d'un **cas fortuit** : un événement **extérieur, insurmontable et impossible à prévoir** (article 129).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"En cas de force majeure ou de cas fortuit","no":["Quand la victime est mineure","Quand le chef était en camp fixe","Quand le dommage est seulement moral"]}},{"id":"t5-11","q":"Qui répond du dommage causé par un animal ou une chose ?","a":"**Toute personne qui en a la maîtrise** (article 137) : le propriétaire qui l'utilise lui-même ou par un préposé. La maîtrise est transférée s'il l'a confié à autrui ou si un tiers l'utilise sans sa volonté (article 138).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"La personne qui en a la maîtrise","no":["Toujours le propriétaire, quoi qu'il arrive","La victime, si elle s'en est approchée","La collectivité locale du lieu de l'accident"]}},{"id":"t5-12","q":"Que prévoit le cours sur la responsabilité des commettants (patrons) et de leurs préposés ?","a":"Les commettants répondent des dommages causés par une personne **soumise à leur autorité** dans l'exercice de ses fonctions (article 146). Commettant et préposé sont **solidairement responsables**, et le civilement responsable peut se retourner contre le préposé : l'**action récursoire** (article 149).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Ils sont solidairement responsables ; recours possible par action récursoire","no":["Seul le préposé est responsable ; le commettant est exonéré","Seul le commettant est responsable ; aucun recours possible","Ils partagent la faute à parts égales ; pas de solidarité"]}},{"id":"t5-13","q":"Qu'est-ce qu'une infraction, et quel principe l'article 4 du Code pénal consacre-t-il ?","a":"Une infraction est **toute action ou omission humaine prévue et punie par la loi pénale**. L'article 4 consacre le **principe de légalité** (exprimé par **Montesquieu puis Beccaria**) : on ne peut punir que de peines prononcées par la loi avant les faits.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Action ou omission punie par la loi ; principe de légalité","no":["Toute faute causant un dommage ; principe de réparation","Toute désobéissance au chef ; principe d'autorité","Tout manquement moral ; principe de prudence"]}},{"id":"t5-14","q":"Quels sont les trois types d'infraction et les peines qui les distinguent ?","a":"La **contravention** (peine de police), le **délit** (peine de police correctionnelle) et le **crime** (peine afflictive ou infamante).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Contravention (police), délit (correctionnelle), crime (afflictive ou infamante)","no":["Contravention (correctionnelle), délit (police), crime (amende)","Faute, délit, crime : tous punis de prison","Contravention (amende), faute (réparation), crime (police)"]}},{"id":"t5-15","q":"Quelle est la seule peine infamante, selon l'article 8 du Code pénal cité ?","a":"La **dégradation civique**.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"La dégradation civique","no":["La peine de mort","L'emprisonnement à perpétuité","L'amende correctionnelle"]}},{"id":"t5-16","q":"Le tapage nocturne : quel type d'infraction, et quelles peines ?","a":"Une **contravention** : amende de **200 F à 70 000 F** et emprisonnement d'**un jour à un mois** (article 8 du Code des contraventions).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Contravention : 200 à 70 000 F et 1 jour à 1 mois","no":["Délit : 20 000 à 250 000 F et 3 mois à 1 an","Contravention : 2 000 à 7 000 F sans prison","Délit : 200 à 70 000 F et 1 à 6 mois"]}},{"id":"t5-17","q":"L'abandon de famille : quel type d'infraction, et quelles peines ?","a":"Un **délit** : emprisonnement de **3 mois à 1 an** et amende de **20 000 F à 250 000 F** (article 350 du Code pénal).","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Délit : 3 mois à 1 an et 20 000 à 250 000 F","no":["Contravention : 1 jour à 1 mois et 200 à 70 000 F","Crime : 5 à 10 ans de prison","Délit : 1 à 3 ans et 50 000 à 500 000 F"]}},{"id":"t5-18","q":"Quels exemples de responsabilité en collectivité éducative le cours donne-t-il pour l'intendant et le secouriste ?","a":"L'**intendant** peut être civilement responsable d'une **intoxication alimentaire** en colonie ; le **secouriste**, d'une **infirmité** causée par une **injection maladroite**.","src":"RESPONSABILITE CIVILE ET PENALE.pdf","qcm":{"ok":"Intendant : intoxication alimentaire ; secouriste : injection maladroite","no":["Intendant : vol d'argent ; secouriste : tapage nocturne","Intendant : coups et blessures ; secouriste : abandon de famille","Intendant : incendie de tente ; secouriste : noyade"]}},{"id":"t5-19","q":"Que signifie « être secouriste » selon le fascicule de la Croix-Rouge sénégalaise ?","a":"Savoir **porter secours efficacement** et **éviter l'aggravation** de l'état d'un accidenté. C'est un rôle **primordial, limité et temporaire** : son action s'arrête quand le spécialiste intervient.","src":"Fascicule de premiers secours.pdf, Secourisme.pdf","qcm":{"ok":"Un rôle primordial, limité et temporaire","no":["Un rôle médical, complet et durable","Un rôle secondaire, libre et permanent","Un rôle de soin, de diagnostic et de traitement"]}},{"id":"t5-20","q":"Que signifie le sigle PAS, et quelles sont les trois étapes de l'action du secouriste ?","a":"**Protéger, Alerter, Secourir** : les trois temps du secourisme.","src":"Session Secourisme.docx, Secourisme Alexis 12e.pdf","qcm":{"ok":"Protéger, Alerter, Secourir","no":["Prévenir, Appeler, Soigner","Porter, Allonger, Surveiller","Protéger, Analyser, Stabiliser"]}},{"id":"t5-21","q":"Quand peut-on déplacer une victime en urgence (dégagement d'urgence) ?","a":"En principe **jamais**. Le dégagement d'urgence est une **manœuvre exceptionnelle**, réservée à un danger **vital, réel, immédiat et non contrôlable** (véhicule qui prend feu, route à grande circulation, pièce enfumée, éboulement…). On tire la victime par les **poignets** ou les **chevilles**.","src":"Formation aux Premiers Secours.pdf, Fascicule de premiers secours.pdf, Session Secourisme.docx","qcm":{"ok":"Seulement face à un danger vital, réel, immédiat et non contrôlable","no":["Dès qu'elle se plaint d'avoir froid au sol","Toujours, pour l'installer plus confortablement","Seulement après l'accord de la famille"]}},{"id":"t5-22","q":"Quels numéros d'urgence le document des Scouts du Sénégal (Groupe XIIe Dakar) indique-t-il ?","a":"En ville : **Sapeurs-pompiers 18**, **SAMU 1515**, **Police 17**. En campagne : sapeurs-pompiers ou SAMU, et **Gendarmerie 800 00 20 20**.","src":"Session Secourisme.docx, Secourisme Alexis 12e.pdf","note":"Formation aux Premiers Secours.pdf est un guide français : il donne le 15 (SAMU), le 18, le 17 et le 112, valables en France. Pour le Sénégal, s'en tenir aux numéros du document scout.","qcm":{"ok":"Pompiers 18, SAMU 1515, Police 17, Gendarmerie 800 00 20 20","no":["Pompiers 15, SAMU 18, Police 17, Gendarmerie 112","Pompiers 18, SAMU 15, Police 112, Gendarmerie 17","Pompiers 17, SAMU 1515, Police 18, Gendarmerie 800 00 18 18"]}},{"id":"t5-23","q":"Quelles informations doit contenir le message d'alerte ?","a":"Son **nom et numéro de téléphone**, la **localisation très précise**, la **nature du problème**, les **risques** éventuels, le **nombre de victimes** et leur état apparent, les **premières mesures prises**. Ne **pas raccrocher** sans y être autorisé.","src":"Session Secourisme.docx, Formation aux Premiers Secours.pdf","qcm":{"ok":"Identité, lieu précis, nature, risques, nombre et état des victimes, gestes faits","no":["Nom de la victime, son âge, son groupe sanguin et son adresse","Le nom du chef, la date du camp et le nombre de tentes","L'heure, la météo et l'itinéraire pour venir"]}},{"id":"t5-24","q":"À quelle distance faut-il baliser un accident de la route ?","a":"Le guide national indique **150 à 200 m** de part et d'autre de l'accident. Les autres documents varient (voir la note).","src":"Formation aux Premiers Secours.pdf, Secourisme.pdf, Secourisme Alexis 12e.pdf, Session Secourisme.docx","note":"Chiffres différents selon les sources : 150 à 200 m (Formation aux Premiers Secours) ; 150 m le jour et 200 m la nuit (Secourisme.pdf) ; 100 à 150 m le jour et 200 m la nuit (Secourisme Alexis 12e) ; « 200 m ou 30 m » (Session Secourisme).","qcm":{"ok":"150 à 200 m de part et d'autre de l'accident","no":["10 à 20 m derrière le véhicule seulement","500 m à 1 km en amont","50 m de part et d'autre"]}},{"id":"t5-25","q":"À quels signes reconnaît-on une victime qui s'étouffe (obstruction totale) ?","a":"Brutalement, elle **porte la main à sa gorge**, **ne peut plus parler**, garde la **bouche ouverte**, fait des efforts pour respirer **sans que l'air passe** et **ne peut plus tousser**.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Main à la gorge, ne parle plus, ne tousse plus, l'air ne passe pas","no":["Toux forte, sifflement et visage rouge","Perte de connaissance immédiate et convulsions","Douleur à la poitrine et sueurs froides"]}},{"id":"t5-26","q":"Quelle est la conduite à tenir face à un adulte conscient qui s'étouffe ?","a":"Le laisser dans sa position, donner **5 claques dans le dos** entre les omoplates ; si inefficace, **5 compressions abdominales (méthode de Heimlich)** ; alterner jusqu'à la désobstruction ou la perte de connaissance, puis demander un avis médical.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"5 claques dans le dos, puis 5 compressions abdominales (Heimlich)","no":["5 compressions abdominales, puis 5 claques dans le dos","2 insufflations, puis 15 compressions thoraciques","Le faire boire, puis l'allonger en PLS"]}},{"id":"t5-27","q":"Chez le nourrisson qui s'étouffe, que remplace-t-on les compressions abdominales par, et pourquoi ?","a":"Par **5 compressions thoraciques** avec **2 doigts** sur le sternum, après 5 claques dans le dos. Les compressions abdominales ne sont pas recommandées car elles peuvent **léser les organes de l'abdomen**.","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"5 compressions thoraciques à 2 doigts (risque pour l'abdomen)","no":["5 compressions abdominales avec le poing (plus efficaces)","10 claques sur la poitrine (thorax trop rigide)","Des insufflations seules (claques interdites)"]}},{"id":"t5-28","q":"Que faire si l'obstruction des voies aériennes n'est que partielle (la victime tousse) ?","a":"**Ne jamais** pratiquer les claques ni les compressions : elles risquent de provoquer une obstruction totale. **Laisser la victime dans la position où elle se sent le mieux** (souvent assise) et **demander un avis médical**.","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"Ne pas faire de claques ni de Heimlich ; installer et appeler","no":["Faire immédiatement 5 compressions abdominales","Faire 5 claques puis la coucher sur le dos","Lui donner à boire pour faire passer l'objet"]}},{"id":"t5-29","q":"Comment reconnaît-on un saignement abondant (hémorragie) ?","a":"Un saignement qui **imbibe un mouchoir** de toile ou de papier **en quelques secondes** et qui **ne s'arrête pas spontanément**.","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"Il imbibe un mouchoir en quelques secondes et ne s'arrête pas","no":["Il imbibe un mouchoir en une heure et s'arrête seul","Il apparaît seulement après une chute sur la tête","Il s'accompagne toujours de perte de connaissance"]}},{"id":"t5-30","q":"Dans quel ordre utilise-t-on les gestes pour arrêter une hémorragie externe ?","a":"1) **Compression directe** de l'endroit qui saigne ; 2) si impossible ou inefficace, **point de compression** (compression à distance) ; 3) en dernière limite, **garrot**. Puis allonger la victime et alerter.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Compression directe, point de compression, puis garrot","no":["Garrot, point de compression, puis compression directe","Point de compression, garrot, puis compression directe","Garrot immédiat, puis pansement compressif"]}},{"id":"t5-31","q":"Où se font les points de compression selon le guide national et la session scoute ?","a":"**Au pli de l'aine** (avec le poing, bras tendu) pour le membre inférieur ; **sur la face interne du bras** (avec le pouce) pour le membre supérieur ; **à la base du cou** (avec le pouce) pour une plaie du cou.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","note":"Le Fascicule de premiers secours (Croix-Rouge) place le point du membre supérieur « derrière la clavicule ». Secourisme Alexis 12e ajoute la face interne de la cuisse et le dessous de la clavicule pour une plaie du cou.","qcm":{"ok":"Pli de l'aine, face interne du bras, base du cou","no":["Genou, poignet, nuque","Cheville, coude, mâchoire","Pli de l'aine, poignet, derrière l'oreille"]}},{"id":"t5-32","q":"Quelles règles s'appliquent à la pose d'un garrot ?","a":"Lien **large** (cravate, foulard), **jamais** ficelle ni fil de fer ; garrot **toujours visible** ; **heure de pose** notée sur la victime ; **ne jamais le desserrer** ; **seul un médecin** peut l'enlever.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx, Fascicule de premiers secours.pdf","qcm":{"ok":"Lien large, visible, heure notée, jamais desserré","no":["Ficelle fine, couverte, desserrée toutes les 10 minutes","Lien élastique, caché, retiré à l'arrivée au camp","Lien large, couvert, desserré par le secouriste"]}},{"id":"t5-33","q":"Comment arrêter un saignement de nez ?","a":"Laisser la victime **assise, tête penchée en avant** (ne pas l'allonger, pour qu'elle n'avale pas son sang) et **comprimer la narine qui saigne pendant 10 minutes**. Si ça ne s'arrête pas ou recommence, avis médical.","src":"Formation aux Premiers Secours.pdf, Fascicule de premiers secours.pdf, Session Secourisme.docx","qcm":{"ok":"Assise, tête en avant, narine comprimée 10 minutes","no":["Allongée sur le dos, tête en arrière, 10 minutes","Debout, tête en arrière, 2 minutes","Assise, tête en arrière, 30 minutes"]}},{"id":"t5-34","q":"À quoi reconnaît-on une hémorragie interne, et que ne faut-il jamais donner ?","a":"Le blessé est **pâle**, a **froid**, peut perdre conscience ; le **pouls est faible et très rapide**. Allonger, jambes surélevées s'il est conscient (PLS s'il est inconscient), évacuer d'urgence. **Jamais de stimulant** : ni café, ni alcool, car cela accentue l'hémorragie.","src":"Fascicule de premiers secours.pdf","qcm":{"ok":"Pâleur, froid, pouls faible et rapide ; jamais café ni alcool","no":["Rougeur, chaleur, pouls lent ; donner du café","Fièvre, toux, pouls normal ; donner de l'eau sucrée","Pâleur, froid, pouls lent ; donner de l'alcool"]}},{"id":"t5-35","q":"Combien de temps au plus faut-il pour apprécier la respiration d'une victime inconsciente ?","a":"**10 secondes au plus**, en regardant le ventre et la poitrine se soulever, en écoutant et en sentant le souffle avec la joue.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"10 secondes au plus","no":["30 secondes au moins","1 minute entière","3 secondes au plus"]}},{"id":"t5-36","q":"Que faire d'une victime inconsciente qui respire ?","a":"Libérer les voies aériennes (bascule de la tête en arrière, menton élevé), puis la mettre en **position latérale de sécurité (PLS)**, alerter et **surveiller sa respiration toutes les minutes**.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"La mettre en PLS et surveiller la respiration","no":["Commencer le massage cardiaque","La laisser sur le dos, jambes surélevées","L'asseoir et lui donner à boire"]}},{"id":"t5-37","q":"Sur quel côté installe-t-on une femme enceinte en PLS ?","a":"Sur le **côté gauche**, pour éviter une détresse par compression de vaisseaux sanguins de l'abdomen.","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"Sur le côté gauche","no":["Sur le côté droit","Sur le dos, jambes fléchies","Sur le ventre"]}},{"id":"t5-38","q":"Quel rythme de RCP (compressions/insufflations) donne le guide national pour un adulte et pour un enfant ?","a":"Adulte : **15 compressions pour 2 insufflations**. Enfant et nourrisson : **5 compressions pour 1 insufflation**. Fréquence : **100 compressions par minute**.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","note":"Formaion Secourisme DRPCK.pdf donne 30 compressions pour 2 insufflations chez l'adulte et chez l'enfant (15/2 chez le nourrisson). Le Fascicule de la Croix-Rouge donne 15/2 pour un secouriste seul et 5/1 à deux secouristes.","qcm":{"ok":"Adulte 15/2, enfant 5/1, à 100 par minute","no":["Adulte 5/1, enfant 15/2, à 60 par minute","Adulte 10/1, enfant 3/1, à 120 par minute","Adulte 15/2, enfant 15/2, à 80 par minute"]}},{"id":"t5-39","q":"Combien d'insufflations initiales avant de commencer la RCP ?","a":"Le guide national et la session scoute : **2 insufflations** efficaces. Les autres documents diffèrent (voir la note).","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","note":"Le Fascicule de premiers secours (Croix-Rouge) indique 4 insufflations ; Formaion Secourisme DRPCK.pdf indique 10 ventilations initiales chez l'adulte et 5 chez le nourrisson.","qcm":{"ok":"2 insufflations","no":["4 insufflations","10 insufflations","Aucune, compressions d'emblée"]}},{"id":"t5-40","q":"De combien enfonce-t-on le sternum lors des compressions thoraciques ?","a":"Adulte : **4 à 5 cm** (deux mains) ; enfant de 1 à 8 ans : **3 à 4 cm** (une main) ; nourrisson : **2 à 3 cm** (deux doigts).","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"Adulte 4–5 cm, enfant 3–4 cm, nourrisson 2–3 cm","no":["Adulte 2–3 cm, enfant 1–2 cm, nourrisson 1 cm","Adulte 6–8 cm, enfant 5–6 cm, nourrisson 4 cm","Adulte 4–5 cm, enfant 4–5 cm, nourrisson 3–4 cm"]}},{"id":"t5-41","q":"Seul face à une victime qui ne respire plus, quand alerte-t-on : tout de suite ou après une minute de RCP ?","a":"**Adulte** : alerter **immédiatement** (l'arrêt du cœur est la première cause). **Enfant de moins de 8 ans, noyé ou intoxiqué** : faire **1 minute de RCP** avant d'aller alerter (c'est l'arrêt respiratoire qui cause l'arrêt cardiaque).","src":"Formation aux Premiers Secours.pdf","qcm":{"ok":"Adulte : tout de suite ; enfant, noyé, intoxiqué : après 1 minute de RCP","no":["Adulte : après 1 minute ; enfant : tout de suite","Toujours après 5 minutes de RCP","Toujours tout de suite, quel que soit l'âge"]}},{"id":"t5-42","q":"Quelles questions poser à une victime consciente qui fait un malaise ?","a":"Depuis **combien de temps** dure ce malaise ? Est-ce **la première fois** ? Prenez-vous des **médicaments** ? Avez-vous été gravement malade ou **hospitalisé** ? Puis demander un avis médical sans tarder.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Durée, première fois, médicaments, hospitalisation","no":["Nom des parents, adresse, groupe, unité","Dernier repas, heure du coucher, sport pratiqué","Âge, poids, taille, groupe sanguin"]}},{"id":"t5-43","q":"Dans quels cas ne faut-il pas donner à boire à un blessé ?","a":"Perte de connaissance ou trouble de la conscience, état de choc, blessures crâniocérébrales, troubles de la déglutition, nausées et vomissements, **blessures abdominales ou du thorax**, blessures qui nécessitent probablement une **opération**.","src":"08_secourisme.pdf","qcm":{"ok":"Inconscience, choc, plaie du ventre ou du thorax","no":["Fièvre légère, toux sèche, mal de gorge","Entorse, coup de soleil, piqûre d'insecte","Saignement de nez, ampoule au pied, fatigue"]}},{"id":"t5-44","q":"Combien de temps et avec quelle eau refroidir une brûlure récente selon le guide national ?","a":"Avec de l'eau à **10 à 25 °C**, **ruisselant sans pression**, pendant **5 minutes** (pas plus pour une brûlure grave, pour ne pas refroidir la victime).","src":"Formation aux Premiers Secours.pdf","note":"premiers_secours_cusstr.pdf conseille 15 à 20 minutes d'eau froide (au moins 10 minutes pour une brûlure simple ou grave) : durée nettement plus longue que les 5 minutes du guide national.","qcm":{"ok":"Eau à 10–25 °C, sans pression, 5 minutes","no":["Eau glacée, au jet, 30 secondes","Eau tiède, en bain, 1 heure","Eau à 10–25 °C, au jet fort, 1 minute"]}},{"id":"t5-45","q":"Comment distinguer une brûlure simple d'une brûlure grave ?","a":"Grave : **cloque plus grande que la moitié de la paume** de la main de la victime, peau noirâtre, ou localisation au **visage, mains, orifices, articulations** ; rougeur étendue chez l'enfant. Simple : rougeur chez l'adulte ou cloque **inférieure à la moitié de la paume**.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Cloque plus grande que la moitié de la paume de la victime = grave","no":["Cloque plus grande qu'une pièce de monnaie = grave","Toute brûlure avec rougeur = grave","Toute cloque, quelle que soit la taille = simple"]}},{"id":"t5-46","q":"Que faire si les vêtements d'une personne prennent feu ?","a":"**L'empêcher de courir**, la **rouler** ou la faire se rouler par terre, et **étouffer les flammes** avec un vêtement ou une couverture.","src":"Formation aux Premiers Secours.pdf, Fascicule de premiers secours.pdf","qcm":{"ok":"L'empêcher de courir, la rouler au sol, étouffer les flammes","no":["La faire courir vers un point d'eau","Lui retirer d'abord tous ses vêtements","Lui verser de l'huile pour calmer la douleur"]}},{"id":"t5-47","q":"Comment soigner une plaie simple, et quand faut-il penser au tétanos ?","a":"Se **laver les mains**, **nettoyer la plaie à l'eau et au savon**, protéger par un pansement. Demander si la victime est **vaccinée contre le tétanos** : si non, ou si la vaccination date de **plus de 10 ans**, consulter un médecin.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Laver, nettoyer, protéger ; consulter si vaccin absent ou de plus de 10 ans","no":["Laver, recoudre, bander ; consulter si vaccin de plus de 2 ans","Mettre de la poudre, couvrir ; tétanos sans importance","Laisser à l'air ; consulter si vaccin de plus de 20 ans"]}},{"id":"t5-48","q":"Quelle position d'attente pour une plaie du thorax ? Et de l'abdomen ?","a":"Thorax : **position demi-assise** (respiration plus facile). Abdomen : **à plat dos, cuisses fléchies**, jambes horizontales (relâche les muscles du ventre).","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Thorax demi-assis ; abdomen à plat dos, cuisses fléchies","no":["Thorax à plat dos ; abdomen demi-assis","Thorax en PLS ; abdomen sur le ventre","Thorax debout ; abdomen jambes surélevées"]}},{"id":"t5-49","q":"Un couteau est planté dans la plaie : faut-il le retirer ?","a":"**Jamais** : son retrait ou sa mobilisation peut **aggraver la lésion et le saignement**. On ne fait pas de compression directe ; on passe au point de compression si besoin.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx","qcm":{"ok":"Non, jamais : cela aggraverait la lésion et le saignement","no":["Oui, tout de suite, pour pouvoir comprimer","Oui, mais seulement s'il est petit","Oui, après avoir posé un garrot"]}},{"id":"t5-50","q":"Quelle conduite tenir devant une victime qui se plaint du dos, de la nuque ou de la tête après une chute ?","a":"**Ne jamais la mobiliser**, lui demander de ne faire aucun mouvement, faire alerter, **maintenir la tête avec les deux mains** de chaque côté (sauveteur à genoux derrière), surveiller et lui parler. Danger : lésion de la **moelle épinière** et paralysie.","src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx, Fascicule de premiers secours.pdf","qcm":{"ok":"Ne pas la bouger et lui maintenir la tête à deux mains","no":["L'asseoir et lui masser la nuque","La relever pour vérifier qu'elle marche","La mettre aussitôt en PLS sans alerter"]}},{"id":"t5-51","q":"Que faut-il vérifier dans la pharmacie avant chaque camp, et que noter pendant le camp ?","a":"Avant : les **dates de péremption**, la quantité de médicaments et pansements, l'état du matériel. Pendant : une **liste des médicaments distribués** (nom, date, heure). Et vérifier contre-indications et allergies : **ne jamais jouer au médecin**.","src":"08_secourisme.pdf","qcm":{"ok":"Dates de péremption avant ; liste des médicaments distribués pendant","no":["La couleur des boîtes avant ; rien à noter pendant","Le prix des médicaments avant ; les repas pendant","Les ordonnances des parents avant ; la météo pendant"]}},{"id":"t5-52","q":"Quels sont les trois éléments du triangle du feu ?","a":"Un **combustible** (solide, liquide ou gazeux), un **comburant** (le plus souvent l'oxygène de l'air) et une **élévation de température** (chaleur, flamme, étincelle…).","src":"Fascicule de premiers secours.pdf","qcm":{"ok":"Combustible, comburant, élévation de température","no":["Bois sec, vent fort, flamme d'allumette","Combustible, eau, dégagement de fumée","Oxygène, azote, élévation de pression"]}},{"id":"t5-53","q":"Quels sont les cinq critères d'un lieu de camp idéal ?","a":"**Bonne accessibilité** (route pour le matériel et l'**ambulance**), lieu **« campable »**, ressources en **eau et en bois**, bon **approvisionnement**, lieu **sécurisé** (dangers repérés, numéros des hôpitaux et médecins proches, abri en cas de tempête).","src":"formation lieu de camp.pdf","qcm":{"ok":"Accès, terrain campable, eau et bois, ravitaillement, sécurité","no":["Vue, ombre, plage, musique, wifi","Accès, piscine, terrain de foot, boutique, parking","Isolement total, pas de route, pas de voisins, pas de magasin, pas de réseau"]}},{"id":"t5-54","q":"Quel éclairage utiliser dans une tente, et pourquoi ?","a":"Une **lanterne à pile** : tout autre éclairage est trop risqué. Si un fanal se brise et se déverse dans une tente, la toile est embrasée **en moins de 5 secondes**.","src":"CAMPISME.docx","qcm":{"ok":"Une lanterne à pile : un fanal renversé embrase la toile en 5 s","no":["Une bougie : elle chauffe la tente en 5 minutes","Un fanal à gaz : il éclaire mieux sur 5 mètres","Une torche à paraffine : elle tient 5 heures"]}},{"id":"t5-55","q":"Quelles règles de sécurité pour le feu de cuisson (table à feu, feu polynésien) ?","a":"**Ne jamais laisser le feu sans surveillance** ; l'éteindre après chaque usage. En sol de **résineux ou de tourbe**, le feu peut **couver sous terre** et ressurgir ailleurs (risque d'incendie de forêt).","src":"CAMPISME.docx","qcm":{"ok":"Jamais sans surveillance ; attention au feu qui couve sous terre","no":["Le laisser couver la nuit pour gagner du temps","Le recouvrir de feuilles sèches en partant","L'installer de préférence sur tourbe ou aiguilles"]}},{"id":"t5-56","q":"Quelles sont les règles pour allumer et garder un feu en sécurité (fiche « Dis gentil chef ») ?","a":"Espace **dégagé, délimité** (trou ou pierres), plat, **non couvert de branches** ; ne **jamais l'abandonner sans l'éteindre totalement** ; ne pas laisser les jeunes jouer avec ; avoir **toujours de l'eau à proximité**.","src":"11_allumer_un_feu.pdf","qcm":{"ok":"Espace dégagé et délimité, jamais abandonné, eau à proximité","no":["Sous les arbres, à l'abri du vent, sans eau","Sur l'herbe sèche, entouré de bois vert","Près des tentes pour se chauffer la nuit"]}},{"id":"t5-57","q":"Quels bois sont bons pour la cuisine, selon le moyen mnémotechnique « CHEF » ?","a":"**Chêne/Charme, Hêtre, Érable, Frêne** (bois durs : braises, chaleur prolongée). Les résineux (pin…) servent surtout à l'**allumage**.","src":"12_specificites_combustible.pdf","qcm":{"ok":"Chêne/Charme, Hêtre, Érable, Frêne","no":["Cèdre, Hêtre, Épicéa, Figuier","Châtaignier, Houx, Épicéa, Frêne","Cyprès, Hêtre, Eucalyptus, Filao"]}},{"id":"t5-58","q":"Quand et comment installer les feuillées (toilettes) au camp ?","a":"Emplacement choisi lors de la **visite du lieu** ; c'est la **première installation, le premier jour**. À l'écart mais facile d'accès ; tranchée d'environ **30 cm de large et 45 cm de profondeur** ; désinfection quotidienne.","src":"CAMPISME.docx","qcm":{"ok":"Première installation, premier jour ; tranchée 30 cm × 45 cm","no":["Dernière installation, dernier jour ; trou 1 m × 1 m","Deuxième jour ; tranchée 10 cm × 15 cm","Au choix des jeunes ; pas de tranchée"]}},{"id":"t5-59","q":"Où ne faut-il pas dresser une tente ?","a":"Dans une **dépression** (inondation), dans le **lit à sec d'un torrent** ou tout près d'un cours d'eau (orages, montée des eaux), dans une ombre épaisse **sous certains arbres** (chute de branches). Et toujours **à bonne distance du feu**.","src":"asjdossier_technique_v3-1msds_20180319.pdf","qcm":{"ok":"Dans un creux, un lit de torrent, sous les arbres, près du feu","no":["Sur sol sablonneux ou couvert d'aiguilles","Sur un terrain plat et dégagé","À distance du feu et des cours d'eau"]}},{"id":"t5-60","q":"Quelles règles pour le trou à détritus et le trou à eaux grasses ?","a":"Ni trop près ni trop loin (moins loin que les feuillées) ; **50 cm de diamètre**, profond ; bien **délimité** et couvert contre les animaux ; **produits biodégradables** pour les eaux grasses ; **reboucher** à la fin du camp.","src":"CAMPISME.docx","qcm":{"ok":"50 cm de diamètre, délimités, couverts, rebouchés en fin de camp","no":["2 m de diamètre, ouverts, laissés en l'état","20 cm de diamètre, près des tentes, jamais rebouchés","Creusés dans le cours d'eau pour évacuer vite"]}}]}$xxb$::jsonb, now()),
  ('cards-6', $xxb${"theme":6,"cards":[{"id":"t6-01","q":"Comment le document « Organisation d'un camp de patrouille » définit-il le camp ?","a":"Le camp est le **lieu d'application par excellence de la méthode scoute**. Différent d'une colonie de vacances, il rassemble des scouts ayant un **vécu commun** et se prépare **plusieurs semaines à l'avance**.","src":"Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Le lieu d'application par excellence de la méthode scoute","no":["Le lieu de repos de fin d'année de la troupe","Le lieu de formation réservé aux chefs de patrouille","Le lieu de rencontre entre plusieurs groupes scouts"]}},{"id":"t6-02","q":"Qu'est-ce qui distingue en principe un camp scout d'une colonie de vacances ?","a":"Le camp scout rassemble des jeunes qui ont **déjà vécu des expériences ensemble** et qui ont effectué une **préparation plusieurs semaines avant** (thème, activités, collecte de fonds, techniques, équipement). Différence essentielle : c'est un **lieu d'application de la méthode scoute**.","src":"Cahier CEP Vert.pdf, Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Des jeunes au vécu commun qui préparent le camp des semaines avant","no":["Des jeunes qui se découvrent le premier jour du camp","Des activités entièrement préparées par les seuls adultes","Un séjour plus long que celui d'une colonie de vacances"]}},{"id":"t6-03","q":"Selon le Cahier CEP Vert, combien d'éléments essentiels la méthode scoute combine-t-elle au camp ?","a":"**Sept** : éducation par l'action, activités dans la nature, intégration des valeurs de la Loi et de la Promesse, relation éducative adultes/jeunes, progression personnelle, vie en équipes, référence à un cadre symbolique. L'originalité tient à leur **combinaison**.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Sept éléments","no":["Cinq éléments","Quatre éléments","Dix éléments"]}},{"id":"t6-04","q":"Quels sont les deux types de camp distingués par « Organisation d'un camp de patrouille » ?","a":"Les **camps fixes**, qui se déroulent dans la même zone du début à la fin (camp service, camp de formation…), et les **camps volants**, dont le lieu est changeant ou non défini.","src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf","note":"La Déclaration de camp propose trois cases : infrastructures résidentielles, sous tente, itinérant.","qcm":{"ok":"Camps fixes et camps volants","no":["Camps d'été et camps d'hiver","Camps de troupe et camps de groupe","Camps courts et camps de longue durée"]}},{"id":"t6-05","q":"Quels exemples de camps fixes et de camps volants donne le Cahier CEP Vert ?","a":"Camps **fixes** : chantier, formation, de vacance, week-end. Camps **volants** (ou bohémiens, itinérants) : **exploration, découverte**.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Fixes : chantier, formation ; volants : exploration, découverte","no":["Fixes : exploration, découverte ; volants : chantier, week-end","Fixes : raid, hike ; volants : formation, vacances","Fixes : jamboree, rallye ; volants : chantier, service"]}},{"id":"t6-06","q":"Comment se déroule la cérémonie d'ouverture d'un camp décrite dans le Cahier CI ?","a":"L'unité forme un **rectangle autour du kraal** (étendard sur deux branches en Y). Le CT remet **trois brindilles** au servant, qui allume le kraal en entonnant **Ingonyama** ; maîtrise et campeurs y mettent chacun leur brindille : tous **acceptent la loi du camp**. Le kraal reste allumé tout le camp.","src":"CAHIER CI-1.pdf","qcm":{"ok":"Le servant allume le kraal avec trois brindilles en chantant Ingonyama","no":["Le CP allume un feu avec une allumette en chantant l'hymne national","Le CT hisse le drapeau pendant que la troupe chante la Promesse","Chaque patrouille allume son propre feu en chantant le chant des adieux"]}},{"id":"t6-07","q":"Quels sont les 4 moments clés d'un camp de patrouille ?","a":"La **préparation du camp**, le **début de camp ou pré-camp**, les **derniers jours du camp** et le **retour du camp**.","src":"Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Préparation, pré-camp, derniers jours, retour","no":["Reconnaissance, montage, activités, démontage","Préparation, installation, veillée, évaluation","Déclaration, voyage, vie de camp, rapport"]}},{"id":"t6-08","q":"Citez des tâches de la phase de préparation du camp.","a":"Choix du type, durée et dates du camp ; répartition des rôles ; choix, réservation et **inspection du lieu** ; prévisions budgétaires, grille des menus, achat des denrées non périssables ; thème et activités ; transport ; **demande d'autorisation** ; programme ; **autorisation des parents** ; inventaire ; assurances ; inscriptions ; réglementation.","src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf","qcm":{"ok":"Inspection du lieu, budget, autorisations, programme","no":["Démontage, inventaire, visites de remerciements","Signalisation, montage des bâches, contacts locaux","Rangement du matériel, bilan financier, classement"]}},{"id":"t6-09","q":"Que fait-on pendant le pré-camp (début de camp) ?","a":"Prendre contact avec le **propriétaire ou gestionnaire** des lieux, **vérifier la sécurité** des lieux, monter l'**équipement lourd** (bâches) s'il y a lieu, et assurer la **signalisation** (signes de piste pour retrouver le lieu de camp).","src":"Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Contact propriétaire, sécurité, bâches, signes de piste","no":["Choix du thème, budget, réservation du transport","Inventaire complet, démontage, nettoyage des lieux","Bilan financier, photos, classement des documents"]}},{"id":"t6-10","q":"Quelle règle donne-t-on pour le budget du transport retour ?","a":"On **dégage le budget du transport aller et retour dès le début du camp** et on **n'y touche pas**. Les derniers jours, on confirme le transport de retour.","src":"Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Le dégager dès le début du camp et ne pas y toucher","no":["Le collecter auprès des parents le dernier jour","Le prévoir avec le reste de la caisse en fin de camp","Le faire avancer par le chef de camp et rembourser au retour"]}},{"id":"t6-11","q":"Quelle est la « loi du Campeur » rappelée à la fin du camp ?","a":"**« Le scout décampe sans laisser de trace »**.","src":"Organisation d_un camp de patrouille BV.pdf","qcm":{"ok":"Le scout décampe sans laisser de trace","no":["Le scout campe là où il est invité","Le scout laisse le lieu plus beau qu'il ne l'a trouvé","Le scout ne décampe qu'après le dernier repas"]}},{"id":"t6-12","q":"En quoi consiste le nettoyage des lieux en fin de camp ?","a":"**Incinération des déchets combustibles** et **rebouchage des trous**, suivis de visites de remerciements et d'une dernière vérification des lieux.","src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf","qcm":{"ok":"Incinérer les déchets combustibles et reboucher les trous","no":["Enterrer tous les déchets et laisser les installations","Remettre les déchets au propriétaire et démonter","Brûler les constructions et ramener les déchets"]}},{"id":"t6-13","q":"Que fait-on au retour du camp ?","a":"**Ranger le matériel** (bien sec, avec fiches de réparation), faire le **bilan financier**, développer et archiver les photos, **classer les documents**, faire un **rapport** si requis.","src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf","note":"Rapport « à la maîtrise » selon Organisation d'un camp de patrouille, « au groupe » selon le Cahier CEP Vert.","qcm":{"ok":"Rangement du matériel sec, bilan financier, rapport","no":["Démontage, nettoyage, visites de remerciements","Inspection du lieu, réservation du transport","Signalisation, montage de l'équipement lourd"]}},{"id":"t6-14","q":"Que doit contenir le rapport de reconnaissance du lieu de camp ?","a":"À rédiger **le plus vite possible après la reconnaissance** : présence de **bois et d'eau** en suffisance, terrain propice aux activités (jeux, constructions, feu de camp) et **coordonnées complètes du propriétaire**.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Bois, eau, terrain adapté et coordonnées du propriétaire","no":["Liste des participants, menus et budget","Horaires des transports et prix des denrées","Programme des veillées et thème du camp"]}},{"id":"t6-15","q":"Quelle question se poser pour fixer le but d'un camp de patrouille ?","a":"**« Qu'est-ce que je veux que ma patrouille retire de ce camp ? »** Le but doit être réalisable et apporter quelque chose au camp.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Qu'est-ce que je veux que ma patrouille retire de ce camp ?","no":["Combien de jeunes vont venir à ce camp ?","Quel lieu de camp est le moins cher ?","Qu'est-ce que la maîtrise attend de ma patrouille ?"]}},{"id":"t6-16","q":"Quelles sont les trois colonnes du timing détaillé d'un projet de camp ?","a":"**Quand ? Quoi ? Qui ?**","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Quand ? Quoi ? Qui ?","no":["Où ? Quoi ? Combien ?","Quand ? Comment ? Pourquoi ?","Qui ? Où ? Avec quoi ?"]}},{"id":"t6-17","q":"Que doit contenir un plan de marche ?","a":"Une **carte avec le trajet tracé**, la **distance**, la **dénivellation**, le **temps de marche** et la manière de gérer la marche (fréquence des pauses, répartition CP/sCP, qui mène).","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Carte du trajet, distance, dénivelé, temps et gestion de la marche","no":["Liste du matériel, menus et budget de la marche","Nom des marcheurs, numéros des parents, assurances","Horaires du car, prix du billet et lieu d'arrivée"]}},{"id":"t6-18","q":"Quelles questions de sécurité le projet de camp de patrouille doit-il traiter ?","a":"Que faire en cas d'**accident grave** ? Le lieu est-il accessible en voiture ou pour une **ambulance** ? Y a-t-il une voiture à proximité ? Coordonnées du **médecin** et de l'**hôpital** les plus proches. La **pharmacie de patrouille** est-elle complète ?","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Accès ambulance, médecin et hôpital proches, pharmacie complète","no":["Assurance du matériel, météo, horaires des repas","Clôture du terrain, gardiennage, éclairage nocturne","Liste des veillées, règlement intérieur, uniforme"]}},{"id":"t6-19","q":"Quels numéros de téléphone faut-il emporter au camp de patrouille ?","a":"Ceux du **CT, CTa, CBE, CB, CBa**, du **médecin le plus proche** et des **parents de chaque participant**.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Chefs (CT, CTa, CB…), médecin le plus proche, parents","no":["Commissaire national, pompiers, mairie","Propriétaire, boutiquier, transporteur","Aumônier, chef de village, gendarmerie"]}},{"id":"t6-20","q":"Comment organiser la rubrique « Matériel » du projet de camp de patrouille ?","a":"Deux listes distinctes : la **commande matériel** donnée au CMAT **2 semaines à l'avance minimum** (prêté gratuitement par la brigade) et la liste du matériel **à acheter** en trois colonnes : Quoi, Combien, Prix.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Commande au CMAT 2 semaines avant, et liste d'achats","no":["Commande au CMAT la veille, et liste de location","Une seule liste remise au CT le jour du départ","Liste remise aux parents 1 mois avant le camp"]}},{"id":"t6-21","q":"Quelles colonnes contient la liste de Q-Métrance (intendance) ?","a":"Quatre colonnes : les **ingrédients**, la **quantité**, le **prix à l'unité** et le **prix total**, établies à partir des menus prévus pour chaque repas.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Ingrédients, quantité, prix unitaire, prix total","no":["Plat, jour, cuisinier, prix","Ingrédient, fournisseur, date d'achat","Repas, nombre de convives, reste en stock"]}},{"id":"t6-22","q":"Quand faut-il établir le budget prévisionnel du camp de patrouille ?","a":"**Avant d'envoyer la première lettre**, pour savoir quel sera le montant de la finance d'inscription. Il est **complété à la fin du camp avec les chiffres réels**.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Avant la première lettre, pour fixer l'inscription","no":["Après le retour, avec les factures","Le premier jour du camp, avec l'intendant","Après le versement de toutes les inscriptions"]}},{"id":"t6-23","q":"Que doit contenir au minimum la rubrique « Correspondances » ?","a":"La **première lettre aux parents**, la **deuxième lettre aux gars** et l'**accord écrit du propriétaire** du lieu de camp.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Lettre aux parents, lettre aux gars, accord écrit du propriétaire","no":["Lettre au Préfet, lettre au district, liste des campeurs","Autorisation de camper et déclaration de camp","Lettre au médecin et lettre à l'aumônier"]}},{"id":"t6-24","q":"Quel test permet de savoir si un projet de camp est bon ?","a":"Se demander : **« si je suis absent, la personne qui me remplace peut-elle mener ce camp à bien sans même devoir m'appeler ? »** Si oui, le projet est bon.","src":"Contenu dun projet de camp de patrouille.pdf","qcm":{"ok":"Mon remplaçant peut-il mener le camp sans m'appeler ?","no":["La maîtrise l'a-t-elle signé sans correction ?","Le budget est-il équilibré sans subvention ?","Les jeunes l'ont-ils approuvé à l'unanimité ?"]}},{"id":"t6-25","q":"Comment définir une fiche technique de camp ?","a":"Un **document opérationnel synthétique** regroupant les informations pédagogiques, logistiques, organisationnelles et pratiques nécessaires au camp. Synthétique mais assez complète pour être mise en pratique : elle **se suffit à elle-même**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Un document opérationnel synthétique qui se suffit à lui-même","no":["Le rapport final rédigé après le retour du camp","La lettre de demande d'autorisation au district","Le formulaire d'inscription rempli par les parents"]}},{"id":"t6-26","q":"Que contient la rubrique « Identification du camp » d'une fiche technique ?","a":"**Nom du camp, troupe/patrouille, dates, lieu**. C'est la « **carte d'identité** » du document.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Nom du camp, troupe ou patrouille, dates, lieu","no":["Thème, objectifs, résultats attendus","Staff, rythme journalier, grille des menus","Tarif, conditions, matériel à prévoir"]}},{"id":"t6-27","q":"Quelles rubriques de la fiche technique sont signalées comme facultatives ?","a":"Le **contexte et justification** et les **moyens** (humains, matériels, financiers), ainsi que les **annexes** dans l'exemple.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Contexte et justification, et moyens","no":["Objectifs et résultats attendus","Staff et programme des activités","Budget prévisionnel et grille des menus"]}},{"id":"t6-28","q":"Combien d'objectifs spécifiques une fiche technique de camp doit-elle compter ?","a":"Un objectif général et **3 à 5 objectifs spécifiques au maximum**. Ils doivent être clairs, mesurables et réalistes, et commencer par un **verbe d'action à l'infinitif**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"3 à 5 au maximum","no":["1 à 2 au maximum","6 à 8 au maximum","Autant que d'activités prévues"]}},{"id":"t6-29","q":"Que signifie l'acronyme SMART utilisé pour formuler les objectifs ?","a":"**Spécifiques, Mesurables, Atteignables, Réalistes et Temporels**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Spécifiques, Mesurables, Atteignables, Réalistes, Temporels","no":["Simples, Motivants, Ambitieux, Rapides, Testés","Scouts, Méthodiques, Actifs, Responsables, Techniques","Spécifiques, Modestes, Adaptés, Rigoureux, Tenables"]}},{"id":"t6-30","q":"Comment formuler les résultats attendus d'un camp ?","a":"Par des phrases **au présent ou au passé** décrivant un **changement concret**. Ils servent de référence pour évaluer le succès en **comparant la situation finale à la situation initiale**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Au présent ou au passé, en décrivant un changement concret","no":["Au futur, en décrivant les activités prévues","À l'infinitif, en commençant par un verbe d'action","Au conditionnel, en listant les risques possibles"]}},{"id":"t6-31","q":"Quels rôles du staff la fiche technique cite-t-elle ?","a":"**Chef de camp, intendant, secouriste, secrétaire, trésorier, matérialiste, liturgiste**… Le staff clarifie **« qui fait quoi »** pour éviter les confusions.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Chef de camp, intendant, secouriste, trésorier, matérialiste…","no":["CP, SP, cuistot, boute-en-train, infirmier…","Commissaire, aumônier, parrain, chauffeur…","Chef de groupe, CT, CTa, CBE, CB…"]}},{"id":"t6-32","q":"Que comprend le programme des activités d'une fiche technique ?","a":"Le **rythme journalier** et le **chronogramme des activités** (description des activités principales). C'est le **cœur opérationnel du camp**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Le rythme journalier et le chronogramme des activités","no":["La grille des menus et la liste des courses","Les objectifs et les résultats attendus","Le staff et les conditions de participation"]}},{"id":"t6-33","q":"À quoi sert la grille des menus ?","a":"Organisée en tableau, elle sert à **équilibrer l'alimentation**, **faciliter la gestion des stocks** et **assurer la diversité** des mets.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Équilibrer l'alimentation, gérer les stocks, varier les mets","no":["Fixer le montant de la participation des jeunes","Désigner le cuistot de chaque patrouille","Justifier les dépenses auprès du district"]}},{"id":"t6-34","q":"Dans l'exemple de fiche technique (patrouille Antilope), quelle est la participation demandée ?","a":"**3 500 FCFA** par jeune, pour une cible de **8 jeunes** de la patrouille Antilope XXIIIème Dakar, camp du 8 au 11 avril 2026.","src":"Rédaction d_une fiche technique de camp.pdf","note":"Dans le budget de cet exemple, les dépenses listées totalisent 65 000 FCFA mais le total affiché est 63 500 et le solde indiqué (3 000) ne correspond pas au calcul 68 000 – 63 500.","qcm":{"ok":"3 500 FCFA","no":["5 000 FCFA","2 500 FCFA","8 000 FCFA"]}},{"id":"t6-35","q":"Quelles conditions de participation figurent dans l'exemple de fiche technique ?","a":"**Être assuré**, avoir versé sa **cotisation mensuelle** de patrouille, venir avec son **matériel de camp au complet** et son **uniforme scout impeccable**.","src":"Rédaction d_une fiche technique de camp.pdf","qcm":{"ok":"Être assuré, cotisation versée, matériel complet, uniforme impeccable","no":["Avoir 12 ans, un certificat médical et un badge","Être CP, avoir fait sa Promesse et un hike","Avoir l'accord du district et payer 10 000 FCFA"]}},{"id":"t6-36","q":"Quelle marge le Cahier CEP Vert recommande-t-il d'ajouter aux prévisions budgétaires du camp ?","a":"Ajouter **10 % « au cas où »**, après avoir tenu compte de l'expérience des camps antérieurs, du coût de la vie et des prix de la région.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"10 %","no":["5 %","20 %","25 %"]}},{"id":"t6-37","q":"Comment gérer l'argent au camp selon le Cahier CEP Vert ?","a":"**Un seul chef** (de préférence) tient la comptabilité, obtient un **reçu pour chaque achat**, ne mélange pas l'argent de l'unité avec le sien, et fait le point **tous les jours** si possible.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Un seul responsable, un reçu par achat, caisse vérifiée chaque jour","no":["Chaque patrouille gère sa caisse sans justificatif","Le chef de camp paie de sa poche puis se rembourse","Les comptes sont faits une seule fois au retour"]}},{"id":"t6-38","q":"Quelles assurances couvrent déjà les membres des Scouts du Sénégal ?","a":"L'**assurance responsabilité civile** et l'**assurance accident**.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Responsabilité civile et assurance accident","no":["Assurance maladie et assurance voyage","Assurance matériel et assurance incendie","Assurance rapatriement et assurance vol"]}},{"id":"t6-39","q":"Sur quoi repose la prévention au camp selon le Cahier CEP Vert ?","a":"Connaître chaque jeune (santé, capacités) grâce à la **fiche de renseignement individuelle**, savoir en tout temps où il se trouve, surveiller plus étroitement **sur l'eau, sur la route, en forêt, par mauvais temps**, vérifier l'équipement et les vêtements.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Fiche de renseignement individuelle et savoir où sont les jeunes","no":["Garder tous les jeunes sous les yeux en permanence","Interdire les activités en dehors du terrain de camp","Confier toute la sécurité au secouriste du camp"]}},{"id":"t6-40","q":"Quelles formalités le programme de camp doit-il mentionner selon le Cahier CEP Vert ?","a":"**Assurances, autorisation des parents, permis de camp, fiche de santé**.","src":"Cahier CEP Vert.pdf","qcm":{"ok":"Assurances, autorisation des parents, permis de camp, fiche de santé","no":["Passeport, vaccins, carte scoute, photo","Lettre au Préfet, devis, facture, reçu","Badge de bois, carnet de chants, brevet"]}},{"id":"t6-41","q":"Quels sont les objectifs du dossier de camp selon les Procédures administratives ?","a":"Informer le **District, la Région et la Nation** du projet, ce qui permet au camp d'être **couvert par l'assurance** et fournit les données pour une **intervention d'urgence** ; montrer l'engagement de la maîtrise et la conformité à la pédagogie des SDS ; préparer à l'avance pour être disponible pour les enfants.","src":"Procédures administratives Camps Scouts.ppt","qcm":{"ok":"Informer District, Région et Nation pour l'assurance et l'urgence","no":["Obtenir une subvention de l'État pour le camp","Informer uniquement les parents des dates du camp","Faire valider le thème par l'aumônier national"]}},{"id":"t6-42","q":"Quels documents composent le dossier destiné aux autorités scoutes ?","a":"La **fiche de déclaration de camp**, le **programme du camp**, la **liste des campeurs**, l'**autorisation de camper** et la **fiche d'évaluation du camp**.","src":"Procédures administratives Camps Scouts.ppt","qcm":{"ok":"Déclaration, programme, liste des campeurs, autorisation, évaluation","no":["Lettre au Préfet, lettre au propriétaire, autorisation parentale","Budget, grille des menus, inventaire du matériel","Fiche de santé, carte scoute, certificat médical"]}},{"id":"t6-43","q":"Quels documents sont destinés aux autorités administratives et aux parents ?","a":"Une **lettre au Préfet / Gouverneur**, une **lettre au propriétaire des lieux ou à la Direction des Eaux et Forêts**, et la **lettre d'autorisation de camper des parents**.","src":"Procédures administratives Camps Scouts.ppt","qcm":{"ok":"Lettre au Préfet, lettre au propriétaire ou aux Eaux et Forêts, accord parental","no":["Fiche de déclaration, programme, liste des campeurs","Lettre au commissaire national et au chef de groupe","Fiche d'évaluation, rapport final et bilan financier"]}},{"id":"t6-44","q":"À qui les dossiers de camp doivent-ils être adressés selon la Déclaration de camp ?","a":"Au **Commissaire Régional**, qui assure la liaison avec les autorités administratives. Il a qualité pour **autoriser, refuser ou arrêter** un camp et se porte garant de la qualification des chefs.","src":"declaration de camp.doc","note":"Organisation d'un camp de patrouille parle d'une demande « à la maîtrise » et le Cahier CEP Vert d'une demande « au district ».","qcm":{"ok":"Au Commissaire Régional","no":["Au Commissaire National","Au chef de groupe","Au Préfet du département"]}},{"id":"t6-45","q":"Quel délai faut-il prévoir entre la remise du dossier de camp et le début du camp ?","a":"**Un mois**. Pour les camps de **plus de 10 jours**, un délai de **deux mois** est requis.","src":"declaration de camp.doc","qcm":{"ok":"1 mois, et 2 mois pour un camp de plus de 10 jours","no":["2 semaines, et 1 mois pour un camp de plus de 10 jours","1 mois, et 3 mois pour un camp de plus de 15 jours","2 mois, et 3 mois pour un camp de plus de 10 jours"]}},{"id":"t6-46","q":"Quand un chef est-il « qualifié » pour diriger un camp selon la Déclaration de camp ?","a":"Il possède un **badge de bois depuis au moins un an**, a **21 ans minimum** et a **animé au moins un an** dans un groupe après son badge de bois. Les SDS le désignent comme **chef confirmé**.","src":"declaration de camp.doc","note":"Le même document définit plus bas le chef confirmé comme « une personne qui a un badge de bois », sans les autres conditions.","qcm":{"ok":"Badge de bois depuis 1 an, 21 ans, 1 an d'animation après","no":["Badge de bois depuis 2 ans, 25 ans, 2 ans d'animation","CEP depuis 1 an, 18 ans, 1 an d'animation","CNB depuis 1 an, 21 ans, 6 mois d'animation"]}},{"id":"t6-47","q":"Quels types de camp la fiche de déclaration propose-t-elle de cocher ?","a":"**Infrastructures résidentielles**, **sous tente** ou **itinérant**.","src":"declaration de camp.doc","note":"Organisation d'un camp de patrouille et le Cahier CEP Vert ne distinguent que deux types : fixes et volants.","qcm":{"ok":"Infrastructures résidentielles, sous tente, itinérant","no":["Camp fixe, camp volant, camp chantier de service","Camp de patrouille, camp de troupe, camp de groupe","Camp de formation, camp de vacances, camp de service"]}},{"id":"t6-48","q":"Que certifie le chef de groupe sur l'autorisation de camper ?","a":"Que les responsables ont reçu la **formation nécessaire** à l'encadrement d'un camp, que les jeunes sont **régulièrement adhérents** des Scouts du Sénégal, et qu'**aucun jeune non-adhérent** ne participe. Le document est ensuite signé par les **commissaires de district et de région**.","src":"declaration de camp.doc","qcm":{"ok":"Chefs formés, jeunes adhérents, aucun non-adhérent","no":["Budget équilibré, lieu réservé, transport payé","Parents d'accord, assurance payée, menus validés","Programme approuvé, matériel vérifié, médecin prévenu"]}},{"id":"t6-49","q":"Dans quel ordre se déroule le cursus de formation des responsables aux Scouts du Sénégal ?","a":"Du **Camp d'Initiation (CI)** au **Camp Badge de Bois (CBB)**, en passant par le **CEP** puis le **CNB**. À la fin, le stagiaire réalise un **projet à dimension communautaire ou régionale**, évalué et soutenu par un rapport.","src":"RAPPOR_1.PDF","qcm":{"ok":"CI, puis CEP, puis CNB, puis CBB","no":["CEP, puis CI, puis CBB, puis CNB","CI, puis CNB, puis CEP, puis CBB","CNB, puis CI, puis CEP, puis CBB"]}},{"id":"t6-50","q":"Quelles grandes parties compte la Fiche d'évaluation camp ?","a":"**Description du projet**, **renseignements utiles** (pays, région, adresses), **déplacements**, **facilités** sur place (approvisionnement, détente), **réalisations** avec leur coût, et **qui a rempli** le questionnaire.","src":"Fiche évaluation camp.doc","qcm":{"ok":"Description, renseignements, déplacements, facilités, réalisations","no":["Objectifs, staff, menus, budget, signatures","Thème, cible, conditions, matériel, programme","Déclaration, liste, autorisation, lettres, rapport"]}},{"id":"t6-51","q":"Quelles rubriques détaillent le coût de l'entreprise dans la Fiche d'évaluation camp ?","a":"**Réalisations**, **intendance**, **transport** et **autres frais**.","src":"Fiche évaluation camp.doc","qcm":{"ok":"Réalisations, intendance, transport, autres frais","no":["Matériel, pharmacie, assurances, imprévus","Inscriptions, subventions, dons, ventes","Location, carburant, communication, cadeaux"]}},{"id":"t6-52","q":"Où et quand s'est déroulé le camp Badge de Bois de la IIIème Dakar ?","a":"**Du 29 juillet au 1er août 2022**, à **Ngazobil et Rof** (Petite Côte).","src":"Dossier de camp Badge de bois IIIème Dakar.pdf, RAPPOR_1.PDF","note":"Le chronogramme date par erreur le lundi 1er août de 2021.","qcm":{"ok":"Du 29 juillet au 1er août 2022, à Ngazobil et Rof","no":["Du 8 au 11 avril 2022, à Ngazobil et Joal","Du 29 juillet au 1er août 2021, à Mbodiène et Rof","Du 11 au 13 juillet 2022, à Sébikotane"]}},{"id":"t6-53","q":"À qui la IIIème Dakar a-t-elle adressé ses demandes d'autorisation pour le camp Badge de Bois ?","a":"Au **commissaire régional de Dakar**, au **commissaire du District Grand Dakar I** et au **directeur du petit séminaire de Ngazobil** (autorisation de camper sur place). Les lettres sont signées par le chef de groupe.","src":"Dossier de camp Badge de bois IIIème Dakar.pdf","note":"Le directeur du séminaire est nommé « abbé Etienne DIOUF » dans la lettre et « Abbé Etienne SENE » dans le rapport final.","qcm":{"ok":"Commissaire régional, commissaire de district, directeur du séminaire","no":["Préfet, gouverneur et maire de Joal","Commissaire national, aumônier et chef de village","Eaux et Forêts, parents et curé de la paroisse"]}},{"id":"t6-54","q":"Quel est l'objectif général du projet Badge de Bois de la IIIème Dakar ?","a":"**« Améliorer le cadre de vie naturel »**, avec des objectifs comme ralentir l'avancée de la mer, diminuer la pollution maritime et conscientiser les populations.","src":"Dossier de camp Badge de bois IIIème Dakar.pdf, PROJET_1.PDF","qcm":{"ok":"Améliorer le cadre de vie naturel","no":["Renforcer l'esprit d'équipe de la troupe","Protéger les tortues marines de Ngazobil","Former les louveteaux au secourisme"]}},{"id":"t6-55","q":"Quelles modalités de participation le dossier Badge de Bois fixe-t-il ?","a":"Être **scout et assuré**, en uniforme impeccable avec son matériel, avoir une **autorisation parentale signée pour la branche jaune**, verser **5 000 FCFA** et apporter son **repas froid**.","src":"Dossier de camp Badge de bois IIIème Dakar.pdf","qcm":{"ok":"Assurance, uniforme, accord parental (jaunes), 5 000 FCFA, repas froid","no":["Assurance, uniforme, accord parental (tous), 3 500 FCFA, tente","Carte scoute, badge, certificat médical, 10 000 FCFA","Uniforme, cotisation mensuelle, matériel, 2 500 FCFA"]}},{"id":"t6-56","q":"Quel a été le budget réellement exécuté du projet Badge de Bois, et comment a-t-il été financé ?","a":"**1 040 000 FCFA** : **600 000** d'aides et subventions et **440 000** de cotisations, les pépinières d'arbres ayant été **offertes**. Le budget prévisionnel annonçait 7 110 000 FCFA.","src":"RAPPOR_1.PDF, PROJET_1.PDF","qcm":{"ok":"1 040 000 FCFA (aides 600 000, cotisations 440 000)","no":["7 110 000 FCFA (subventions 5 630 000, cotisations)","1 040 000 FCFA (cotisations 600 000, aides 440 000)","600 000 FCFA (aides 300 000, cotisations 300 000)"]}},{"id":"t6-57","q":"Quelles difficultés le rapport du Badge de Bois signale-t-il ?","a":"Un souci d'**acheminement des plantes**, les **intempéries** (fortes pluies **2 jours sur 3**), un **retard sur le programme** (fatigue et pluie) et un **manque de couverture médiatique**.","src":"RAPPOR_1.PDF","qcm":{"ok":"Acheminement des plantes, pluie, retard, pas de médias","no":["Refus du propriétaire, vol de matériel, blessures","Manque d'eau, chaleur, conflits avec les villageois","Budget dépassé, annulation du transport, maladie"]}},{"id":"t6-58","q":"Quelle condition permet d'obtenir le badge « Messager de la paix » selon le rapport Badge de Bois ?","a":"Une moyenne de **10 heures de service communautaire**. À l'issue du camp, **24 louveteaux, 21 éclaireurs, 2 routiers et 8 responsables** ont dépassé 10 heures sur 3 jours de travaux.","src":"RAPPOR_1.PDF","qcm":{"ok":"Au moins 10 heures de service communautaire","no":["Au moins 5 heures de service communautaire","Au moins 20 heures de service communautaire","La plantation d'au moins 10 arbres"]}},{"id":"t6-59","q":"Où le devoir de projet Badge de Bois doit-il être déposé selon le canevas ?","a":"Auprès du **Commissaire Régional aux Ressources**, avec **copie au Commissaire National aux Ressources adultes**, et enregistré au courrier de la Permanence nationale. La **version manuscrite est acceptée**.","src":"CANEVAS-PROJET-BADGE-DE-BOIS-ORIGINAL (2).doc","qcm":{"ok":"Au Commissaire Régional aux Ressources, copie au national","no":["Au chef de groupe, copie au district","Au Commissaire National Programme des Jeunes","Au directeur de stage, sans copie"]}},{"id":"t6-60","q":"Quelles sont les caractéristiques d'un bon projet de service communautaire selon le CEP branche verte ?","a":"Motivation des participants, pas d'obstacle financier ou social sérieux, étapes réalisables, jeunes **impliqués du début à la fin**, rôle de chacun **clairement défini**, réponse à un **réel besoin**, échanges avec la communauté, possibilité de **poursuite**.","src":"CAHIER CEP BRANCHE VERTE.pdf","qcm":{"ok":"Jeunes impliqués de bout en bout, réel besoin, rôles clairs","no":["Projet décidé par les adultes puis confié aux jeunes","Projet spectaculaire, même sans suite après le camp","Projet coûteux pour marquer la communauté"]}}]}$xxb$::jsonb, now()),
  ('cards-7', $xxb${"theme":7,"cards":[{"id":"t7-01","q":"Selon le récap Planification et animation, quelles raisons expliquent que des unités déroulent mal leur programme ?","a":"Des unités animées **uniquement sur les modules que maîtrisent leurs responsables**, des activités **monotones** et peu diversifiées, et le **refus de faire appel à des spécialistes**. Cela contribue à la **perte des effectifs**.","src":"Récap planification et animation.pdf","qcm":{"ok":"Modules limités aux savoirs des chefs, monotonie, refus des spécialistes","no":["Manque de matériel, de local et de moyens financiers","Trop de sorties, de camps et d'activités extérieures","Absence de parents, de partenaires et de sponsors"]}},{"id":"t7-02","q":"De quoi partent les approches de planification proposées dans le récap ?","a":"Du **besoin du jeune**, pour dérouler sur une **thématique** et une **période données** un programme coordonné qui implique **toute la maîtrise**.","src":"Récap planification et animation.pdf","qcm":{"ok":"Du besoin du jeune","no":["Du calendrier du District","Des compétences du chef d'unité","Du budget disponible de l'unité"]}},{"id":"t7-03","q":"Combien de points compte la méthodologie de planification et d'animation du récap, et lesquels ouvrent la liste ?","a":"**12 points**, en commençant par l'**approche thématique**, les **compétences externes**, les **sorties ou excursions**, puis les chants, le jeu comme moyen éducatif, les ATMs…","src":"Récap planification et animation.pdf","qcm":{"ok":"12 points : approche thématique, compétences externes, sorties…","no":["10 points : jeux, chants, veillées, sorties…","12 points : ordre du jour, convocation, rapport…","8 points : loi, promesse, patrouilles, nature…"]}},{"id":"t7-04","q":"Dans le cas pratique du récap, quelle thématique est traitée et sur quelle durée ?","a":"La **santé bucco-dentaire**, abordée pendant **un mois** avec les jeunes.","src":"Récap planification et animation.pdf","qcm":{"ok":"La santé bucco-dentaire, pendant un mois","no":["L'hygiène corporelle, pendant une semaine","La protection de l'environnement, pendant un trimestre","Le paludisme, pendant deux mois"]}},{"id":"t7-05","q":"Dans le cas pratique bucco-dentaire, comment sont illustrées les « compétences externes » et les « sorties » ?","a":"Compétence externe : **faire appel à un dentiste** pour expliquer l'importance d'une bonne santé bucco-dentaire. Sortie : **amener les jeunes dans un cabinet dentaire**.","src":"Récap planification et animation.pdf","qcm":{"ok":"Inviter un dentiste ; visiter un cabinet dentaire","no":["Inviter un infirmier ; visiter un hôpital","Inviter un pharmacien ; visiter une pharmacie","Inviter un médecin ; visiter un poste de santé"]}},{"id":"t7-06","q":"Dans le cas pratique, quel ATM est proposé et quel défi lui est associé ?","a":"ATM : apprendre aux jeunes à **fabriquer de la pâte dentifrice**. Défi : par **petits groupes**, les jeunes **reproduisent eux-mêmes** cet ATM.","src":"Récap planification et animation.pdf","qcm":{"ok":"Fabriquer de la pâte dentifrice, puis la refaire en petits groupes","no":["Fabriquer une brosse à dents, puis un concours de dessin","Fabriquer du savon, puis une course de relais","Fabriquer un bain de bouche, puis un quiz individuel"]}},{"id":"t7-07","q":"Faut-il utiliser les 12 points de la méthodologie pour chaque thématique ?","a":"**Non.** L'essentiel est de **confier chaque point retenu à un membre de la maîtrise**, qui le pilote, pour **éviter les assistants oisifs**.","src":"Récap planification et animation.pdf","qcm":{"ok":"Non : chaque point retenu est confié à un membre de la maîtrise","no":["Oui : les 12 points sont obligatoires pour chaque thème","Non : le chef d'unité pilote seul tous les points retenus","Oui : mais les assistants n'en pilotent aucun"]}},{"id":"t7-08","q":"Comment le document Gestion d'une unité scoute définit-il la planification ?","a":"Un processus qui fixe pour une unité, après études et réflexion prospective, **les objectifs à atteindre, les moyens nécessaires, les étapes de réalisation, les méthodes de suivi et les délais**.","src":"gestion d_une unite scoute.pdf","qcm":{"ok":"Fixer objectifs, moyens, étapes, méthodes de suivi et délais","no":["Répartir les jeunes en patrouilles selon leur âge","Tenir les comptes et rédiger les rapports financiers","Choisir les jeux, les chants et les veillées du camp"]}},{"id":"t7-09","q":"À quoi servent le cahier de bord et le livre d'or d'une unité ?","a":"Ce sont des **cahiers manuscrits** où l'unité raconte ses expériences et événements collectifs, pour **partager son histoire avec les absents et les futurs membres**. Ils contribuent à **donner une identité** au groupe.","src":"gestion d_une unite scoute.pdf","qcm":{"ok":"Raconter l'histoire de l'unité et lui donner une identité","no":["Répertorier officiellement les informations des jeunes","Noter les recettes et dépenses de l'unité","Consigner les décisions des instances du Groupe"]}},{"id":"t7-10","q":"Comment le document Animer les réunions définit-il une réunion ?","a":"« Une **animation** qui met des personnes **en communication** ensemble à un moment donné **pour un objectif précis**. » Il n'est pas nécessaire d'être physiquement ensemble.","src":"animer les reunions.pdf","qcm":{"ok":"Une animation qui met en communication des personnes pour un objectif précis","no":["Un rassemblement physique obligatoire des membres d'une instance","Une séance où le chef informe ses assistants des décisions prises","Une rencontre régulière fixée par le calendrier de l'unité"]}},{"id":"t7-11","q":"Quelles questions se poser avant d'organiser une réunion ?","a":"1. **Pourquoi** faire une réunion ? 2. Est-ce **le meilleur moyen** d'atteindre l'objectif (une lettre ou un coup de fil suffirait-il) ? 3. **Que va-t-on y faire**, de quoi parler et comment ? Sans réponse, **remettre la réunion en cause**.","src":"animer les reunions.pdf","qcm":{"ok":"Pourquoi ? Est-ce le meilleur moyen ? Que va-t-on y faire ?","no":["Qui convoquer ? Où se réunir ? Combien de temps ?","Quel budget ? Quel matériel ? Quelle salle ?","Qui préside ? Qui note ? Qui évalue ?"]}},{"id":"t7-12","q":"Que doit reprendre la convocation à une réunion ?","a":"La **date**, l'**heure de début et de fin**, les **objectifs** ; l'**ordre du jour** et le **type de réunion** ; les **coordonnées de la personne à prévenir** en cas d'absence ; les **documents de travail**.","src":"animer les reunions.pdf","qcm":{"ok":"Date, heures, objectifs, ODJ, type, contact, documents de travail","no":["Date, lieu, liste des absents et procès-verbal précédent","Heure de début, nom du président et budget de la réunion","Ordre du jour, décisions déjà prises et tâches de chacun"]}},{"id":"t7-13","q":"Comment fixer les heures de début et de fin d'une réunion ?","a":"Le début doit permettre à **chacun d'arriver** (horaire de travail, trajet, moyen de locomotion). La fin dépend de la **durée nécessaire** pour les points prévus et de **l'horaire de chacun** : après, chacun doit pouvoir manger ou dormir.","src":"animer les reunions.pdf","qcm":{"ok":"Selon les possibilités de chacun et la durée des points prévus","no":["Selon la disponibilité du seul animateur","Toujours le samedi après-midi, pour deux heures","Selon l'horaire habituel des activités des jeunes"]}},{"id":"t7-14","q":"Quels avantages et quelles limites ont les réunions virtuelles ?","a":"Avantages : **gain de temps**, **pas de déplacement**, **pas de logistique**. Limites : moyens d'animation **relativement limités** ; elles conviennent à un **petit nombre de personnes qui se connaissent bien**.","src":"animer les reunions.pdf","qcm":{"ok":"Gain de temps et pas de logistique, mais pour un petit groupe","no":["Plus de participants et plus de moyens d'animation","Moins chères, mais réservées aux grandes assemblées","Plus formelles, donc idéales pour les assemblées générales"]}},{"id":"t7-15","q":"Quelle est la « règle d'or » de l'animateur de réunion, quels que soient les moyens utilisés ?","a":"**Rester l'animateur** (l'administrateur) de la réunion, sinon **sa conduite va t'échapper**.","src":"animer les reunions.pdf","qcm":{"ok":"Rester l'animateur de la réunion","no":["Prendre soi-même toutes les notes","Donner son avis le premier sur chaque point","Laisser chacun parler sans limite de temps"]}},{"id":"t7-16","q":"Pour quel type de réunion le document Animer les réunions recommande-t-il la disposition en U ?","a":"Pour les réunions où l'on utilise un **écran de projection** : tout le monde est tourné vers l'écran **sans tourner le dos aux autres**.","src":"animer les reunions.pdf","note":"La session Techniques d'animation décrit le U comme une disposition où les échanges sont plutôt centralisés sur l'animateur ; le devoir de Kevin Coly le propose pour que tous se voient et s'entendent.","qcm":{"ok":"Les réunions avec écran de projection","no":["Les assemblées générales très formelles","Le travail en petits groupes","Les réunions virtuelles par chat"]}},{"id":"t7-17","q":"Pourquoi faut-il éviter de placer des personnes au centre d'une disposition en carré ?","a":"Elles **tournent le dos aux trois quarts de l'assistance** et **ne participent donc pas au débat**.","src":"animer les reunions.pdf","qcm":{"ok":"Elles tournent le dos à l'assistance et ne participent pas","no":["Elles monopolisent la parole au détriment des autres","Elles gênent la vue de l'écran de projection","Elles empêchent l'animateur de circuler"]}},{"id":"t7-18","q":"Comment disposer la salle pour un travail en petits groupes ?","a":"En **petits carrés ou cercles** : **chaque groupe a « sa » table**. Autour d'une même grande table, la notion de petit groupe est moins ressentie.","src":"animer les reunions.pdf","qcm":{"ok":"Chaque groupe à sa propre table","no":["Tous les groupes autour d'une grande table","Les groupes en rangées face à l'animateur","Les groupes en U autour d'un écran"]}},{"id":"t7-19","q":"Au bout de combien de temps de concentration l'attention retombe-t-elle en réunion ?","a":"Après **une heure et demie** de concentration.","src":"animer les reunions.pdf","qcm":{"ok":"Après une heure et demie","no":["Après quarante-cinq minutes","Après deux heures et demie","Après trois heures"]}},{"id":"t7-20","q":"Quels signes montrent que les participants ne sont plus attentifs ?","a":"On **rediscute une décision déjà prise**, des **arguments sont répétés** par différentes personnes, des **discussions en aparté** démarrent, des participants **dessinent sur leurs feuilles**.","src":"animer les reunions.pdf","qcm":{"ok":"Décision rediscutée, arguments répétés, apartés, dessins","no":["Silence total, prise de notes, questions précises","Votes rapides, accord unanime, fin anticipée","Retards, absences, convocations non lues"]}},{"id":"t7-21","q":"Que faire quand l'attention des participants retombe ?","a":"Prévoir une **pause brève**, voire un **petit jeu actif** ou une autre animation qui **fasse bouger physiquement** les participants.","src":"animer les reunions.pdf","qcm":{"ok":"Une pause brève ou un petit jeu actif","no":["Lever la séance et la reporter","Passer directement au vote","Rappeler les participants à l'ordre"]}},{"id":"t7-22","q":"Que doit comprendre une bonne décision prise en réunion ?","a":"L'**objet** (ce que l'on a décidé), l'**échéance** (à partir de quand), la **personne chargée** de la mettre en place et, éventuellement, **ce qui se passe si cela ne marche pas**.","src":"animer les reunions.pdf","qcm":{"ok":"Objet, échéance, personne chargée, plan si échec","no":["Objet, vote, majorité, signature","Contexte, débat, avis du chef, date","Objectif, budget, matériel, lieu"]}},{"id":"t7-23","q":"Que faut-il produire après toute réunion, physique ou virtuelle ?","a":"Un **rapport** reprenant **les décisions et leurs applications**, pour que chacun sache quoi faire et pour quand. Il doit arriver **dans un délai raisonnable** : c'est un document de travail.","src":"animer les reunions.pdf","qcm":{"ok":"Un rapport des décisions, dans un délai raisonnable","no":["Une nouvelle convocation dans la semaine","Une évaluation écrite par chaque participant","Un article pour le cahier de bord de l'unité"]}},{"id":"t7-24","q":"Selon Animer les réunions, quelle part de la réussite d'une réunion repose sur une bonne préparation ?","a":"**50 %** : « une bonne préparation, c'est 50 % de la réussite d'une réunion ».","src":"animer les reunions.pdf","note":"La session Techniques d'animation affirme, elle, que la réussite de la réunion dépend à 50 % de l'animateur.","qcm":{"ok":"50 %","no":["25 %","75 %","90 %"]}},{"id":"t7-25","q":"Selon la session Techniques d'animation, quelles qualités doivent avoir les aides visuelles ?","a":"Offrir un message **synthétique**, un message **image** et un message **structuré**.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Un message synthétique, imagé et structuré","no":["Un message long, détaillé et complet","Un message coloré, animé et sonore","Un message écrit, signé et daté"]}},{"id":"t7-26","q":"Selon la session Techniques d'animation, quel type d'échanges produit chaque disposition des tables ?","a":"**En cercle** : échanges **non centralisés**, l'animateur en fait partie. **En U** : échanges **plutôt centralisés sur l'animateur**. **En parallèle** : échanges **centralisés et plutôt unilatéraux**.","src":"Session Techniques d_animation(1).pdf","note":"Animer les réunions associe plutôt le U aux réunions avec écran de projection.","qcm":{"ok":"Cercle : non centralisés ; U : sur l'animateur ; parallèle : unilatéraux","no":["Cercle : unilatéraux ; U : non centralisés ; parallèle : sur l'animateur","Cercle : sur l'animateur ; U : unilatéraux ; parallèle : non centralisés","Cercle : non centralisés ; U : unilatéraux ; parallèle : sur l'animateur"]}},{"id":"t7-27","q":"Quels sont les trois traits d'un objectif bien formulé pour l'ordre du jour ?","a":"Il utilise un **verbe d'action** (développer, améliorer, agir) ; il traite **un seul sujet** à la fois ; il **ne présuppose pas de solution**.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Verbe d'action, un seul sujet, pas de solution présupposée","no":["Un nom court, plusieurs sujets, une solution proposée","Une question fermée, un responsable, une date","Un chiffre, un budget, un délai"]}},{"id":"t7-28","q":"Lequel de ces points d'ordre du jour est donné comme efficace dans la session Techniques d'animation ?","a":"« **Comment améliorer la sécurité des jeunes lors du prochain rallye** » est efficace ; « Sécurité » seul est inefficace.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Comment améliorer la sécurité des jeunes lors du prochain rallye","no":["Point sur la sécurité, le matériel et les trousses du rallye","Sécurité des jeunes : divers points à voir lors du rallye","Informations générales sur l'organisation et la sécurité"]}},{"id":"t7-29","q":"Quels types de réunion distingue-t-on selon leur nature ?","a":"Réunion visant à **informer les autres** (informations descendantes), à **s'informer**, à **recueillir un avis**, à **proposer des solutions**.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Informer, s'informer, recueillir un avis, proposer des solutions","no":["Physique, virtuelle, plénière, restreinte","Ordinaire, extraordinaire, statutaire, élective","Ouverture, débat, vote, clôture"]}},{"id":"t7-30","q":"Quelle conduite tenir lors d'une réunion selon la session Techniques d'animation ?","a":"Avoir un **langage positif**, soigner son expression, **ne pas inverser les rôles**, **proposer une méthode de travail**, **faire participer tout le monde**, **progresser vers l'objectif**.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Langage positif, méthode de travail, faire participer tout le monde","no":["Parler le premier, trancher seul, conclure vite","Laisser libre cours aux débats sans méthode","Imposer l'ordre du jour sans le présenter"]}},{"id":"t7-31","q":"Quels indicateurs servent à évaluer le style de l'animateur ?","a":"Le **nombre de silences**, le **nombre de personnes qui prennent la parole**, le caractère constructif des interventions, les attitudes générales (intérêt ou indifférence), la **gestion du temps**, la **satisfaction exprimée**.","src":"Session Techniques d_animation(1).pdf","qcm":{"ok":"Silences, prises de parole, gestion du temps, satisfaction","no":["Nombre de décisions, de votes et de documents","Durée de la convocation et nombre d'invités","Taille de la salle et qualité du matériel"]}},{"id":"t7-32","q":"Selon la Pédagogie du jeu, sur quels plans le jeu développe-t-il la personne ?","a":"Au plan **physique**, **mental** et **affectif**, tout en procurant du **plaisir**. Pour l'enfant, le jeu est **vital**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Physique, mental et affectif","no":["Spirituel, social et civique","Intellectuel, moral et religieux","Physique, économique et culturel"]}},{"id":"t7-33","q":"Quelles sont les trois phases de la pédagogie du jeu ?","a":"La phase **avant** (préparatoire), la phase **pendant** (exécution du jeu) et la phase **après** (ramassage du matériel et nettoyage de l'aire). Ces phases valent aussi pour le chant et la veillée.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Avant (préparation), pendant (exécution), après (ramassage)","no":["Accueil, explication, proclamation des résultats","Échauffement, compétition, récompense","Explication, coup pour rien, arbitrage"]}},{"id":"t7-34","q":"Que comprend la phase préparatoire d'un jeu ?","a":"Le **rassemblement du matériel**, l'**identification et la délimitation de l'aire de jeu**, et le **ratissage des objets dangereux** sur l'aire.","src":"LA PEDAGOGIE DU JEU.docx","note":"Le document emploie aussi le mot « ratissage » pour nommer la phase après.","qcm":{"ok":"Matériel rassemblé, aire délimitée, objets dangereux ôtés","no":["Matériel ramassé et aire de jeu nettoyée","Équipes formées, arbitre désigné, prix choisis","Silence obtenu, règles expliquées, coup pour rien"]}},{"id":"t7-35","q":"Quelles sont les trois étapes de l'évolution du jeu chez l'enfant ?","a":"Le jeu comme activité **fonctionnelle**, puis **symbolique**, puis **socialisante**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Fonctionnelle, symbolique, socialisante","no":["Individuelle, collective, compétitive","Imitative, sportive, traditionnelle","Fonctionnelle, sportive, culturelle"]}},{"id":"t7-36","q":"À quel âge dominent les jeux d'imitation (activité symbolique) ?","a":"**De 2-3 ans jusqu'à 5 ans** : l'enfant transpose le monde qui l'entoure en aspects symboliques, magiques.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"De 2-3 ans jusqu'à 5 ans","no":["De 5 à 7 ans","Vers 7 à 8 ans","De 8 à 12 ans"]}},{"id":"t7-37","q":"Vers quel âge l'enfant peut-il élaborer des règles de jeu avec ses camarades ?","a":"**Vers 7 à 8 ans** (activité socialisante) : il est en partie libéré de son **égocentrisme** social et intellectuel.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Vers 7 à 8 ans","no":["Vers 2 à 3 ans","Vers 4 à 5 ans","Vers 12 à 13 ans"]}},{"id":"t7-38","q":"Quels critères conditionnent l'activité ludique, et quel est le double rôle de l'animateur ?","a":"Critères : **durée, intensité, âge, lieu, capacité et sexe** des enfants. L'animateur doit **faciliter la compréhension du jeu** et **veiller au respect des règles**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Durée, intensité, âge, lieu, capacité, sexe ; expliquer et faire respecter","no":["Prix, matériel, météo, budget ; choisir et récompenser","Nombre, taille, force, niveau ; jouer et arbitrer","Saison, heure, tenue, terrain ; installer et ranger"]}},{"id":"t7-39","q":"Qui a dit : « L'enfant qui joue est aussi sérieux que le chercheur dans son laboratoire » ?","a":"**Piaget**, cité dans la Pédagogie du jeu.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Piaget","no":["Baden-Powell","Macaire","Roger Mucchielli"]}},{"id":"t7-40","q":"Quels sont le premier et le dernier des 10 conseils pour bien animer un jeu ?","a":"Le premier : **obtenir le silence**. Le dernier : **faire jouer un coup pour rien**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Obtenir le silence ; faire jouer un coup pour rien","no":["Délimiter l'aire ; proclamer les résultats","Former les équipes ; ranger le matériel","Expliquer les règles ; désigner le vainqueur"]}},{"id":"t7-41","q":"Parmi les conseils pour animer un jeu, comment l'animateur doit-il s'exprimer ?","a":"**Parler pour les yeux autant que pour les oreilles**, à **haute voix et lentement**, utiliser **schémas et exemples**, **associer gestes et paroles**, être **bref et concis**, **clair et impartial**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Haut, lentement, bref, en associant gestes et paroles","no":["Longuement, en détaillant chaque règle possible","À voix basse, pour obliger les enfants à se taire","Par écrit, en distribuant la fiche technique"]}},{"id":"t7-42","q":"Combien de rubriques compte la fiche technique de jeu, et par quoi se termine-t-elle ?","a":"**14 rubriques**, du **nom du jeu** jusqu'aux **observations et évaluation** (en passant par nature, origine, lieu, but, joueurs, matériel, durée, règles, déroulement, variantes).","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"14 rubriques, jusqu'aux observations et évaluation","no":["10 rubriques, jusqu'au déroulement","14 rubriques, jusqu'aux règles et gains","12 rubriques, jusqu'aux variantes du jeu"]}},{"id":"t7-43","q":"Parmi ces listes, laquelle reprend des types de jeu cités par la Pédagogie du jeu ?","a":"Jeu **d'esprit**, **d'adresse**, **sportif et pré-sportif**, **d'intérieur**, **d'extérieur**, **de création**, **de maîtrise**, **de société**, **traditionnel**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"D'esprit, d'adresse, de création, de société, traditionnel","no":["De salutation, d'ambiance, de circonstance, des rituels","Fonctionnel, symbolique, socialisant, égocentrique","Légitime, coercitif, d'expertise, de récompense"]}},{"id":"t7-44","q":"Contre quel travers la Pédagogie du jeu met-elle en garde ?","a":"Ne pas pousser les enfants vers le **chauvinisme** (refuser de perdre) : le jeu est d'abord un **facteur d'épanouissement et d'éducation**.","src":"LA PEDAGOGIE DU JEU.docx","qcm":{"ok":"Le chauvinisme : ne pas vouloir perdre","no":["La paresse : ne pas vouloir jouer","La timidité : ne pas oser parler","La désobéissance : ne pas suivre le chef"]}},{"id":"t7-45","q":"Comment la Pédagogie du chant définit-elle le chant, et en quoi diffère-t-il d'une chanson ?","a":"Le chant est une **émission de sons musicaux par la voix humaine, avec ou sans paroles**. La **chanson** est le **texte** rédigé pour être chanté, avec ou sans instruments.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Le chant est le son de la voix ; la chanson, le texte à chanter","no":["Le chant est le texte ; la chanson, la mélodie jouée","Le chant est toujours sans paroles ; la chanson, toujours avec","Le chant est collectif ; la chanson, toujours individuelle"]}},{"id":"t7-46","q":"Quel auteur est cité pour dire que le chant répond à un besoin naturel de l'enfant ?","a":"**Macaire (1979)** : le chant répond à un **besoin naturel** de l'enfant et permet une « **classe active** » pleine de joie et d'entrain.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Macaire (1979)","no":["Piaget (1979)","Mucchielli (1979)","Stogdill (1979)"]}},{"id":"t7-47","q":"Quels types de chant la Pédagogie du chant cite-t-elle ?","a":"Le chant de **salutation**, d'**ambiance** (égayer l'atmosphère), de **circonstance** (décès, mariage), des **rituels** et des **jeux**.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Salutation, ambiance, circonstance, rituels, jeux","no":["D'esprit, d'adresse, de société, traditionnel","Fonctionnel, symbolique, socialisant","Patriotique, religieux, militaire, scolaire"]}},{"id":"t7-48","q":"Comment le chef ou la cheftaine doit-il se préparer pour le chant ?","a":"Se préparer du point de vue **physique (gorge)**, **moral** et **mental**, et **choisir ses chansons en les adaptant à la cible**.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Physiquement (gorge), moralement, mentalement ; adapter à la cible","no":["Apprendre la musique et jouer d'un instrument","Chanter toujours les mêmes chants connus de tous","Laisser les jeunes choisir seuls les chants"]}},{"id":"t7-49","q":"Que faire avant l'apprentissage d'un chant ?","a":"**Bien maîtriser le chant**, assurer une **bonne disposition de l'auditoire**, **réclamer le silence**, **préparer les cordes vocales**, mettre en place un **instrument d'accompagnement**.","src":"PEDAGOGIE DU CHANT.docx","note":"Le même document demande aussi de n'utiliser les instruments que lorsque le chant est bien suivi.","qcm":{"ok":"Maîtriser le chant, disposer l'auditoire, silence, cordes vocales","no":["Applaudir, distribuer les paroles, choisir un soliste","Chanter un chant déjà connu, puis passer au jeu","Répartir les rôles, fixer l'ODJ, convoquer"]}},{"id":"t7-50","q":"Comment répartit-on les jeunes pendant l'apprentissage d'un chant ?","a":"En groupes **selon leur voix** : **fine, moyenne, grave**.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Selon leur voix : fine, moyenne, grave","no":["Selon leur âge : jeunes, moyens, grands","Selon leur patrouille ou sizaine","Selon leur taille : petits devant, grands derrière"]}},{"id":"t7-51","q":"Dans quel ordre se déroule l'apprentissage d'un chant ?","a":"**Présenter** le chant (titre, origine), **le chanter en entier**, appliquer le GRIG, **apprendre phrase par phrase**, procéder **par assemblage**, **allier gestuelle et chant**, puis **reprendre tout le chant**.","src":"PEDAGOGIE DU CHANT.docx","note":"Le sigle GRIG n'est pas expliqué dans le document.","qcm":{"ok":"Présenter, chanter en entier, phrase par phrase, assemblage, reprise","no":["Distribuer le texte, lire, faire chanter seul, corriger","Jouer l'air, apprendre le refrain, applaudir, évaluer","Apprendre phrase par phrase, puis présenter le titre"]}},{"id":"t7-52","q":"Que faut-il éviter pendant l'apprentissage d'un chant ?","a":"Faire chanter les élèves **enrhumés**, enseigner un chant **déjà connu**, et **applaudir** durant l'apprentissage.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Les enrhumés, un chant déjà connu, les applaudissements","no":["Les gestes, les instruments, la répétition","Ouvrir les fenêtres, chanter debout, le silence","Présenter le titre, l'origine et l'auteur"]}},{"id":"t7-53","q":"Quand utiliser les instruments de musique lors de l'apprentissage d'un chant ?","a":"**Seulement lorsque le chant est bien suivi** ; il faut **favoriser l'apprentissage oral**.","src":"PEDAGOGIE DU CHANT.docx","note":"La liste « Avant » du même document prévoit pourtant de mettre en place un instrument d'accompagnement.","qcm":{"ok":"Seulement quand le chant est bien suivi","no":["Dès la présentation du chant","Uniquement pour les chants de circonstance","Jamais, le chant scout se fait sans instrument"]}},{"id":"t7-54","q":"Selon la conclusion de la Pédagogie du chant, comment choisir les chants ?","a":"Selon la **mélodie** et les **paroles** : mélodie **simple** ; paroles **jamais vulgaires**, d'une **valeur éducative** ; texte simple, car **l'enfant doit comprendre ce qu'il chante**.","src":"PEDAGOGIE DU CHANT.docx","qcm":{"ok":"Mélodie simple, paroles éducatives que l'enfant comprend","no":["Mélodie complexe pour faire progresser les voix","Chants à la mode que les jeunes connaissent déjà","Chants en langue étrangère pour l'ouverture"]}},{"id":"t7-55","q":"Comment le leadership est-il défini dans le scoutisme ?","a":"Un **processus de collaboration** permettant d'**élaborer une vision**, de **mobiliser et responsabiliser les autres**, et de mettre en place les mesures pour **atteindre un objectif commun** (définition de l'OMMS en 2014).","src":"leadership SDS.pptx, devoir N°3 formateur des formateurs KEVIN COLY.pdf","qcm":{"ok":"Un processus de collaboration pour une vision et un objectif commun","no":["Un don inné réservé à quelques chefs charismatiques","Le pouvoir de commander que donne un grade","La capacité d'administrer les finances d'une unité"]}},{"id":"t7-56","q":"Quel est le but du système des patrouilles selon Baden-Powell, cité dans la session Leadership ?","a":"« **Donner une responsabilité réelle à autant de garçons que possible.** »","src":"leadership SDS.pptx","qcm":{"ok":"Donner une responsabilité réelle à autant de garçons que possible","no":["Faire gagner les jeux à la meilleure équipe","Faciliter la surveillance des jeunes par les chefs","Répartir les tâches ménagères au camp"]}},{"id":"t7-57","q":"Quand la participation des jeunes est-elle devenue la priorité stratégique n°1 de l'OMMS ?","a":"**Dès 2002**, à la **36e Conférence mondiale du Scoutisme**. En **2014**, l'OMMS adopte la **Politique de la participation des jeunes**.","src":"leadership SDS.pptx","qcm":{"ok":"En 2002, à la 36e Conférence mondiale","no":["En 2014, à la 40e Conférence mondiale","En 2008, à la 38e Conférence mondiale","En 1999, à la 35e Conférence mondiale"]}},{"id":"t7-58","q":"Quelles sont les cinq phases du cycle de vie d'une équipe ?","a":"**Constitution**, **tension**, **normalisation**, **production**, **dissolution**.","src":"devoir N°3 formateur des formateurs KEVIN COLY.pdf","qcm":{"ok":"Constitution, tension, normalisation, production, dissolution","no":["Accueil, intégration, action, évaluation, départ","Constitution, production, tension, dissolution, renaissance","Préparation, exécution, ratissage, bilan, fête"]}},{"id":"t7-59","q":"Quel est le rôle du leader pendant la phase de tension d'une équipe ?","a":"**Réduire les tensions** et **réguler les échanges** en laissant chacun s'exprimer, gérer les conflits si besoin, et être **assertif** : s'affirmer tout en écoutant.","src":"devoir N°3 formateur des formateurs KEVIN COLY.pdf","qcm":{"ok":"Réduire les tensions, réguler les échanges, être assertif","no":["Reconnaître le travail fait et valoriser chacun","Motiver l'équipe à produire si nécessaire","Faire trouver un consensus sur les règles"]}},{"id":"t7-60","q":"Quels sont les quatre styles de leadership face à la décision ?","a":"Le leader **autocratique** (décide seul), l'**autocrate qui recueille des informations** avant de décider seul, le leader **consultatif** (favorise la discussion) et le leader **démocratique** (décision en groupe).","src":"devoir N°3 formateur des formateurs KEVIN COLY.pdf","qcm":{"ok":"Autocratique, autocrate informé, consultatif, démocratique","no":["Légitime, coercitif, d'expertise, de l'exemple","Directif, persuasif, participatif, délégatif","Intuitif, rationnel, moral, empirique"]}}]}$xxb$::jsonb, now()),
  ('cards-8', $xxb${"theme":8,"cards":[{"id":"t8-01","q":"Quelles sont les trois branches du scoutisme et leurs tranches d'âge selon le Guide du louvetier ?","a":"**Louveteaux : 7 à 12 ans**, **éclaireurs : 13 à 17 ans**, **routiers : 18 ans et plus**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Louveteaux 7-12 ans, éclaireurs 13-17 ans, routiers 18 ans et plus","no":["Louveteaux 6-11 ans, éclaireurs 12-16 ans, routiers 17 ans et plus","Louveteaux 8-12 ans, éclaireurs 13-18 ans, routiers 19 ans et plus","Louveteaux 7-11 ans, éclaireurs 12-17 ans, routiers 18 à 25 ans"]}},{"id":"t8-02","q":"Qui a mis au point la méthode du louvetisme avec Baden-Powell, et quand parut le manuel des louveteaux ?","a":"**Vera Barclay**, jeune femme catholique, avec B.-P. Le manuel (*Livre des louveteaux*) parut en **1916**, retardé par la guerre ; il s'inspire du *Livre de la jungle* de **Rudyard Kipling**.","src":"GUIDE DU LOUVETIER.pdf, Livre de Baloo.pdf","qcm":{"ok":"Vera Barclay, en 1916","no":["Olave Baden-Powell, en 1916","Agnès Baden-Powell, en 1914","Vera Barclay, en 1920"]}},{"id":"t8-03","q":"Qui est le saint patron des louveteaux, et quand est-il fêté ?","a":"**Saint François d'Assise** (1182-1226), fondateur de l'ordre franciscain (pauvreté et joie), fêté le **4 octobre**. La légende du **loup de Gubbio** inspire l'iconographie du louvetisme (mâts de meute).","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Saint François d'Assise, fêté le 4 octobre","no":["Saint Georges, fêté le 4 octobre","Saint Ignace de Loyola, fêté le 3 octobre","Saint Vincent de Paul, fêté le 29 avril"]}},{"id":"t8-04","q":"Selon Vera Barclay, quel est le but prochain de la meute et quel est son but véritable ?","a":"But prochain : donner aux garçons une **provision de joie et de bonheur**, donc **faire jouer les enfants**. But véritable : **la formation du caractère**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Faire jouer les enfants ; former le caractère","no":["Discipliner les enfants ; préparer la promesse","Instruire les enfants ; obtenir les brevets","Occuper les enfants ; préparer le camp"]}},{"id":"t8-05","q":"Qui prend les décisions à la meute, à la troupe et à la route ?","a":"À la meute, **la maîtrise** ; à la troupe, **le conseil des chefs** (C.P. et maîtrise) ; à la route, **le conseil de Communauté**. D'où la mise en garde : ne pas faire à la meute du scoutisme « **éclaireur en réduction** ».","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Maîtrise ; conseil des chefs ; conseil de Communauté","no":["Rocher du conseil ; cour d'honneur ; conseil d'équipe","Conseil des sizeniers ; conseil des chefs ; maîtrise","Conseil d'Akéla ; conseil de patrouille ; conseil de maîtrise"]}},{"id":"t8-06","q":"Quelle grande règle de Baden-Powell le louvetier doit-il appliquer avant tout ?","a":"« **Ask the Boy** » (demande-le au garçon) : avant de connaître le louvetisme, il faut **d'abord connaître le garçon**, ce qu'il aime, ce qui l'ennuie, ses qualités et ses défauts.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"« Ask the Boy » : connaître d'abord le garçon","no":["« Be Prepared » : toujours prêt à servir","« Look wide » : regarder au loin","« Learn by doing » : apprendre en faisant"]}},{"id":"t8-07","q":"Combien de louveteaux au maximum dans une meute, et quel chiffre B.-P. donnait-il ?","a":"**24 louveteaux au maximum**, soit **quatre sizaines**. B.-P. disait pouvoir s'occuper individuellement de **16 garçons** au plus.","src":"GUIDE DU LOUVETIER.pdf, Livre de Baloo.pdf","qcm":{"ok":"24 louveteaux (4 sizaines) ; B.-P. parlait de 16","no":["32 louveteaux (4 sizaines) ; B.-P. parlait de 24","18 louveteaux (3 sizaines) ; B.-P. parlait de 12","30 louveteaux (5 sizaines) ; B.-P. parlait de 20"]}},{"id":"t8-08","q":"Quelle est la loi de la meute ?","a":"« **Le louveteau écoute le vieux loup, le louveteau ne s'écoute pas lui-même.** »","src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf","qcm":{"ok":"Le louveteau écoute le vieux loup, il ne s'écoute pas lui-même","no":["Le louveteau pense d'abord aux autres, il ne pense pas à lui","Le louveteau obéit à Akéla, il ne discute jamais les ordres","Le louveteau fait de son mieux, il n'abandonne jamais"]}},{"id":"t8-09","q":"Combien y a-t-il de maximes du louveteau, et quelle est la première ?","a":"**Cinq maximes** : le louveteau **pense d'abord aux autres** ; ouvre les yeux et les oreilles ; est toujours propre ; dit toujours vrai ; est toujours gai.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Cinq ; le louveteau pense d'abord aux autres","no":["Quatre ; le louveteau dit toujours vrai","Six ; le louveteau est toujours propre","Dix ; le louveteau est toujours gai"]}},{"id":"t8-10","q":"Quel est le maître-mot (devise) du louveteau ?","a":"« **De notre mieux** ». C'est le garçon lui-même qui est juge de son effort, aidé par Akéla : aujourd'hui mieux qu'hier, demain mieux qu'aujourd'hui.","src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf","qcm":{"ok":"De notre mieux","no":["Toujours prêt","Servir","Sois prêt"]}},{"id":"t8-11","q":"Quel est le texte de la promesse du louveteau ?","a":"« Je promets de faire de mon mieux pour être fidèle **à Dieu, au Sénégal, à mes parents, à la loi de la Meute**, et pour **rendre chaque jour un service à quelqu'un**. »","src":"LOUVETISME.pdf, GUIDE DU LOUVETIER.pdf","note":"Le Guide du louvetier écrit « à mon pays » ; LOUVETISME.pdf écrit « au Sénégal ».","qcm":{"ok":"Fidèle à Dieu, au Sénégal, à mes parents, à la loi de la Meute","no":["Fidèle à Dieu, à l'Église, à la patrie et à la loi scoute","Fidèle à Dieu, à Akéla, à ma sizaine et à la loi de la Meute","Fidèle à Dieu, au Sénégal, à mes chefs et aux maximes"]}},{"id":"t8-12","q":"Quel est le sens de la promesse du louveteau, et à qui est-elle faite ?","a":"Ce n'est **pas un engagement sur l'honneur**, mais le **désir de vivre selon le style de vie louveteau**. Elle est faite **à Akéla devant toute la meute**, qui aidera le louveteau à la tenir.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Désir de vivre en louveteau ; faite à Akéla devant la meute","no":["Engagement sur l'honneur ; faite à l'aumônier seul","Serment solennel ; faite au chef de groupe","Engagement d'honneur ; faite au sizenier devant la sizaine"]}},{"id":"t8-13","q":"Comment se fait le salut louveteau et que symbolise-t-il ?","a":"De la **main droite**, **index et majeur dressés et légèrement écartés**, le **pouce recouvrant les deux autres doigts**. Les deux doigts représentent **les deux oreilles du loup** dressées pour entendre les bruits de la jungle.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Deux doigts dressés : les oreilles du loup","no":["Trois doigts dressés : les trois parties de la promesse","Deux doigts dressés : les deux étoiles du louveteau","Trois doigts dressés : les trois branches du scoutisme"]}},{"id":"t8-14","q":"Qu'est-ce que le « Bon Tour » ?","a":"C'est la **B.A. du louveteau** : « **rendre chaque jour un service à quelqu'un** », présentée avec l'idée de **plaisir et de joie** à apporter aux autres.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"La B.A. du louveteau : rendre chaque jour un service","no":["Le jeu d'ouverture de chaque réunion de meute","Le tour du cercle fait au grand hurlement","La ronde de nuit au camp de meute"]}},{"id":"t8-15","q":"Que signifient « Fleur rouge », « Pelage » et « Chasse » dans le vocabulaire de la meute ?","a":"**Fleur rouge = le feu** ; **Pelage = l'uniforme** ; **Chasse = les jeux**. Aussi : Tanière = local, Lune = réunion, Kaya boum = assis, Karéla = debout.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Le feu ; l'uniforme ; les jeux","no":["Le foulard ; la sizaine ; la sortie","Le sang ; la tente ; la promenade","Le soleil ; le béret ; la réunion"]}},{"id":"t8-16","q":"Comment est composée une sizaine et quels noms portent les sizaines ?","a":"**Six louveteaux** : 1 sizenier, 1 second et 4 garçons. En général **quatre sizaines** aux couleurs de pelage : **blanc, gris, noir, brun** ; une cinquième éventuelle : tacheté, fauve ou roux.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Six louveteaux ; blancs, gris, noirs, bruns","no":["Huit louveteaux ; rouges, jaunes, verts, bleus","Six louveteaux ; Akéla, Baloo, Bagheera, Kaa","Cinq louveteaux ; blancs, gris, fauves, roux"]}},{"id":"t8-17","q":"Quel est le mât de meute et quand y ajoute-t-on une flamme jaune ?","a":"Un mât d'**1,50 m** surmonté d'une **tête de loup** (ou d'un loup entier). On ajoute une **flamme jaune** si **tous les louveteaux de plus de 10 ans et de plus de 10 mois de présence** ont leur **deuxième étoile**.","src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf","note":"Le Guide du louvetier donne 1,50 m de hauteur ; LOUVETISME.pdf dit « 1,50 m au minimum ».","qcm":{"ok":"Quand tous les plus de 10 ans (10 mois de présence) ont la 2e étoile","no":["Quand la meute a gagné un rallye de district","Quand tous les louveteaux ont fait leur promesse","Quand un louveteau monte à la troupe"]}},{"id":"t8-18","q":"Quelles couleurs correspondent aux brevets « service du prochain » et « religion » ?","a":"Service du prochain : **rouge** ; religion : **blanc**. Les autres : intelligence **bleu**, habileté manuelle **jaune**, aptitudes physiques **vert**.","src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf","qcm":{"ok":"Rouge ; blanc","no":["Blanc ; rouge","Vert ; bleu","Jaune ; blanc"]}},{"id":"t8-19","q":"Qu'est-ce que la « patte tendre » et comment s'achève cette étape ?","a":"C'est le **jeune garçon qui vient d'entrer** à la meute. Au bout de **six mois** normalement, il fait sa **promesse** et devient louveteau.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Le nouveau venu ; il fait sa promesse après environ six mois","no":["Le louveteau à une étoile ; il passe la 2e étoile après un an","Le futur sizenier ; il est investi après trois mois","Le louveteau qui monte ; il fait sa promesse à la troupe"]}},{"id":"t8-20","q":"Que symbolisent les deux étoiles du louveteau ?","a":"Les **deux yeux ouverts** : le louveteau à deux étoiles « voit clair » et peut aller à la recherche de **proies, c'est-à-dire les brevets**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Les deux yeux ouverts du loup","no":["Les deux oreilles du loup","La loi et le maître-mot","Akéla et Baloo"]}},{"id":"t8-21","q":"Quels sont les quatre conseils (instances) de la meute ?","a":"**Le Rocher du conseil**, **le conseil des sizeniers**, **le conseil d'Akéla** et **le conseil de sizaine**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Rocher du conseil, conseil des sizeniers, d'Akéla, de sizaine","no":["Rocher du conseil, cour d'honneur, conseil de maîtrise, de sizaine","Conseil de meute, conseil des seconds, d'Akéla, de groupe","Rocher du conseil, conseil de communauté, d'Akéla, d'équipe"]}},{"id":"t8-22","q":"Qui réunit le Rocher du conseil et à quelle fréquence ?","a":"**Tous les louveteaux et la maîtrise**. Il se tient **au moins une fois par mois**, **chaque jour au camp**, et souvent dans une nouvelle meute. Akéla ne doit pas interdire à un louveteau de parler.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Toute la meute et la maîtrise ; au moins une fois par mois","no":["La maîtrise seule ; une fois par trimestre","Les sizeniers et seconds ; une fois par semaine","Toute la meute ; une fois par an au camp"]}},{"id":"t8-23","q":"Qui compose le conseil d'Akéla et que s'y fait-il ?","a":"**Toute la maîtrise** : CM, ACM, aumônier, frère conseiller ; **au moins une fois par mois**. On y fait le **bilan du mois**, on suit la **progression** de chaque louveteau et on prépare le **programme du mois** suivant.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"La maîtrise ; bilan, progression et programme du mois","no":["Les sizeniers ; choix des jeux et des chants","Tous les louveteaux ; sanctions et récompenses","Les parents ; budget et inscriptions au camp"]}},{"id":"t8-24","q":"Le conseil des sizeniers prend-il les décisions à la meute ?","a":"**Non** : ce n'est pas un conseil de chefs comme à la troupe ; **c'est la maîtrise qui décide**. C'est surtout une **instance de formation** des sizeniers, où l'on recueille leurs idées et explique le programme.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Non, c'est une instance de formation ; la maîtrise décide","no":["Oui, il fixe le programme mensuel de la meute","Oui, il décide des promesses et des étoiles","Non, c'est le Rocher du conseil qui fixe tout le programme"]}},{"id":"t8-25","q":"Qu'est-ce que le Grand Hurlement, et combien de fois le louveteau le reçoit-il en son honneur ?","a":"À la fois **salut, cri de joie et renouvellement de la promesse**. Le louveteau le reçoit **deux fois** : le jour de son **entrée** dans la meute et le jour où il la **quitte pour devenir éclaireur**. Les novices n'y participent pas.","src":"LOUVETISME.pdf","qcm":{"ok":"Deux fois : à sa promesse et à sa montée à la troupe","no":["Une fois : le jour de sa promesse","Trois fois : promesse, 1re étoile et 2e étoile","Chaque année : à la fête de saint François"]}},{"id":"t8-26","q":"Quelle est la fréquence et la durée d'une réunion de meute ?","a":"**Une fois par semaine** (ou trois fois par mois s'il y a une grande sortie), à jour et heure fixes ; elle dure **une à deux heures**, normalement **en plein air**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Chaque semaine, une à deux heures","no":["Chaque mois, une demi-journée","Deux fois par semaine, trente minutes","Chaque trimestre, une journée entière"]}},{"id":"t8-27","q":"Combien de temps dure un camp de meute et à quelle fréquence a-t-il lieu ?","a":"Le camp a lieu **une fois par an** et dure **trois à huit jours** : mieux vaut un camp de trois jours réussi qu'un camp de huit jours raté. B.-P. jugeait **une semaine** comme maximum.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Une fois par an, trois à huit jours","no":["Deux fois par an, dix à quinze jours","Une fois par an, deux à trois semaines","Chaque trimestre, un à deux jours"]}},{"id":"t8-28","q":"Quelles règles de sécurité et de rythme le Guide du louvetier fixe-t-il au camp de meute ?","a":"**Jeux de nuit interdits** ; veillées **d'une heure maximum** ; **neuf à dix heures de sommeil** par nuit et une bonne heure de sieste ; aumônier présent un ou deux jours ; circulaire aux parents **un mois avant** ; tous les participants **assurés**.","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Pas de jeux de nuit, veillée d'1 h max, 9 à 10 h de sommeil","no":["Jeux de nuit chaque soir, veillée de 2 h, 7 h de sommeil","Pas de sieste, veillée libre, 8 h de sommeil","Jeux de nuit le dernier soir, veillée d'1 h, 6 h de sommeil"]}},{"id":"t8-29","q":"Que recommande le Livre de Baloo avant de lancer un jeu, et pour la fin d'une ATM ?","a":"Jeu : présenter le matériel, rappeler l'objectif et **toujours faire un essai** (« un tour pour rien ») avant de démarrer. ATM : favoriser les **produits locaux et le matériel de récupération**, et ne jamais négliger la dernière phase : **ranger le matériel et nettoyer les lieux**.","src":"Livre de Baloo.pdf","qcm":{"ok":"Faire un essai avant le jeu ; ranger et nettoyer après l'ATM","no":["Désigner un arbitre ; exposer les objets après l'ATM","Former les équipes ; noter les enfants après l'ATM","Siffler le départ ; distribuer des prix après l'ATM"]}},{"id":"t8-30","q":"Que signifie le nom de Mowgli, et qui sont Raksha et Lungri ?","a":"Mowgli veut dire **la Grenouille** (« petite grenouille »). **Raksha (le Démon)** est Mère Louve ; **Lungri (le Boiteux)** est le surnom de **Shere Khan**, boiteux d'un pied.","src":"Le livre de la Jungle I.pdf, GUIDE DU LOUVETIER.pdf","qcm":{"ok":"La Grenouille ; Mère Louve ; Shere Khan","no":["Le Petit Loup ; Mère Louve ; Tabaqui","La Grenouille ; la panthère ; le chacal","L'Enfant nu ; Shere Khan ; Mère Louve"]}},{"id":"t8-31","q":"Comment Mowgli est-il accepté dans le Clan au Rocher du Conseil ?","a":"La Loi exige que **deux membres du Clan**, autres que son père et sa mère, parlent pour lui. **Baloo** parle en sa faveur et **Bagheera** offre **un taureau fraîchement tué** pour racheter le Petit d'Homme.","src":"Le livre de la Jungle I.pdf, GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Baloo parle pour lui et Bagheera paie un taureau","no":["Akéla le défend et Kaa paie un daim","Bagheera parle pour lui et Baloo paie un buffle","Père Loup et Mère Louve votent pour lui"]}},{"id":"t8-32","q":"Quel maître-mot Mowgli utilise-t-il pour appeler Chil quand les Bandar-log l'enlèvent ?","a":"« **Nous sommes du même sang, toi et moi** ». Chil le Vautour prévient Baloo et Bagheera, qui vont chercher Kaa pour délivrer Mowgli aux **Grottes Froides**.","src":"Le livre de la Jungle I.pdf, GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Nous sommes du même sang, toi et moi","no":["Bonne chasse à tous qui gardez la Loi","Le Clan avant tout, le loup ensuite","La Jungle est grande, le loup est petit"]}},{"id":"t8-33","q":"Quel rôle jouent Baloo et Bagheera dans l'éducation de Mowgli ?","a":"**Baloo** (l'ours brun) lui enseigne **la Loi de la Jungle** ; **Bagheera** (la panthère noire) lui apprend **à chasser**.","src":"GUIDE DU LOUVETIER.pdf, Le livre de la Jungle I.pdf","qcm":{"ok":"Baloo enseigne la Loi ; Bagheera apprend à chasser","no":["Baloo apprend à chasser ; Bagheera enseigne la Loi","Baloo enseigne la nage ; Kaa enseigne la Loi","Akéla enseigne la Loi ; Baloo apprend à grimper"]}},{"id":"t8-34","q":"Quel est le maître-mot de Kaa selon le Guide du louvetier ?","a":"« **Assieds-toi, petit frère, réfléchis et fais un plan.** » (Akéla : « En tout ce que la loi pourrait taire, la parole du chef est la loi » ; Baloo : « La jungle est grande, le loup est petit, il doit se taire et méditer ».)","src":"GUIDE DU LOUVETIER.pdf","qcm":{"ok":"Assieds-toi, petit frère, réfléchis et fais un plan","no":["Œil qui voit dans le noir, pieds qui ne font pas de bruit","La jungle est grande, le loup est petit","En tout ce que la loi pourrait taire, la parole du chef est la loi"]}},{"id":"t8-35","q":"Quand la branche des routiers voit-elle le jour, et dans quel livre B.-P. présenta-t-il leur programme ?","a":"La Route voit le jour **à partir de 1917** ; B.-P. présenta le programme des routiers dans ***La Route du succès* en 1922**. Le Fondateur ne fixe pas d'âge limite : « **une vie qui vaut la peine d'être vécue** ».","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf, GUIDE DU LOUVETIER.pdf","qcm":{"ok":"À partir de 1917 ; La Route du succès (1922)","no":["En 1907 ; Éclaireurs (1908)","En 1916 ; Le Livre des louveteaux (1916)","En 1920 ; La Route du succès (1929)"]}},{"id":"t8-36","q":"Combien de routiers compte une équipe ?","a":"Selon le CNBR, **6 à 8 routiers**. Le Guide du chef de communauté révisé (2023) dit **4 à 6 membres**, et jusqu'à 8 au-delà de 24 routiers.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","note":"Contradiction : CNBR et l'ancien Guide chef de communauté disent 6 à 8 ; le Guide révisé de 2023 dit 4 à 6.","qcm":{"ok":"6 à 8 routiers (CNBR)","no":["2 à 3 routiers","10 à 12 routiers","12 à 15 routiers"]}},{"id":"t8-37","q":"Quelles sont les trois instances de la Communauté et leur fréquence minimale ?","a":"**Conseil de communauté** : au moins **une fois par trimestre** ; **conseil de maîtrise** : au moins **une fois par mois** ; **conseil d'équipe** : au moins **une fois par mois**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Communauté par trimestre ; maîtrise et équipe chaque mois","no":["Communauté chaque mois ; maîtrise et équipe chaque semaine","Communauté chaque année ; maîtrise et équipe par trimestre","Communauté chaque semaine ; maîtrise et équipe chaque mois"]}},{"id":"t8-38","q":"Quel est le rôle du conseil de communauté selon le Guide du chef de communauté révisé ?","a":"C'est **la pièce maîtresse de la Route** : la **prise en charge de la communauté par ses propres membres**, organe de gestion où se prennent **toutes les grandes décisions** (entreprise, camps, demandes de compagnonnage et de départ). L'animation et l'exécution restent au **conseil de maîtrise**.","src":"Guide du chef de Communauté revisé.pdf","qcm":{"ok":"La pièce maîtresse : la communauté se prend en charge","no":["Un organe d'exécution dirigé par l'aumônier","Une réunion de détente entre équipes","Une instance de formation des chefs d'équipe"]}},{"id":"t8-39","q":"Quelles sont les quatre étapes de progression à la Route ?","a":"**Le noviciat**, **l'apprentissage**, **le compagnonnage** et **le départ routier** (ce dernier marque l'engagement définitif dans la vie adulte).","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","qcm":{"ok":"Noviciat, apprentissage, compagnonnage, départ routier","no":["Patte tendre, 1re étoile, 2e étoile, départ routier","Novice, 2e classe, 1re classe, compagnonnage","Accueil, engagement, service, investiture"]}},{"id":"t8-40","q":"Quel âge minimum et quelle durée pour le noviciat selon le CNBR, et comment s'achève-t-il ?","a":"Il faut avoir **au moins 18 ans** ; le noviciat **dure une année** et doit être **couronné par la Promesse scoute** pour ceux qui ne l'ont pas encore faite.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","note":"Le Guide du chef de communauté révisé décrit un temps de découverte d'un à deux mois, puis évoque le passage au compagnonnage « au bout d'un ou deux ans ».","qcm":{"ok":"18 ans au moins ; un an ; couronné par la Promesse","no":["16 ans au moins ; six mois ; couronné par le départ","17 ans au moins ; deux ans ; couronné par l'engagement","18 ans au moins ; trois ans ; couronné par l'investiture"]}},{"id":"t8-41","q":"Combien de temps dure l'apprentissage et quelle est sa pièce maîtresse ?","a":"**Deux années**. Sa pièce maîtresse est **le service** : toute équipe d'apprentis doit trouver un **service continu pendant l'année**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Deux ans ; le service continu","no":["Un an ; l'entreprise de communauté","Trois ans ; le chapitre","Six mois ; les camps volants"]}},{"id":"t8-42","q":"Que marque le compagnonnage et comment se termine-t-il ?","a":"C'est le **choix du service définitif** (individuel ou collectif), l'engagement vers le départ ; il se termine par un **engagement personnel**. Le compagnon révise cet engagement devant la communauté.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Le choix du service définitif ; un engagement personnel","no":["L'entrée dans la Route ; la promesse scoute","La fin de la Route ; la remise du bâton","Le début du service ; l'investiture de chef"]}},{"id":"t8-43","q":"Le départ routier est-il obligatoire, et comment se prépare-t-il ?","a":"**Non** : c'est un **libre choix** que tous ne sont pas tenus de faire. Il est préférable qu'il intervienne au bout d'**une année de réflexion** avec l'encadrement d'un **parrain**. Le routier parti assiste **au moins à un conseil de communauté par an**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Non ; un an de réflexion avec un parrain","no":["Oui ; à 25 ans révolus","Oui ; après deux ans de compagnonnage","Non ; trois mois de retraite avec l'aumônier"]}},{"id":"t8-44","q":"Que représente l'insigne des étapes de la Route, et quelles couleurs de fond se succèdent ?","a":"Une **fourche noire** symbolisant **le choix au carrefour** (le bon chemin ou celui de la tentation), bordée de rouge. Fond **vert** (novice), **jaune** (apprenti), **rouge** (compagnon), puis **vert-jaune-rouge avec étoile verte et R.S.** au départ.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","note":"Emplacement et taille divergent : CNBR, manche gauche à 2 cm de l'épaule (3 x 4 cm) ; Guide révisé, sous la patte d'épaule gauche (5 x 4 cm).","qcm":{"ok":"Une fourche noire ; vert, jaune, rouge","no":["Un bâton croisé ; rouge, jaune, vert","Une fourche noire ; gris, marron, rouge","Une fleur de lys ; vert, jaune, rouge"]}},{"id":"t8-45","q":"Qu'est-ce que le bâton à fourche ?","a":"Un bâton en **bois de vène** de **1,50 m**, symbole de la **route de la vie** et signe d'aînesse, comme le bâton du pèlerin. Il est remis au routier **autorisé à faire son départ**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","qcm":{"ok":"Bâton en bois de vène remis pour le départ routier","no":["Bâton de 1,40 m remis au chef d'équipe","Bâton en bambou remis au novice à l'accueil","Bâton en bois de vène remis à l'apprenti"]}},{"id":"t8-46","q":"À quelle tranche d'âge s'adresse la méthode de la branche Route selon le CNBR ?","a":"Aux jeunes routiers de **18 à 35 ans**. La méthode scoute y est adaptée en éléments allant de la Promesse et la Loi jusqu'à **l'engagement dans la communauté**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","note":"Le Guide du chef de communauté révisé parle de 18 à 26 ans, l'ancien guide de 17 à 30 ans ; le CNBR annonce « sept éléments » mais en liste huit.","qcm":{"ok":"De 18 à 35 ans","no":["De 16 à 25 ans","De 17 à 30 ans","De 21 à 40 ans"]}},{"id":"t8-47","q":"Quel doit être le rôle de l'adulte (chef de communauté) à la Route ?","a":"Il se fait **beaucoup plus discret** : **plus conseiller que dirigeant**. Ce n'est pas à lui d'élaborer les programmes d'équipe ; il **écoute beaucoup plus qu'il ne dirige**.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","qcm":{"ok":"Discret : un conseiller plutôt qu'un dirigeant","no":["Directif : il fixe le programme de chaque équipe","Absent : les routiers se dirigent seuls","Instructeur : il fait passer les épreuves techniques"]}},{"id":"t8-48","q":"Quelle est la devise des routiers ?","a":"« **Servir** » (« La Route pour… servir »). À la Route, on ne demande plus une B.A. de louveteau, mais **un engagement pour un service continu**.","src":"Guide du chef de Communauté revisé.pdf, GUIDE CHEF DE COMMUNAUTE.pdf","qcm":{"ok":"Servir","no":["De notre mieux","Toujours prêt","Sois prêt"]}},{"id":"t8-49","q":"Qu'est-ce que l'entreprise à la Route, et qui la décide ?","a":"« **Pas de route sans entreprise** » : un **service collectif** de grande envergure assumé par la communauté ou l'équipe (Père Forestier). Elle est **décidée par les routiers** et arrêtée en **conseil de communauté** ; le CC peut suggérer, **jamais décider**.","src":"Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Un service collectif décidé par les routiers en conseil","no":["Un service individuel choisi par le chef de communauté","Une activité lucrative fixée par l'aumônier","Un grand jeu imposé par le district"]}},{"id":"t8-50","q":"Que sont les maximes, la loi et la charte dans les trois branches ?","a":"« Les **louveteaux** ont les **Maximes**. Les **scouts** ont la **Loi**. Les **routiers** ont la **Charte**. » La charte est l'ensemble des **exigences acceptées par la communauté et révisées périodiquement** ; on la rebâtit au conseil qui termine le grand camp.","src":"Guide du chef de Communauté revisé.pdf","qcm":{"ok":"Maximes aux louveteaux, Loi aux scouts, Charte aux routiers","no":["Loi aux louveteaux, Maximes aux scouts, Charte aux routiers","Charte aux louveteaux, Loi aux scouts, Maximes aux routiers","Maximes aux louveteaux, Charte aux scouts, Loi aux routiers"]}},{"id":"t8-51","q":"Combien de jours dure le camp routier, et quelles formes peut-il prendre ?","a":"Le camp dure **6 à 12 jours**, de préférence en saison sèche. Il peut être **volant** (déplacement chaque jour, avec une partie fixe de 3 ou 4 jours) ou **fixe**. Sa préparation occupe la communauté **3 ou 4 mois**.","src":"Guide du chef de Communauté revisé.pdf","qcm":{"ok":"6 à 12 jours ; volant ou fixe","no":["3 à 8 jours ; volant ou fixe","15 à 21 jours ; fixe uniquement","2 à 4 jours ; volant uniquement"]}},{"id":"t8-52","q":"Combien de routiers au maximum dans une communauté, et qui en fait aussi partie ?","a":"Une communauté ne doit pas dépasser **30 routiers** (4 ou 5 équipes). **Les chefs et assistants de meute et de troupe font partie de la communauté** route, en une ou deux équipes.","src":"Guide du chef de Communauté revisé.pdf","note":"Le même guide dit plus loin qu'au-delà de 32 routiers il faut créer une nouvelle communauté.","qcm":{"ok":"30 routiers ; les chefs de meute et de troupe en font partie","no":["50 routiers ; les parents en font partie","20 routiers ; les sizeniers en font partie","40 routiers ; les commissaires en font partie"]}},{"id":"t8-53","q":"Qui prépare le louveteau à la montée à la troupe ?","a":"Toute la vie de la meute prépare cette montée ; la préparation immédiate se fait dans les semaines précédentes par les soins conjugués du **chef de meute**, du **chef de troupe** et de **l'aumônier**.","src":"LOUVETISME.pdf","qcm":{"ok":"Le chef de meute, le chef de troupe et l'aumônier","no":["Le sizenier, le second et Baloo","Le chef de groupe et le commissaire de district","Les parents et le chef de patrouille"]}},{"id":"t8-54","q":"Comment se déroule la cérémonie de montée à la troupe ?","a":"La troupe est en **rectangle**, la meute en cercle de parade. Le louveteau reçoit **une deuxième et dernière fois le Grand Hurlement** ; le chef de meute le présente au chef de troupe et à l'aumônier ; il salue l'**étendard**, puis est **confié à un chef de patrouille**.","src":"LOUVETISME.pdf","qcm":{"ok":"Dernier Grand Hurlement, salut à l'étendard, confié à un CP","no":["Promesse scoute immédiate devant la troupe","Remise du foulard de troupe par le sizenier","Cri de patrouille puis remise du bâton à fourche"]}},{"id":"t8-55","q":"Que devient l'uniforme du louveteau qui monte à la troupe ?","a":"Il **garde son uniforme et ses insignes jusqu'au jour de sa promesse** d'éclaireur. Faisant déjà partie de la fraternité scoute, il devrait faire sa promesse **plus rapidement qu'un novice ordinaire**.","src":"LOUVETISME.pdf","qcm":{"ok":"Il le garde jusqu'à sa promesse d'éclaireur","no":["Il le rend le jour de la montée","Il le garde jusqu'à la fin de l'année scoute","Il le remplace dès qu'il reçoit son foulard"]}},{"id":"t8-56","q":"Comment sont disposées les unités lors de la montée de la troupe à la communauté ?","a":"Les deux unités sont **en rectangle face à face**, séparées par les deux **maîtrises dos à dos à 5 mètres**. Le **chef de patrouille lance une dernière fois le cri de patrouille**, le chef de troupe présente le garçon (bref CV), puis le CC le confie au **chef d'équipe**, qui lance le cri de l'équipe.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","qcm":{"ok":"En rectangle, maîtrises dos à dos à 5 m","no":["En cercle, maîtrises face à face à 3 m","En ligne, maîtrises côte à côte à 10 m","En demi-cercle, maîtrises dos à dos à 2 m"]}},{"id":"t8-57","q":"Quand a lieu la cérémonie d'accueil du novice à la Route, et que lui remet-on ?","a":"**Un mois après son intégration** à la communauté. Le CC lui remet **la chemise route, le foulard de région et l'insigne de noviciat**, après lui avoir demandé : « La route est longue, es-tu prêt à la suivre ? »","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf","note":"Le novice se tient « à 6 pas » de la maîtrise selon le CNBR, « à 3 pas » selon le Guide révisé.","qcm":{"ok":"Un mois après ; chemise route, foulard de région, insigne","no":["Le jour même ; bâton à fourche et flots","Un an après ; insigne R.S. et Bible","Six mois après ; foulard gris et barrette"]}},{"id":"t8-58","q":"Lors de la cérémonie du départ routier, que symbolise le pain remis au routier ?","a":"Le pain est la **nourriture pour la route** et le **signe de la solidarité humaine** ; il invite au travail, au partage et au combat pour la justice. On remet aussi une **flamme** (torche) et l'aumônier glisse une **Bible** dans le sac.","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","qcm":{"ok":"La nourriture pour la route et la solidarité humaine","no":["La récompense des années de service","Le partage du dernier repas d'équipe","L'hospitalité due aux visiteurs"]}},{"id":"t8-59","q":"Quelles couleurs portent les flots remis au départ routier, et que rappellent-elles ?","a":"**Jaune**, couleur des **louveteaux** (la joie) ; **vert**, couleur des **éclaireurs** (l'espérance) ; **rouge**, couleur des **routiers** (le sang et l'amour).","src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf","note":"LOUVETISME.pdf (document plus ancien) attribue des flots marron aux compagnons et gris aux apprentis.","qcm":{"ok":"Jaune, vert, rouge : louveteaux, éclaireurs, routiers","no":["Vert, jaune, rouge : couleurs du drapeau national","Bleu, vert, gris : louveteaux, éclaireurs, routiers","Rouge, blanc, vert : service, religion, physique"]}},{"id":"t8-60","q":"Que doit retirer l'éclaireur qui entre dans une communauté ?","a":"Les insignes de fonction doivent être retirés : il retire **les baguettes de patrouille, insignes de classe, badges et bandes**. Les étoiles d'ancienneté se portent jusqu'à la montée à la communauté.","src":"LOUVETISME.pdf","qcm":{"ok":"Baguettes de patrouille, insignes de classe, badges et bandes","no":["Son foulard de région et son insigne de promesse","Sa chemise verte et son ceinturon","Son insigne mondial et l'écusson national"]}}]}$xxb$::jsonb, now()),
  ('cards-9', $xxb${"theme":9,"cards":[{"id":"t9-01","q":"Quelle est la mission du scoutisme et quand a-t-elle été adoptée ?","a":"Contribuer à l'éducation des jeunes, en partant des valeurs de la Promesse et de la Loi, pour construire **un monde meilleur** peuplé de personnes épanouies. Adoptée à la **35e Conférence mondiale, Durban (Afrique du Sud), 1999**.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"35e Conférence mondiale, Durban, 1999","no":["40e Conférence mondiale, Ljubljana, 2014","41e Conférence mondiale, Bakou, 2017","35e Conférence mondiale, Thessalonique, 2002"]}},{"id":"t9-02","q":"Que prévoyait la Vision 2023 de l'OMMS ?","a":"D'ici 2023, faire du scoutisme le principal mouvement éducatif pour les jeunes, permettant à **100 millions de jeunes** de devenir des citoyens actifs. Adoptée à la **40e Conférence mondiale de Ljubljana (Slovénie), 2014**.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"100 millions de jeunes citoyens actifs ; adoptée à Ljubljana en 2014","no":["50 millions de jeunes citoyens actifs ; adoptée à Durban en 1999","100 millions de jeunes citoyens actifs ; adoptée à Bakou en 2017","200 millions de jeunes citoyens actifs ; adoptée à Ljubljana en 2014"]}},{"id":"t9-03","q":"Quelles sont les six priorités stratégiques de l'OMMS définies à Ljubljana en 2014 ?","a":"**Engagement des jeunes, Méthodes éducatives, Diversité et inclusion, Impact social, Communication et relations extérieures, Gouvernance.**","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Jeunes, méthodes éducatives, diversité, impact social, communication, gouvernance","no":["Paix, environnement, développement, santé, éducation, climat et partenariats","Jeunes, santé, nutrition, climat, partenariats, finances et patrimoine","Promesse et loi, équipes, nature, progression, service, relation aux adultes"]}},{"id":"t9-04","q":"Qu'est-ce que l'OMMS d'après la session sur les programmes ?","a":"Une organisation **indépendante, non lucrative et non partisane**, comptant **plus de 50 millions de membres** dans **160 pays et territoires**.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","note":"Le dépliant « Paroissiens POURQUOI ADHERER AU SCOUTISME.pdf » donne d'autres chiffres : +57 millions de scouts et +200 organisations scoutes nationales.","qcm":{"ok":"Plus de 50 millions de membres dans 160 pays et territoires","no":["Plus de 20 millions de membres dans 100 pays","Plus de 100 millions de membres dans 216 pays","Plus de 50 millions de membres dans 60 pays"]}},{"id":"t9-05","q":"Quelle est l'instance gouvernante de l'OMMS, et à quel rythme se réunit-elle ?","a":"La **Conférence mondiale**, qui se réunit **tous les trois ans**. Son conseil exécutif est le **Comité mondial**, composé de volontaires élus.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"La Conférence mondiale, tous les trois ans","no":["Le Comité mondial, chaque année","Le Bureau mondial, tous les deux ans","La Conférence mondiale, tous les cinq ans"]}},{"id":"t9-06","q":"En quelle année le Bureau mondial a-t-il proposé le Brevet Scouts du Monde ?","a":"En **2004**, premier programme de la liste historique (puis 2005 : Programme Environnement).","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"2004","no":["2011","2016","1999"]}},{"id":"t9-07","q":"Quels programmes de l'OMMS datent de 2016 et de 2018 ?","a":"**2016 : Cadre Monde Meilleur** (Better World Framework). **2018 : Mobilisation scouts pour les ODD**.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"2016 : Cadre Monde Meilleur ; 2018 : Mobilisation pour les ODD","no":["2016 : Tribu de la Terre ; 2018 : Leaders de la vie","2016 : Messagers de la paix ; 2018 : Alliés pour la santé","2016 : Mobilisation pour les ODD ; 2018 : Cadre Monde Meilleur"]}},{"id":"t9-08","q":"Quels programmes de l'OMMS sont apparus en 2020 et en 2024 ?","a":"**2020 : Tribu de la Terre**. **2024 : Leaders de la vie** et **Alliés pour la santé**.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"2020 : Tribu de la Terre ; 2024 : Leaders de la vie et Alliés pour la santé","no":["2020 : Messagers de la paix ; 2024 : Tribu de la Terre","2020 : Alliés pour la santé ; 2024 : Brevet Scouts du Monde","2020 : Leaders de la vie ; 2024 : Programme Environnement"]}},{"id":"t9-09","q":"Que signifie la « théorie de l'alignement » du Bureau mondial ?","a":"S'aligner sur les programmes et concepts des grandes organisations (**UNESCO, UNICEF, Nations unies**) : les **OSN ajustent leurs plans, programmes et opérations** pour être cohérentes avec la stratégie globale de l'OMMS. C'est dans ce contexte qu'est né **Scouts for SDGs**.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"Les OSN ajustent leurs plans et programmes à la stratégie globale de l'OMMS","no":["L'OMMS impose un uniforme unique à toutes les OSN","Chaque OSN choisit ses priorités sans lien avec l'OMMS","Les branches s'alignent sur les mêmes tranches d'âge partout"]}},{"id":"t9-10","q":"Quand et par quel cadre les 17 ODD de l'ONU ont-ils été adoptés ?","a":"En **2015**, via l'**Agenda 2030** : un plan pour éradiquer la pauvreté, protéger la planète et garantir la prospérité d'ici 2030.","src":"Récap 17 ODDs.pdf","qcm":{"ok":"En 2015, via l'Agenda 2030","no":["En 2000, via l'Agenda 2015","En 2014, via la Vision 2023","En 2018, via l'Agenda 2030"]}},{"id":"t9-11","q":"Quel est l'ODD n° 4 ?","a":"**Éducation de qualité** : garantir une éducation inclusive et équitable et promouvoir l'apprentissage tout au long de la vie.","src":"BETTER WORLD FRAMWORK.pdf, Récap 17 ODDs.pdf","qcm":{"ok":"Éducation de qualité","no":["Égalité entre les sexes","Bonne santé et bien-être","Travail décent et croissance économique"]}},{"id":"t9-12","q":"Quel est l'ODD n° 16 ?","a":"**Paix, justice et institutions efficaces** : promouvoir des sociétés pacifiques et inclusives.","src":"BETTER WORLD FRAMWORK.pdf, Récap 17 ODDs.pdf","qcm":{"ok":"Paix, justice et institutions efficaces","no":["Partenariats pour la réalisation des objectifs","Inégalités réduites","Vie terrestre"]}},{"id":"t9-13","q":"Combien d'initiatives et de défis compte le programme « Les Scouts pour les ODD » ?","a":"**4 initiatives** regroupant **10 défis** : Messagers de la Paix, Tribus de la Terre, Life Leaders, Health Allies (Alliés de la santé).","src":"Récap initiatives et défis.PDF, SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"4 initiatives et 10 défis","no":["3 initiatives et 17 défis","4 initiatives et 8 défis","5 initiatives et 10 défis"]}},{"id":"t9-14","q":"Quels sont les défis de l'initiative Tribus de la Terre (Earth Tribe) ?","a":"**Champions de la Nature**, **Plastic Tide Turners** (contre la marée de plastique) et **Go Solar** (énergie solaire).","src":"Récap initiatives et défis.PDF, SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"Champions de la Nature, Plastic Tide Turners, Go Solar","no":["Dialogue pour la paix, Patrimonito, Go Solar","Impact Innovators, Mind Builders, Nutrition","Champions de la Nature, EQ in action, Patrimonito"]}},{"id":"t9-15","q":"Quels sont les défis de l'initiative Messagers de la Paix ?","a":"**Dialogue pour la paix**, **Dialogue interreligieux** et **Scout Patrimonito** (protection du patrimoine culturel, historique et naturel).","src":"Récap initiatives et défis.PDF, SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"Dialogue pour la paix, Dialogue interreligieux, Patrimonito","no":["Plastic Tide Turners, Go Solar, Patrimonito","Dialogue pour la paix, Impact Innovators, Nutrition","Mind Builders, EQ in action, Dialogue interreligieux"]}},{"id":"t9-16","q":"Quels défis composent les initiatives Life Leaders et Alliés de la santé ?","a":"**Life Leaders** : Impact Innovators et EQ in action (intelligence émotionnelle). **Alliés de la santé (Health Allies)** : Mind Builders (santé mentale) et Nutrition.","src":"Récap initiatives et défis.PDF, SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","note":"Dans le récap, l'attribution de Mind Builders se lit d'après la mise en page ; la session (pptx) confirme qu'un défi santé mentale relève des Alliés de la santé.","qcm":{"ok":"Life Leaders : Impact Innovators, EQ ; Santé : Mind Builders, Nutrition","no":["Life Leaders : Go Solar, Nutrition ; Santé : EQ, Patrimonito","Life Leaders : Mind Builders, Nutrition ; Santé : Impact Innovators, EQ","Life Leaders : Patrimonito, EQ ; Santé : Plastic Tide Turners, Nutrition"]}},{"id":"t9-17","q":"Combien d'activités minimum faut-il réaliser pour obtenir un badge Scouts for SDGs ?","a":"Au moins **5 activités** de la banque d'activités du site, avec les questions de réflexion après chacune, puis un **projet de service communautaire**.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"5 activités au minimum","no":["3 activités au minimum","10 activités au minimum","17 activités, une par ODD"]}},{"id":"t9-18","q":"Après avoir réalisé son projet Scouts for SDGs, où le partage-t-on et que reçoit-on ?","a":"On partage l'histoire du projet sur **sdgs.scout.org**, on attend **jusqu'à une semaine** l'e-mail de commentaires, puis on reçoit un **badge numérique** dans son compte.","src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx","qcm":{"ok":"Sur sdgs.scout.org ; badge numérique après jusqu'à une semaine","no":["Au district ; badge en tissu remis au camp","Sur scout.org ; diplôme papier après un mois","À l'OSN ; badge numérique après trois mois"]}},{"id":"t9-19","q":"Quels sont les trois éléments de l'initiative Messagers de la Paix (MoP) ?","a":"**Le programme, le réseau et le fonds de soutien.** Le réseau inspire des idées de projets, le programme conseille sur leur mise en œuvre, le fonds donne les moyens aux OSN.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Le programme, le réseau et le fonds de soutien","no":["La découverte, le service volontaire et le réseau","Les principes, les buts et les fiches d'activités","Le badge, le site web et le Jamboree"]}},{"id":"t9-20","q":"Citez des buts du Programme Mondial Environnement du Scoutisme.","a":"Un monde où : humains et nature disposent d'**eau et d'air purs** ; les habitats suffisent aux **espèces natives** ; les risques des **substances dangereuses** sont minimisés ; les **pratiques écologiques les plus adaptées** sont utilisées ; les gens sont **prêts à réagir aux catastrophes naturelles**. (5 buts)","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Cinq buts, dont l'eau et l'air purs et la protection des espèces natives","no":["Trois buts : paix, environnement et développement","Quatre buts : planter, recycler, nettoyer, sensibiliser","Six buts calqués sur les priorités stratégiques"]}},{"id":"t9-21","q":"Autour de quels trois thèmes s'articule le Brevet Scouts du Monde (SDM) ?","a":"**Paix, Environnement et Développement**, pour préparer les jeunes adultes à la « citoyenneté mondiale ».","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Paix, Environnement et Développement","no":["Santé, Éducation et Climat","Paix, Dialogue et Patrimoine","Foi, Service et Communauté"]}},{"id":"t9-22","q":"À qui s'adresse le Brevet Scouts du Monde ?","a":"Aux jeunes de **15 à 26 ans**, sans distinction d'aptitude, de religion, d'origine ethnique ou géographique ; on peut y inviter des non-scouts.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Aux jeunes de 15 à 26 ans, scouts ou non","no":["Aux routiers de 18 à 22 ans uniquement","Aux chefs d'unité de plus de 21 ans","Aux éclaireurs de 12 à 17 ans"]}},{"id":"t9-23","q":"Quels sont les trois éléments du Brevet SDM ?","a":"1) **La Découverte SDM** (Explorer et Répondre) ; 2) **Le Service Volontaire SDM** (Passer à l'action) ; 3) **Le Réseau SDM**.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"Découverte, Service Volontaire, Réseau","no":["Programme, Réseau, Fonds de soutien","Explorer, Répondre, Partager","Découverte, Badge, Jamboree"]}},{"id":"t9-24","q":"Combien d'heures dure au minimum la Découverte SDM, et quelles en sont les deux phases ?","a":"Au moins **21 heures** de travail. Phases : **Explorer** (« De quoi cela traite-t-il ? ») puis **Répondre** (« Qu'est-ce que cela veut dire pour moi ? »).","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"21 heures ; Explorer puis Répondre","no":["80 heures ; Explorer puis Agir","21 heures ; Découvrir puis Partager","12 heures ; Explorer puis Répondre"]}},{"id":"t9-25","q":"Dans quel cadre stratégique le Brevet SDM a-t-il été développé ?","a":"Dans le cadre des priorités « **Participation des jeunes** » et « **Adolescents** » adoptées par la **Conférence mondiale de Thessalonique en 2002**.","src":"BETTER WORLD FRAMWORK.pdf","qcm":{"ok":"« Participation des jeunes » et « Adolescents », Thessalonique 2002","no":["« Impact social » et « Diversité », Ljubljana 2014","« Engagement des jeunes » et « Gouvernance », Durban 1999","« Méthodes éducatives » et « Adolescents », Bakou 2017"]}},{"id":"t9-26","q":"Quels sont les trois principes du Mouvement scout ?","a":"Le principe spirituel **« Devoir envers Dieu »**, le principe social **« Devoir envers autrui »** et le principe personnel **« Devoir envers soi-même »**.","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf, Paroissiens POURQUOI ADHERER AU SCOUTISME.pdf","qcm":{"ok":"Devoir envers Dieu, envers autrui, envers soi-même","no":["Franchise, Dévouement, Pureté","Paix, Environnement, Développement","Promesse, Loi, Méthode"]}},{"id":"t9-27","q":"Comment le principe « Devoir envers autrui » est-il formulé (premier paragraphe) ?","a":"**« La participation au développement de la société dans le respect de la dignité de l'homme et de l'intégrité de la nature. »** Le service y est compris au sens large, comme contribution au développement de la société.","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"Participer au développement de la société en respectant l'homme et la nature","no":["Adhérer à des principes spirituels et à la religion qui les exprime","Être responsable de son propre développement","Pratiquer chaque jour une bonne action dans sa patrouille"]}},{"id":"t9-28","q":"Quelle est la définition du scoutisme rappelée au symposium de Libreville ?","a":"Un **mouvement éducatif pour les jeunes, fondé sur le volontariat**, à caractère **non politique**, **ouvert à tous sans distinction d'origine, de race ni de croyance**, conformément aux buts, principes et méthode du Fondateur.","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"Mouvement éducatif, volontaire, non politique, ouvert à tous","no":["Mouvement religieux réservé aux baptisés","Mouvement politique de jeunesse patriotique","Mouvement sportif financé par l'État"]}},{"id":"t9-29","q":"Quand et où le 8e élément de la méthode scoute a-t-il été ajouté, et lequel est-ce ?","a":"À la **41e Conférence mondiale de Bakou (Azerbaïdjan), en août 2017** : l'**engagement dans la communauté**.","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"Bakou, août 2017 : l'engagement dans la communauté","no":["Ljubljana, 2014 : le partenariat éducatif","Durban, 1999 : le cadre symbolique","Bakou, août 2017 : le contact avec la nature"]}},{"id":"t9-30","q":"Selon le Père Jacques Sevin, qui est « ton prochain » ?","a":"« Ce n'est pas seulement les scouts, ni tes concitoyens, ni les hommes qui parlent la même langue que toi […]. **C'est tous les hommes.** »","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"Tous les hommes","no":["Les scouts du monde entier","Les membres de sa paroisse","Ses concitoyens et sa famille"]}},{"id":"t9-31","q":"Que répond Baden-Powell quand on lui demande où la religion entre dans le scoutisme (High Leigh, 1926) ?","a":"« **Elle n'y entre pas du tout. Elle est déjà là.** » Elle est le facteur fondamental sous-jacent du scoutisme et du guidisme.","src":"Education spirituelle des branchesV21_09_22.pdf, Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"« Elle n'y entre pas du tout. Elle est déjà là. »","no":["« Elle entre par la Promesse et la Loi. »","« Elle reste l'affaire des aumôniers. »","« Elle entre par la prière du soir au camp. »"]}},{"id":"t9-32","q":"Que déclare la résolution 14/24 de la Conférence mondiale de 1924 ?","a":"« Le Mouvement des scouts ne veut pas **affaiblir, mais au contraire renforcer** les croyances religieuses de chacun de ses membres. La Loi exige que le scout **pratique fidèlement et sincèrement sa religion**. »","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Le scoutisme veut renforcer les croyances religieuses de chacun","no":["Le scoutisme doit rester neutre et sans religion","Chaque troupe doit adopter une seule religion","La religion est réservée à la branche Route"]}},{"id":"t9-33","q":"Qui a élaboré le Programme d'éducation spirituelle des branches de la CICS-Afrique ?","a":"**Ernest Clément Mendy**, formateur Scouts du Sénégal, avec des relecteurs. Il a été validé lors du **1er Symposium de la CICS-Afrique à Dakar en août 2022**.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Ernest Clément Mendy, formateur Scouts du Sénégal","no":["Peter Kabo, théologien et formateur-adjoint","Marcelin Henry Diène, président CICS Afrique","Francis Ely Mbengue, chef de groupe"]}},{"id":"t9-34","q":"Quelles sont les quatre compétences pédagogiques de base du programme d'éducation spirituelle ?","a":"1) **S'engager dans un cheminement spirituel** ; 2) **Connaître l'héritage spirituel chrétien et comprendre les autres religions** ; 3) **Vivre et célébrer sa foi** personnellement et avec d'autres ; 4) **Témoigner de l'Évangile par ses actes au service des autres**.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Cheminer, connaître, vivre et célébrer, témoigner par le service","no":["Prier, jeûner, donner l'aumône, faire un pèlerinage","Explorer, répondre, agir, partager","Paix, environnement, développement, santé"]}},{"id":"t9-35","q":"Quelle est la tranche d'âge des louveteaux selon le programme, et à quoi sont-ils spontanément attirés ?","a":"**7 à 12 ans**. Le louveteau est attiré par **l'aspect rituel** (codes, cérémonies, signes) et adore les **histoires** ; il découvre la prière.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"7 à 12 ans ; attirés par les rites et les récits","no":["12 à 17 ans ; attirés par les débats","7 à 12 ans ; attirés par la méditation longue","5 à 8 ans ; attirés par la solitude"]}},{"id":"t9-36","q":"Au camp, combien de temps faut-il prévoir avant un temps de prière avec les louveteaux, et quelle limite respecter ?","a":"Compter **20 à 30 min de retour au calme** après une activité festive ; **au-delà de 30 min** de concentration, les louveteaux s'endorment ou chahutent.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"20 à 30 min de retour au calme ; pas plus de 30 min de prière","no":["5 min de retour au calme ; pas plus d'une heure","1 heure de retour au calme ; pas plus de 10 min","Aucun délai ; pas plus de 45 min"]}},{"id":"t9-37","q":"Quel est l'objectif terminal d'intégration de la branche éclaireur ?","a":"L'éclaireur sera capable de **prendre de bonnes initiatives** personnelles et dans sa communauté, et d'**opérer des choix éclairés** en se basant sur les enseignements de l'Église catholique.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Prendre de bonnes initiatives et faire des choix éclairés","no":["Vivre sa religion et s'intégrer dans un contexte religieux","Découvrir son charisme de témoin par le service","Réciter les principales prières catholiques"]}},{"id":"t9-38","q":"Quelle pratique quotidienne relie l'Heure des Loups à l'Heure Route chez les éclaireurs ?","a":"Chaque jour, au moins **une minute de silence** pour confier une intention au Seigneur et à Marie.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Au moins une minute de silence par jour","no":["Une heure de méditation en solitaire","La récitation du Rosaire chaque soir","Un jeûne d'une journée par semaine"]}},{"id":"t9-39","q":"D'après Baden-Powell cité dans le programme, à quoi sert la bonne action quotidienne (BA) ?","a":"C'est le moyen pratique de formation à la charité : « **le meilleur moyen de faire des chrétiens en fait et pas seulement en théorie** ».","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Faire des chrétiens en fait et pas seulement en théorie","no":["Gagner rapidement des badges de progression personnelle","Remplacer la prière du soir pendant les camps","Préparer l'examen du Brevet Scouts du Monde"]}},{"id":"t9-40","q":"Que signifie Ubuntu dans la culture xhosa ?","a":"**« Je suis, parce que nous sommes. »** C'est une philosophie d'Afrique australe : un individu n'existe qu'à travers sa relation avec les autres.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"« Je suis, parce que nous sommes. »","no":["« La grandeur du cœur »","« Le chemin parcouru ensemble »","« Toujours prêt à servir »"]}},{"id":"t9-41","q":"Quand commence et quand se termine l'année liturgique catholique ?","a":"Elle commence avec l'**Avent** et se termine avec la solennité du **Christ Roi** (34e dimanche du Temps ordinaire, fin novembre). Son cœur est le **Triduum pascal**.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Commence à l'Avent, finit au Christ Roi","no":["Commence à Noël, finit à la Toussaint","Commence au Carême, finit à Pâques","Commence le 1er janvier, finit à l'Avent"]}},{"id":"t9-42","q":"Quelle tranche d'âge le programme donne-t-il pour les routiers, et quel est leur objectif terminal ?","a":"**18 à 26 ans** (jeunes adultes). Objectif : **découvrir son charisme personnel de témoin de l'amour de Dieu** pour les hommes, **par le service routier**.","src":"Education spirituelle des branchesV21_09_22.pdf","note":"Le Better World Framework parle d'une branche Route de 18 à 22 ans.","qcm":{"ok":"18 à 26 ans ; découvrir son charisme de témoin par le service","no":["15 à 18 ans ; prendre de bonnes initiatives","18 à 22 ans ; réciter les prières catholiques","18 à 26 ans ; s'intégrer dans un contexte religieux"]}},{"id":"t9-43","q":"Sur quels deux piliers le routier appuie-t-il sa formation spirituelle ?","a":"**Le mentorat** (parrain routier et Père spirituel) et **l'Heure Route**.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Le mentorat et l'Heure Route","no":["La BA et le secourisme","Le Rosaire et la messe dominicale","Le Brevet SDM et le Jamboree"]}},{"id":"t9-44","q":"Qu'est-ce que l'Heure Route, et quelle est sa seule règle ?","a":"Une heure de **retraite quotidienne** où les routiers s'éloignent pour méditer, prier, réfléchir sur soi. **Une seule règle : le silence.**","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Une heure de retraite quotidienne ; seule règle : le silence","no":["Une heure de service ; seule règle : la ponctualité","Une heure de chant en clan ; seule règle : l'unité","Une heure de jeu ; seule règle : le fair-play"]}},{"id":"t9-45","q":"Quel rôle joue le parrain routier, et qui peut l'être ?","a":"Il est le **« premier de cordée »** qui précède le routier et l'aide à faire ses choix ; il est **nécessairement un Routier Scout**. Il écoute, questionne, fait réfléchir.","src":"Education spirituelle des branchesV21_09_22.pdf","qcm":{"ok":"Le « premier de cordée », nécessairement un Routier Scout","no":["Le chef de troupe, nécessairement un prêtre","Le commissaire de district, élu par le clan","Un parent du routier, choisi par la famille"]}},{"id":"t9-46","q":"Quand la CICS a-t-elle été fondée, et où se trouve son siège ?","a":"**Fondée en 1962** par des associations scoutes catholiques membres de l'OMMS ; **siège à Rome**.","src":"Quest ce que la CICS PDF.pdf","note":"La présentation de Libreville présente le Père Sevin comme « co-fondateur de la CICS », alors que la CICS est fondée en 1962 et que Sevin meurt en 1951 ; il a cofondé l'OISC en 1920.","qcm":{"ok":"Fondée en 1962 ; siège à Rome","no":["Fondée en 1920 ; siège à Paris","Fondée en 1962 ; siège à Genève","Fondée en 1907 ; siège à Londres"]}},{"id":"t9-47","q":"Quel statut la CICS a-t-elle auprès du scoutisme mondial ?","a":"Un **statut consultatif** auprès de l'OMMS (comité mondial). Ses statuts sont approuvés par l'OMMS et par le Saint-Siège.","src":"Quest ce que la CICS PDF.pdf, Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf","qcm":{"ok":"Un statut consultatif","no":["Membre fondateur de l'OMMS","Organisation scoute nationale","Bureau régional Afrique de l'OMMS"]}},{"id":"t9-48","q":"Citez des buts de la CICS.","a":"Contribuer à l'**éducation complète des jeunes du point de vue de la foi catholique** ; développer la **dimension spirituelle du scoutisme** ; assurer la présence des catholiques scouts dans l'Église ; **garantir la communication entre l'Église et le Mouvement scout mondial**.","src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf, Quest ce que la CICS PDF.pdf","qcm":{"ok":"Développer la dimension spirituelle, relier Église et OMMS","no":["Organiser les Jamborees mondiaux de l'OMMS","Délivrer le Brevet Scouts du Monde aux routiers","Gérer les finances des associations catholiques"]}},{"id":"t9-49","q":"Qui était le Père Jacques Sevin (dates et statut) ?","a":"Prêtre **jésuite** français, né à **Lille le 7 décembre 1882**, mort le **19 juillet 1951**. Déclaré **vénérable par Benoît XVI le 10 mai 2012**.","src":"Quest ce que la CICS PDF.pdf","qcm":{"ok":"Jésuite né en 1882, mort en 1951, déclaré vénérable en 2012","no":["Dominicain né en 1857, mort en 1941, canonisé en 2000","Jésuite né en 1882, mort en 1962, béatifié en 1994","Franciscain né en 1890, mort en 1951, vénérable en 2005"]}},{"id":"t9-50","q":"Quel office international le Père Sevin a-t-il contribué à former en 1920, et quel y était son rôle ?","a":"L'**Office International des Scouts Catholiques (OISC)**, avec Mario di Carpegna (Italie) et Jean Corbisier (Belgique) ; Sevin en est nommé **secrétaire**.","src":"Quest ce que la CICS PDF.pdf","qcm":{"ok":"L'OISC, dont il est nommé secrétaire","no":["La CICS, dont il est nommé président","L'OMMS, dont il est nommé commissaire","La CSS, dont il est nommé aumônier"]}},{"id":"t9-51","q":"Que signifie la croix potencée de la croix scoute catholique ?","a":"Quatre **« Tau »** tournés vers les quatre points cardinaux : l'**universalité du salut**. Sevin a repris les armes des **Chevaliers hospitaliers de Saint-Jean de Jérusalem** (service et dévouement).","src":"Quest ce que la CICS PDF.pdf","qcm":{"ok":"L'universalité du salut, d'après les armes des Hospitaliers","no":["Les quatre branches du scoutisme","Les quatre points de la Loi scoute","Les quatre évangélistes et leurs symboles"]}},{"id":"t9-52","q":"Que rappelle la fleur de lys choisie par Baden-Powell vers 1909 ?","a":"Le scout sait **s'orienter** (elle indiquait le Nord sur les boussoles) ; elle rappelle les **trois parties de la Promesse** et trois vertus : **Franchise, Dévouement, Pureté**.","src":"Quest ce que la CICS PDF.pdf","qcm":{"ok":"Franchise, Dévouement, Pureté","no":["Foi, Espérance, Charité","Paix, Environnement, Développement","Loyauté, Courage, Honneur"]}},{"id":"t9-53","q":"Quel récit évangélique illustre le rôle de l'accompagnateur spirituel (aumônier) ?","a":"Les **pèlerins d'Emmaüs** (Lc 24, 13-35) : il écoute, partage la parole et le repas, puis disparaît, pour qu'on se tourne vers le Christ.","src":"Quest ce que la CICS PDF.pdf","qcm":{"ok":"Les pèlerins d'Emmaüs","no":["La parabole du bon Samaritain","Les noces de Cana","Le pauvre Lazare et le mauvais riche"]}},{"id":"t9-54","q":"Qui a conçu le Programme sur le dialogue interreligieux de la CICS-Afrique ?","a":"**Peter Kabo**, formateur-adjoint Scouts du Sénégal, théologien, sociologue des religions et canoniste.","src":"Programme Dialogue Interreligieux CICS.pdf","qcm":{"ok":"Peter Kabo","no":["Ernest Clément Mendy","Serge Badji","Jean Pascal Correa"]}},{"id":"t9-55","q":"À qui l'OMMS destine-t-elle le Brevet du Dialogue Interreligieux (BDI), et qu'ajoute la CICS-Afrique ?","a":"L'OMMS le destine aux **jeunes des branches aînées** ; la CICS-Afrique ouvre son programme à **toutes les branches**.","src":"Programme Dialogue Interreligieux CICS.pdf","qcm":{"ok":"Aux branches aînées ; la CICS l'ouvre à toutes les branches","no":["Aux louveteaux ; la CICS le réserve aux routiers","Aux chefs ; la CICS l'ouvre aux parents","Aux éclaireurs ; la CICS le limite aux catholiques"]}},{"id":"t9-56","q":"Quelles sont les trois orientations du BDI suivies pour les aînés ?","a":"**La maturation spirituelle**, **l'exploration de l'invisible** et **le vivre-ensemble**.","src":"Programme Dialogue Interreligieux CICS.pdf","qcm":{"ok":"Maturation spirituelle, exploration de l'invisible, vivre-ensemble","no":["Identité religieuse, richesse des autres religions, prière commune","Découverte SDM, service volontaire SDM, réseau SDM","Explorer, répondre, puis passer à l'action dans la communauté"]}},{"id":"t9-57","q":"Quelles devises le programme de dialogue interreligieux donne-t-il à chaque branche ?","a":"**Branche jaune** : « L'ouverture dans la joie » ; **branche verte** : « L'action dans l'espérance » ; **aînés** : « Le témoignage dans la charité ».","src":"Programme Dialogue Interreligieux CICS.pdf","qcm":{"ok":"Jaune : ouverture dans la joie ; verte : action dans l'espérance","no":["Jaune : action dans l'espérance ; verte : ouverture dans la joie","Jaune : témoignage dans la charité ; verte : service dans la paix","Jaune : prière dans le silence ; verte : action dans la joie"]}},{"id":"t9-58","q":"Quels sont les saints patrons des louveteaux, des louvettes et des éclaireurs ?","a":"**Saint François d'Assise** : louveteaux. **Sainte Claire d'Assise** : louvettes. **Saint Georges** : éclaireurs.","src":"Section sur les Saint Patrons.docx","note":"Le programme d'éducation spirituelle présente saint Georges comme « saint patron des scouts » en général.","qcm":{"ok":"François (louveteaux), Claire (louvettes), Georges (éclaireurs)","no":["Georges (louveteaux), Claire (louvettes), François (éclaireurs)","François (louveteaux), Marie (louvettes), Paul (éclaireurs)","Claire (louveteaux), François (louvettes), Georges (routiers)"]}},{"id":"t9-59","q":"Quand fête-t-on saint Georges, et que symbolise le dragon pour l'éclaireur ?","a":"Le **23 avril**. Le dragon symbolise **la difficulté ou le danger** : l'éclaireur doit y faire face **avec courage et confiance**.","src":"Section sur les Saint Patrons.docx","qcm":{"ok":"Le 23 avril ; le dragon symbolise la difficulté ou le danger","no":["Le 4 octobre ; le dragon symbolise l'orgueil","Le 11 août ; le dragon symbolise la pauvreté","Le 23 avril ; le dragon symbolise la nature sauvage"]}},{"id":"t9-60","q":"Quelles sont les quatre principales confréries musulmanes du Sénégal citées ?","a":"La **Qadiriyya** (la plus ancienne), la **Tijaniyya** (la plus répandue), les **Mourides** (fondée par Cheikh Ahmadou Bamba) et les **Layènes** (Yoff, Seydina Limamou Laye).","src":"Confréries du Sénégal (1).docx","qcm":{"ok":"Qadiriyya, Tijaniyya, Mourides, Layènes","no":["Qadiriyya, Tijaniyya, Mourides, Soufis","Tijaniyya, Mourides, Layènes, Ahmadiyya","Qadiriyya, Mourides, Layènes, Sanousiyya"]}}]}$xxb$::jsonb, now()),
  ('fiche-1', $xxb${"theme":1,"titre":"Bases et histoire","intro":"Construite à partir des documents du dossier Bases Générales et du dossier Troupe. Chaque section indique ses sources.","sections":[{"h":"Baden-Powell en repères","items":["**22 février 1857**, Londres. Père : pasteur protestant et professeur de géométrie à Oxford. Mère : naturaliste. Militaire de **1876 à 1910**.","**Brownsea, du 29 juillet au 9 août 1907** : une vingtaine de jeunes. Premières patrouilles : **loups, taureaux, courlis, corbeaux**. Jeux d'observation et de traque, secourisme, nœuds, camping, cuisine au feu de camp.","**1908** : *Scouting for Boys* (Éclaireurs). **1909** : premier rallye à Crystal Palace (10 000 éclaireurs). **1910** : B-P quitte l'armée.","**1912** : mariage avec Olave Soames (30 octobre), trois enfants : Peter, Heather, Betty. **1914** : création du louvetisme. **1916** : Livre du louveteau.","**1919** : camp de formation des chefs de Gilwell. **1920** : premier Jamboree mondial à Londres, B-P proclamé Chef scout du monde. **1922** : *La route du succès* (annale Rallye).","**1929** : titre de Lord Baden-Powell of Gilwell. **1939** : nommé pour le Nobel de la paix. **8 janvier 1941** : décès à Nyeri (Kenya), à 83 ans."],"src":"Bases du scoutisme.pdf, fiches-BP.pdf, Quiz-BP.pdf, Connaissance du mvt rallye dak23.pdf"},{"h":"Les 15 éléments fondamentaux","items":["**5 buts (acronyme SSSDF)** : Santé, Service du prochain, Sens de Dieu, Débrouillardise (sens du concret), Formation du caractère.","**5 dimensions** : la nature et le camp, la patrouille, la règle du jeu (la loi scoute), le civisme (la B.A.), l'engagement (la promesse).","**5 moteurs** : l'intérêt, l'action, les responsabilités, le système des patrouilles, la CDH et le CDC.","Nuance du texte : le « sens de Dieu » n'est pas en soi un but défini par B-P. Le but du scoutisme n'est pas de former de futurs prêtres, mais de bons citoyens."],"src":"Bases du scoutisme.pdf"},{"h":"Promesse, loi, devise, signes","items":["**Promesse** : triple engagement, être loyal, aider autrui, observer la loi scoute. Engagement volontaire, pris sur l'honneur devant ses frères.","**Loi** : des « conseils de vie » proposés, pas des interdictions. Pas de sanction : une discussion pour progresser. La loi de B-P compte 10 articles, plus un 11e non écrit : « le scout n'est pas un sot ».","**Devise « Sois prêt »** (Be Prepared), tirée des initiales de B-P. Trois qualités : le sens des autres, la compétence, l'observation suivie du réflexe.","**B.A.** : un service gratuit, jamais contre récompense. À la meute, un plaisir fait chaque jour ; à la troupe, un réflexe d'aider ; au clan, un service permanent.","**Signes** : salut de la main droite, trois doigts levés, pouce sur l'auriculaire ; poignée de main **gauche** (héritée des Ashantis) ; **fleur de lys** (indique le nord) ; trèfle pour les guides."],"src":"Bases du scoutisme.pdf, la devise, l'esprit et les éléments fondamentaux du scoutismes.docx, fiches-BP.pdf"},{"h":"Le scoutisme au Sénégal : les débuts","items":["**1931** : le R.P. Lecocq, curé de Dakar (Sacré-Cœur), veut créer des scouts. Naissance officieuse en décembre 1931, affiliation officielle en **1932** aux **Scouts de France**.","**8 mai 1932** : première promesse de quatre garçons, dans la cour de l'école Saint Michel (Dakar), fête de Sainte Jeanne d'Arc : Gabriel Sagna, Emmanuel Nunez, Georges Monteiro, Paul de Souza.","Première troupe : **Sainte Jeanne d'Arc**. Chef de troupe : Léon Fabert (jeune militaire du 6e RAC). Aumônier : R.P. Doutremepuich.","Deux premières patrouilles : **Rats palmistes** (CP Gabriel Sagna, SP Paul de Souza) et **Iguanes** (CP Emmanuel Nunez, SP Georges Monteiro).","Ensuite : une meute, puis les troupes René Caillé et Charles Foucault. Les scouts aînés deviennent routiers en **1938**."],"src":"Historique Scoutisme Senegal.pdf (Dakar Matin, 6 mai 1968)"},{"h":"Repères du Rallye et de la progression","items":["Saint patron des éclaireurs : **saint Georges, le 23 avril**.","**Carnet de preuves** : manuel-guide qui permet à l'éclaireur de progresser. 4 parties : **volontaire, engagé, technicien, animateur**.","Plus haute distinction : le **Loup de bronze**. Premier Sénégalais décoré : Albert Ndiaye (source unique, l'annale Rallye Dakar 2023, à confirmer)."],"src":"Connaissance du mvt rallye dak23.pdf, La Progression Personnelle.pdf, Livret Carnet de Preuves.pdf"}],"vigilance":["**Taille d'une patrouille** : huit dans *Bases du scoutisme* (récit des débuts), cinq à sept dans *LE SCOUTISME.docx* (dossier Troupe) et la fiche EDLN, six à huit dans le *Manuel du CP* (voir la zone de décembre).","**Création de la Route** : 1918 selon l'annale Rallye, 1919 selon *Bases du scoutisme*. Date de *La route du succès* : 1922 (annale Rallye) ou 1919 (Bases du scoutisme).","**Âge des jeunes à Brownsea** : 9 à 17 ans (fiches-BP) contre 12 à 17 ans (Quiz-BP).","**Promesse de B-P** : le texte original parle de Dieu et du roi. Chaque association l'adapte (Dieu, l'Église et la Patrie dans la promesse de 1932 au Sénégal)."]}$xxb$::jsonb, now()),
  ('fiche-10', $xxb${"theme":10,"titre":"Spécialités et finances","intro":"Fiche construite à partir du *Guide du trésorier* de la Région de Dakar (2023), des supports de session Matelotage et des documents de topographie et d'orientation (Topographie.pdf, Section ORIENTATION, fiches boussole, rose des vents, morse).","sections":[{"h":"Le trésorier et ses missions","items":["**Trésorerie** : ensemble des sommes disponibles **en caisse ou placées en banque** ; objectif : optimiser l'équilibre financier.","Trois missions : **accompagnement** des scouts, **performance** (budget prévisionnel, respect des procédures), **technique** (tenue des comptes, collecte des pièces).","Il fixe avec le **responsable de groupe** la participation des parents et encadre le **juste recours aux extra-jobs**.","Profil : gérer un budget **« en bon père de famille »**, tenir et expliquer les comptes, être intègre et fiable ; il est **membre du Conseil de groupe**.","Bases : **bénéfice** = recettes − dépenses (5 000 F − 2 000 F = 3 000 F) ; **ressource** (ex. cotisations) / **emploi** ; bilan : emplois = ressources."],"src":"LE GUIDE DU TRÉSORIER.pdf"},{"h":"Outils : budget, tableaux et pièces","items":["**Budget prévisionnel annuel** élaboré en début d'année, **validé par l'instance de décision**, revu à intervalles réguliers ; rythme **trimestriel** recommandé.","Solde final **> 0** : fonds disponibles ; **< 0** : chercher des fonds ; **= 0** : équilibre sans réserve. **Trésorerie zéro** (début des années 1970) : placer les excédents, combler les manques au moindre coût.","**Cahier recettes-dépenses** (ordre chronologique) → base du **tableau des comptes** (récapitulatif cumulé) ; le solde final devient le solde initial suivant.","**Notes de frais** : suivi des achats d'un chef ayant reçu de l'argent ; **PCR / PCD** : pièces de caisse recette / dépense ; **décharge** : prouve une remise d'argent.","Une pièce justificative porte au minimum **date, noms et adresses des parties, montant, objet**."],"src":"LE GUIDE DU TRÉSORIER.pdf"},{"h":"Contrôle interne et placements","items":["Toute dépense doit être **vue par deux personnes** ; si le chef d'unité est trésorier : **double signature**.","**Quatre fonctions incompatibles** : décision/autorisation, ordonnancement, enregistrement/finance, contrôle.","**Chef décideur** des décaissements : chef d'unité, **Chef de groupe**, commissaire de district, commissaire régional de branche — pas le trésorier.","**DAT** : somme bloquée en banque contre intérêts ; sans risque, rémunération connue, taux négociable ; malus si retrait anticipé.","Activités lucratives proposées : spectacle, exposition-vente, tee-shirts, **programmes de messes (avec accord du curé)**, journée d'amitié, lavage de voitures."],"src":"LE GUIDE DU TRÉSORIER.pdf"},{"h":"Matelotage : cordages, vocabulaire et familles","items":["Cordage de **10 à 20 mm** en chanvre, sisal ou polypropylène ; cordes de **5-6 m** (œil épissé + épissure), **une dizaine par patrouille**.","Ranger : **lover et suspendre** ; à l'abri de l'humidité, nœuds défaits sauf épissures d'extrémité.","**Courant** : bout qui noue ; **dormant** : partie inactive ; **étaler en biture** : à plat en zigzag ; **décommettre** : desserrer les torons.","SDS : **deux familles** — nœuds **d'arrêt** et **de jonction** ; les nœuds d'amarrage sont rangés avec l'arrêt.","Message en morse sur une corde : **nœud simple = point**, **nœud de capucin = trait**."],"src":"Matelotage.pdf, Section MATELOTAGE.docx"},{"h":"Nœuds d'aspirant et brelages","items":["**10 nœuds d'aspirant** : simple, ganse, ganse à tête d'alouette, **tour mort** (délimiter un sous-camp), demi-clef, **cabestan/batelier** (débuter un brelage), **chaise** (secours), **pêcheur**, **plat**, **tisserand/écoute**.","Même diamètre : **plat** (aussi les bandages) ou **pêcheur** (plus solide) ; diamètres différents : **tisserand** ; gros câbles : **carrick**.","**Nœud de vache** = nœud plat fait à l'envers ; **jambe de chien** : raccourcir une corde, soulager une partie usée ; **bonnet de turc** : bague de foulard.","Brelages : **carré** (perpendiculaires), **diagonal** et **en étoile** (angle quelconque), **triple** (3 perches), **tête de bigue** (trépied), **en long** (parallèles), **ligature auto-serrante** (V inversé pour un toit)."],"src":"Matelotage.pdf, Section MATELOTAGE.docx"},{"h":"Topographie : signalisation et orientation","items":["*Topos* (lieu) + *graphien* (dessiner) ; chez les scouts : **signalisation** et **orientation**.","Pistes **directives** / **indicatives** ; signes de **10 à 15 cm**, **à gauche du chemin**, **sous 1 m** ; le **dernier pisteur** efface ; « suivre ce cours d'eau » valable **500 m**.","**Morse** (27 avril 1791 – 2 avril 1872) ; 1er message le **24 mai 1844** Washington–Baltimore. Ti = 1, ta = 3, espace lettres = 3, espace mots = 7.","**Trois nords** : magnétique (îles de la Reine Elizabeth, Canada), géographique, cartésien ; l'angle entre eux = **déclinaison**. Contre-azimut : ± 180°.","Rose des vents : **16 directions** ; un tour = 360° = 400 grades = **6 400 millièmes** (1 m vu à 1 km).","Sans boussole : **étoile polaire** (5 fois l'écart des deux étoiles du bout de la casserole), **montre** (bissectrice petite aiguille / 12 = Sud), soleil à **180° à midi**, 15° par heure."],"src":"Topographie.pdf, Section ORIENTATION.docx, La boussole.docx, La rose des vents.docx, Les trois nords.docx, Méthodes Apprentissage du Morse.docx, SESSION SIGNALISATION ORIENTATION-1.pdf"}],"vigilance":["**Missions du trésorier** : le plan du *Guide du trésorier* annonce une « mission politique », le corps du texte une « mission de performance ».","**Nœud de vache** : Matelotage.pdf lui donne l'utilité « joindre 2 cordes de même épaisseur », Section MATELOTAGE.docx le dit « d'aucune utilité ».","**Nom du nœud de cabestan** : « cabestan ou de batelier » dans la liste des nœuds d'aspirant, mais « cabestan ou d'écoute » dans la classification de Matelotage.pdf (« écoute » désigne aussi le tisserand).","**Familles de nœuds** : les SDS retiennent deux familles (arrêt, jonction), alors que le support de Benoît Maugis traite l'amarrage et l'ajut comme des familles distinctes.","**Code de la route** : Topographie.pdf écrit d'abord « horizontal : panneaux, vertical : marquage au sol », puis détaille l'inverse (panneaux = vertical, marquage au sol = horizontal).","**Orientation par la Lune** : SESSION SIGNALISATION ORIENTATION-1.pdf exclut la pleine lune, Section ORIENTATION.docx n'exclut que la nouvelle lune.","**Pôle de l'aiguille** : Topographie.pdf et Section ORIENTATION.docx disent que, dans un compas, « le Nord de la boussole est un pôle Nord » ; le document pdfcoffee dit que le Nord de la boussole est « un petit pôle Sud ».","**Invention du morse** : « inventé en 1832 » selon SESSION SIGNALISATION ORIENTATION-1.pdf ; selon Topographie.pdf, 1832 est l'année de l'idée, l'appareil est achevé en 1836 et le premier message envoyé en 1844."]}$xxb$::jsonb, now()),
  ('fiche-11', $xxb${"theme":11,"titre":"Annales du Rallye","intro":"Fiche construite à partir des questionnaires et des corrigés du Rallye : Mbour 2015, Médinakel 2017, Kaolack 2018 (national), Dakar 2022 et Rallye DAK23. Seules les réponses présentes dans les corrigés sont reprises.","sections":[{"h":"Connaissance du mouvement","items":["**Saint Georges**, patron des éclaireurs, fêté le **23 avril**. La Pensée scoute célèbre la **naissance de B-P** (22 février 1857).","Repères : **1907** Brownsea, **1908** *Scouting for Boys*, **1909** rallye de Crystal Palace, **1914** louvetisme, **1916** *Livre du louveteau*, **1918** route, **1922** *La route du succès*.","Plus haute distinction : le **Loup de bronze** ; premier Sénégalais distingué : **Albert Ndiaye**. Morse inventé par **Samuel Morse en 1832**.","Région de Dakar : **5 districts** (Plateau, Grand Dakar I et II, Niayes, Magola). OMMS : **172 pays** (corrigé 2022). Scoutisme africain : **13 mars**.","Méthode scoute : **8 éléments** depuis 2017, dont l'**engagement communautaire**. Principes : devoir envers **Dieu**, envers **autrui**, envers **soi-même**. Devise « Toujours prêt » : de **Be Prepared**."],"src":"Connaissance du mvt rallye dak23.pdf, Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf, Questions-Reponses Rallye National Branche Verte Kaolack 2018.pdf"},{"h":"Vie de patrouille et rôle du CP","items":["**Cour d'honneur** : organe directeur de la troupe (objectifs de l'année, admission à la promesse, sanction des progressions).","**Fanion** : emblème de la pat, **40 cm x 25 cm**, tresse 2 cm ; il est planté à terre lors de l'**investiture du CP**. Symboles de la branche verte : étendard, rassemblement, fanion, manoir.","**Livre d'or** : totem, saint patron, prière, hymne, loi, devise, cri, langage secret, liste des membres. **Cahier de bord** : comptes rendus, mémoire de la pat.","Promesse en **4 phases** : décision du jeune, décision du groupe (cour d'honneur), veillée de promesse, engagement. Nomination du CP : choix des jeunes, lettre (facultative), cour d'honneur, investiture.","Premier signe de fraternité scoute : l'**uniforme**. Kraal : chœur d'**Engonyama** (« Il est un lion… il est un hippopotame »)."],"src":"CP RALLYE DAK23.pdf, Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2023.pdf"},{"h":"Signalisation, orientation, topographie","items":["**Déclinaison** : écart entre Nord magnétique et Nord géographique. Montre : ombre d'une brindille sur l'aiguille des heures, nord sur la **bissectrice** avec l'axe 12h-6h.","Constellations : queue de la **grande ourse** et tête de la **petite ourse** vers le nord ; **Cassiopée** et le **dragon** au nord ; pointe basse de la **croix du sud** vers le sud.","Lune : seulement en **croissant**, jamais pleine. Lettres **B, Q** bonnes ; **P, D** mauvaises (prendre le sens opposé).","Boussoles : d'**orientation** (carte), de **visée** (objectif), **compas** (direction continue). **Courbe de niveau** : points de même altitude. **Rose des vents** : 16 directions.","Codages : dents de scie, clé de 100, clé de 10, sémaphore. Signalisation : **verticale, horizontale, lumineuse**."],"src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf, TOPO RALLYE DAK23.pdf, Questions Réponses Rallye 2023.pdf"},{"h":"Matelotage","items":["**10 nœuds de l'aspirant** : ganse, demi-clé, simple, tour mort, ganse à tête d'alouette, plat, pêcheur, cabestan, tisserand, chaise.","Familles : **arrêt** (simple, huit), **jonction** (plat), **coulant**. Sortir d'un puits : **chaise**. Raccourcir : **jambe de chien**. Cordes inégales : **vache** (selon les corrigés).","Crochet : **gueule de raie** ; rondin : **nœud de bois** ; clôture : **cabestan** ; effilochage : **simple** ou **capucin**.","Brêlages : **carré** (2 perches perpendiculaires), **en long** (parallèles), **triple** (3 perches), **tête de bigue** (trépied), diagonal et étoile (angle quelconque).","Vocabulaire : **toron**, **décommettre**, **frapper**, **élinguer**, **étaler en biture**, **glène**."],"src":"Questions Réponses Rallye 2017.pdf, Questions Réponses Rallye 2022.pdf, matelotage rallye dak23.pdf"},{"h":"Secourisme et sécurité","items":["**PAS** : Protéger, Alerter, Secourir. Baliser **100 à 150 m le jour**, **200 à 300 m la nuit**. Numéros : pompiers **18**, police **17**, SAMU **1515**, gendarmerie 800 00 20 20.","Hémorragie externe : compression locale, pansement compressif, point de compression, **garrot en dernier**. Interne : **position du choqué**, diète, couvrir, évacuer.","Examen : saignement, conscience, respiration, circulation, squelette. Absence de respiration : **LVA + VA**. Fréquence cardiaque adulte : **60 à 80/min**.","Brûlures : 1er degré (épiderme), 2e (cloques, ne pas percer), 3e (protocole **EEE**). Fracture fermée : protocole **RIRE** (Refroidissement, Immobilisation, Repos, Élévation).","Feux : classes **A** solides, **B** hydrocarbures, **C** gaz, **D** métaux, E électrique, F huiles. Extincteur : goupille, percuter, test, **base des flammes**."],"src":"Questions Réponses Rallye 2017.pdf, secourisme rallye dak23.pdf, Questions Réponses Rallye 2022.pdf"},{"h":"Religion et civisme","items":["Évangélistes : **Matthieu** l'homme, **Marc** le lion, **Luc** le taureau, **Jean** l'aigle. Verset le plus court : **Jean 11, 35**.","Islam : premier muezzin **Bilal** ; Tamkharit = **Achoura**. Piliers : prière, jeûne, aumône, pèlerinage, profession de foi.","Sacrements : baptême, eucharistie, confirmation, réconciliation, mariage, ordre, onction des malades. Couleurs liturgiques : **blanc, vert, violet, rouge**.","Sénégal : devise **Un peuple, un but, une foi** ; sceaux : **lion** (présidence) et **baobab** (administration)."],"src":"Questions Réponses Rallye 2023.pdf, Questions Réponses Rallye 2022.pdf, QUESTIONS REPONSES RALLYE MBOUR 2015.pdf, Questions Réponses Rallye 2017.pdf"}],"vigilance":["**Parties du carnet de preuves** : le corrigé DAK23 en donne 4 (volontaire, engagé, technicien, animateur) ; le corrigé 2017 annonce 4 parties mais n'en cite que 3 (engagé, technicien, animateur).","**5e pilier de l'islam** : « croire en Dieu » dans le corrigé 2015, « les deux témoignages » dans le corrigé 2017.","**Noms des responsables** : ils changent selon l'année (Général Serge Daniel Badji en 2017, Antoine Ghislain Kaly en 2023). Vérifier les titulaires actuels avant le Rallye.","**Brêlages diagonal et en étoile** : le corrigé DAK23 leur donne la même utilité ; seule la disposition des perches diffère."]}$xxb$::jsonb, now()),
  ('fiche-2', $xxb${"theme":2,"titre":"Cérémonial et symboles","intro":"Construite à partir de l'*Aurore cérémonial* de la branche verte, du *Cérémonial Sénégal* révisé et du texte *Montée ou levée des couleurs* (dossiers Bases Générales et Troupe). Le document sur les objets et symboles protégés, scanné sans texte, n'a pas pu être utilisé.","sections":[{"h":"Le cérémonial et les étapes du jeune","items":["Un **cérémonial** est l'ensemble des signes qui crée un **décorum** et permet à la troupe de mesurer l'importance des instants vécus. On y associe les éclaireurs.","**Accueil** : après trois ou quatre réunions, le CT remet le **foulard** au cours d'une petite cérémonie (rassemblement en rectangle, prière, remise du foulard, confiance au CP, chant).","**Montée meute → troupe** : troupe en **rectangle**, meute en **cercle**, maîtrises dos à dos à **5 m**. Le louveteau reçoit une **deuxième et dernière fois le Grand Hurlement**, salue l'étendard et garde son uniforme jusqu'à sa promesse.","**Montée troupe → communauté** : cérémonie **officieuse** (session régionale de 1996 à Pikine, non homologuée). Le CC remet l'**uniforme gris** et le **flot d'apprenti**.","**Technicien** (une bande rouge) et **animateur** (deux bandes rouges) : insigne sur la manche gauche, remis devant la troupe ; le CT entonne ensuite le **chant de la promesse**."],"src":"Aurore Ceremonial Verte.pdf, CEREMONIAL+SENEGAL+revise (1) (1).pdf"},{"h":"Cour d'honneur et promesse","items":["La **cour d'honneur** éduque **par la confiance** et garde la loi scoute. Y siègent CP, SP, éclaireurs animateurs et maîtrise ; le **CT préside avec droit de veto**. Délibérations **secrètes** ; seule une autre C.H. peut revenir sur une décision, sur faits nouveaux.","La **promesse** est une **adhésion libre, volontaire et personnelle**, demandée par le scout. Quatre phases : **décision du garçon** (demande manuscrite au CT, signée du CP), **cour d'honneur**, **veillée**, **engagement**.","**Veillée de promesse** (héritière de la *veillée d'armes*) : de nuit, 1 h 50 au plus, chant **Notre-Dame des Éclaireurs** autour d'un feu (symbole de l'unité). Seule cérémonie scoute possible **dans une église**.","**Engagement** : troupe en **rectangle sur trois côtés**, le quatrième pour les parents ; jamais en lieu fermé. Vertus : **Franchise, Dévouement, Pureté** ; première obligation : **la bonne action quotidienne** ; durée : **« S'il plaît à Dieu, toujours »**.","Formule : « Devant tous, avec la grâce de Dieu, je m'engage sur mon honneur, à servir de toutes mes forces **Dieu, l'Église et ma patrie**… ». Salut de la main droite, **main gauche sur la hampe de l'étendard**. Fin : chant de la promesse puis chant national des S.D.S."],"src":"Aurore Ceremonial Verte.pdf, CEREMONIAL+SENEGAL+revise (1) (1).pdf"},{"h":"Investitures et cérémonies de camp","items":["**Investiture d'un chef** : obligatoirement par le **commissaire de district** ou en sa présence ; le chef renouvelle sa promesse avec un engagement de chef, puis reçoit l'**obédience** de ses assistants.","**Investiture d'un CP** : demande manuscrite, conseil de maîtrise, décision de la **cour d'honneur**. Il reçoit la **cordelière kaki** et le **bâton portant le fanion**, puis l'obédience de sa patrouille.","Bandes blanches verticales sur la poche gauche : **une** (second), **deux** (CP), **trois** (premier CP).","**Ouverture du camp** : le servant allume le kraal avec **trois brins d'allumette** ; chants *Ingonyama* et *Du fagot jaillit la flamme* ; chacun dépose sa brindille : tous **acceptent la loi du camp**. Le kraal reste allumé tout le camp.","**Reconnaissance officielle** d'une unité : par le **commissaire de région**, avec remise de la lettre de reconnaissance et de l'**étendard**."],"src":"Aurore Ceremonial Verte.pdf, CEREMONIAL+SENEGAL+revise (1) (1).pdf"},{"h":"La montée et la descente des couleurs","items":["Les couleurs expriment la fidélité aux principes du scoutisme : **la fraternité scoute** et **le service de la Patrie**. Envoi **à l'ouverture du camp** et **chaque matin** au premier rassemblement ; préparation **un quart d'heure avant**.","Fixation (Aurore) : **nœud de chaise** autour du cabillot en haut, **nœud de tisserand** en bas. Seuls les scouts **ayant fait leur promesse** manœuvrent les drisses et font le salut.","Commandements : **« Attention pour les couleurs ! » – « Parés » – « Envoyez ! » – « Scouts, saluez ! »**. À bloc : **hymne national**, puis **« Pour le Sénégal » – « Dieu nous garde »**.","**Descente** au coucher du soleil par la patrouille d'honneur : chacun se met au prêt **là où il se trouve** et salue vers le mât. On commande **« Envoyez »**, jamais « Amenez » (défaite).","Lexique : **drisse** (corde), **pavillon** (drapeau sur la drisse), **ferlé** (plié), **déferlé et battant** (flottant), **à bloc** (tout en haut), **en berne** (mi-mât, deuil). Au Sénégal, on plie **en rectangle**, partie verte en dehors.","Le mât est **le point de ralliement, le cœur du camp** ; on lève les couleurs non par orgueil mais **pour dire qui nous sommes**."],"src":"Aurore Ceremonial Verte.pdf, CEREMONIAL+SENEGAL+revise (1) (1).pdf, Montée ou levée des couleurs.docx"},{"h":"Emblèmes et objets protégés","items":["Emblèmes **nationaux** (drapeau, pavillon) et **propres** : mât de meute, étendard de troupe, fanions de communauté et de patrouille, flamme scoute.","**Drapeau sénégalais** : carré de **90 cm**, vert-jaune-rouge, étoile verte, **frange or de 6 cm**, lys stylisé. Porté par un **chef ganté** escorté de **5 garçons gantés** ; placé **à droite du chef** qui commande. Seules les régions en possèdent un réglementaire.","**Étendard de troupe** : étamine verte de 1 m, insigne SDS, **hampe de 2,10 m**, **7 ganses**, lys argenté. Porté par **un assistant encadré de 2 éclaireurs** ; **jamais hissé au mât** (au pied du mât, ou au kraal si la flamme est hissée). Propriété de l'Association.","**Flamme scoute** : fond vert, hissée sur une **branche distincte**, après ou avec le pavillon. **Fanion de patrouille** : 25 × 40 cm, porté par le CP ou le second, **jamais au sol, jamais hissé**.","**Mât de meute** : **1,50 m** minimum, tête de loup ; rubans des brevets (religion blanc, intelligence bleu, habileté manuelle jaune, service rouge, aptitudes physiques vert).","**Insigne de promesse** : **fleur de lys jaune sur baobab**, poche gauche."],"src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf"},{"h":"Saluts, acclamation et deuil","items":["**Signe scout** : main droite, pouce sur l'ongle du petit doigt, trois doigts tendus ; on se serre **la main gauche** (jamais avec un non-scout). Un novice donne la main droite.","**Salut brandi** : uniquement au **refrain du chant de la promesse** et pour la **voûte d'honneur**, bras à 45°.","**Acclamation** : le chef crie **« Sunu gal »**, les scouts répondent **« Ta kanam »**, trois fois, pour un chef ou un visiteur de marque.","**Deuil** : **losange noir** sur la manche gauche ; durée fixée par la **cour d'honneur** à la mort d'un garçon ; emblèmes cravatés de crêpe, pavillon et flamme en berne.","À l'église, l'étendard de l'échelon le plus élevé se place dans le **chœur, côté de l'Épître**."],"src":"CEREMONIAL+SENEGAL+revise (1) (1).pdf, Aurore Ceremonial Verte.pdf"}],"vigilance":["**Cri après les couleurs** : « Pour le Sénégal » – « Dieu nous garde » (*Cérémonial Sénégal*, *Aurore*), contre « Pour son règne ! » – « Dieu nous garde ! » dans *Montée ou levée des couleurs*, texte non spécifique au Sénégal.","**Hymne et drisse** : le *Cérémonial Sénégal* fait chanter l'hymne quand les couleurs sont à bloc, avant de fixer la drisse ; l'*Aurore* fait attacher la drisse d'abord, puis chanter l'hymne.","**Servants** : un servant et son aide (*Cérémonial Sénégal*), le CP de la patrouille d'honneur et trois patrouillards (*Aurore*), deux servants par mât (*Montée des couleurs*).","**Signaux de la descente** : coup long + coups brefs au début et coup long à la fin (*Cérémonial Sénégal*) ; coup long puis second coup bref (*Montée des couleurs*) ; l'*Aurore* mêle les deux.","**Pliage** : l'*Aurore* exclut le triangle au Sénégal ; *Montée des couleurs* présente rectangle et triangle.","**Allocution après la promesse** : quatre minutes au plus (*Cérémonial Sénégal*), cinq (*Aurore*).","**Obédience au CP** : « t'aider comme un frère aîné » (formule générale) contre « t'aimer comme un frère aîné » (*Aurore*, investiture du CP).","**Acclamation** : « SUNU GAL TA KANAM » / « CIA-KA-NAM » (*Cérémonial Sénégal*), « SUNU GAAL CA KANAM » (*Aurore*)."]}$xxb$::jsonb, now()),
  ('fiche-3', $xxb${"theme":3,"titre":"Troupe et progression","intro":"Construite à partir des documents du dossier Xam Louy Troupe : manuels du CP et du CT, carnet de preuves, projet éducatif éclaireurs, sessions sur la progression, le cahier de bord et le livre d'or. Chaque section indique ses sources.","sections":[{"h":"Les étapes de la progression","items":["À l'entrée à la troupe, le garçon est **volontaire**. Il franchit ensuite trois étapes : **Engagé**, **Technicien**, **Animateur**. Il faut d'abord être engagé, puis technicien, enfin animateur.","**Volontaire** : étape de découverte qui ne doit pas dépasser **3 à 6 mois** (carnet), sous la responsabilité du **CP et du second**, supervisée par le CT.","**Promesse** : lettre de demande adressée à la maîtrise **sous couvert du CP**. Le CP défend le garçon en **cour d'honneur**. Viennent ensuite la **veillée de promesse** puis la cérémonie. Insigne : l'**insigne des SDS**.","**Engagé** : le garçon acquiert le **1er degré de compétence générale** (esprit scout, vie religieuse, sport, observation, hygiène, civisme…). Pas d'insigne chez les SDS pour cette étape.","**Technicien** : **au moins 3 degrés de compétence dans 2 séries de services** différentes. Badge : **tête de biche traversée d'une bande rouge**.","**Animateur** : brevets de compétence (acolyte, évangéliste, catéchiste-missionnaire, secouriste, campeur…). CH après consultation des parents, professeurs ou patron, **vote secret aux ¾**. Badge : tête de biche, **deux bandes rouges**."],"src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf, manuel du CP.pdf"},{"h":"Le carnet de preuves et l'esprit de la progression","items":["Le *Carnet de preuves* est l'outil de travail de la branche verte. **Faire ses preuves**, c'est montrer ce dont on est capable après un apprentissage : ce n'est pas une épreuve d'examen.","Le garçon **colorie le cercle** réservé à chaque technique dès qu'il la maîtrise. Il contrôle ainsi lui-même ses progrès.","Le volontaire suit l'exemple de **Nangmo**, enfant africain qui vécut seul **3 semaines** en forêt et revint **guerrier de la tribu**.","Évaluation **continue** : à chaque activité, à la maison, à l'école, partout. La finalité : faire du garçon un **bon routier et un bon citoyen**.","Cycle préparatoire à la promesse en **4 étapes** : décision du jeune (lettre), décision du groupe (CH), retraite spirituelle (veillée), geste final (cérémonie). La promesse **n'est pas un grade** : c'est le début de la vie scoute."],"src":"La Progression Personnelle (1).pdf, Livret Carnet de Preuves.pdf, Manuel du CT.pdf, proposition educative eclaireurs VF.pdf"},{"h":"Structures et instances de la troupe","items":["**Patrouille** : **6 à 8 jeunes de 13 à 17 ans**. Une troupe compte **2 à 4 patrouilles** : ce sont les patrouilles qui forment la troupe, et non la troupe qui est divisée.","**Maîtrise** : le CT, son ou ses assistants et l'aumônier. Elle veille à la bonne marche de la troupe ; ses chefs doivent donner l'exemple.","**Cour d'honneur** : **organe directeur** et **gardienne de la loi**, « loin d'être un tribunal ». Elle fixe les objectifs de l'année, admet à la promesse, décide de la progression et des sanctions. Le **CT la préside** avec un **droit de veto** ; délibérations **secrètes**.","**Conseil des chefs** (maîtrise + CP) : organise et coordonne la vie de la troupe. **Haute patrouille** (maîtrise + CP + SP) : forme les CP et SP, c'est « l'**université du CP** ».","**Conseil de patrouille** : présidé par le CP, « cœur de la patrouille », au moins **tous les 15 jours**. **Conseil de troupe** : toute la troupe, évalue les activités, environ **tous les deux mois**."],"src":"Structures et Instances à la Troupe.doc, Manuel du CT.pdf, manuel du CP.pdf, proposition educative eclaireurs VF.pdf"},{"h":"Le chef de patrouille et son second","items":["Le CP est le **premier scout** de sa patrouille et son exemple. Il est l'**intermédiaire** : représentant des jeunes auprès de la maîtrise et des adultes auprès des jeunes, pas une « courroie de transmission ».","Le **SP** aide le CP et le remplace en son absence. Il est choisi **par le CP avec l'accord de la maîtrise** (ou de la CH). Ce sont des **rôles de service, pas des grades**.","**Investiture du CP** : demande manuscrite au CT, décision de la CH. Le CP reçoit la **cordelière kaki** et le **bâton avec le fanion**, puis l'obédience de sa patrouille.","Les **deux bandes blanches** rappellent sa double mission : faire de ses garçons **une patrouille** et faire d'eux **des scouts**.","B-P : « Attendez beaucoup de vos CP et **9 sur 10** ils se révéleront à la hauteur. » Méthode de direction : **Observer, Juger, Décider**. Sagesse : « N'ordonne pas, entraîne ! »"],"src":"Session le Role du chef de patrouille camp CP SP Yeumbeul.docx, proposition educative eclaireurs VF.pdf, Manuel du CT.pdf, manuel du CP.pdf"},{"h":"Postes d'action et mœurs de patrouille","items":["Postes d'action, attribués par le **conseil de patrouille** : secrétaire, trésorier, intendant, bibliothécaire, maître de jeu, **cigalou** (boute-en-train), liturgiste, secouriste, topographe.","Le **totem** (animal), le **saint patron**, la **devise** (un objectif à atteindre, pas une étape franchie) et le **cri** donnent son identité à la patrouille.","La **prière** de patrouille s'adresse au **saint patron** ; l'**hymne** chante l'**animal totem**. La **loi de patrouille** : de préférence **5 articles au plus**.","Le **fanion** : ogive de **25 × 40 cm**, hampe de **1,40 m**. Seul le **CP** le porte (ou son second) ; il ne se hisse pas au mât et n'est jamais couché au sol.","Réforme nationale des **Patrouilles africaines** : totems de la faune africaine, avec couleurs (animal et milieu de vie), cri du jour et cri de nuit. Ex. : **Lion**, rouge et jaune, « Lion toujours courageux »."],"src":"Manuel du CT.pdf, manuel du CP.pdf, Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf, Patrouilles Africaines.pdf"},{"h":"Cahier de bord et livre d'or","items":["Le **livre d'or** est « l'**âme et l'histoire** de la patrouille ». Il est jalousement gardé et sa rédaction se fait après coup, avec soin.","Livre d'or en **5 parties** : présentation de l'animal totem, présentation du saint patron, présentation de la patrouille, **fiche signalétique**, **dédicaces**.","Cahier de bord en **4 parties** : présentation de la patrouille, présentation de la troupe (maîtrise et haute patrouille), **volet administratif**, **comptes rendus**.","Volet administratif : **état nominatif**, programme de patrouille en accord avec celui de la troupe, **tableau d'assiduité**, **état des cotisations**.","La présentation de la patrouille doit être **identique** dans les deux documents. Dans les dédicaces, ne pas accumuler des **signatures sans texte**. On privilégie tradition et créativité plutôt que l'impression."],"src":"Cahier De Bord et Livre D_Or.pdf, Guide Pratique pour Complément Sessions Cahier de Bord et Livre d’Or (1).pdf"}],"vigilance":["**Âge des patrouillards** : 13 à 17 ans (*Structures et Instances*, *Manuel du CT*, projet éducatif), contre 12 à 17 ans (*Manuel du CP*).","**Taille de la patrouille** : 6 à 8 jeunes (*Manuel du CT*, *Manuel du CP*, *Structures et Instances*), contre « sept ou huit » à un autre endroit du projet éducatif.","**Nombre de séries de services (technicien)** : sept (*La Progression Personnelle*), contre six (*Manuel du CP*). La version Word du carnet en liste six, la version PDF en contient davantage.","**Composition de la cour d'honneur** : CP et maîtrise (*Structures et Instances*, projet éducatif), contre CP, SP, éclaireurs animateurs et maîtrise (*Manuel du CT*).","**Fréquence de la cour d'honneur** : seulement dans des circonstances particulières (*Structures et Instances*, *Manuel du CT*), contre « se réunit régulièrement » (*Manuel du CP*).","**Conseil des chefs** : maîtrise + CP (*Structures et Instances*, *Manuel du CT*), contre maîtrise, CP, SP et aumônier (*Manuel du CP*), ou même composition que la CH (projet éducatif).","**Conseil de patrouille** : tous les membres (*Structures et Instances*), contre seulement ceux qui ont fait leur promesse (*Manuel du CP* ; le *Manuel du CT* dit les deux). Fréquence : au moins tous les 15 jours (manuels), contre au moins deux fois par trimestre (projet éducatif).","**Désignation du CP** : « nommé par ses frères de patrouille » (*Manuel du CP*), contre une demande manuscrite au CT puis une décision de la CH (*Manuel du CT*), ou une nomination par le chef d'unité après avis de la CH (projet éducatif).","**Garde du livre d'or** : le CP (*Cahier de Bord et Livre d'Or*), contre le secrétaire (*Manuel du CT* ; le *Manuel du CP* cite les deux).","**Rôle de l'intendant** : responsable du matériel (*Manuel du CT*), contre responsable du ravitaillement, le matériel revenant au « matérialiste » (*Manuel du CP*).","**Âge central de la branche** : vers 14 ans (*Manuel du CT*), contre vers 15 ans (projet éducatif).","**Patrouilles Africaines** : erreurs de copie probables (fanion du Dauphin décrit comme « un requin gris », fanion du Chacal comme « un léopard ou un guépard », cri de nuit de l'Éléphant = « bruit de pas du rhinocéros »). Le cri « Requin jusqu'au sang » contredit le *Manuel du CP*, qui proscrit les devises du type « sanglant »."]}$xxb$::jsonb, now()),
  ('fiche-4', $xxb${"theme":4,"titre":"Statuts et règlements","intro":"Fiche construite à partir des Statuts SGDS 2018, du Règlement intérieur (1991), des Procédures administratives et financières des SDS, de la Réglementation religieuse (1983), des Statuts de l'ASDS (2024) et du découpage de la région de Dakar. Chaque section indique ses sources.","sections":[{"h":"L'Association SGDS : identité et membres","items":["**Scouts & Guides du Sénégal (S.G.D.S.)** coordonne deux Mouvements : les **Scouts du Sénégal** (insigne : **fleur de lys** stylisée) et les **Guides du Sénégal** (insigne : **trèfle**). Durée illimitée, association **apolitique**, régie par la **loi 68-08 du 26 mars 1968**.","Affiliations des Scouts : **OMMS**, **CICS**, **CSS** (Confédération Sénégalaise du Scoutisme) et **CNJS**. Les Guides : **AMGE**, **CICG** et CNJS.","Membres : **adhérents** (les jeunes), **Chefs et Cheftaines**, **Conseillers spirituels**, **membres d'honneur**, **Ressources adultes**.","Perte de la qualité de membre : **démission motivée** ou **radiation** pour raisons graves (Conseil Général ou instances de base érigées en **Cour d'honneur**).","Structuration : **régions, districts, groupes/ménies, unités**. Un district compte **2 à 6 groupes ou ménies** (RI art. 30).","Statuts signés à **Gorée le 1er septembre 2018** ; Règlement intérieur fait à **Joal, 31 août - 1er septembre 1991**."],"src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf"},{"h":"Instances et organes nationaux","items":["**Assemblée Générale Ordinaire (AGO)** : instance **suprême délibérante et légiférante** ; se réunit **tous les 3 ans** ; documents envoyés **2 mois avant**, procès-verbaux **dans les 4 mois** qui suivent.","Quorum de l'AGO : **majorité des Régions** et **au moins le tiers** des membres de droit, les deux Mouvements représentés. Sinon, nouvelle AGO **dans les 2 mois**.","**Session nationale** : instance de **réflexion annuelle** qui choisit le **thème d'année** et le programme commun aux deux Mouvements.","**Conseil Général** : **exécutif national**, présidé par le/la Président(e), se réunit **au moins une fois par trimestre**. **Haut Conseil** : organe **consultatif** (Président, deux Commissaires Généraux, Trésorier Général, 3 conseillers au maximum).","Le/la **Président(e)** est le **garant moral** ; mandat de **3 ans renouvelable une fois**. L'AGO élit **2 commissaires aux comptes** (3 ans, renouvelable **deux fois**)."],"src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf"},{"h":"Région, district, groupe : qui fait quoi","items":["**Assemblée Régionale Ordinaire (ARO)** : organe suprême de la Région, **tous les 3 ans**, présidée par le/la Commissaire de Région, qu'elle **élit**. Participants âgés d'**au moins 18 ans**.","**Conseil Régional**, **Conseil de District** et **Conseil de Groupe/Ménie** se réunissent **une fois par trimestre** ; décisions à la **majorité absolue** des présents.","Le **Commissaire de District** est **élu par le Conseil de District**, confirmé et investi par le **Commissaire de Région** ; mandat de **3 ans renouvelable une fois**.","Le **Chef de Groupe** est **élu par le Conseil de Groupe** (3 ans renouvelable une fois). Les **Chefs d'Unité** sont nommés **chaque année** par le Chef de Groupe et investis par le **Commissaire de District**.","Le **Groupe** = **Meute + Troupe + Communauté** ; la **Ménie** = **Ronde + Compagnie + Feu**.","Seuls votent et sont éligibles les membres **à jour de leur cotisation-assurance**."],"src":"Statuts SGDS 2018.pdf, Règlement intérieur de Scouts et Guides.pdf"},{"h":"Unités, branches et discipline (Règlement intérieur)","items":["Branches scoutes : **Louveteaux 7-12 ans** (Meute), **Éclaireurs 13-17 ans** (Troupe), **Routiers 18 ans et plus** (Communauté). Branches guides : **Jeannettes 7-11**, **Guides 12-15**, **Guides Aînées 15 ans et plus**.","**Meute** : 2 à 5 **sizaines de 6** garçons. **Troupe** : 2 à 4 **patrouilles de 5 à 8**. Routiers organisés en **équipes de 8**.","**Cour d'honneur** : investitures des chefs, admission à la **promesse**, au **départ routier**, honorer les actions méritantes, sanctionner les fautes.","Les fêtes et manifestations régionales versent **15 %** de leur revenu à la **caisse nationale**. Une Région qui ne paie pas sa cotisation perd son **droit de vote à l'AG**.","Les cérémonies et les insignes suivent le livre *Cérémonial des Scouts et Guides du Sénégal*."],"src":"Règlement intérieur de Scouts et Guides.pdf"},{"h":"Procédures administratives et financières","items":["**Nomination** : mandat donné par le Mouvement, **pas un droit**. Le chef remplit l'engagement personnel, le Chef de Groupe donne son avis, le **Commissaire Régional** nomme et signe la carte.","Formation : **CI** dès la 1re année (régional), **CEP** et **19 ans au moins** pour être assistant (régional), **CNB** (national), puis **badge de bois**.","**Assurance** obligatoire, incluse dans la cotisation, période du **1er octobre au 30 septembre**. Jeune non assuré : responsabilité personnelle du **chef d'unité** et des **parents**.","Accident : déclaration à la permanence nationale **dans les 5 jours**, en **3 exemplaires**, avec un **certificat médical**.","Comptabilité : **cahier recettes/dépenses**, une **pièce justificative** pour chaque dépense ; **tableau des comptes** au trésorier régional **avant le 31 décembre**.","Camp : dossier au **Commissaire Régional** **un mois avant** ; chef de camp : **1 an** d'animation + **badge de bois** ; adjoints : **6 mois** + **camp national de branche**."],"src":"Procédures Administratives et Financières des SDS.pdf"},{"h":"Aumônerie, nouvelle ASDS et découpage de Dakar","items":["Réglementation religieuse (**Dakar, 10 décembre 1983**) : l'Association reconnaît l'autorité de l'**Assemblée des Ordinaires du Sénégal**. Les **aumôniers nationaux** sont nommés par elle ; les aumôniers de groupe sont **titularisés par l'aumônier régional**.","L'aumônier de groupe qui ne peut assister à un camp de **plus de 3 jours** prévient l'aumônier régional. Toute publication engageant la responsabilité religieuse ou morale est soumise à l'aumônier concerné.","**Association des Scouts du Sénégal (ASDS)** : créée à **Bambey le 15 septembre 2023** après l'AGO de **Ziguinchor (2022)**. Organes : **Comité national** de **9 membres**, **Bureau national** (exécutif), **Conseil national**, **Forums des jeunes (15-26 ans)**.","ASDS : **pas de procuration** dans les instances ; **nul ne peut jouir d'une double investiture**.","Région scoute de Dakar : **18 groupes reconnus** et **5 non reconnus**, répartis en **5 districts** : Plateau, **Grand Dakar I**, **Grand Dakar II**, Niayes, Magola.","**Grand Dakar I** : 3e (Saint Pierre), 5e (Sainte Thérèse), 12e (Notre Dame des Anges), Saint Christophe. **Grand Dakar II** : 9e, 10e (Saint Paul), 13e, 16e (Sainte Bakita et Notre Dame des Rails)."],"src":"Règlementation Religieuse doc.pdf, STATUTS DE L_ASDS_Somone_2024_10_05.doc, Le découpage de la région de Dakar.docx"}],"vigilance":["**Adresse du siège** : *Statuts 2018* « 4 allées Papa Gueye Fall » ; *Règlement intérieur* « 4, rue Sandiniéry (El Hadji Mbaye Gueye) » ; *Procédures SDS* « 49, avenue Lamine Gueye » ; *Statuts ASDS 2024* « Lot 2, Cité Keur-Gorgui, Sicap Sacré Cœur III ». Seule la **BP 1354** est commune.","**Nomination des chefs d'unité** : *Statuts 2018* : nommés par le **Chef de Groupe**, investis par le Commissaire de District ; *Règlement intérieur* : nommés et investis par le **Commissaire de District** sur proposition du Chef de Groupe ; *Procédures SDS* : nommés par le **Commissaire Régional**.","**Chef de Groupe** : *Statuts 2018* : **élu par le Conseil de Groupe**, investi par le Commissaire de Région ; *Règlement intérieur* : **nommé et investi par l'Équipe Régionale** sur proposition des Commissaires de District.","**Compte rendu du Commissaire de District** : **tous les 3 mois** selon les *Statuts 2018* ; **chaque semestre** selon le *Règlement intérieur*.","**Admission** : *Statuts 2018* : « tous les jeunes **croyants** » ; *Règlement intérieur* : « les jeunes **chrétiens** volontaires », d'autres croyants pouvant être acceptés.","**Convocation de la Session nationale** : par le/la **Président(e)** selon les *Statuts 2018* ; par le **Conseil Général** selon le *Règlement intérieur*.","**Statuts SGDS 2018 et ASDS 2024** : modification des statuts aux **2/3** (2018) contre la **majorité absolue** (2024) ; dissolution avec **3/4 des membres de droit** (2018) contre la **majorité absolue** (2024). Le texte ASDS laisse des blancs (date, numéro de loi) : à vérifier s'il est définitif.","**Découpage de Dakar** : le 9e et le 13e Dakar portent tous deux le nom « Martyrs de l'Ouganda », le 7e et le 15e tous deux « Saint Abraham ». Erreur de saisie possible, à faire confirmer."]}$xxb$::jsonb, now()),
  ('fiche-5', $xxb${"theme":5,"titre":"Sécurité et responsabilité","intro":"Fiche construite à partir du cours *Responsabilité civile et pénale*, du fascicule de la Croix-Rouge sénégalaise, du guide national *Formation aux premiers secours*, de la session secourisme du Groupe XIIe Dakar et des documents de campisme. Chaque section indique ses sources.","sections":[{"h":"Droits, devoirs et responsabilité civile du chef","items":["**Collectivité éducative** : définie par la **loi n° 96-07 du 22 mars 1996**, c'est un regroupement d'enfants, d'adolescents et d'adultes pendant les vacances et les loisirs.","**Droits du chef** : information sur le **projet pédagogique**, **assurance** de sa personne et de ses biens, **moyens suffisants**. **Devoirs** : réaliser le projet, éduquer, veiller à l'**hygiène et à la sécurité physique, morale et matérielle 24 h/24**.","**Responsabilité civile** : on **répare** par des dommages-intérêts le dommage causé par soi, par le **jeune sous son contrôle**, ou par la **chose ou l'animal** sous sa garde. Fondement : « **neminem laedere** » (ne pas nuire à autrui).","**Trois conditions** (art. 118 du COCC) : **faute**, **préjudice**, **lien de causalité**. Même la faute la plus légère (*culpa levissima*) suffit. Le dommage doit être **certain et direct**.","**Pas de responsabilité** en cas de **force majeure** ou de **cas fortuit** : événement extérieur, insurmontable, imprévisible (art. 129). Commettant et préposé sont **solidairement responsables** (art. 149)."],"src":"RESPONSABILITE CIVILE ET PENALE.pdf"},{"h":"Responsabilité pénale","items":["**Infraction** : action ou omission prévue et punie par la loi pénale. **Principe de légalité** (art. 4 du Code pénal), hérité de Montesquieu et Beccaria.","**Trois types** : **contravention** (peine de police), **délit** (police correctionnelle), **crime** (peine afflictive ou infamante). Seule peine infamante : la **dégradation civique**.","Exemples : **tapage nocturne** = contravention (200 à 70 000 F, 1 jour à 1 mois) ; **abandon de famille** = délit (3 mois à 1 an, 20 000 à 250 000 F).","En camp : le chef qui **vole** l'argent d'un jeune ou le **frappe** jusqu'à le blesser commet une infraction. L'intendant peut répondre d'une **intoxication alimentaire**, le secouriste d'une **injection maladroite**."],"src":"RESPONSABILITE CIVILE ET PENALE.pdf"},{"h":"Protéger et alerter","items":["Le secouriste a un rôle **primordial, limité et temporaire**. Trois temps : **PAS** (**Protéger, Alerter, Secourir**).","**Dégagement d'urgence** : manœuvre exceptionnelle, seulement face à un danger **vital, réel, immédiat et non contrôlable**. On tire la victime par les **poignets** ou les **chevilles**.","**Numéros au Sénégal** (doc. Groupe XIIe Dakar) : **Pompiers 18**, **SAMU 1515**, **Police 17**, **Gendarmerie 800 00 20 20**.","**Message d'alerte** : identité et téléphone, **lieu précis**, nature du problème, risques, **nombre et état des victimes**, gestes faits. **Ne pas raccrocher** sans autorisation."],"src":"Fascicule de premiers secours.pdf, Formation aux Premiers Secours.pdf, Session Secourisme.docx, Secourisme Alexis 12e.pdf"},{"h":"Les gestes qui sauvent","items":["**Étouffement** (main à la gorge, ne parle ni ne tousse) : **5 claques dans le dos**, puis **5 compressions abdominales (Heimlich)**. Nourrisson : compressions **thoraciques**. Obstruction partielle : **ne rien faire de tout cela**, installer et appeler.","**Hémorragie** : **compression directe** → **point de compression** (pli de l'aine, face interne du bras, base du cou) → **garrot** en dernier recours (lien large, visible, heure notée, **jamais desserré**).","**Saignement de nez** : assis, **tête en avant**, narine comprimée **10 minutes**.","**Inconscient qui respire** : libérer les voies aériennes, **PLS**, surveiller chaque minute (respiration appréciée **10 s au plus**). Femme enceinte : **côté gauche**.","**Ne respire plus** (guide national) : 2 insufflations, puis **15 compressions / 2 insufflations** chez l'adulte, **5/1** chez l'enfant, **100 par minute**. Seul : alerter tout de suite pour un adulte, après **1 minute de RCP** pour un enfant, un noyé ou un intoxiqué."],"src":"Formation aux Premiers Secours.pdf, Fascicule de premiers secours.pdf, Session Secourisme.docx"},{"h":"Plaies, brûlures, traumatismes, pharmacie","items":["**Brûlure** : arroser à l'eau (10 à 25 °C) sans pression ; grave si la cloque dépasse **la moitié de la paume** de la victime, ou au visage, aux mains, aux articulations. Vêtements en feu : **empêcher de courir, rouler au sol, étouffer**.","**Plaie simple** : se laver les mains, nettoyer à l'eau et au savon, protéger ; vérifier le **tétanos** (vaccin de plus de **10 ans** = médecin). **Corps étranger** dans une plaie : **ne jamais le retirer**.","**Positions d'attente** : plaie du thorax **demi-assis** ; plaie de l'abdomen **à plat dos, cuisses fléchies**. Douleur du dos ou de la nuque : **ne pas bouger** la victime, **tenir sa tête à deux mains**.","**Ne pas donner à boire** : inconscience, état de choc, blessure du crâne, du ventre ou du thorax, opération probable.","**Pharmacie** : vérifier les **dates de péremption** avant le camp, tenir la **liste des médicaments distribués**, vérifier allergies et contre-indications. **Ne jamais jouer au médecin.**"],"src":"Formation aux Premiers Secours.pdf, Session Secourisme.docx, 08_secourisme.pdf, Fascicule de premiers secours.pdf"},{"h":"Sécurité et hygiène au camp","items":["**Lieu de camp** : accès pour le matériel et l'**ambulance**, terrain campable, **eau et bois**, ravitaillement, **sécurité** (dangers, numéros des hôpitaux et médecins, abri en cas de tempête).","**Feu** : espace dégagé et délimité, **jamais laissé sans surveillance**, éteint après usage, **eau à proximité**. En sol de résineux ou de tourbe, le feu peut **couver sous terre**. Bois de cuisine : **CHEF** (Chêne/Charme, Hêtre, Érable, Frêne).","**Éclairage** : dans la tente, **lanterne à pile** seulement (un fanal renversé embrase la toile en moins de 5 s).","**Tentes** : jamais dans une dépression, un lit de torrent ou sous certains arbres ; **à bonne distance du feu**.","**Hygiène** : les **feuillées** sont la **première installation du premier jour** (tranchée d'environ 30 × 45 cm) ; trous à détritus et à eaux grasses de **50 cm**, couverts, **rebouchés** en fin de camp ; **jamais de plastique** à l'incinérateur."],"src":"formation lieu de camp.pdf, CAMPISME.docx, 11_allumer_un_feu.pdf, 12_specificites_combustible.pdf, asjdossier_technique_v3-1msds_20180319.pdf"}],"vigilance":["**Rythme de RCP** : 15 compressions / 2 insufflations chez l'adulte (*Formation aux premiers secours*, Fascicule, Session Secourisme), contre **30/2** dans *Formaion Secourisme DRPCK*.","**Insufflations initiales** : 2 (guide national, Session Secourisme), contre **4** (Fascicule Croix-Rouge) et **10** (DRPCK).","**Numéros d'urgence** : le guide *Formation aux premiers secours* est français (15, 18, 17, 112) ; pour le Sénégal, le document scout donne **18, 1515, 17 et 800 00 20 20**.","**Point de compression du bras** : face interne du bras (guide national, Session Secourisme), contre **derrière la clavicule** (Fascicule Croix-Rouge).","**Refroidir une brûlure** : 5 minutes (guide national), contre **15 à 20 minutes**, ou au moins 10 (*premiers_secours_cusstr*).","**Distance de balisage** : 150 à 200 m (guide national) ; 150 m le jour et 200 m la nuit (*Secourisme.pdf*) ; 100 à 150 m le jour et 200 m la nuit (*Secourisme Alexis 12e*) ; « 200 m ou 30 m » (*Session Secourisme*)."]}$xxb$::jsonb, now()),
  ('fiche-6', $xxb${"theme":6,"titre":"Camps et projets","intro":"Construite à partir des documents Xam Louy Troupe (projet, organisation et fiche technique d'un camp de patrouille), des Réglements et Procédures (déclaration, procédures administratives, fiche d'évaluation) et du dossier Badge de Bois de la IIIème Dakar, complétés par le chapitre « Le camp scout » des cahiers CEP et CI.","sections":[{"h":"Le camp scout : sens et types","items":["Le camp est le **lieu d'application par excellence de la méthode scoute**. Différent d'une colonie de vacances, il rassemble des scouts qui ont un **vécu commun** et se **prépare plusieurs semaines à l'avance**.","Il fait valoir le **système de patrouilles**, le contact nature et la vie en petit groupe ; il développe l'esprit scout, le **système D**, la solidarité, et accentue la formation du caractère.","Le *Cahier CEP Vert* le décrit comme un lieu où se combinent les **sept éléments** de la méthode : éducation par l'action, nature, Loi et Promesse, relation adultes/jeunes, progression personnelle, vie en équipes, cadre symbolique.","Deux types : **camps fixes** (même zone du début à la fin : chantier, formation, service, week-end) et **camps volants** ou itinérants (lieu changeant : exploration, découverte).","Ouverture du camp : la troupe forme un rectangle autour du **kraal** ; le servant l'allume avec trois brindilles en chantant **Ingonyama**, puis chacun y met sa brindille (acceptation de la loi du camp). Le kraal reste allumé tout le camp."],"src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf, CAHIER CI-1.pdf"},{"h":"Les 4 moments clés de l'organisation","items":["**Préparation** : type, durée et dates du camp, répartition des rôles, choix, réservation et **inspection du lieu**, prévisions budgétaires et grille des menus, thème et activités, transport, **demande d'autorisation**, programme, autorisation des parents, inventaire, assurances, inscriptions, réglementation.","**Pré-camp** : contacts avec le propriétaire (et, selon le *Cahier CEP Vert*, les autorités locales et le curé), vérification de la sécurité, montage de l'équipement lourd (bâches), **signalisation** par signes de piste.","**Derniers jours** : vérification des effets et de l'équipement, confirmation du transport retour (budget aller-retour **dégagé dès le début et intouchable**), inventaire, démontage, nettoyage (incinération des déchets combustibles, rebouchage des trous), visites de remerciements.","Loi du campeur : **« Le scout décampe sans laisser de trace »**.","**Au retour** : rangement du matériel bien sec (avec fiches de réparation), **bilan financier**, photos, classement des documents, rapport si requis."],"src":"Organisation d_un camp de patrouille BV.pdf, Cahier CEP Vert.pdf"},{"h":"Le projet et la fiche technique de camp","items":["Fiche technique : **document opérationnel synthétique** qui regroupe les informations pédagogiques, logistiques et pratiques ; elle **se suffit à elle-même**.","Rubriques : identification (la « carte d'identité »), contexte et justification (*facultatif*), cible, thème, objectifs, résultats attendus, participation, conditions, matériel, moyens (*facultatif*), staff, programme, grille des menus, budget prévisionnel.","Objectifs : un général et **3 à 5 spécifiques**, formulés selon la méthode **SMART** (Spécifiques, Mesurables, Atteignables, Réalistes, Temporels) et commençant par un **verbe d'action à l'infinitif**.","Résultats attendus : phrases **au présent ou au passé** décrivant un changement concret ; ils servent à évaluer en comparant situation finale et initiale.","Projet de camp de patrouille : rapport de reconnaissance (bois, eau, terrain, propriétaire), but, timing **Quand ? Quoi ? Qui ?**, plan de marche, sécurité, numéros utiles, matériel, Q-Métrance, budget, correspondances.","Test d'un bon projet : **si je suis absent, mon remplaçant peut-il mener le camp sans m'appeler ?**"],"src":"Rédaction d_une fiche technique de camp.pdf, Contenu dun projet de camp de patrouille.pdf"},{"h":"Budget, intendance et sécurité","items":["Budget prévisionnel : **dépenses** (nourriture, transport, matériel…) et **recettes** (cotisations, subventions…). Le faire **avant la première lettre** pour fixer l'inscription, puis le compléter avec les chiffres réels.","Ajouter **10 % « au cas où »** aux prévisions. Au camp, **une seule personne** tient la comptabilité, garde un **reçu pour chaque achat** et ne mélange pas l'argent de l'unité avec le sien.","Grille des menus : équilibrer l'alimentation, faciliter la gestion des stocks, varier les mets. Q-Métrance : ingrédients, quantité, prix unitaire, prix total.","Prévention : connaître chaque jeune grâce à la **fiche de renseignement individuelle**, savoir où il est, surveiller davantage sur l'eau, la route, en forêt, par mauvais temps ; **pas de jeans**.","Les membres des Scouts du Sénégal sont déjà couverts en **responsabilité civile** et **assurance accident**."],"src":"Rédaction d_une fiche technique de camp.pdf, Contenu dun projet de camp de patrouille.pdf, Cahier CEP Vert.pdf"},{"h":"Déclaration et dossier administratif","items":["Le dossier de camp informe **District, Région et Nation**, permet la **couverture par l'assurance** et fournit les données pour une intervention d'urgence.","Pour les autorités scoutes : **fiche de déclaration**, programme, liste des campeurs, **autorisation de camper**, fiche d'évaluation. Pour les autorités administratives et les parents : lettre au **Préfet/Gouverneur**, lettre au propriétaire ou aux **Eaux et Forêts**, autorisation des parents.","Dossier adressé au **Commissaire Régional**, qui peut autoriser, refuser ou arrêter un camp. Délai : **1 mois** avant le camp, **2 mois** pour un camp de plus de 10 jours.","Chef qualifié : **badge de bois depuis au moins un an**, **21 ans minimum**, au moins un an d'animation après le badge.","L'autorisation de camper est certifiée par le **chef de groupe** puis signée par les **commissaires de district et de région**."],"src":"Procédures administratives Camps Scouts.ppt, declaration de camp.doc"},{"h":"Évaluation et exemple du Badge de Bois","items":["Fiche d'évaluation : description du projet, renseignements utiles, déplacements, facilités sur place, réalisations et **coût** (réalisations, intendance, transport, autres frais), auteur du questionnaire.","Cursus de formation : **CI → CEP → CNB → CBB** ; à la fin, un **projet communautaire** réalisé et soutenu par un rapport.","Exemple IIIème Dakar : camp **du 29 juillet au 1er août 2022 à Ngazobil et Rof**, thème environnement (reboisement, nettoyage des déchets plastiques), objectif général **« Améliorer le cadre de vie naturel »**.","Bilan financier réel : **1 040 000 FCFA** (aides 600 000, cotisations 440 000, pépinières offertes), loin du prévisionnel de 7 110 000 FCFA.","Difficultés : acheminement des plantes, **pluie 2 jours sur 3**, retard sur le programme, pas de couverture médiatique."],"src":"Fiche évaluation camp.doc, RAPPOR_1.PDF, PROJET_1.PDF, Dossier de camp Badge de bois IIIème Dakar.pdf"}],"vigilance":["**À qui demander l'autorisation de camp** : à la maîtrise selon *Organisation d'un camp de patrouille*, au district selon le *Cahier CEP Vert*, au Commissaire Régional selon la *Déclaration de camp* (qui fait signer district et région).","**Types de camp** : deux types (fixes, volants) dans *Organisation d'un camp de patrouille* et le *Cahier CEP Vert*, contre trois cases (infrastructures résidentielles, sous tente, itinérant) dans la *Déclaration de camp*.","**Rapport au retour** : « à la maîtrise » (Organisation d'un camp de patrouille) contre « au groupe » (Cahier CEP Vert).","**Chef confirmé** : la *Déclaration de camp* exige badge de bois depuis un an, 21 ans et un an d'animation, mais définit plus bas le chef confirmé comme « une personne qui a un badge de bois ».","**Exemple de budget de la fiche technique** : les dépenses listées font 65 000 FCFA alors que le total indiqué est 63 500, et le solde affiché (3 000) ne correspond pas à 68 000 – 63 500.","**Dossier Badge de Bois** : le directeur du séminaire s'appelle Etienne DIOUF dans la lettre mais Etienne SENE dans le rapport ; « Arbres : 1500 » alors que les quantités listées font 1 600 ; le 1er août est daté 2021 au lieu de 2022.","**Contenu d'un projet de camp de patrouille** : sigles (CMAT, brigade, CBE) et montants (« 8.- par jour et par personne ») qui ne se retrouvent dans aucun autre document : à adapter au contexte local."]}$xxb$::jsonb, now()),
  ('fiche-7', $xxb${"theme":7,"titre":"Gestion et animation","intro":"Construite à partir des documents du dossier Gestion de Branche : pédagogie du jeu et du chant, animation et techniques de réunion, récap de planification, gestion d'unité et leadership. Chaque section indique ses sources.","sections":[{"h":"Planifier les activités de l'unité","items":["**Constat** : des unités vivent mal leur programme, ce qui contribue à la **perte des effectifs**. Causes citées : unités animées seulement sur les modules que maîtrisent leurs responsables, activités **monotones**, refus de faire appel à des **spécialistes**.","Toutes les approches partent du **besoin du jeune** : une **thématique** sur une période donnée, déroulée de façon coordonnée par toute la maîtrise.","**Méthodologie en 12 points** : approche thématique, compétences externes, sorties, chants, jeu éducatif, ATMs, défis, projection, contes et légendes, cadeau ou don, service ou témoignage d'impact, digital.","Cas pratique : **un mois sur la santé bucco-dentaire** (dentiste invité, visite d'un cabinet, ATM pâte dentifrice, samedi ciné…). Inutile de prendre les 12 points : l'essentiel est de **confier chaque point à un membre de la maîtrise** pour éviter les **assistants oisifs**.","La **planification** fixe, après étude et réflexion prospective, les **objectifs, les moyens, les étapes, les méthodes de suivi et les délais**.","Outils de gestion : **cahier de bord et livre d'or** (histoire de l'unité, identité du groupe), rapports et comptes rendus, **états nominatifs**, rapports financiers (transparence, décision éclairée, évaluation des performances)."],"src":"Récap planification et animation.pdf, gestion d_une unite scoute.pdf"},{"h":"Préparer une réunion","items":["Réunion : « une animation qui met des personnes en communication ensemble à un moment donné **pour un objectif précis** ». Elle peut être **physique** ou **virtuelle**.","Trois questions d'abord : **pourquoi** une réunion ? est-ce **le meilleur moyen** (une lettre, un coup de fil suffirait-il) ? **que va-t-on y faire** ? Sans réponse, on remet la réunion en cause.","**Convocation** : date, heures de début et de fin, objectifs, **ordre du jour**, type de réunion, personne à prévenir en cas d'absence, documents de travail. Un **court rappel** quelques jours avant.","Les horaires doivent permettre à **chacun d'arriver** ; l'heure de fin dépend de la durée nécessaire et de l'horaire de chacun.","Un **objectif** se reconnaît à trois points : un **verbe d'action**, **un seul sujet** à la fois, **aucune solution présupposée**. ODJ efficace : « Comment améliorer la sécurité des jeunes lors du prochain rallye » plutôt que « Sécurité ».","Préciser la **nature** de la réunion (informer, s'informer, recueillir un avis, proposer des solutions), sinon les participants risquent de jouer un rôle qui ne leur est pas reconnu."],"src":"animer les reunions.pdf, Session Techniques d_animation(1).pdf"},{"h":"Conduire et clôturer une réunion","items":["**Règle d'or** : tu dois **rester l'animateur** de la réunion, sinon sa conduite t'échappe.","Salle : tous doivent voir celui qui parle, les autres et les panneaux. **Cercle** : échanges non centralisés, l'animateur en fait partie. **Parallèle** : échanges centralisés et unilatéraux. Ne mettre **personne au centre du carré**. En petits groupes, **une table par groupe**.","Pendant : attendre que l'autre ait fini, signaler qui monopolise la parole, recentrer, rester **impartial**, **synthétiser et reformuler** les décisions, ne pas prendre soi-même les notes. **Après une heure et demie**, l'attention retombe.","Signes de décrochage : décision rediscutée, arguments répétés, apartés, participants qui dessinent. Remède : **pause brève** ou **petit jeu actif**.","Une **bonne décision** contient l'**objet**, l'**échéance**, la **personne chargée** de l'appliquer et éventuellement ce qui se passe si cela ne marche pas.","Après : un **rapport** reprenant les décisions, envoyé dans un délai raisonnable. Style de l'animateur évalué par le nombre de silences, de prises de parole, la gestion du temps, la satisfaction exprimée."],"src":"animer les reunions.pdf, Session Techniques d_animation(1).pdf"},{"h":"Pédagogie du jeu","items":["Le jeu procure du plaisir et développe la personne aux plans **physique, mental et affectif**. Pour l'enfant, il est **vital**.","**Trois phases** : **avant** (rassembler le matériel, délimiter l'aire, ôter les objets dangereux), **pendant** (exécution), **après** (ramassage du matériel, nettoyage de l'aire).","Évolution : activité **fonctionnelle** (le corps), **symbolique** (de 2-3 à 5 ans, jeux d'imitation), **socialisante** (vers 7-8 ans, règles élaborées entre camarades).","10 conseils : du **silence** obtenu d'abord jusqu'au **coup pour rien** ; parler pour les yeux autant que pour les oreilles, associer gestes et paroles, être bref, **arbitrage juste**.","**Fiche technique de jeu** en **14 rubriques**, du nom du jeu aux observations et évaluation. Éviter de pousser au **chauvinisme**. Piaget : « L'enfant qui joue est aussi sérieux que le chercheur dans son laboratoire »."],"src":"LA PEDAGOGIE DU JEU.docx"},{"h":"Pédagogie du chant","items":["Chant : **émission de sons musicaux par la voix humaine, avec ou sans paroles**. Une **chanson** est le texte rédigé pour être chanté. Selon **Macaire (1979)**, le chant répond à un **besoin naturel** de l'enfant.","Types : chant de **salutation**, d'**ambiance**, de **circonstance** (décès, mariage), des **rituels**, des **jeux**.","Le chef se prépare **physiquement (gorge), moralement et mentalement**, et adapte ses chansons à la cible.","Apprentissage : présenter (titre, origine), chanter tout le chant, **phrase par phrase**, **assemblage**, gestuelle, puis reprise complète. Groupes de voix **fine, moyenne, grave**. Pas d'élèves **enrhumés**, pas de chant **déjà connu**.","Après : reprendre un chant bien connu. **Ne pas applaudir** pendant l'apprentissage, favoriser l'**oral**. Mélodie simple, paroles **jamais vulgaires**, à **valeur éducative**."],"src":"PEDAGOGIE DU CHANT.docx"},{"h":"Le chef d'unité et le leadership","items":["Le chef **encadre et anime**, **planifie et organise**, forme et conseille, inculque des valeurs, communique avec parents et partenaires. Qualités : **leadership, patience et écoute, créativité, sens des responsabilités**.","Leadership dans le scoutisme (OMMS, **2014**) : un **processus de collaboration** pour élaborer une vision, mobiliser et responsabiliser les autres, et atteindre un objectif commun.","B-P : le système des patrouilles vise à « donner une **responsabilité réelle** à autant de garçons que possible ». **Participation des jeunes** : priorité stratégique n°1 de l'OMMS dès **2002**.","Cycle de vie d'une équipe : **constitution, tension, normalisation, production, dissolution**.","Quatre styles face à la décision : **autocratique**, autocrate qui s'informe, **consultatif**, **démocratique**. Une décision prise en groupe est mieux comprise et acceptée."],"src":"gestion d_une unite scoute.pdf, leadership SDS.pptx, devoir N°3 formateur des formateurs KEVIN COLY.pdf"}],"vigilance":["**Les 50 % de la réussite** : *Animer les réunions* attribue 50 % de la réussite d'une réunion à **une bonne préparation**, tandis que la session *Techniques d'animation* dit qu'elle dépend à 50 % **de l'animateur**.","**Disposition en U** : la session *Techniques d'animation* parle d'échanges **centralisés sur l'animateur** ; *Animer les réunions* la réserve aux réunions **avec écran de projection** ; le devoir de Kevin Coly propose le U (ou V) pour que **tous se voient et s'entendent**, le responsable au centre.","**Instrument d'accompagnement** : la *Pédagogie du chant* demande de le mettre en place **avant** l'apprentissage, mais aussi de **n'utiliser les instruments que lorsque le chant est bien suivi**.","**Le mot « ratissage »** : dans la *Pédagogie du jeu*, il désigne à la fois l'élimination des objets dangereux (phase **avant**) et la phase **après** (ramassage et nettoyage)."]}$xxb$::jsonb, now()),
  ('fiche-8', $xxb${"theme":8,"titre":"Autres branches : Meute et Communauté","intro":"Fiche construite à partir du Guide du louvetier, de LOUVETISME, du Livre de Baloo et du Livre de la Jungle I (Meute), du manuel CNBR et du Guide du chef de communauté révisé 2023 (Route). Chaque section indique ses sources.","sections":[{"h":"Le louvetisme : origines et buts","items":["Trois branches : **louveteaux 7-12 ans**, **éclaireurs 13-17 ans**, **routiers 18 ans et plus**. La meute est la **branche cadette** ; sa pédagogie repose sur **le jeu**.","**1914** : plan d'action, salut, insigne, promesse et épreuves pour les 7-12 ans. **1916** : *Livre des louveteaux*, mis au point par **Vera Barclay** avec B.-P., inspiré du *Livre de la jungle* de **Kipling**.","Patron : **saint François d'Assise**, fêté le **4 octobre** (légende du loup de Gubbio).","Buts (Vera Barclay) : but prochain **faire jouer les enfants**, but véritable **la formation du caractère**. Règle de B.-P. : « **Ask the Boy** ».","Ne pas faire un scoutisme « **éclaireur en réduction** » : à la meute la **maîtrise** décide, à la troupe le **conseil des chefs**, à la route le **conseil de Communauté**.","Le louvetisme prépare à la troupe : « être louveteau pourquoi ? **pour devenir un bon éclaireur et un bon routier plus tard** »."],"src":"GUIDE DU LOUVETIER.pdf, Livre de Baloo.pdf, LOUVETISME.pdf"},{"h":"Vie et symboles de la meute","items":["Loi : « **Le louveteau écoute le vieux loup, le louveteau ne s'écoute pas lui-même** ». **Cinq maximes**, la première : le louveteau **pense d'abord aux autres**. Maître-mot : « **De notre mieux** ».","Promesse (pas un engagement sur l'honneur) faite **à Akéla devant la meute** : fidèle à Dieu, au Sénégal, à mes parents, à la loi de la Meute, et **rendre chaque jour un service à quelqu'un** (le **Bon Tour**).","Meute : **24 louveteaux maximum**, en **sizaines de 6** (blancs, gris, noirs, bruns). Salut : deux doigts = **les oreilles du loup**. Pas de sifflet ; parades en **cercle** et **demi-cercle**.","**Mât de meute** d'1,50 m à tête de loup ; ruban de la couleur du brevet ; **flamme jaune** si tous les plus de 10 ans (10 mois de présence) ont la 2e étoile.","Vocabulaire : **Fleur rouge = feu**, **Pelage = uniforme**, **Chasse = jeux**, Tanière = local, Lune = réunion."],"src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf"},{"h":"Progression, conseils et activités à la meute","items":["**Patte tendre** (environ six mois) puis **promesse**, **1re étoile**, **2e étoile** (les deux yeux ouverts), puis **brevets** : bleu intelligence, jaune habileté manuelle, vert physique, rouge service, blanc religion.","Quatre conseils : **Rocher du conseil** (toute la meute, au moins une fois par mois, chaque jour au camp), **conseil d'Akéla** (maîtrise, mensuel), **conseil des sizeniers** (formation, ne décide pas), **conseil de sizaine**.","**Grand Hurlement** : salut, cri de joie et renouvellement de la promesse ; reçu en son honneur **deux fois** (entrée dans la meute, départ pour la troupe).","Réunion **hebdomadaire d'une à deux heures** ; camp **une fois par an, 3 à 8 jours**, **pas de jeux de nuit**, veillée d'**une heure maximum**, 9 à 10 h de sommeil.","Livre de Baloo : fiche technique de jeu avec un **essai avant de démarrer** ; ATM avec **matériel local ou de récupération**, et toujours **ranger et nettoyer** à la fin."],"src":"GUIDE DU LOUVETIER.pdf, LOUVETISME.pdf, Livre de Baloo.pdf"},{"h":"L'univers de la Jungle","items":["Mowgli, « **la Grenouille** », est adopté par **Raksha** (Mère Louve) contre **Shere Khan**, surnommé **Lungri le Boiteux**.","Au **Rocher du Conseil**, **Baloo** parle pour lui et **Bagheera** paie **un taureau** ; Akéla, « le Solitaire », préside. Un chef qui manque sa proie devient le « **Loup Mort** ».","**Baloo** enseigne la Loi, **Bagheera** apprend à chasser. Enlevé par les **Bandar-log**, Mowgli appelle **Chil le Vautour** : « **Nous sommes du même sang, toi et moi** » ; Kaa le délivre aux **Grottes Froides**.","Maître-mot de **Kaa** : « Assieds-toi, petit frère, réfléchis et fais un plan ». Ennemis : Shere Khan, Bandar-log, Chiens Rouges, **Tabaqui** le chacal."],"src":"Le livre de la Jungle I.pdf, GUIDE DU LOUVETIER.pdf"},{"h":"La Communauté (Route, branche Rouge)","items":["Route née **à partir de 1917** ; *La Route du succès* en **1922**. Devise : « **Servir** ». Méthode adaptée aux **18-35 ans** (CNBR).","Structures : **l'équipe** (cellule de base) et **la maîtrise** (CC, assistants, aumônier). Instances : **conseil de communauté** (au moins une fois par trimestre, « pièce maîtresse de la Route »), **conseil de maîtrise** et **conseil d'équipe** (mensuels).","Étapes : **noviciat** (18 ans au moins, un an, couronné par la Promesse), **apprentissage** (deux ans, centré sur le **service**), **compagnonnage** (choix du service définitif, **engagement personnel**), **départ routier** (libre choix, un an de réflexion avec un **parrain**).","Insigne : **fourche noire** (le choix au carrefour) sur fond **vert**, **jaune**, **rouge**, puis vert-jaune-rouge avec **R.S. (Routier en service)**. **Bâton à fourche** en bois de vène, remis pour le départ.","L'adulte est **conseiller plus que dirigeant**. Outils : **entreprise** (« pas de route sans entreprise », décidée par les routiers), **chapitre** (débat organisé), **charte** (« les louveteaux ont les Maximes, les scouts la Loi, les routiers la Charte »), camp de **6 à 12 jours**."],"src":"CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf"},{"h":"Accompagner les passages entre branches","items":["**Montée à la troupe** : préparée par le **chef de meute, le chef de troupe et l'aumônier** ; dernier Grand Hurlement, salut à l'étendard, louveteau **confié à un chef de patrouille**.","Le louveteau monté **garde son uniforme jusqu'à sa promesse** d'éclaireur et devrait la faire plus vite qu'un novice ordinaire.","**Montée à la communauté** : unités en rectangle, **maîtrises dos à dos à 5 m** ; le CP lance **une dernière fois le cri de patrouille**, le CT présente le garçon, le CC le confie au **chef d'équipe**.","**Accueil du novice** un mois après son arrivée : remise de la **chemise route, du foulard de région et de l'insigne de noviciat**. L'éclaireur retire ses **insignes de fonction** de la troupe.","**Départ routier** : remise du **pain**, d'une **flamme**, d'une **Bible** et des **flots jaune (louveteaux), vert (éclaireurs), rouge (routiers)**. Les chefs de meute et de troupe font eux-mêmes partie de la communauté."],"src":"LOUVETISME.pdf, GUIDE DU LOUVETIER.pdf, CNBR - MANUEL - VERSION FINALE + (05.09.2018)_2.pdf, Guide du chef de Communauté revisé.pdf"}],"vigilance":["**Taille de l'équipe** : 6 à 8 routiers (CNBR, ancien Guide chef de communauté), contre 4 à 6 (Guide du chef de communauté révisé 2023).","**Âge des routiers** : 18 à 35 ans (CNBR), 18 à 26 ans (Guide révisé), 17 à 30 ans (ancien guide) ; le CNBR rappelle aussi que B.-P. ne fixait pas d'âge limite.","**Durée du noviciat** : un an (CNBR), contre une découverte d'un à deux mois puis un passage au compagnonnage « au bout d'un ou deux ans » (Guide révisé).","**Insignes d'étape route** : manche gauche à 2 cm de l'épaule, 3 x 4 cm (CNBR, qui parle aussi de manche droite et de patte d'épaule), contre sous la patte d'épaule gauche, 5 x 4 cm (Guide révisé).","**Accueil du novice** : à 6 pas de la maîtrise (CNBR), à 3 pas (Guide révisé).","**Méthode route** : le CNBR annonce sept éléments mais en énumère huit.","**Flots des routiers** : jaune, vert, rouge au départ (CNBR) ; LOUVETISME (plus ancien) donne des flots marron aux compagnons et gris aux apprentis.","**Promesse du louveteau** : « à mon pays » (Guide du louvetier) ou « au Sénégal » (LOUVETISME). **Mât de meute** : 1,50 m (Guide) ou 1,50 m au minimum (LOUVETISME).","**Scoutisme au Sénégal** : présent depuis 1928 (Livre de Baloo) ; le Guide du louvetier dit 1928 « de mémoire », premières traces officielles en 1932."]}$xxb$::jsonb, now()),
  ('fiche-9', $xxb${"theme":9,"titre":"OMMS et spiritualité","intro":"Fiche construite à partir du *Better World Framework*, de la session sur les programmes de l'OMMS et des récaps du District (ODD, initiatives), puis des documents CICS : programme d'éducation spirituelle des branches, présentation « Devoir envers autrui », présentation de la CICS, programme de dialogue interreligieux et fiches sur les saints patrons.","sections":[{"h":"L'OMMS : mission, vision, priorités","items":["**Mission** (35e Conférence mondiale, **Durban 1999**) : contribuer à l'éducation des jeunes, en partant de la Promesse et de la Loi, pour un **monde meilleur**. Marque : **« Créer un monde meilleur »**.","**Vision 2023** (40e Conférence, **Ljubljana 2014**) : **100 millions de jeunes** citoyens actifs.","**6 priorités stratégiques** (Ljubljana 2014) : engagement des jeunes, méthodes éducatives, diversité et inclusion, **impact social**, communication et relations extérieures, gouvernance.","OMMS : organisation indépendante, non lucrative, non partisane ; **plus de 50 millions de membres, 160 pays et territoires**. Instance gouvernante : **Conférence mondiale tous les 3 ans** ; exécutif : **Comité mondial**.","**Théorie de l'alignement** : les OSN ajustent plans et programmes à la stratégie de l'OMMS, elle-même alignée sur l'ONU, l'UNESCO, l'UNICEF."],"src":"BETTER WORLD FRAMWORK.pdf, SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx"},{"h":"Programmes du Bureau mondial et ODD","items":["Historique : **2004** Brevet Scouts du Monde ; **2005** Programme Environnement ; **2011** Messagers de la Paix ; **2016** Cadre Monde Meilleur ; **2018** Mobilisation pour les ODD ; **2020** Tribu de la Terre ; **2024** Leaders de la vie et Alliés pour la santé.","**17 ODD** adoptés en **2015** (Agenda 2030). Repères : ODD 4 éducation de qualité, ODD 6 eau, ODD 13 climat, ODD 16 paix et justice, ODD 17 partenariats.","**Scouts for SDGs : 4 initiatives, 10 défis.** Messagers de la Paix (Dialogue pour la paix, Dialogue interreligieux, Patrimonito) ; Tribus de la Terre (Champions de la Nature, Plastic Tide Turners, Go Solar) ; Life Leaders (Impact Innovators, EQ in action) ; Alliés de la santé (Mind Builders, Nutrition).","Badge : au moins **5 activités** + questions de réflexion + **projet de service communautaire**, histoire partagée sur **sdgs.scout.org**, **badge numérique** sous une semaine environ.","**Messagers de la Paix** : 3 éléments (**programme, réseau, fonds de soutien**) et 4 objectifs (culture de la paix, culture du dialogue, soutien aux ODD, réseau mondial).","**Programme Environnement** : 5 buts (eau et air purs, habitats pour les espèces natives, substances dangereuses, pratiques écologiques, préparation aux catastrophes)."],"src":"SESSION LES PROGRAMMES DE L_OMMS vue globale.pptx, Récap 17 ODDs.pdf, Récap initiatives et défis.PDF, BETTER WORLD FRAMWORK.pdf"},{"h":"Le Brevet Scouts du Monde (SDM)","items":["Citoyenneté mondiale autour de **Paix, Environnement, Développement** ; pour les **15-26 ans**, scouts ou non.","3 éléments : **Découverte SDM** (au moins **21 h** : Explorer puis Répondre), **Service Volontaire SDM** (au moins **80 h**, environ deux semaines), **Réseau SDM**.","Né des priorités « Participation des jeunes » et « Adolescents » (**Thessalonique 2002**)."],"src":"BETTER WORLD FRAMWORK.pdf"},{"h":"Principes du scoutisme et devoir envers autrui","items":["**3 principes** : Devoir envers **Dieu** (spirituel), envers **autrui** (social), envers **soi-même** (personnel).","Devoir envers autrui : **participer au développement de la société dans le respect de la dignité de l'homme et de l'intégrité de la nature** ; **loyauté envers son pays** et **amitié mondiale**.","B-P (High Leigh, **1926**) : la religion « **n'y entre pas du tout. Elle est déjà là** ». Résolution **14/24 (1924)** : le scoutisme veut **renforcer** les croyances de chacun.","Méthode scoute : **8 éléments** depuis la 41e Conférence de **Bakou (août 2017)**, avec l'**engagement dans la communauté**.","Père Sevin : « Ton prochain […] **c'est tous les hommes** »."],"src":"Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf, Education spirituelle des branchesV21_09_22.pdf, Paroissiens POURQUOI ADHERER AU SCOUTISME.pdf"},{"h":"Éducation spirituelle par branche (CICS-Afrique)","items":["Programme rédigé par **Ernest Clément Mendy**, validé au **1er Symposium CICS-Afrique, Dakar, août 2022**. **4 compétences pédagogiques de base** : cheminer, connaître (et comprendre les autres religions), vivre et célébrer sa foi, témoigner par le service. **10 compétences de vie courante**.","**Louveteaux (7-12 ans)** : rites, récits, prière ; 20-30 min de retour au calme avant la prière, **30 min maximum**. Objectif : vivre sa religion et s'intégrer dans un contexte religieux.","**Éclaireurs** : religion active, **BA** (« faire des chrétiens en fait »), **une minute de silence par jour** ; objectif : initiatives et choix éclairés. Thème **Ubuntu** (« Je suis, parce que nous sommes ») et **teranga** sénégalaise.","**Routiers (18-26 ans)** : deux piliers, **mentorat** (parrain routier « premier de cordée », Père spirituel) et **Heure Route** (seule règle : **le silence**) ; **bilan au moins une fois par an**.","Saints patrons : **François d'Assise** (louveteaux), **Claire d'Assise** (louvettes), **Georges** (éclaireurs, fêté le **23 avril**)."],"src":"Education spirituelle des branchesV21_09_22.pdf, Section sur les Saint Patrons.docx"},{"h":"La CICS et le dialogue interreligieux","items":["**CICS** fondée en **1962**, siège à **Rome**, **statut consultatif** auprès de l'OMMS ; relation avec le **Dicastère pour les Laïcs, la Famille et la Vie**. **20 organisations membres** en Afrique.","**Père Jacques Sevin** (jésuite, 1882-1951, vénérable en 2012) : Scouts de France le **25 juillet 1920**, secrétaire de l'**OISC** ; croix potencée (universalité du salut) ; prière scoute attribuée à **saint Ignace de Loyola**.","Fleur de lys (B-P, vers 1909) : s'orienter ; **Franchise, Dévouement, Pureté**. Aumônier : modèle des **pèlerins d'Emmaüs**.","**Dialogue interreligieux** (Peter Kabo) : BDI de l'OMMS destiné aux aînés, élargi par la CICS à toutes les branches. Aînés : **maturation spirituelle, exploration de l'invisible, vivre-ensemble**.","Sénégal : 4 confréries (**Qadiriyya, Tijaniyya, Mourides, Layènes**) ; Tijaniyya propagée par **El Hadj Omar Tall**."],"src":"Quest ce que la CICS PDF.pdf, Présentation DEVOIR ENVERS AUTRUI Symposium Libreville Déc 2023.pdf, Paroissiens POURQUOI ADHERER AU SCOUTISME.pdf, Programme Dialogue Interreligieux CICS.pdf, Confréries du Sénégal (1).docx"}],"vigilance":["**Effectifs mondiaux** : la session OMMS indique plus de 50 millions de membres dans 160 pays, contre +57 millions et +200 organisations scoutes nationales dans le dépliant « Paroissiens ».","**Âge de la branche Route** : 18-22 ans dans le *Better World Framework*, contre 18-26 ans dans le programme d'éducation spirituelle.","**Premier Jamboree mondial (1920)** : Richmond Park, du 31 juillet au 8 août, dans la présentation de la CICS, contre Olympia Hall, en août, dans le programme de dialogue interreligieux.","**Le Père Sevin et la CICS** : la présentation de Libreville le dit « co-fondateur de la CICS », mais la CICS est fondée en 1962 et Sevin meurt en 1951. Il a cofondé l'OISC en 1920.","**Saint Georges** : « patron des scouts » dans le programme d'éducation spirituelle, « patron des éclaireurs » dans la fiche sur les saints patrons."]}$xxb$::jsonb, now()),
  ('plan', $xxb${"cadence":["4 jours par semaine, 15 à 20 minutes : lire la fiche du mois, puis répondre aux cartes du jour.","1 quiz mixte par semaine (10 minutes) : le thème du mois et les anciens.","1 bilan en fin de mois : un mini-examen sur le thème, puis reprogrammation des points faibles.","Répétition espacée automatique : une carte réussie revient à J+1, J+3, J+7, J+21, puis J+60. Une carte ratée revient le lendemain."],"months":[{"n":1,"o":"Maîtriser les repères de B-P, les 15 éléments fondamentaux, la promesse, la loi, la devise et les débuts du scoutisme au Sénégal."},{"n":2,"o":"Connaître le cérémonial scout au Sénégal, la montée des couleurs et les objets et symboles protégés."},{"n":3,"o":"Comprendre la progression personnelle, le carnet de preuves, le rôle du CP et le fonctionnement des patrouilles."},{"n":4,"o":"Savoir ce que disent les statuts, le règlement intérieur et les procédures administratives et financières."},{"n":5,"o":"Maîtriser la responsabilité civile et pénale, les premiers secours et les règles de sécurité en camp."},{"n":6,"o":"Monter un projet de camp : fiche technique, déclaration, organisation et évaluation."},{"n":7,"o":"Planifier et animer une unité : réunions, techniques d'animation, pédagogie du jeu et du chant."},{"n":8,"o":"Connaître la Meute (louvetisme) et la Communauté (routiers) pour accompagner les passages entre branches."},{"n":9,"o":"Situer l'action locale dans les programmes de l'OMMS et l'éducation spirituelle des branches."},{"n":10,"o":"Consolider topographie et matelotage, et les bases de la gestion financière d'une unité."},{"n":11,"o":"S'entraîner sur les annales du Rallye, de 2015 à 2023."},{"n":12,"o":"Quiz mixte sur toute l'année et plan de rattrapage."}]}$xxb$::jsonb, now())
